CREATE FUNCTION public._churn_can_read() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid()
      AND role::text = ANY (ARRAY['admin','manager','csm','direction','copil'])
  );
$$;


