--
-- Name: acknowledge_churn(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_churn(p_etab uuid, p_until timestamp with time zone, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public._churn_can_write() THEN RAISE EXCEPTION 'Accès refusé'; END IF;

  UPDATE public.churn_predictions
  SET acknowledged_until = p_until,
      acknowledged_by = auth.uid(),
      acknowledged_note = p_note,
      updated_at = now()
  WHERE etablissement_id = p_etab;

  RETURN jsonb_build_object('ok', true, 'acknowledged_until', p_until);
END;
$$;


--
-- Name: acknowledge_prospect(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_prospect(p_etab uuid, p_until date, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public._scoring_can_write() THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  UPDATE public.etablissements
  SET scoring_snoozed_until = p_until,
      scoring_snooze_note = p_note
  WHERE id = p_etab;

  RETURN jsonb_build_object('ok', true, 'snoozed_until', p_until);
END;
$$;


--
-- Name: add_user_to_pulse_team_conversations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_user_to_pulse_team_conversations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_role TEXT;
BEGIN
  SELECT role::text INTO user_role FROM user_roles WHERE user_id = NEW.id LIMIT 1;
  
  IF user_role IS NULL THEN
    user_role := 'commercial';
  END IF;
  
  -- Annonces (tous)
  INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
  SELECT pc.id, NEW.id, 'member', 'all'
  FROM pulse_conversations pc
  WHERE pc.metadata->>'type' = 'team_annonces'
  ON CONFLICT DO NOTHING;
  
  -- Général (tous)
  INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
  SELECT pc.id, NEW.id, 'member', 'mentions'
  FROM pulse_conversations pc
  WHERE pc.metadata->>'type' = 'team_general'
  ON CONFLICT DO NOTHING;
  
  -- Direction (admin, rh)
  IF user_role IN ('admin', 'rh') THEN
    INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
    SELECT pc.id, NEW.id, 'member', 'all'
    FROM pulse_conversations pc
    WHERE pc.metadata->>'type' = 'team_direction'
    ON CONFLICT DO NOTHING;
  END IF;
  
  -- Technique (admin, chef_projet)
  IF user_role IN ('admin', 'chef_projet') THEN
    INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
    SELECT pc.id, NEW.id, 'member', 'all'
    FROM pulse_conversations pc
    WHERE pc.metadata->>'type' = 'team_technique'
    ON CONFLICT DO NOTHING;
  END IF;
  
  -- CSM (admin, csm)
  IF user_role IN ('csm', 'admin') THEN
    INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
    SELECT pc.id, NEW.id, 'member', 'all'
    FROM pulse_conversations pc
    WHERE pc.metadata->>'type' = 'team_csm'
    ON CONFLICT DO NOTHING;
  END IF;
  
  -- Commercial (admin, commercial)
  IF user_role IN ('commercial', 'admin') THEN
    INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
    SELECT pc.id, NEW.id, 'member', 'all'
    FROM pulse_conversations pc
    WHERE pc.metadata->>'type' = 'team_commercial'
    ON CONFLICT DO NOTHING;
  END IF;
  
  -- Notes personnelles
  INSERT INTO pulse_conversations (name, description, visibility, created_by, metadata)
  VALUES (
    '📝 Notes personnelles',
    'Vos notes et rappels privés',
    'private',
    NEW.id,
    jsonb_build_object('auto_created', true, 'type', 'personal', 'owner_id', NEW.id)
  )
  ON CONFLICT DO NOTHING;
  
  INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
  SELECT pc.id, NEW.id, 'admin', 'all'
  FROM pulse_conversations pc
  WHERE pc.metadata->>'type' = 'personal' 
    AND (pc.metadata->>'owner_id')::uuid = NEW.id
  ON CONFLICT DO NOTHING;
  
  RETURN NEW;
END;
$$;


--
-- Name: add_user_to_team_conversation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_user_to_team_conversation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  team_conv_id UUID;
BEGIN
  -- Trouver la conversation d'équipe générale
  SELECT id INTO team_conv_id 
  FROM pulse_conversations 
  WHERE metadata->>'type' = 'team_general' 
  LIMIT 1;
  
  IF team_conv_id IS NOT NULL THEN
    INSERT INTO pulse_conversation_members (
      conversation_id,
      user_id,
      role,
      notification_level
    ) VALUES (
      team_conv_id,
      NEW.id,
      'member',
      'mentions'
    )
    ON CONFLICT DO NOTHING;
  END IF;
  
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to add user % to team conversation: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: admin_provision_portal_user(uuid, public.citext, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_provision_portal_user(p_etablissement_id uuid, p_email public.citext, p_full_name text) RETURNS TABLE(user_id uuid, temp_password text, existed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_password text;
  v_hash text;
  v_id uuid;
  v_existed boolean := false;
BEGIN
  -- Idempotence : si compte actif existe déjà pour cet (email, etab) → renvoie tel quel
  SELECT id INTO v_id
  FROM public.client_portal_users
  WHERE etablissement_id = p_etablissement_id
    AND email = p_email
    AND actif = true
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN QUERY SELECT v_id, NULL::text, true;
    RETURN;
  END IF;

  -- Génération mot de passe (14 chars URL-safe)
  v_password := encode(extensions.gen_random_bytes(10), 'base64');
  v_password := replace(replace(replace(v_password, '/', 'A'), '+', 'B'), '=', '');
  v_password := substring(v_password from 1 for 14);
  v_hash := extensions.crypt(v_password, extensions.gen_salt('bf', 10));

  INSERT INTO public.client_portal_users(email, password_hash, etablissement_id, full_name, created_by)
  VALUES (p_email, v_hash, p_etablissement_id, COALESCE(p_full_name, p_email::text), NULL)
  RETURNING id INTO v_id;

  RETURN QUERY SELECT v_id, v_password, false;
END;
$$;


--
-- Name: admin_reset_portal_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_portal_password(p_user_id uuid) RETURNS TABLE(temp_password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_password text;
  v_hash text;
BEGIN
  v_password := encode(extensions.gen_random_bytes(10), 'base64');
  v_password := replace(replace(replace(v_password, '/', 'A'), '+', 'B'), '=', '');
  v_password := substring(v_password from 1 for 14);
  v_hash := extensions.crypt(v_password, extensions.gen_salt('bf', 10));

  UPDATE public.client_portal_users
  SET password_hash = v_hash, actif = true
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Portal user not found';
  END IF;

  RETURN QUERY SELECT v_password;
END;
$$;


