  EXECUTE format('ANALYZE public.%I', table_name);
END;
$$;


--
-- Name: apply_task_models_to_establishment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_task_models_to_establishment(etablissement_id_param uuid) RETURNS TABLE(etablissement_id uuid, etablissement_nom text, statut_etablissement public.statut_etablissement, taches_creees integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  etablissement_record RECORD;
  commercial_category_id UUID;
  deployment_categories UUID[];
  production_category_id UUID;
  tasks_created INTEGER := 0;
BEGIN
  SELECT e.id, e.nom, e.statut, e.date_signature
  INTO etablissement_record
  FROM public.etablissements e
  WHERE e.id = etablissement_id_param;
  
  IF NOT FOUND THEN
    RETURN;
  END IF;
  
  SELECT id INTO commercial_category_id 
  FROM public.categories_taches 
  WHERE nom = 'Commercial';
  
  SELECT ARRAY_AGG(id) INTO deployment_categories
  FROM public.categories_taches 
  WHERE nom IN ('Contractuel', 'Conformité', 'Déploiement', 'Formation', 'Go-Live');
  
  SELECT id INTO production_category_id 
  FROM public.categories_taches 
  WHERE nom = 'Suivi Production';
  
  IF etablissement_record.statut IN ('Prospect', 'Contacté', 'Attente RDV', 'RDV pris', 'Attente post RDV', 'Dans les RDV', 'Etude émise', 'Dans les RDV post EME', 'Négociation', 'Bloqué', 'Reporté') 
     AND commercial_category_id IS NOT NULL THEN
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
    SELECT 
      etablissement_record.id,
      mt.categorie_id,
      mt.titre,
      mt.description,
      mt.priorite,
      mt.ordre,
      CASE 
        WHEN mt.delai_jours IS NOT NULL AND etablissement_record.date_signature IS NOT NULL
        THEN etablissement_record.date_signature + INTERVAL '1 day' * mt.delai_jours
        ELSE NULL
      END
    FROM public.modeles_taches mt
    WHERE mt.actif = true 
      AND mt.categorie_id = commercial_category_id
      AND NOT EXISTS (
        SELECT 1 FROM public.taches t 
        WHERE t.etablissement_id = etablissement_record.id 
          AND t.categorie_id = mt.categorie_id 
          AND t.titre = mt.titre
      );
    
    GET DIAGNOSTICS tasks_created = ROW_COUNT;
    
  ELSIF etablissement_record.statut IN ('Vendu', 'Contractualisation', 'Contractuel', 'Conformité', 'Déploiement', 'Formation', 'Go-Live') 
        AND deployment_categories IS NOT NULL AND array_length(deployment_categories, 1) > 0 THEN
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
    SELECT 
      etablissement_record.id,
      mt.categorie_id,
      mt.titre,
      mt.description,
      mt.priorite,
      mt.ordre,
      CASE 
        WHEN mt.delai_jours IS NOT NULL AND etablissement_record.date_signature IS NOT NULL
        THEN etablissement_record.date_signature + INTERVAL '1 day' * mt.delai_jours
        ELSE NULL
      END
    FROM public.modeles_taches mt
    WHERE mt.actif = true 
      AND mt.categorie_id = ANY(deployment_categories)
      AND NOT EXISTS (
        SELECT 1 FROM public.taches t 
        WHERE t.etablissement_id = etablissement_record.id 
          AND t.categorie_id = mt.categorie_id 
          AND t.titre = mt.titre
      );
    
    GET DIAGNOSTICS tasks_created = ROW_COUNT;
    
  ELSIF etablissement_record.statut = 'Production' AND production_category_id IS NOT NULL THEN
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
    SELECT 
      etablissement_record.id,
      mt.categorie_id,
      mt.titre,
      mt.description,
      mt.priorite,
      mt.ordre,
      NULL
    FROM public.modeles_taches mt
    WHERE mt.actif = true 
      AND mt.categorie_id = production_category_id
      AND NOT EXISTS (
        SELECT 1 FROM public.taches t 
        WHERE t.etablissement_id = etablissement_record.id 
          AND t.categorie_id = mt.categorie_id 
          AND t.titre = mt.titre
      );
    
    GET DIAGNOSTICS tasks_created = ROW_COUNT;
  END IF;
  
  RETURN QUERY SELECT 
    etablissement_record.id::UUID,
    etablissement_record.nom::TEXT,
    etablissement_record.statut,
    tasks_created;
END;
$$;


--
-- Name: apply_task_models_to_existing_establishments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_task_models_to_existing_establishments() RETURNS TABLE(etablissement_id uuid, etablissement_nom text, statut_etablissement public.statut_etablissement, taches_creees integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.etablissement_id,
    r.etablissement_nom,
    r.statut_etablissement,
    r.taches_creees
  FROM public.etablissements e
  CROSS JOIN LATERAL public.apply_task_models_to_establishment(e.id) r;
END;
$$;


--
-- Name: archive_deleted_pulse_message(uuid, uuid, uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_deleted_pulse_message(p_original_message_id uuid, p_conversation_id uuid, p_user_id uuid, p_content text, p_message_type text, p_metadata jsonb, p_created_at timestamp with time zone, p_deleted_at timestamp with time zone, p_deleted_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.pulse_message_archive (
    original_message_id,
    conversation_id,
    user_id,
    content,
    message_type,
    metadata,
    created_at,
    deleted_at,
    deleted_by
  ) VALUES (
    p_original_message_id,
    p_conversation_id,
    p_user_id,
    p_content,
    p_message_type,
    p_metadata,
    p_created_at,
    p_deleted_at,
    p_deleted_by
  );
END;
$$;


--
-- Name: archive_old_completed_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_completed_tasks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.statut = 'Terminé' AND (OLD.statut IS NULL OR OLD.statut != 'Terminé') THEN
    IF NEW.date_realisation IS NULL THEN
      NEW.date_realisation = CURRENT_DATE;
    END IF;
  END IF;

  IF NEW.statut = 'Terminé' 
     AND NEW.date_realisation IS NOT NULL 
     AND NEW.date_realisation < (CURRENT_DATE - INTERVAL '90 days')
     AND NEW.archive = false THEN
    NEW.archive = true;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: archive_pulse_message_on_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_pulse_message_on_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Only archive if deleted_at is being set (soft delete)
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    PERFORM public.archive_deleted_pulse_message(
      OLD.id,
      OLD.conversation_id,
      OLD.user_id,
      OLD.content,
      OLD.message_type,
      OLD.metadata,
      OLD.created_at,
      NEW.deleted_at,
      auth.uid()
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_block_etablissement_on_task_blocked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_block_etablissement_on_task_blocked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Si la tâche passe en statut "Bloqué"
  IF NEW.statut = 'Bloqué' AND (OLD.statut IS NULL OR OLD.statut != 'Bloqué') THEN
    -- Bloquer l'établissement associé
    UPDATE public.etablissements
    SET 
      statut = 'Bloqué',
      notes = COALESCE(notes || E'\n\n', '') || 
              '🚫 [' || CURRENT_DATE || '] Établissement bloqué automatiquement suite au blocage de la tâche : "' || 
              NEW.titre || '"'
    WHERE id = NEW.etablissement_id
    AND statut != 'Bloqué'; -- Ne pas bloquer si déjà bloqué
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: auto_detect_partenaire_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_detect_partenaire_contacts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  participant_data JSONB;
  participant_email TEXT;
  participant_name TEXT;
  contact_exists BOOLEAN;
  domain TEXT;
  is_official_domain BOOLEAN;
BEGIN
  -- Vérifier si l'email est lié à un partenaire
  IF NEW.partenaire_id IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Vérifier si participants existe et n'est pas vide
  IF NEW.participants IS NULL OR jsonb_array_length(NEW.participants) = 0 THEN
    RETURN NEW;
  END IF;

  -- Parcourir les participants
  FOR participant_data IN SELECT * FROM jsonb_array_elements(NEW.participants)
  LOOP
    BEGIN
      participant_email := participant_data->>'email';
      participant_name := participant_data->>'name';
      
      -- Ignorer si pas d'email
      IF participant_email IS NULL OR participant_email = '' THEN
        CONTINUE;
      END IF;
      
      -- Extraire le domaine
      domain := split_part(participant_email, '@', 2);
      
      -- Ignorer si pas de domaine
      IF domain IS NULL OR domain = '' THEN
        CONTINUE;
      END IF;
      
      -- Vérifier si c'est un domaine officiel du partenaire (condition relâchée)
      SELECT EXISTS(
        SELECT 1 FROM email_domain_mappings 
        WHERE partenaire_id = NEW.partenaire_id 
        AND lower(domain) = lower(domain)
        AND COALESCE(is_excluded, false) = false
        AND COALESCE(verified, true) = true
      ) INTO is_official_domain;
      
      IF NOT is_official_domain THEN
        CONTINUE;
      END IF;
      
      -- Vérifier si le contact existe déjà
      SELECT EXISTS(
        SELECT 1 FROM partenaires_contacts 
        WHERE partenaire_id = NEW.partenaire_id 
        AND lower(email) = lower(participant_email)
      ) INTO contact_exists;
      
      IF contact_exists THEN
        CONTINUE;
      END IF;
      
      -- Vérifier si déjà en attente
      SELECT EXISTS(
        SELECT 1 FROM pending_contacts 
        WHERE partenaire_id = NEW.partenaire_id 
        AND lower(extracted_data->>'email') = lower(participant_email)
        AND status = 'pending'
      ) INTO contact_exists;
      
      IF contact_exists THEN
        CONTINUE;
      END IF;
      
      -- Créer le contact en attente avec parsing amélioré du nom
      INSERT INTO pending_contacts (
        partenaire_id,
        email_thread_id,
        extracted_data,
        confidence,
        status
      ) VALUES (
        NEW.partenaire_id,
        NEW.id,
        jsonb_build_object(
          'email', participant_email,
          'nom', COALESCE(
            CASE 
              WHEN participant_name IS NULL OR participant_name = '' THEN split_part(participant_email, '@', 1)
              WHEN participant_name LIKE '% %' THEN split_part(participant_name, ' ', 2)
              ELSE participant_name 
            END,
            'Inconnu'
          ),
          'prenom', CASE 
            WHEN participant_name IS NOT NULL AND participant_name LIKE '% %' 
            THEN split_part(participant_name, ' ', 1) 
            ELSE NULL 
          END
        ),
        0.75,
        'pending'
      );
      
    EXCEPTION WHEN OTHERS THEN
      -- Log l'erreur mais ne pas bloquer le trigger
      RAISE WARNING 'Erreur lors de la création du contact en attente pour % (thread %): %', 
        participant_email, NEW.id, SQLERRM;
    END;
  END LOOP;
  
  RETURN NEW;
END;
$$;


--
-- Name: award_forum_badges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_forum_badges() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_badges JSONB := '[]'::jsonb;
BEGIN
  -- Badge "Première contribution"
  IF NEW.posts_count = 1 AND NEW.comments_count = 0 THEN
    new_badges := new_badges || jsonb_build_object(
      'id', 'first_post',
      'name', 'Première contribution',
      'description', 'A publié son premier post',
      'icon', '🎉',
      'awarded_at', now()
    );
  END IF;

  -- Badge "Aidant" (50+ commentaires)
  IF OLD.comments_count < 50 AND NEW.comments_count >= 50 THEN
    new_badges := new_badges || jsonb_build_object(
      'id', 'helpful',
      'name', 'Aidant',
      'description', '50+ commentaires publiés',
      'icon', '🤝',
      'awarded_at', now()
    );
  END IF;

  -- Badge "Expert" (10+ posts)
  IF OLD.posts_count < 10 AND NEW.posts_count >= 10 THEN
    new_badges := new_badges || jsonb_build_object(
      'id', 'expert',
      'name', 'Expert',
      'description', '10+ posts publiés',
      'icon', '⭐',
      'awarded_at', now()
    );
  END IF;

  -- Badge "Populaire" (100+ upvotes reçus)
  IF OLD.total_upvotes_received < 100 AND NEW.total_upvotes_received >= 100 THEN
    new_badges := new_badges || jsonb_build_object(
      'id', 'popular',
      'name', 'Populaire',
      'description', '100+ votes positifs reçus',
      'icon', '🌟',
      'awarded_at', now()
    );
  END IF;

  -- Ajouter les nouveaux badges s'il y en a
  IF jsonb_array_length(new_badges) > 0 THEN
    NEW.badges := NEW.badges || new_badges;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: backfill_email_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_email_contacts() RETURNS TABLE(contacts_created integer, contacts_updated integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contacts_created INTEGER := 0;
  v_contacts_updated INTEGER := 0;
BEGIN
  -- Vérifier que l'utilisateur est admin
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Seuls les administrateurs peuvent exécuter cette fonction';
  END IF;

  -- Logique de backfill (exemple simplifié)
  -- À adapter selon les besoins réels de l'application
  
  RETURN QUERY SELECT v_contacts_created, v_contacts_updated;
END;
$$;


--
-- Name: bump_etablissement_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_etablissement_updated_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  target_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    target_id := OLD.etablissement_id;
  ELSE
    target_id := NEW.etablissement_id;
    -- Also bump the old parent when the row is reassigned to another etablissement
    IF TG_OP = 'UPDATE' AND OLD.etablissement_id IS DISTINCT FROM NEW.etablissement_id AND OLD.etablissement_id IS NOT NULL THEN
      UPDATE public.etablissements SET updated_at = now() WHERE id = OLD.etablissement_id;
    END IF;
  END IF;

  IF target_id IS NOT NULL THEN
    UPDATE public.etablissements SET updated_at = now() WHERE id = target_id;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: bump_workflow_graph_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_workflow_graph_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.graph IS DISTINCT FROM OLD.graph THEN
    NEW.graph_version := COALESCE(OLD.graph_version, 1) + 1;
  END IF;
  RETURN NEW;
END;
$$;


