    pays text DEFAULT 'France'::text,
    periodicite_paiement text DEFAULT 'mensuel'::text,
    paiement_initial numeric(10,2),
    date_premier_paiement date,
    modele_detaille text,
    logo_url text,
    email_facturation text,
