    backend_url text,
    dpi_portail text DEFAULT 'hm'::text,
    site_web text,
    apporteurs_affaires_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    CONSTRAINT etablissements_dpi_portail_check CHECK ((dpi_portail = ANY (ARRAY['hm'::text, 'resurgences'::text]))),
    CONSTRAINT etablissements_enrichment_status_check CHECK ((enrichment_status = ANY (ARRAY['pending'::text, 'enriched'::text, 'failed'::text, 'skipped'::text, 'manual'::text]))),
    CONSTRAINT etablissements_periodicite_paiement_check CHECK (((periodicite_paiement IS NULL) OR (periodicite_paiement = ANY (ARRAY['mensuel'::text, 'trimestriel'::text, 'semestriel'::text, 'annuel'::text]))))
);


