--
-- Name: calculate_contract_value(public.etablissements); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_contract_value(etablissement_row public.etablissements) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  tarif_val numeric := 0;
  pal_num text;
  key_match text;
BEGIN
  IF etablissement_row.type_offre = 'Au succès' 
     AND etablissement_row.pallier_vise IS NOT NULL 
     AND etablissement_row.tarifs_palliers IS NOT NULL THEN
    pal_num := SUBSTRING(lower(etablissement_row.pallier_vise) FROM '\d+');
    IF pal_num IS NOT NULL THEN
      key_match := NULL;
      IF etablissement_row.tarifs_palliers ? ('palier' || pal_num) THEN 
        key_match := 'palier' || pal_num;
      ELSIF etablissement_row.tarifs_palliers ? ('pallier' || pal_num) THEN 
        key_match := 'pallier' || pal_num;
      ELSIF etablissement_row.tarifs_palliers ? ('palier_' || pal_num) THEN 
        key_match := 'palier_' || pal_num;
      ELSIF etablissement_row.tarifs_palliers ? ('pallier_' || pal_num) THEN 
        key_match := 'pallier_' || pal_num;
      END IF;
      
      IF key_match IS NOT NULL THEN
        tarif_val := COALESCE((etablissement_row.tarifs_palliers->>key_match)::numeric, 0);
      END IF;
    END IF;
  END IF;
  
  IF tarif_val = 0 AND etablissement_row.modele_statique_succes IS NOT NULL THEN
    IF etablissement_row.modele_statique_succes ~ '^[0-9]+\.?[0-9]*$' THEN
      tarif_val := etablissement_row.modele_statique_succes::numeric;
    END IF;
  END IF;
  
  IF tarif_val = 0 AND etablissement_row.nombre_passages_urgences_annuel IS NOT NULL THEN
    tarif_val := etablissement_row.nombre_passages_urgences_annuel * 2;
  END IF;
  
  RETURN tarif_val;
END;
$_$;


--
-- Name: calculate_contract_value(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_contract_value(tarifs_data jsonb, pallier_realise text, pallier_vise text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  ca_annuel numeric := 0;
  pallier_a_utiliser text;
BEGIN
  IF tarifs_data IS NULL THEN
    RETURN 0;
  END IF;

  pallier_a_utiliser := COALESCE(
    NULLIF(pallier_realise, ''),
    NULLIF(pallier_vise, ''),
    'Pallier 1'
  );

  CASE LOWER(TRIM(pallier_a_utiliser))
    WHEN 'pallier 1' THEN 
      ca_annuel := COALESCE((tarifs_data->>'fixe')::numeric, 0) + 
                   COALESCE((tarifs_data->>'palier1')::numeric, 0);
    WHEN 'pallier 2' THEN 
      ca_annuel := COALESCE((tarifs_data->>'fixe')::numeric, 0) + 
                   COALESCE((tarifs_data->>'palier2')::numeric, 0);
    WHEN 'pallier 3' THEN 
      ca_annuel := COALESCE((tarifs_data->>'fixe')::numeric, 0) + 
                   COALESCE((tarifs_data->>'palier3')::numeric, 0);
    WHEN 'pallier 4' THEN 
      ca_annuel := COALESCE((tarifs_data->>'fixe')::numeric, 0) + 
                   COALESCE((tarifs_data->>'palier4')::numeric, 0);
    ELSE
      ca_annuel := COALESCE((tarifs_data->>'fixe')::numeric, 0) + 
                   COALESCE((tarifs_data->>'palier1')::numeric, 0);
  END CASE;

  RETURN ca_annuel;
END;
$$;


--
-- Name: calculate_engagement_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_engagement_score(etab_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  score integer := 0;
  days_since_last_contact integer;
  total_threads integer;
  avg_response_hours numeric;
BEGIN
  SELECT EXTRACT(days FROM now() - MAX(last_message_date))::integer
  INTO days_since_last_contact
  FROM email_threads
  WHERE etablissement_id = etab_id;
  
  IF days_since_last_contact IS NOT NULL THEN
    score := score + GREATEST(0, 40 - days_since_last_contact);
  END IF;
  
  SELECT COUNT(*)
  INTO total_threads
  FROM email_threads
  WHERE etablissement_id = etab_id
  AND last_message_date > now() - interval '90 days';
  
  score := score + LEAST(30, total_threads * 3);
  
  SELECT AVG(
    EXTRACT(epoch FROM (em2.sent_date - em1.sent_date)) / 3600
  )::numeric
  INTO avg_response_hours
  FROM email_messages em1
  JOIN email_messages em2 ON em2.thread_id = em1.thread_id
  JOIN email_threads et ON et.id = em1.thread_id
  WHERE et.etablissement_id = etab_id
  AND em1.is_sent = false
  AND em2.is_sent = true
  AND em2.sent_date > em1.sent_date
  AND em2.sent_date > em1.sent_date + interval '1 minute';
  
  IF avg_response_hours IS NOT NULL AND avg_response_hours > 0 THEN
    score := score + GREATEST(0, LEAST(30, 30 - (avg_response_hours / 24)::integer));
  END IF;
  
  RETURN LEAST(100, GREATEST(0, score));
END;
$$;


--
-- Name: calculate_engagement_score(timestamp with time zone, numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_engagement_score(dernier_echange timestamp with time zone, progression_val numeric, nb_taches_terminees integer, nb_taches_total integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  score numeric := 0;
  days_since_contact integer;
BEGIN
  IF dernier_echange IS NOT NULL THEN
    days_since_contact := EXTRACT(DAY FROM (now() - dernier_echange));
    score := score + CASE
      WHEN days_since_contact <= 7 THEN 30
      WHEN days_since_contact <= 30 THEN 20
      WHEN days_since_contact <= 90 THEN 10
      ELSE 0
    END;
  END IF;
  
  IF progression_val IS NOT NULL THEN
    score := score + (progression_val * 0.4);
  END IF;
  
  IF nb_taches_total > 0 THEN
    score := score + ((nb_taches_terminees::numeric / nb_taches_total::numeric) * 30);
  END IF;
  
  RETURN LEAST(score, 100);
END;
$$;


--
-- Name: calculer_solde_reel(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculer_solde_reel(date_reference date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  solde_initial DECIMAL(15,2) := 50000; -- À paramétrer
  operations_total DECIMAL(15,2);
BEGIN
  SELECT COALESCE(
    SUM(CASE 
      WHEN type_operation = 'credit' THEN montant
      WHEN type_operation = 'debit' THEN -montant
      ELSE 0
    END),
    0
  ) INTO operations_total
  FROM tresorerie_operations_bancaires
  WHERE date_valeur <= date_reference;
  
  RETURN solde_initial + operations_total;
END;
$$;


--
-- Name: can_access_folder(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_folder(p_folder_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT 
    NOT (SELECT is_restricted FROM document_folders WHERE id = p_folder_id)
    OR (SELECT owner_id FROM document_folders WHERE id = p_folder_id) = p_user_id
    OR EXISTS (SELECT 1 FROM document_folder_permissions WHERE folder_id = p_folder_id AND user_id = p_user_id)
    OR EXISTS (
      SELECT 1 FROM document_folder_permissions dfp
      JOIN user_group_members ugm ON ugm.group_id = dfp.group_id
      JOIN profiles prof ON prof.id = ugm.user_id
      WHERE dfp.folder_id = p_folder_id AND prof.user_id = p_user_id
    )
    OR EXISTS (SELECT 1 FROM user_roles WHERE user_id = p_user_id AND role = 'admin');
$$;


--
-- Name: can_access_live_chat_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_live_chat_session(_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.live_chat_sessions s
    WHERE s.id = _session_id
      AND (
        public.is_admin()
        OR s.assigned_agent_id IN (SELECT p.id FROM public.profiles p WHERE p.user_id = auth.uid())
        OR EXISTS (
          SELECT 1 FROM public.live_chat_agents a
          WHERE a.profile_id IN (SELECT p.id FROM public.profiles p WHERE p.user_id = auth.uid())
            AND a.is_available = true
        )
        OR (
          length(COALESCE((current_setting('request.headers', true)::json ->> 'x-session-token'), '')) >= 32
          AND s.session_token_hash = encode(
            extensions.digest(
              COALESCE((current_setting('request.headers', true)::json ->> 'x-session-token'), ''),
              'sha256'
            ),
            'hex'
          )
        )
      )
  )
$$;


