--
-- Name: can_access_visio_room(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_visio_room(p_room_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile_id uuid;
  v_room_created_by uuid;
  v_conversation_id uuid;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE user_id = auth.uid();
  IF v_profile_id IS NULL THEN RETURN false; END IF;
  
  SELECT created_by, conversation_id INTO v_room_created_by, v_conversation_id
  FROM pulse_visio_rooms WHERE id = p_room_id;
  
  IF v_room_created_by = v_profile_id THEN RETURN true; END IF;
  
  IF v_conversation_id IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM pulse_conversation_members WHERE conversation_id = v_conversation_id AND user_id = v_profile_id);
  END IF;
  
  RETURN false;
END;
$$;


