--
-- Name: contacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    etablissement_id uuid,
    nom text NOT NULL,
    prenom text,
    fonction text NOT NULL,
    email text,
    telephone text,
    est_contact_principal boolean DEFAULT false,
    type_contact text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    groupe_id uuid,
    niveau_contact text DEFAULT 'etablissement'::text,
    created_source text DEFAULT 'manual'::text,
    created_metadata jsonb DEFAULT '{}'::jsonb,
    interlocuteur_csm boolean DEFAULT false,
    influence text,
    engagement text,
    CONSTRAINT contacts_created_source_check CHECK ((created_source = ANY (ARRAY['manual'::text, 'email_ai'::text, 'import_csv'::text, 'backfill'::text, 'api'::text]))),
    CONSTRAINT contacts_niveau_contact_check CHECK ((niveau_contact = ANY (ARRAY['etablissement'::text, 'groupe'::text])))
);


