-- Name: COLUMN contacts.etablissement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.etablissement_id IS 'Doit être non null pour niveau_contact = ''etablissement'' ; peut être null pour niveau_contact = ''groupe'' ou ''partenaire''.';


