-- Name: COLUMN contacts.created_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.created_source IS 'Source de création du contact : manual, email_ai, import_csv, backfill, api';


--
-- Name: COLUMN contacts.created_metadata; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.created_metadata IS 'Métadonnées supplémentaires (ex: {email_thread_id, confidence, model_used})';


--
-- Name: can_view_contact(public.contacts); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_contact(contact_row public.contacts) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_profile_id UUID;
BEGIN
  -- Admins et direction voient tout
  IF is_admin() OR has_role(auth.uid(), 'direction'::app_role) THEN
    RETURN TRUE;
  END IF;
  
  -- Récupérer le profile_id de l'utilisateur courant
  SELECT id INTO user_profile_id FROM profiles WHERE user_id = auth.uid();
  
  -- Contacts de niveau etablissement : voir si assigné
  IF contact_row.niveau_contact = 'etablissement' AND contact_row.etablissement_id IS NOT NULL THEN
    RETURN EXISTS (
      SELECT 1 FROM etablissements e
      WHERE e.id = contact_row.etablissement_id
      AND (e.commercial_id = user_profile_id 
           OR e.chef_projet_id = user_profile_id 
           OR e.csm_id = user_profile_id)
    );
  END IF;
  
  -- Contacts de niveau groupe : admin seulement (déjà géré)
  IF contact_row.niveau_contact = 'groupe' THEN
    RETURN FALSE;
  END IF;
  
  RETURN FALSE;
END;
$$;


--
-- Name: can_view_etablissement_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_etablissement_data(_etablissement_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.has_role(auth.uid(), 'admin'::app_role)
    OR public.has_role(auth.uid(), 'direction'::app_role)
    OR public.has_role(auth.uid(), 'copil'::app_role)
    OR public.has_role(auth.uid(), 'rh'::app_role)
    OR EXISTS (
      SELECT 1 FROM public.etablissements e
      WHERE e.id = _etablissement_id
        AND (
          e.commercial_id = auth.uid()
          OR e.csm_id = auth.uid()
          OR e.chef_projet_id = auth.uid()
        )
    );
$$;


--
-- Name: can_view_full_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_full_profile(target_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT 
    -- L'utilisateur lui-même
    EXISTS (SELECT 1 FROM profiles WHERE id = target_profile_id AND user_id = auth.uid())
    OR
    -- Personnel RH
    can_manage_rh_data()
    OR
    -- Admin avec 2FA
    has_admin_role_strict(auth.uid())
$$;


