--
-- Name: check_custom_dashboards_quota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_custom_dashboards_quota() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (SELECT COUNT(*) FROM public.custom_dashboards
      WHERE owner_id = NEW.owner_id AND is_template = false) >= 50 THEN
    RAISE EXCEPTION 'Quota dépassé : maximum 50 rapports par utilisateur';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_lcp_p75_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_lcp_p75_alert() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_fp text;
BEGIN
  FOR r IN
    SELECT route,
           percentile_cont(0.75) WITHIN GROUP (ORDER BY value)::double precision AS p75,
           count(*)::bigint AS samples
    FROM public.web_vitals_log
    WHERE created_at > now() - interval '24 hours'
      AND metric = 'LCP'
    GROUP BY route
    HAVING count(*) >= 10
       AND percentile_cont(0.75) WITHIN GROUP (ORDER BY value) > 4000
  LOOP
    v_fp := 'lcp_p75_route:' || r.route;
    INSERT INTO public.monitor_alerts (rule_key, fingerprint, source, severity, title, message, occurrences, first_seen_at, last_seen_at, status, metadata)
    VALUES (
      'lcp_p75_over_4s',
      v_fp,
      'frontend',
      'warning',
      'LCP dégradé sur ' || r.route,
      'P75 LCP = ' || round(r.p75)::text || ' ms (' || r.samples || ' échantillons sur 24h)',
      1, now(), now(), 'open',
      jsonb_build_object('route', r.route, 'p75_ms', r.p75, 'samples', r.samples)
    )
    ON CONFLICT (fingerprint) DO UPDATE
      SET occurrences = monitor_alerts.occurrences + 1,
          last_seen_at = now(),
          message = EXCLUDED.message,
          metadata = EXCLUDED.metadata,
          updated_at = now(),
          status = CASE WHEN monitor_alerts.status = 'resolved' THEN 'open' ELSE monitor_alerts.status END;
  END LOOP;
END;
$$;


--
-- Name: check_thread_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_thread_integrity() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_orphan_messages integer;
  v_threads_without_messages integer;
  v_drift_count integer;
  v_total_threads integer;
  v_total_messages integer;
  v_drift_samples jsonb;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  SELECT COUNT(*) INTO v_total_threads FROM public.email_threads;
  SELECT COUNT(*) INTO v_total_messages FROM public.email_messages;

  SELECT COUNT(*) INTO v_orphan_messages
  FROM public.email_messages m
  LEFT JOIN public.email_threads t ON t.id = m.thread_id
  WHERE t.id IS NULL;

  SELECT COUNT(*) INTO v_threads_without_messages
  FROM public.email_threads t
  LEFT JOIN public.email_messages m ON m.thread_id = t.id
  WHERE m.id IS NULL;

  WITH drift AS (
    SELECT t.id, t.message_count AS stored, COUNT(m.id)::int AS actual
    FROM public.email_threads t
    LEFT JOIN public.email_messages m ON m.thread_id = t.id
    GROUP BY t.id, t.message_count
    HAVING t.message_count <> COUNT(m.id)
  )
  SELECT COUNT(*), COALESCE(jsonb_agg(jsonb_build_object('thread_id', id, 'stored', stored, 'actual', actual) ORDER BY abs(stored-actual) DESC) FILTER (WHERE true), '[]'::jsonb)
  INTO v_drift_count, v_drift_samples
  FROM (SELECT * FROM drift LIMIT 20) s;

  RETURN jsonb_build_object(
    'total_threads', v_total_threads,
    'total_messages', v_total_messages,
    'orphan_messages', v_orphan_messages,
    'threads_without_messages', v_threads_without_messages,
    'message_count_drift', v_drift_count,
    'drift_ratio', CASE WHEN v_total_threads = 0 THEN 0 ELSE ROUND(v_drift_count::numeric / v_total_threads::numeric, 4) END,
    'drift_samples', v_drift_samples,
    'checked_at', now()
  );
END;
$$;


--
-- Name: FUNCTION check_thread_integrity(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_thread_integrity() IS 'Session 9 — Lot A: rapport intégrité threads emails (admin uniquement).';


