--
-- Name: cleanup_old_emails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_emails(days_to_keep integer DEFAULT 30) RETURNS TABLE(threads_deleted bigint, messages_deleted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  deleted_threads BIGINT;
  deleted_messages BIGINT;
BEGIN
  -- Supprimer les messages plus anciens que days_to_keep (utiliser received_date)
  DELETE FROM public.email_messages
  WHERE received_date < NOW() - INTERVAL '1 day' * days_to_keep;
  
  GET DIAGNOSTICS deleted_messages = ROW_COUNT;
  
  -- Supprimer les threads orphelins (sans messages)
  DELETE FROM public.email_threads
  WHERE id NOT IN (SELECT DISTINCT thread_id FROM public.email_messages WHERE thread_id IS NOT NULL);
  
  GET DIAGNOSTICS deleted_threads = ROW_COUNT;
  
  RETURN QUERY SELECT deleted_threads, deleted_messages;
END;
$$;


