--
-- Name: cleanup_old_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  deleted_security INTEGER;
  deleted_ai INTEGER;
  deleted_email_sync INTEGER;
  deleted_frontend INTEGER;
  deleted_suggestions INTEGER;
  deleted_api_logs INTEGER;
  deleted_statut_hist INTEGER;
  table_size BIGINT;
BEGIN
  DELETE FROM public.security_logs 
  WHERE created_at < NOW() - INTERVAL '90 days';
  GET DIAGNOSTICS deleted_security = ROW_COUNT;

  DELETE FROM public.ai_processing_log 
  WHERE processed_at < NOW() - INTERVAL '60 days';
  GET DIAGNOSTICS deleted_ai = ROW_COUNT;

  DELETE FROM public.email_sync_logs 
  WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS deleted_email_sync = ROW_COUNT;

  DELETE FROM public.frontend_error_logs 
  WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS deleted_frontend = ROW_COUNT;

  DELETE FROM public.email_to_etablissement_suggestions 
  WHERE status IN ('accepted', 'rejected', 'applied') 
    AND created_at < NOW() - INTERVAL '90 days';
  GET DIAGNOSTICS deleted_suggestions = ROW_COUNT;

  DELETE FROM public.api_logs 
  WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS deleted_api_logs = ROW_COUNT;

  DELETE FROM public.taches_statut_historique 
  WHERE changed_at < NOW() - INTERVAL '365 days';
  GET DIAGNOSTICS deleted_statut_hist = ROW_COUNT;

  -- Size monitoring alerts
  SELECT pg_total_relation_size('email_to_etablissement_suggestions') INTO table_size;
  IF table_size > 100 * 1024 * 1024 THEN
    RAISE WARNING 'ALERT: email_to_etablissement_suggestions size = % MB', (table_size / (1024*1024));
  END IF;

  SELECT pg_total_relation_size('email_messages') INTO table_size;
  IF table_size > 200 * 1024 * 1024 THEN
    RAISE WARNING 'ALERT: email_messages size = % MB', (table_size / (1024*1024));
  END IF;

  RAISE LOG 'cleanup_old_logs: security=%, ai=%, email_sync=%, frontend=%, suggestions=%, api_logs=%, statut_hist=%',
    deleted_security, deleted_ai, deleted_email_sync, deleted_frontend, deleted_suggestions, deleted_api_logs, deleted_statut_hist;
END;
$$;


--
-- Name: cleanup_pulse_for_hidden_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_pulse_for_hidden_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.actif = true
     AND NOT COALESCE(NEW.is_sandbox, false)
     AND (
       OLD.actif IS DISTINCT FROM NEW.actif
       OR COALESCE(OLD.is_sandbox, false) IS DISTINCT FROM COALESCE(NEW.is_sandbox, false)
     ) THEN
    RETURN NEW;
  END IF;

  IF NEW.actif IS DISTINCT FROM true OR COALESCE(NEW.is_sandbox, false) THEN
    UPDATE public.pulse_conversations c
    SET is_archived = true,
        archived_at = COALESCE(c.archived_at, now()),
        archived_by = NULL,
        updated_at = now(),
        metadata = COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('archived_reason', 'hidden_profile_offboarding')
    WHERE c.is_archived = false
      AND COALESCE(c.metadata->>'type', '') IN ('dm', 'personal', 'personal_notes')
      AND EXISTS (
        SELECT 1
        FROM public.pulse_conversation_members pcm
        WHERE pcm.conversation_id = c.id
          AND pcm.user_id = NEW.id
      );

    DELETE FROM public.pulse_conversation_members pcm
    USING public.pulse_conversations c
    WHERE c.id = pcm.conversation_id
      AND c.is_archived = false
      AND pcm.user_id = NEW.id;

    DELETE FROM public.pulse_presence pp
    WHERE pp.user_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


