--
-- Name: close_expired_challenges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_expired_challenges() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_closed_count INT := 0;
  v_winners_count INT := 0;
  v_total_points INT := 0;
  rec RECORD;
BEGIN
  FOR rec IN
    SELECT id, reward_points, target_value
    FROM public.gamification_challenges
    WHERE closed_at IS NULL
      AND end_date < NOW()
      AND is_active = true
  LOOP
    -- Marquer les participants gagnants
    WITH winners AS (
      UPDATE public.gamification_challenge_participants
      SET completed_at = COALESCE(completed_at, NOW()),
          updated_at = NOW()
      WHERE challenge_id = rec.id
        AND progress >= rec.target_value
        AND completed_at IS NULL
      RETURNING user_id
    ),
    credited AS (
      UPDATE public.gamification_user_stats us
      SET total_points = us.total_points + rec.reward_points
      FROM winners w
      WHERE us.user_id = w.user_id
      RETURNING us.user_id
    )
    SELECT COUNT(*) INTO v_winners_count FROM credited;

    v_total_points := v_total_points + (v_winners_count * rec.reward_points);

    -- Clôturer le défi
    UPDATE public.gamification_challenges
    SET closed_at = NOW(),
        is_active = false
    WHERE id = rec.id;

    v_closed_count := v_closed_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'closed_challenges', v_closed_count,
    'total_points_distributed', v_total_points,
    'executed_at', NOW()
  );
END;
$$;


