begin
  update public.time_entries
  set clock_out = date_trunc('day', clock_in) + interval '23 hours 59 minutes',
      auto_closed = true
  where clock_out is null
    and clock_in < date_trunc('day', now() at time zone 'Europe/Paris');
end;
$$;


--
-- Name: compta_check_equilibre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compta_check_equilibre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  total_debit numeric;
  total_credit numeric;
BEGIN
  IF NEW.statut = 'validee' AND (OLD.statut IS NULL OR OLD.statut = 'brouillon') THEN
    SELECT COALESCE(SUM(debit),0), COALESCE(SUM(credit),0)
      INTO total_debit, total_credit
      FROM public.compta_lignes WHERE ecriture_id = NEW.id;
    IF ROUND(total_debit,2) <> ROUND(total_credit,2) THEN
      RAISE EXCEPTION 'Écriture non équilibrée: débit=% crédit=%', total_debit, total_credit;
    END IF;
    IF total_debit = 0 THEN
      RAISE EXCEPTION 'Écriture vide';
    END IF;
    NEW.validated_at = now();
    NEW.validated_by = auth.uid();
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: compute_attribution(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_attribution(_etablissement_id uuid, _model text DEFAULT 'time_decay'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _by_channel jsonb; _by_user jsonb; _first_touch jsonb; _last_touch jsonb;
BEGIN
  SELECT jsonb_object_agg(channel, weight_total) INTO _by_channel FROM (
    SELECT channel,
      round(SUM(weight * CASE
        WHEN _model = 'time_decay' THEN EXP(-EXTRACT(EPOCH FROM (now() - occurred_at)) / (30 * 86400))
        ELSE 1 END)::numeric, 2) AS weight_total
    FROM public.attribution_touchpoints WHERE etablissement_id = _etablissement_id GROUP BY channel
  ) t;

  SELECT jsonb_object_agg(user_id::text, weight_total) INTO _by_user FROM (
    SELECT user_id,
      round(SUM(weight * EXP(-EXTRACT(EPOCH FROM (now() - occurred_at)) / (30 * 86400)))::numeric, 2) AS weight_total
    FROM public.attribution_touchpoints WHERE etablissement_id = _etablissement_id AND user_id IS NOT NULL GROUP BY user_id
  ) u;

  SELECT to_jsonb(t) INTO _first_touch FROM (
    SELECT channel, occurred_at, user_id FROM public.attribution_touchpoints
    WHERE etablissement_id = _etablissement_id ORDER BY occurred_at ASC LIMIT 1) t;

  SELECT to_jsonb(t) INTO _last_touch FROM (
    SELECT channel, occurred_at, user_id FROM public.attribution_touchpoints
    WHERE etablissement_id = _etablissement_id ORDER BY occurred_at DESC LIMIT 1) t;

  RETURN jsonb_build_object('model', _model,
    'by_channel', COALESCE(_by_channel, '{}'::jsonb),
    'by_user', COALESCE(_by_user, '{}'::jsonb),
    'first_touch', _first_touch, 'last_touch', _last_touch);
END; $$;


--
-- Name: compute_attribution_v2(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_attribution_v2(p_model text DEFAULT 'time-decay'::text, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start date := COALESCE(p_start, (now() - interval '12 months')::date);
  v_end   date := COALESCE(p_end, now()::date);
  v_result jsonb;
BEGIN
  IF NOT (
    public.has_role(auth.uid(), 'admin')
    OR public.has_role(auth.uid(), 'direction')
    OR public.has_role(auth.uid(), 'commercial')
    OR public.has_role(auth.uid(), 'copil')
  ) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  WITH touch AS (
    SELECT
      t.etablissement_id,
      t.channel::text AS channel,
      t.occurred_at,
      ROW_NUMBER() OVER (PARTITION BY t.etablissement_id ORDER BY t.occurred_at) AS rn,
      COUNT(*) OVER (PARTITION BY t.etablissement_id) AS total,
      MAX(t.occurred_at) OVER (PARTITION BY t.etablissement_id) AS last_touch,
      MIN(t.occurred_at) OVER (PARTITION BY t.etablissement_id) AS first_touch,
      e.statut::text AS statut,
      CASE
        WHEN e.modele_statique_succes IS NOT NULL AND e.modele_statique_succes <> ''
          THEN CAST(e.modele_statique_succes AS numeric)
        WHEN e.nombre_passages_urgences_annuel IS NOT NULL
          THEN e.nombre_passages_urgences_annuel * 1.5
        ELSE 0
      END AS deal_value
    FROM public.attribution_touchpoints t
    JOIN public.etablissements e ON e.id = t.etablissement_id
    WHERE t.occurred_at::date BETWEEN v_start AND v_end
  ),
  weighted AS (
    SELECT
      t.*,
      CASE p_model
        WHEN 'linear' THEN 1.0 / NULLIF(t.total, 0)
        WHEN 'u-shape' THEN
          CASE
            WHEN t.total = 1 THEN 1.0
            WHEN t.total = 2 THEN 0.5
            WHEN t.rn = 1 THEN 0.4
            WHEN t.rn = t.total THEN 0.4
            ELSE 0.2 / NULLIF(t.total - 2, 0)
          END
        ELSE -- time-decay (default), demi-vie 14j depuis last_touch
          POWER(0.5, EXTRACT(EPOCH FROM (t.last_touch - t.occurred_at)) / (86400.0 * 14))
      END AS raw_weight
    FROM touch t
  ),
  normalized AS (
    SELECT
      w.*,
      w.raw_weight / NULLIF(SUM(w.raw_weight) OVER (PARTITION BY w.etablissement_id), 0) AS norm_weight
    FROM weighted w
  ),
  per_channel AS (
    SELECT
      channel,
      COUNT(*) AS touchpoints,
      COUNT(DISTINCT etablissement_id) AS etablissements,
      COUNT(DISTINCT etablissement_id) FILTER (WHERE statut = 'Production') AS signed,
      ROUND(SUM(norm_weight * deal_value)::numeric, 0) AS attributed_value,
      ROUND(SUM(norm_weight)::numeric, 2) AS attributed_touches
    FROM normalized
    GROUP BY channel
  )
  SELECT jsonb_build_object(
    'model', p_model,
    'range', jsonb_build_object('start', v_start, 'end', v_end),
    'computed_at', now(),
    'channels', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'channel', channel,
        'touchpoints', touchpoints,
        'etablissements', etablissements,
        'signed', signed,
        'conversion_rate', CASE WHEN etablissements > 0 THEN ROUND((signed::numeric / etablissements) * 100, 1) ELSE 0 END,
        'attributed_value', attributed_value,
        'attributed_touches', attributed_touches,
        'value_per_touch', CASE WHEN attributed_touches > 0 THEN ROUND(attributed_value / attributed_touches, 0) ELSE 0 END
      ) ORDER BY attributed_value DESC)
      FROM per_channel
    ), '[]'::jsonb),
    'totals', (
      SELECT jsonb_build_object(
        'touchpoints', COALESCE(SUM(touchpoints), 0),
        'etablissements', COALESCE(SUM(etablissements), 0),
        'signed', COALESCE(SUM(signed), 0),
        'attributed_value', COALESCE(SUM(attributed_value), 0)
      )
      FROM per_channel
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: compute_behavioral_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_behavioral_score(_etablissement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _decay_days numeric := 30; _score numeric := 0; _velocity numeric := 0;
  _events_7d numeric := 0; _events_prev numeric := 0; _last_event timestamptz;
BEGIN
  SELECT COALESCE(SUM(weight * EXP(-EXTRACT(EPOCH FROM (now() - occurred_at)) / (_decay_days * 86400))), 0)
  INTO _score FROM public.prospect_behavioral_events
  WHERE etablissement_id = _etablissement_id AND occurred_at > now() - interval '90 days';

  SELECT COALESCE(SUM(weight), 0) INTO _events_7d
  FROM public.prospect_behavioral_events
  WHERE etablissement_id = _etablissement_id AND occurred_at > now() - interval '7 days';

  SELECT COALESCE(SUM(weight), 0) INTO _events_prev
  FROM public.prospect_behavioral_events
  WHERE etablissement_id = _etablissement_id
    AND occurred_at BETWEEN now() - interval '14 days' AND now() - interval '7 days';

  _velocity := _events_7d - _events_prev;
  SELECT MAX(occurred_at) INTO _last_event FROM public.prospect_behavioral_events WHERE etablissement_id = _etablissement_id;

  RETURN jsonb_build_object(
    'behavioral_score', LEAST(50, GREATEST(0, round(_score)::int)),
    'engagement_velocity', round(_velocity::numeric, 2),
    'last_event_at', _last_event,
    'raw_score', round(_score::numeric, 2));
END; $$;


--
-- Name: compute_churn_predictions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_churn_predictions() RETURNS TABLE(processed integer, high_risk integer, critical_risk integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_etab RECORD;
  v_score numeric;
  v_risk text;
  v_factors jsonb;
  v_recommendations jsonb;
  v_open_tickets integer;
  v_emails_30d integer;
  v_unpaid_invoices integer;
  v_days_since_last_interaction integer;
  v_processed integer := 0;
  v_high integer := 0;
  v_critical integer := 0;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin')
       OR public.has_role(auth.uid(), 'manager')
       OR public.has_role(auth.uid(), 'csm')
       OR public.has_role(auth.uid(), 'direction')) THEN
    RAISE EXCEPTION 'Accès refusé : rôle admin, manager, csm ou direction requis';
  END IF;

  FOR v_etab IN
    SELECT id, nom, date_signature
    FROM public.etablissements
    WHERE statut = 'production'
      AND (date_signature IS NULL OR date_signature < now() - interval '90 days')
  LOOP
    v_score := 0;
    v_factors := '{}'::jsonb;
    v_recommendations := '[]'::jsonb;

    SELECT COUNT(*) INTO v_open_tickets
    FROM public.support_tickets
    WHERE etablissement_id = v_etab.id AND statut IN ('ouvert', 'en_cours');
    IF v_open_tickets >= 5 THEN
      v_score := v_score + 30;
      v_recommendations := v_recommendations || jsonb_build_array('Traiter les ' || v_open_tickets || ' tickets support ouverts');
    ELSIF v_open_tickets >= 3 THEN v_score := v_score + 15;
    END IF;
    v_factors := v_factors || jsonb_build_object('open_tickets', v_open_tickets);

    SELECT COUNT(*) INTO v_emails_30d
    FROM public.email_threads
    WHERE etablissement_id = v_etab.id AND last_message_at > now() - interval '30 days';
    IF v_emails_30d = 0 THEN
      v_score := v_score + 25;
      v_recommendations := v_recommendations || jsonb_build_array('Aucun échange email depuis 30 jours - reprendre contact');
    ELSIF v_emails_30d < 3 THEN v_score := v_score + 10;
    END IF;
    v_factors := v_factors || jsonb_build_object('emails_30d', v_emails_30d);

    SELECT COUNT(*) INTO v_unpaid_invoices
    FROM public.factures
    WHERE etablissement_id = v_etab.id AND statut IN ('en_retard', 'impayee')
      AND date_emission < now() - interval '30 days';
    IF v_unpaid_invoices >= 2 THEN
      v_score := v_score + 25;
      v_recommendations := v_recommendations || jsonb_build_array('Relancer ' || v_unpaid_invoices || ' factures impayées');
    ELSIF v_unpaid_invoices = 1 THEN v_score := v_score + 10;
    END IF;
    v_factors := v_factors || jsonb_build_object('unpaid_invoices', v_unpaid_invoices);

    SELECT COALESCE(EXTRACT(DAY FROM now() - MAX(created_at))::integer, 999)
    INTO v_days_since_last_interaction
    FROM public.interactions WHERE etablissement_id = v_etab.id;
    IF v_days_since_last_interaction > 60 THEN
      v_score := v_score + 20;
      v_recommendations := v_recommendations || jsonb_build_array('Aucune interaction depuis ' || v_days_since_last_interaction || ' jours');
    ELSIF v_days_since_last_interaction > 30 THEN v_score := v_score + 10;
    END IF;
    v_factors := v_factors || jsonb_build_object('days_since_last_interaction', v_days_since_last_interaction);

    IF v_score >= 75 THEN v_risk := 'critical'; v_critical := v_critical + 1;
    ELSIF v_score >= 50 THEN v_risk := 'high'; v_high := v_high + 1;
    ELSIF v_score >= 25 THEN v_risk := 'medium';
    ELSE v_risk := 'low';
    END IF;

    INSERT INTO public.churn_predictions (
      etablissement_id, score, risk_level, factors, recommendations,
      predicted_at, model_version
    ) VALUES (
      v_etab.id, v_score, v_risk, v_factors, v_recommendations, now(), 'rule-v1.0'
    )
    ON CONFLICT (etablissement_id) DO UPDATE SET
      score = EXCLUDED.score,
      risk_level = EXCLUDED.risk_level,
      factors = EXCLUDED.factors,
      recommendations = EXCLUDED.recommendations,
      predicted_at = EXCLUDED.predicted_at,
      model_version = EXCLUDED.model_version,
      updated_at = now();

    -- snapshot historique (1 par jour par étab)
    INSERT INTO public.churn_predictions_history (etablissement_id, score, risk_level, factors, snapshot_date)
    VALUES (v_etab.id, v_score, v_risk, v_factors, CURRENT_DATE)
    ON CONFLICT DO NOTHING;

    v_processed := v_processed + 1;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_high, v_critical;
END;
$$;


--
-- Name: compute_deal_probability_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_deal_probability_v2(_etablissement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_static numeric := 0;
  v_statut text;
  v_behav int;
  v_velocity numeric;
  v_last_eng timestamptz;
  v_days_silence numeric;
  v_hist_rate numeric;
  v_bonus_behav numeric := 0;
  v_bonus_vel numeric := 0;
  v_malus_silence numeric := 0;
  v_final numeric;
  v_won int;
  v_lost int;
BEGIN
  SELECT
    e.statut::text,
    COALESCE(e.behavioral_score, 0),
    COALESCE(e.engagement_velocity, 0),
    e.last_engagement_at
  INTO v_statut, v_behav, v_velocity, v_last_eng
  FROM public.etablissements e
  WHERE e.id = _etablissement_id;

  IF v_statut IS NULL THEN
    RETURN jsonb_build_object('probability', 0, 'factors', jsonb_build_array());
  END IF;

  -- 1) Probabilité statique du statut
  SELECT COALESCE((rd.metadata->>'probability')::numeric, 0)
  INTO v_static
  FROM public.reference_data rd
  WHERE rd.type = 'statut_etablissement' AND rd.code = v_statut
  LIMIT 1;

  -- 2) Bonus comportemental (max +15)
  v_bonus_behav := LEAST(15, GREATEST(0, (v_behav - 30) * 0.3));

  -- 3) Bonus vélocité (-10 à +10)
  v_bonus_vel := GREATEST(-10, LEAST(10, v_velocity * 5));

  -- 4) Malus silence
  IF v_last_eng IS NOT NULL THEN
    v_days_silence := EXTRACT(EPOCH FROM (now() - v_last_eng)) / 86400.0;
    IF v_days_silence > 30 THEN
      v_malus_silence := -LEAST(20, (v_days_silence - 30) * 0.5);
    END IF;
  ELSE
    v_malus_silence := -10;
  END IF;

  -- 5) Taux historique du statut (12 derniers mois)
  SELECT
    COUNT(*) FILTER (WHERE e.statut::text = 'Production' OR e.statut::text = 'Signé')::int,
    COUNT(*) FILTER (WHERE e.statut::text = 'Perdu' OR e.statut::text = 'Abandonné')::int
  INTO v_won, v_lost
  FROM public.etablissements e
  WHERE e.updated_at >= now() - interval '12 months';

  IF (v_won + v_lost) > 0 THEN
    v_hist_rate := (v_won::numeric / (v_won + v_lost)) * 100;
  ELSE
    v_hist_rate := v_static;
  END IF;

  -- 6) Combinaison : 70% (static + bonus) + 30% (historique)
  v_final := 0.7 * (v_static + v_bonus_behav + v_bonus_vel + v_malus_silence)
           + 0.3 * v_hist_rate;
  v_final := GREATEST(0, LEAST(100, v_final));

  RETURN jsonb_build_object(
    'probability', round(v_final, 1),
    'static', v_static,
    'historical_rate', round(v_hist_rate, 1),
    'factors', jsonb_build_array(
      jsonb_build_object('label', 'Statique statut', 'points', v_static),
      jsonb_build_object('label', 'Score comportemental', 'points', round(v_bonus_behav, 1)),
      jsonb_build_object('label', 'Vélocité', 'points', round(v_bonus_vel, 1)),
      jsonb_build_object('label', 'Récence engagement', 'points', round(v_malus_silence, 1)),
      jsonb_build_object('label', 'Taux historique (30%)', 'points', round(v_hist_rate * 0.3, 1))
    )
  );
END;
$$;


--
-- Name: compute_gamification_points(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_gamification_points(p_user_id uuid, p_period text DEFAULT 'all'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_weights jsonb;
  v_w_deal int;
  v_w_rdv int;
  v_w_prospect int;
  v_w_task int;
  v_from timestamptz;
  v_deals int;
  v_rdv int;
  v_prospects int;
  v_tasks int;
  v_total int;
BEGIN
  SELECT value INTO v_weights FROM app_config WHERE key='gamification_weights';
  v_w_deal := COALESCE((v_weights->>'deal_signed')::int, 100);
  v_w_rdv := COALESCE((v_weights->>'rdv_held')::int, 10);
  v_w_prospect := COALESCE((v_weights->>'prospect_created')::int, 5);
  v_w_task := COALESCE((v_weights->>'task_completed')::int, 2);

  v_from := CASE p_period
    WHEN 'week' THEN now() - interval '7 days'
    WHEN 'month' THEN date_trunc('month', now())
    WHEN 'quarter' THEN date_trunc('quarter', now())
    WHEN 'year' THEN date_trunc('year', now())
    ELSE 'epoch'::timestamptz
  END;

  SELECT COUNT(*) INTO v_deals FROM etablissements
    WHERE statut IN ('vendu','production','client') AND updated_at >= v_from
      AND (commercial_id = p_user_id OR account_manager_id = p_user_id);

  SELECT COUNT(*) INTO v_rdv FROM interactions
    WHERE created_by = p_user_id AND type_interaction IN ('rdv','meeting','visite')
      AND created_at >= v_from;

  SELECT COUNT(*) INTO v_prospects FROM etablissements
    WHERE created_at >= v_from AND created_by = p_user_id;

  SELECT COUNT(*) INTO v_tasks FROM taches
    WHERE assigne_a = p_user_id AND statut = 'termine' AND updated_at >= v_from;

  v_total := v_deals * v_w_deal + v_rdv * v_w_rdv + v_prospects * v_w_prospect + v_tasks * v_w_task;
  RETURN COALESCE(v_total, 0);
EXCEPTION WHEN OTHERS THEN
  RETURN 0;
END;
$$;


--
-- Name: compute_next_export_run(text, integer, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_next_export_run(p_frequency text, p_hour_utc integer, p_day_of_week integer, p_day_of_month integer, p_from timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_next timestamptz;
BEGIN
  IF p_frequency = 'daily' THEN
    v_next := date_trunc('day', p_from) + make_interval(hours => COALESCE(p_hour_utc, 6));
    IF v_next <= p_from THEN v_next := v_next + interval '1 day'; END IF;
  ELSIF p_frequency = 'weekly' THEN
    v_next := date_trunc('day', p_from) + make_interval(hours => COALESCE(p_hour_utc, 6));
    WHILE EXTRACT(DOW FROM v_next)::int <> COALESCE(p_day_of_week, 1) OR v_next <= p_from LOOP
      v_next := v_next + interval '1 day';
    END LOOP;
  ELSIF p_frequency = 'monthly' THEN
    v_next := date_trunc('month', p_from)
              + make_interval(days => COALESCE(p_day_of_month, 1) - 1, hours => COALESCE(p_hour_utc, 6));
    IF v_next <= p_from THEN
      v_next := date_trunc('month', p_from + interval '1 month')
                + make_interval(days => COALESCE(p_day_of_month, 1) - 1, hours => COALESCE(p_hour_utc, 6));
    END IF;
  ELSE
    v_next := NULL;
  END IF;
  RETURN v_next;
END;
$$;


--
-- Name: contacts_access_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_access_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Log access to sensitive contact data
  PERFORM log_contact_access(
    COALESCE(NEW.id, OLD.id),
    COALESCE(NEW.etablissement_id, OLD.etablissement_id), 
    TG_OP,
    CASE 
      WHEN TG_OP = 'SELECT' THEN ARRAY['nom', 'prenom', 'email', 'telephone']
      WHEN TG_OP = 'UPDATE' THEN ARRAY['contact_updated']
      WHEN TG_OP = 'INSERT' THEN ARRAY['contact_created'] 
      WHEN TG_OP = 'DELETE' THEN ARRAY['contact_deleted']
      ELSE NULL
    END
  );
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: count_pulse_unread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_pulse_unread(p_user_id uuid) RETURNS TABLE(conversation_id uuid, unread_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT m.conversation_id, COUNT(*)::bigint as unread_count
  FROM pulse_messages m
  JOIN pulse_conversation_members pcm ON pcm.conversation_id = m.conversation_id
  JOIN pulse_conversations pc ON pc.id = m.conversation_id
  WHERE pcm.user_id = p_user_id
    AND m.user_id != p_user_id
    AND m.deleted_at IS NULL
    AND m.created_at > COALESCE(pcm.last_read_at, '1970-01-01'::timestamptz)
    AND pc.is_archived = false
  GROUP BY m.conversation_id;
$$;


--
-- Name: create_all_tasks_from_models(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_all_tasks_from_models() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Créer TOUTES les tâches actives de TOUTES les catégories
  -- pour permettre une gestion flexible du parcours
  INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
  SELECT 
    NEW.id,
    mt.categorie_id,
    mt.titre,
    mt.description,
    mt.priorite,
    mt.ordre,
    CASE 
      WHEN mt.delai_jours IS NOT NULL AND NEW.date_signature IS NOT NULL
      THEN NEW.date_signature::date + INTERVAL '1 day' * mt.delai_jours
      WHEN mt.delai_jours IS NOT NULL AND NEW.date_previsionnelle_signature IS NOT NULL
      THEN NEW.date_previsionnelle_signature::date + INTERVAL '1 day' * mt.delai_jours
      ELSE NULL
    END
  FROM public.modeles_taches mt
  WHERE mt.actif = true;
  
  RETURN NEW;
END;
$$;


--
-- Name: create_client_portal_user(public.citext, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_client_portal_user(p_email public.citext, p_full_name text, p_etablissement_id uuid) RETURNS TABLE(user_id uuid, temp_password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_password text;
  v_hash text;
  v_id uuid;
  v_creator uuid;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin'::app_role)
          OR public.has_role(auth.uid(), 'direction'::app_role)) THEN
    RAISE EXCEPTION 'Accès refusé : admin ou direction requis';
  END IF;

  -- created_by référence profiles(id) : on met NULL si pas de profil
  SELECT id INTO v_creator FROM public.profiles WHERE id = auth.uid() LIMIT 1;

  v_password := encode(extensions.gen_random_bytes(10), 'base64');
  v_password := replace(replace(replace(v_password, '/', 'A'), '+', 'B'), '=', '');
  v_password := substring(v_password from 1 for 14);

  v_hash := extensions.crypt(v_password, extensions.gen_salt('bf', 10));

  INSERT INTO public.client_portal_users(email, password_hash, etablissement_id, full_name, created_by)
  VALUES (p_email, v_hash, p_etablissement_id, p_full_name, v_creator)
  RETURNING id INTO v_id;

  RETURN QUERY SELECT v_id, v_password;
END;
$$;


--
-- Name: create_client_portal_user_admin(public.citext, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_client_portal_user_admin(p_email public.citext, p_nom text, p_prenom text, p_etablissement_id uuid, p_admin_id uuid) RETURNS TABLE(user_id uuid, temp_password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_password text;
  v_hash text;
  v_id uuid;
  v_creator uuid;
  v_full_name text;
BEGIN
  -- p_admin_id doit être admin ou direction (ou NULL = appel automatique trustless interne)
  IF p_admin_id IS NOT NULL THEN
    IF NOT (public.has_role(p_admin_id, 'admin'::app_role)
            OR public.has_role(p_admin_id, 'direction'::app_role)) THEN
      RAISE EXCEPTION 'Accès refusé : admin ou direction requis (p_admin_id=%)', p_admin_id;
    END IF;
    SELECT id INTO v_creator FROM public.profiles WHERE id = p_admin_id LIMIT 1;
  END IF;

  v_password := encode(extensions.gen_random_bytes(10), 'base64');
  v_password := replace(replace(replace(v_password, '/', 'A'), '+', 'B'), '=', '');
  v_password := substring(v_password from 1 for 14);
  v_hash := extensions.crypt(v_password, extensions.gen_salt('bf', 10));

  v_full_name := trim(coalesce(p_prenom, '') || ' ' || coalesce(p_nom, ''));
  IF v_full_name = '' THEN v_full_name := NULL; END IF;

  INSERT INTO public.client_portal_users(email, password_hash, etablissement_id, full_name, nom, prenom, created_by)
  VALUES (p_email, v_hash, p_etablissement_id, v_full_name, p_nom, p_prenom, v_creator)
  RETURNING id INTO v_id;

  RETURN QUERY SELECT v_id, v_password;
END;
$$;


--
-- Name: create_contrat_alertes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_contrat_alertes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.date_fin IS NOT NULL THEN
    INSERT INTO public.contrat_alertes (contrat_id, type, date_alerte, date_echeance, titre, description)
    VALUES (
      NEW.id,
      'expiration_30j',
      (NEW.date_fin - INTERVAL '30 days')::date,
      NEW.date_fin,
      'Contrat arrivant à échéance',
      'Le contrat ' || COALESCE(NEW.numero, NEW.titre) || ' arrive à échéance dans 30 jours.'
    );

    INSERT INTO public.contrat_alertes (contrat_id, type, date_alerte, date_echeance, titre, description)
    VALUES (
      NEW.id,
      'expiration_60j',
      (NEW.date_fin - INTERVAL '60 days')::date,
      NEW.date_fin,
      'Contrat arrivant à échéance (60 jours)',
      'Le contrat ' || COALESCE(NEW.numero, NEW.titre) || ' arrive à échéance dans 60 jours.'
    );
  END IF;
  RETURN NEW;
END;
$$;


