--
-- Name: pulse_conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pulse_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    etablissement_id uuid,
    name character varying(255) NOT NULL,
    description text,
    visibility text DEFAULT 'private'::text NOT NULL,
    created_by uuid,
    is_archived boolean DEFAULT false NOT NULL,
    archived_at timestamp with time zone,
    archived_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pulse_conversations_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'public'::text])))
);


--
-- Name: create_pulse_conversation(text, text, text, uuid, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pulse_conversation(p_name text, p_description text DEFAULT NULL::text, p_visibility text DEFAULT 'private'::text, p_etablissement_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_member_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.pulse_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile_id uuid;
  v_conversation public.pulse_conversations%ROWTYPE;
  v_member_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT p.id
    INTO v_profile_id
  FROM public.profiles p
  WHERE p.user_id = auth.uid()
    AND p.actif = true
    AND (
      NOT COALESCE(p.is_sandbox, false)
      OR public.is_sandbox_user(auth.uid())
      OR p.user_id = auth.uid()
    )
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Active profile not found' USING ERRCODE = 'P0001';
  END IF;

  IF NULLIF(BTRIM(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Conversation name is required' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_visibility, 'private') NOT IN ('private', 'public') THEN
    RAISE EXCEPTION 'Invalid conversation visibility' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.pulse_conversations (
    name,
    description,
    visibility,
    etablissement_id,
    created_by,
    metadata
  ) VALUES (
    BTRIM(p_name),
    NULLIF(BTRIM(COALESCE(p_description, '')), ''),
    COALESCE(p_visibility, 'private'),
    p_etablissement_id,
    v_profile_id,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING * INTO v_conversation;

  INSERT INTO public.pulse_conversation_members (
    conversation_id,
    user_id,
    role,
    invited_by
  ) VALUES (
    v_conversation.id,
    v_profile_id,
    'admin',
    v_profile_id
  )
  ON CONFLICT (conversation_id, user_id) DO NOTHING;

  FOR v_member_id IN
    SELECT DISTINCT unnest(COALESCE(p_member_ids, '{}'::uuid[]))
  LOOP
    IF v_member_id <> v_profile_id AND public.is_pulse_visible_profile(v_member_id) THEN
      INSERT INTO public.pulse_conversation_members (
        conversation_id,
        user_id,
        role,
        invited_by
      ) VALUES (
        v_conversation.id,
        v_member_id,
        'member',
        v_profile_id
      )
      ON CONFLICT (conversation_id, user_id) DO NOTHING;
    END IF;
  END LOOP;

  RETURN v_conversation;
END;
$$;


--
-- Name: create_pulse_dm_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pulse_dm_conversation(profile1_id uuid, profile2_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  dm_conv_id UUID;
  user1_name TEXT;
  user2_name TEXT;
BEGIN
  -- Vérifier si le DM existe déjà
  SELECT pc.id INTO dm_conv_id
  FROM pulse_conversations pc
  WHERE pc.metadata->>'type' = 'dm'
  AND (
    (pc.metadata->'participants' @> to_jsonb(profile1_id::text) AND pc.metadata->'participants' @> to_jsonb(profile2_id::text))
  );
  
  IF dm_conv_id IS NOT NULL THEN
    RETURN dm_conv_id;
  END IF;
  
  -- Récupérer les noms
  SELECT COALESCE(prenom, '') || ' ' || COALESCE(nom, '') INTO user1_name FROM profiles WHERE id = profile1_id;
  SELECT COALESCE(prenom, '') || ' ' || COALESCE(nom, '') INTO user2_name FROM profiles WHERE id = profile2_id;
  
  -- Créer la conversation DM
  INSERT INTO pulse_conversations (
    name, description, visibility, created_by, metadata
  ) VALUES (
    TRIM(user1_name) || ' & ' || TRIM(user2_name),
    'Conversation directe',
    'private',
    profile1_id,
    jsonb_build_object(
      'auto_created', true, 
      'type', 'dm',
      'participants', jsonb_build_array(profile1_id::text, profile2_id::text)
    )
  ) RETURNING id INTO dm_conv_id;
  
  -- Ajouter les deux membres
  INSERT INTO pulse_conversation_members (conversation_id, user_id, role, notification_level)
  VALUES 
    (dm_conv_id, profile1_id, 'admin', 'all'),
    (dm_conv_id, profile2_id, 'admin', 'all')
  ON CONFLICT DO NOTHING;
  
  RETURN dm_conv_id;
END;
$$;


--
-- Name: create_pulse_dm_for_new_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pulse_dm_for_new_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  existing_member RECORD;
BEGIN
  -- Vérifier si c'est un membre OpenPulse IA
  IF NEW.email NOT LIKE '%exemple.fr' AND NEW.email NOT LIKE '%OpenPulse-ia.com' THEN
    RETURN NEW;
  END IF;
  
  -- Créer un DM avec chaque membre existant
  FOR existing_member IN 
    SELECT id FROM profiles 
    WHERE id != NEW.id 
    AND (email LIKE '%exemple.fr' OR email LIKE '%OpenPulse-ia.com')
  LOOP
    PERFORM create_pulse_dm_conversation(NEW.id, existing_member.id);
  END LOOP;
  
  -- Créer aussi les notes personnelles
  INSERT INTO pulse_conversations (name, description, visibility, created_by, metadata)
  VALUES (
    '📝 Notes personnelles',
    'Vos notes privées',
    'private',
    NEW.id,
    jsonb_build_object('type', 'personal_notes', 'auto_created', true, 'owner_id', NEW.id)
  )
  ON CONFLICT DO NOTHING;
  
  RETURN NEW;
END;
$$;


--
-- Name: create_pulse_personal_conversation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pulse_personal_conversation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  conv_id UUID;
BEGIN
  -- Créer une conversation personnelle pour le nouvel utilisateur
  INSERT INTO pulse_conversations (
    name,
    description,
    visibility,
    created_by,
    metadata
  ) VALUES (
    'Notes personnelles',
    'Votre espace personnel pour prendre des notes et enregistrer des idées',
    'private',
    NEW.id,
    jsonb_build_object('type', 'personal', 'auto_created', true)
  )
  RETURNING id INTO conv_id;
  
  -- Ajouter l'utilisateur comme admin
  INSERT INTO pulse_conversation_members (
    conversation_id,
    user_id,
    role,
    notification_level
  ) VALUES (
    conv_id,
    NEW.id,
    'admin',
    'all'
  );
  
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log l'erreur mais ne bloque pas l'inscription
    RAISE WARNING 'Failed to create personal Pulse conversation for user %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: create_section_version_on_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_section_version_on_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Créer une version seulement si le contenu a changé significativement
  IF OLD.contenu_html IS DISTINCT FROM NEW.contenu_html OR OLD.titre IS DISTINCT FROM NEW.titre THEN
    INSERT INTO contrat_section_versions (section_id, contenu_html, titre, created_by, version_number)
    SELECT 
      OLD.id, 
      OLD.contenu_html, 
      OLD.titre, 
      auth.uid(),
      COALESCE((SELECT MAX(version_number) FROM contrat_section_versions WHERE section_id = OLD.id), 0) + 1;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: create_tasks_by_phase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tasks_by_phase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_phase_categories TEXT[];
BEGIN
  v_phase_categories := public.get_phase_categories(NEW.statut::TEXT);
  
  INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
  SELECT 
    NEW.id,
    mt.categorie_id,
    mt.titre,
    mt.description,
    mt.priorite,
    mt.ordre,
    CASE 
      WHEN mt.delai_jours IS NOT NULL AND NEW.date_signature IS NOT NULL
      THEN NEW.date_signature::date + INTERVAL '1 day' * mt.delai_jours
      WHEN mt.delai_jours IS NOT NULL AND NEW.date_previsionnelle_signature IS NOT NULL
      THEN NEW.date_previsionnelle_signature::date + INTERVAL '1 day' * mt.delai_jours
      ELSE NULL
    END
  FROM public.modeles_taches mt
  INNER JOIN public.categories_taches ct ON ct.id = mt.categorie_id
  WHERE mt.actif = true
    AND LOWER(ct.nom) = ANY(v_phase_categories);
  
  RETURN NEW;
END;
$$;


--
-- Name: cron_close_stale_email_syncs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_close_stale_email_syncs() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.email_sync_logs
     SET status = 'failed',
         execution_end = COALESCE(execution_end, now()),
         error_details = COALESCE(error_details, jsonb_build_object('reason', 'closed by watchdog (stale > 30 min)'))
   WHERE status = 'running'
     AND execution_start < now() - interval '30 minutes';
$$;


--
-- Name: cron_disable_failing_email_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_disable_failing_email_accounts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.user_email_accounts
     SET sync_enabled = false,
         last_sync_error = COALESCE(last_sync_error, 'Auto-disabled by watchdog (no successful sync > 6h)')
   WHERE sync_enabled = true
     AND is_active = true
     AND last_sync_error IS NOT NULL
     AND (last_sync_at IS NULL OR last_sync_at < now() - interval '6 hours');
END
$$;


--
-- Name: cron_trigger_email_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_trigger_email_sync() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_secret text;
  v_anon text;
  v_base_url text;
  v_request_id bigint;
BEGIN
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets WHERE name = 'CRON_SECRET' LIMIT 1;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'CRON_SECRET absent du coffre';
  END IF;

  -- L'URL de l'instance et la cle publique sont propres a chaque
  -- deploiement : elles vivent dans le coffre, jamais dans le schema.
  SELECT decrypted_secret INTO v_base_url
  FROM vault.decrypted_secrets WHERE name = 'INSTANCE_BASE_URL' LIMIT 1;
  IF v_base_url IS NULL THEN
    RAISE EXCEPTION 'INSTANCE_BASE_URL absent du coffre';
  END IF;

  SELECT decrypted_secret INTO v_anon
  FROM vault.decrypted_secrets WHERE name = 'INSTANCE_ANON_KEY' LIMIT 1;
  IF v_anon IS NULL THEN
    RAISE EXCEPTION 'INSTANCE_ANON_KEY absent du coffre';
  END IF;

  SELECT net.http_post(
    url := v_base_url || '/functions/v1/hourly-email-sync-and-analysis',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_anon,
      'apikey', v_anon,
      'X-CRON-Secret', v_secret
    ),
    body := jsonb_build_object('mode', 'cron', 'timestamp', now())
  ) INTO v_request_id;

  RETURN v_request_id;
END
$$;


--
-- Name: decode_html_entities(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decode_html_entities(input_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN regexp_replace(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(input_text, '&amp;', '&', 'g'),
          '&lt;', '<', 'g'
        ),
        '&gt;', '>', 'g'
      ),
      '&quot;', '"', 'g'
    ),
    '&#39;', '''', 'g'
  );
END;
$$;


--
-- Name: decrement_upvotes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_upvotes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.post_id IS NOT NULL THEN
    UPDATE public.forum_posts
    SET upvotes = upvotes - 1
    WHERE id = OLD.post_id;
  ELSIF OLD.comment_id IS NOT NULL THEN
    UPDATE public.forum_comments
    SET upvotes = upvotes - 1
    WHERE id = OLD.comment_id;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: decrypt_social_secret(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrypt_social_secret(ciphertext text, encryption_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF ciphertext IS NULL OR ciphertext = '' THEN RETURN NULL; END IF;
  RETURN extensions.pgp_sym_decrypt(decode(ciphertext, 'base64'), encryption_key);
END; $$;


--
-- Name: delete_phantom_threads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_phantom_threads() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  -- Delete threads that claim to have messages but actually don't
  WITH deleted AS (
    DELETE FROM email_threads et
    WHERE et.message_count > 0
      AND NOT EXISTS (
        SELECT 1 
        FROM email_messages em 
        WHERE em.thread_id = et.id
      )
    RETURNING et.id
  )
  SELECT COUNT(*) INTO deleted_count FROM deleted;
  
  RETURN deleted_count;
END;
$$;


--
-- Name: FUNCTION delete_phantom_threads(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_phantom_threads() IS 'Deletes email threads that have message_count > 0 but no actual messages in email_messages table';


--
-- Name: designate_sequence_winners(uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.designate_sequence_winners(_sequence_id uuid DEFAULT NULL::uuid, _min_sends integer DEFAULT 50, _min_diff numeric DEFAULT 0.05) RETURNS TABLE(sequence_id uuid, step_index integer, winner_variant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH grouped AS (
    SELECT
      v.sequence_id,
      v.step_index,
      v.id AS variant_id,
      COALESCE(s.sends_count, 0) AS sends,
      COALESCE(s.open_rate, 0) AS open_rate
    FROM public.email_sequence_variants v
    LEFT JOIN public.email_sequence_variant_stats s ON s.variant_id = v.id
    WHERE v.is_active = true
      AND (_sequence_id IS NULL OR v.sequence_id = _sequence_id)
      AND NOT EXISTS (
        SELECT 1 FROM public.email_sequence_variants v2
        WHERE v2.sequence_id = v.sequence_id
          AND v2.step_index = v.step_index
          AND v2.is_winner = true
      )
  ),
  ranked AS (
    SELECT
      g.sequence_id,
      g.step_index,
      g.variant_id,
      g.sends,
      g.open_rate,
      MIN(g.sends) OVER (PARTITION BY g.sequence_id, g.step_index) AS min_sends,
      MAX(g.open_rate) OVER (PARTITION BY g.sequence_id, g.step_index) AS top_rate,
      g.open_rate - MIN(g.open_rate) OVER (PARTITION BY g.sequence_id, g.step_index) AS diff
    FROM grouped g
  ),
  winners AS (
    SELECT DISTINCT ON (r.sequence_id, r.step_index)
      r.sequence_id, r.step_index, r.variant_id
    FROM ranked r
    WHERE r.min_sends >= _min_sends
      AND r.open_rate = r.top_rate
      AND (r.top_rate - (r.top_rate - r.diff)) >= _min_diff
    ORDER BY r.sequence_id, r.step_index, r.open_rate DESC
  ),
  applied AS (
    UPDATE public.email_sequence_variants v
    SET is_winner = true, updated_at = now()
    FROM winners w
    WHERE v.id = w.variant_id
    RETURNING v.sequence_id, v.step_index, v.id AS variant_id
  )
  SELECT a.sequence_id, a.step_index, a.variant_id FROM applied a;
END;
$$;


--
-- Name: document_has_entity_relation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_has_entity_relation(doc_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM document_relations dr
    -- Join with etablissements to check user access
    LEFT JOIN etablissements e ON dr.related_etablissement_id = e.id
    LEFT JOIN profiles p_etab ON (p_etab.id = e.commercial_id OR p_etab.id = e.chef_projet_id OR p_etab.id = e.csm_id)
    -- Join with taches to check user access via responsable or etablissement
    LEFT JOIN taches t ON dr.related_tache_id = t.id
    LEFT JOIN profiles p_tache ON p_tache.id = t.responsable_id
    LEFT JOIN etablissements e_tache ON t.etablissement_id = e_tache.id
    LEFT JOIN profiles p_tache_etab ON (p_tache_etab.id = e_tache.commercial_id OR p_tache_etab.id = e_tache.chef_projet_id OR p_tache_etab.id = e_tache.csm_id)
    -- Join with groupes to check user access via etablissements in group
    LEFT JOIN groupes_etablissements g ON dr.related_groupe_id = g.id
    LEFT JOIN etablissements_groupes eg ON eg.groupe_id = g.id
    LEFT JOIN etablissements e_groupe ON eg.etablissement_id = e_groupe.id
    LEFT JOIN profiles p_groupe ON (p_groupe.id = e_groupe.commercial_id OR p_groupe.id = e_groupe.chef_projet_id OR p_groupe.id = e_groupe.csm_id)
    -- Join with partenaires to check user access via responsable_marque_id
    LEFT JOIN partenaires part ON dr.related_partenaire_id = part.id
    LEFT JOIN profiles p_part ON p_part.id = part.responsable_marque_id
    -- Join with contacts to check access via etablissement
    LEFT JOIN contacts c ON dr.related_contact_id = c.id
    LEFT JOIN etablissements e_contact ON c.etablissement_id = e_contact.id
    LEFT JOIN profiles p_contact ON (p_contact.id = e_contact.commercial_id OR p_contact.id = e_contact.chef_projet_id OR p_contact.id = e_contact.csm_id)
    WHERE dr.document_id = doc_id
      AND (
        -- Admin has access to everything
        is_admin()
        -- User has access via etablissement relation (assigned as commercial, chef_projet, or csm)
        OR (dr.related_etablissement_id IS NOT NULL AND p_etab.user_id = auth.uid())
        -- User has access via tache relation (is responsable OR has access to task's etablissement)
        OR (dr.related_tache_id IS NOT NULL AND (p_tache.user_id = auth.uid() OR p_tache_etab.user_id = auth.uid()))
        -- User has access via groupe relation (has access to an etablissement in the group)
        OR (dr.related_groupe_id IS NOT NULL AND p_groupe.user_id = auth.uid())
        -- User has access via partenaire relation (is responsable_marque or admin)
        OR (dr.related_partenaire_id IS NOT NULL AND (p_part.user_id = auth.uid() OR is_admin()))
        -- User has access via contact relation (has access to contact's etablissement)
        OR (dr.related_contact_id IS NOT NULL AND p_contact.user_id = auth.uid())
      )
  )
$$;


--
-- Name: FUNCTION document_has_entity_relation(doc_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_has_entity_relation(doc_id uuid) IS 'Checks if the current user has access to a document via entity relations.
User must have access to at least one of the related entities:
- Etablissements: User must be assigned (commercial, chef_projet, or csm)
- Taches: User must be responsable OR have access to the task''s etablissement
- Groupes: User must have access to at least one etablissement in the group
- Partenaires: User must be responsable_marque or admin
- Contacts: User must have access to the contact''s etablissement
Admins always have access.';


--
-- Name: emit_platform_client_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_platform_client_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_type text;
  v_payload jsonb;
BEGIN
  IF (TG_OP = 'INSERT') THEN
    IF NEW.statut = 'Production'::statut_etablissement THEN
      v_event_type := 'client.created';
    ELSE
      RETURN NEW;
    END IF;
  ELSIF (TG_OP = 'UPDATE') THEN
    IF OLD.statut IS DISTINCT FROM NEW.statut AND NEW.statut = 'Production'::statut_etablissement THEN
      v_event_type := 'client.created';
    ELSIF OLD.statut IS DISTINCT FROM NEW.statut AND NEW.statut = 'Suspendu'::statut_etablissement THEN
      v_event_type := 'client.suspended';
    ELSIF NEW.statut = 'Production'::statut_etablissement THEN
      v_event_type := 'client.updated';
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  v_payload := jsonb_build_object(
    'nom', NEW.nom,
    'siren', NEW.siren_client,
    'ville', NEW.ville,
    'statut', NEW.statut
  );

  INSERT INTO public.platform_events (event_type, etablissement_id, payload, target)
  VALUES (v_event_type, NEW.id, v_payload, 'all');

  RETURN NEW;
END $$;


--
-- Name: encrypt_email_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encrypt_email_password(password_to_encrypt text, encryption_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- Only allow service_role to call this function
  IF current_setting('request.jwt.claims', true)::json->>'role' IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Access denied: this function requires service_role privileges';
  END IF;

  RETURN encode(
    extensions.pgp_sym_encrypt(password_to_encrypt, encryption_key),
    'base64'
  );
END;
$$;


--
-- Name: encrypt_social_secret(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encrypt_social_secret(plaintext text, encryption_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ciphertext bytea;
BEGIN
  IF plaintext IS NULL OR plaintext = '' THEN RETURN NULL; END IF;
  ciphertext := extensions.pgp_sym_encrypt(plaintext, encryption_key);
  RETURN encode(ciphertext, 'base64');
END; $$;


--
-- Name: enforce_2fa_for_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_2fa_for_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.role = 'admin' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.user_id = NEW.user_id
        AND (
          p.two_factor_enabled = true
          OR (
            p.is_sandbox = true
            AND lower(p.email) = 'test-admin@exemple.fr'
          )
        )
    ) THEN
      RAISE EXCEPTION 'Cannot assign admin role without 2FA enabled';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_admin_2fa_requirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_admin_2fa_requirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_is_admin BOOLEAN;
  old_user_is_admin BOOLEAN;
BEGIN
  -- Check if user has admin role now
  SELECT EXISTS(
    SELECT 1 FROM public.user_roles 
    WHERE user_id = NEW.user_id AND role = 'admin'
  ) INTO user_is_admin;
  
  -- Check if user had admin role before (for role changes)
  SELECT EXISTS(
    SELECT 1 FROM public.user_roles 
    WHERE user_id = OLD.user_id AND role = 'admin'
  ) INTO old_user_is_admin;
  
  -- If user was just promoted to admin role
  IF user_is_admin AND NOT old_user_is_admin THEN
    -- Log the admin role assignment
    INSERT INTO public.security_logs (
      log_type,
      user_id,
      user_email,
      risk_level,
      metadata
    ) VALUES (
      'admin_role_assigned',
      NEW.user_id,
      NEW.email,
      'critical',
      jsonb_build_object(
        'promoted_by', auth.uid(),
        'timestamp', now(),
        'has_2fa', NEW.two_factor_enabled,
        'security_requirement', 'immediate_2fa_setup_required'
      )
    );
    
    -- If 2FA is not enabled, prevent admin access until setup
    IF NOT NEW.two_factor_enabled THEN
      RAISE WARNING 'Admin role assigned without 2FA - user must enable 2FA before accessing admin functions';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: enforce_admin_2fa_setup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_admin_2fa_setup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_is_admin BOOLEAN;
BEGIN
  -- Check if user has admin role in user_roles table
  SELECT EXISTS(
    SELECT 1 FROM public.user_roles 
    WHERE user_id = NEW.user_id AND role = 'admin'
  ) INTO user_is_admin;
  
  -- If user is admin, check 2FA requirement
  IF user_is_admin THEN
    -- Log the admin status
    INSERT INTO public.security_logs (
      log_type,
      user_id,
      user_email,
      risk_level,
      metadata
    ) VALUES (
      'admin_profile_check',
      NEW.user_id,
      NEW.email,
      CASE WHEN NEW.two_factor_enabled THEN 'low' ELSE 'critical' END,
      jsonb_build_object(
        'checked_by', auth.uid(),
        'timestamp', now(),
        'has_2fa', NEW.two_factor_enabled,
        'security_requirement', CASE 
          WHEN NOT NEW.two_factor_enabled THEN 'immediate_2fa_setup_required'
          ELSE 'compliant'
        END
      )
    );
    
    -- Warn if 2FA not enabled
    IF NOT NEW.two_factor_enabled THEN
      RAISE WARNING 'Admin user without 2FA - must enable 2FA before accessing admin functions';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: enforce_pulse_member_visibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_pulse_member_visibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_member public.profiles%ROWTYPE;
  existing_member record;
  conv_type text;
BEGIN
  SELECT * INTO new_member FROM public.profiles WHERE id = NEW.user_id;

  IF new_member.id IS NULL THEN
    RAISE EXCEPTION 'Profil Pulse introuvable';
  END IF;

  IF new_member.actif IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Ce profil est archivé et ne peut pas être ajouté à Pulse';
  END IF;

  SELECT metadata->>'type' INTO conv_type
  FROM public.pulse_conversations
  WHERE id = NEW.conversation_id;

  IF conv_type LIKE 'team_%' AND COALESCE(new_member.is_sandbox, false) THEN
    RAISE EXCEPTION 'Les comptes test ne peuvent pas être ajoutés aux conversations équipe';
  END IF;

  IF conv_type = 'dm' THEN
    FOR existing_member IN
      SELECT p.id, p.actif, COALESCE(p.is_sandbox, false) AS is_sandbox
      FROM public.pulse_conversation_members pcm
      JOIN public.profiles p ON p.id = pcm.user_id
      WHERE pcm.conversation_id = NEW.conversation_id
        AND pcm.user_id <> NEW.user_id
    LOOP
      IF existing_member.actif IS DISTINCT FROM true THEN
        RAISE EXCEPTION 'Ce message direct contient un profil archivé';
      END IF;

      IF existing_member.is_sandbox IS DISTINCT FROM COALESCE(new_member.is_sandbox, false) THEN
        RAISE EXCEPTION 'Les messages directs Pulse ne peuvent pas mélanger comptes test et comptes réels';
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_single_test_sandbox_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_test_sandbox_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = NEW.user_id
      AND p.is_sandbox = true
      AND lower(p.email) LIKE 'test-%@exemple.fr'
  ) THEN
    DELETE FROM public.user_roles ur
    WHERE ur.user_id = NEW.user_id
      AND ur.role IS DISTINCT FROM NEW.role;
  END IF;

  RETURN NEW;
END;
$$;


