-- Name: ensure_document_has_folder(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_document_has_folder() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  etudes_folder_id uuid := 'e3763f37-9f4d-49d0-8edc-66296122b280';
  autres_folder_id uuid := '72008f57-d6e8-42e7-a950-6894525343ee';
BEGIN
  -- If folder_id is already set, do nothing
  IF NEW.folder_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  
  -- Route "Etude médico-éco" documents to the studies folder
  IF NEW.name ILIKE 'Etude %' OR NEW.name ILIKE 'Étude %' THEN
    NEW.folder_id := etudes_folder_id;
    RETURN NEW;
  END IF;
  
  -- Default: route to "Autres documents"
  NEW.folder_id := autres_folder_id;
  RETURN NEW;
END;
$$;


