--
-- Name: evaluate_csm_playbooks_for_etablissement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_csm_playbooks_for_etablissement(_etablissement_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_playbook record;
  v_metrics record;
  v_triggered_count integer := 0;
  v_existing_recent integer;
  v_trigger jsonb;
  v_threshold numeric;
  v_operator text;
  v_field text;
  v_value numeric;
  v_should_trigger boolean;
  v_first_step record;
BEGIN
  -- Récupère les métriques actuelles
  SELECT health_score, health_status INTO v_metrics
  FROM public.customer_health_metrics
  WHERE etablissement_id = _etablissement_id
  ORDER BY calculated_at DESC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- Itère sur chaque playbook actif
  FOR v_playbook IN
    SELECT * FROM public.csm_playbooks
    WHERE is_active = true
    ORDER BY priority ASC
  LOOP
    v_trigger := v_playbook.trigger_config;
    v_should_trigger := false;

    -- Évaluation des conditions
    v_field := COALESCE(v_trigger->>'field', 'health_score');
    v_operator := COALESCE(v_trigger->>'operator', 'lt');
    v_threshold := (v_trigger->>'threshold')::numeric;

    IF v_field = 'health_score' THEN
      v_value := v_metrics.health_score;
    ELSIF v_field = 'health_status' THEN
      -- Comparaison string : status_in = liste autorisée
      IF v_trigger ? 'status_in' THEN
        v_should_trigger := (
          SELECT v_metrics.health_status = ANY(
            ARRAY(SELECT jsonb_array_elements_text(v_trigger->'status_in'))
          )
        );
      END IF;
    END IF;

    IF v_field = 'health_score' AND v_threshold IS NOT NULL THEN
      v_should_trigger := CASE v_operator
        WHEN 'lt' THEN v_value < v_threshold
        WHEN 'lte' THEN v_value <= v_threshold
        WHEN 'gt' THEN v_value > v_threshold
        WHEN 'gte' THEN v_value >= v_threshold
        WHEN 'eq' THEN v_value = v_threshold
        ELSE false
      END;
    END IF;

    -- Filtrage additionnel par status_in
    IF v_should_trigger AND v_trigger ? 'status_in' AND v_field = 'health_score' THEN
      v_should_trigger := (
        SELECT v_metrics.health_status = ANY(
          ARRAY(SELECT jsonb_array_elements_text(v_trigger->'status_in'))
        )
      );
    END IF;

    IF NOT v_should_trigger THEN
      CONTINUE;
    END IF;

    -- Vérifie cooldown : pas d'exécution récente du même playbook pour cet établissement
    SELECT COUNT(*) INTO v_existing_recent
    FROM public.csm_playbook_executions
    WHERE playbook_id = v_playbook.id
      AND etablissement_id = _etablissement_id
      AND started_at > now() - (v_playbook.cooldown_days || ' days')::interval
      AND status NOT IN ('failed','cancelled');

    IF v_existing_recent > 0 THEN
      CONTINUE;
    END IF;

    -- Récupère la première étape
    SELECT * INTO v_first_step
    FROM public.csm_playbook_steps
    WHERE playbook_id = v_playbook.id
    ORDER BY step_order ASC
    LIMIT 1;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    -- Crée l'exécution
    INSERT INTO public.csm_playbook_executions (
      playbook_id, etablissement_id, status,
      current_step_order, next_action_at, trigger_context
    ) VALUES (
      v_playbook.id, _etablissement_id, 'pending',
      v_first_step.step_order,
      now() + (v_first_step.delay_days || ' days')::interval,
      jsonb_build_object(
        'health_score', v_metrics.health_score,
        'health_status', v_metrics.health_status,
        'triggered_at', now()
      )
    );

    v_triggered_count := v_triggered_count + 1;
  END LOOP;

  RETURN v_triggered_count;
END;
$$;


--
-- Name: evaluate_jarvis_condition(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_jarvis_condition(p_condition_type text, p_user_id uuid, p_params jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(condition_met boolean, current_value numeric, threshold_value numeric, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile_id UUID;
BEGIN
  -- Get profile_id from user_id
  SELECT id INTO v_profile_id FROM profiles WHERE user_id = p_user_id;
  
  -- Evaluate based on condition type (predefined templates only)
  CASE p_condition_type
    
    -- TREASURY CONDITIONS
    WHEN 'treasury_below_threshold' THEN
      RETURN QUERY
      SELECT 
        COALESCE(SUM(CASE WHEN type_operation = 'credit' THEN montant ELSE -montant END), 0) < COALESCE((p_params->>'threshold')::NUMERIC, 10000),
        COALESCE(SUM(CASE WHEN type_operation = 'credit' THEN montant ELSE -montant END), 0)::NUMERIC,
        COALESCE((p_params->>'threshold')::NUMERIC, 10000),
        jsonb_build_object('metric', 'current_balance')
      FROM tresorerie_operations_bancaires
      WHERE is_reconciled = true;
      
    WHEN 'monthly_revenue_above' THEN
      RETURN QUERY
      SELECT 
        COALESCE(SUM(montant_ttc), 0) > COALESCE((p_params->>'threshold')::NUMERIC, 50000),
        COALESCE(SUM(montant_ttc), 0)::NUMERIC,
        COALESCE((p_params->>'threshold')::NUMERIC, 50000),
        jsonb_build_object('metric', 'monthly_revenue', 'month', to_char(now(), 'YYYY-MM'))
      FROM tresorerie_revenus
      WHERE date_trunc('month', date_revenu) = date_trunc('month', now());
    
    -- CRM CONDITIONS  
    WHEN 'prospect_inactive_days' THEN
      RETURN QUERY
      SELECT 
        COUNT(*) > 0,
        COUNT(*)::NUMERIC,
        COALESCE((p_params->>'days')::NUMERIC, 7),
        jsonb_build_object('inactive_prospects', 
          (SELECT jsonb_agg(jsonb_build_object('id', id, 'nom', nom)) 
           FROM etablissements 
           WHERE statut = 'Prospect'
             AND (commercial_id = v_profile_id OR v_profile_id IS NULL)
             AND updated_at < now() - (COALESCE((p_params->>'days')::INTEGER, 7) || ' days')::INTERVAL
           LIMIT 5))
      FROM etablissements
      WHERE statut = 'Prospect'
        AND (commercial_id = v_profile_id OR v_profile_id IS NULL)
        AND updated_at < now() - (COALESCE((p_params->>'days')::INTEGER, 7) || ' days')::INTERVAL;
    
    WHEN 'overdue_tasks_count' THEN
      RETURN QUERY
      SELECT 
        COUNT(*) >= COALESCE((p_params->>'min_count')::INTEGER, 1),
        COUNT(*)::NUMERIC,
        COALESCE((p_params->>'min_count')::NUMERIC, 1),
        jsonb_build_object('overdue_tasks',
          (SELECT jsonb_agg(jsonb_build_object('id', id, 'titre', titre, 'echeance', echeance))
           FROM taches
           WHERE assignee_id = v_profile_id
             AND statut IN ('A faire', 'En cours')
             AND echeance < now()
           LIMIT 5))
      FROM taches
      WHERE assignee_id = v_profile_id
        AND statut IN ('A faire', 'En cours')
        AND echeance < now();
    
    -- INVOICE CONDITIONS
    WHEN 'unpaid_invoices_over_days' THEN
      RETURN QUERY
      SELECT 
        COUNT(*) > 0,
        COUNT(*)::NUMERIC,
        COALESCE((p_params->>'days')::NUMERIC, 30),
        jsonb_build_object('unpaid_invoices',
          (SELECT jsonb_agg(jsonb_build_object('id', id, 'numero', numero, 'montant', montant_ttc, 'date_emission', date_emission))
           FROM factures
           WHERE statut IN ('envoyee', 'rappel')
             AND date_emission < now() - (COALESCE((p_params->>'days')::INTEGER, 30) || ' days')::INTERVAL
           LIMIT 5))
      FROM factures
      WHERE statut IN ('envoyee', 'rappel')
        AND date_emission < now() - (COALESCE((p_params->>'days')::INTEGER, 30) || ' days')::INTERVAL;
    
    -- SUPPORT CONDITIONS
    WHEN 'open_tickets_count' THEN
      RETURN QUERY
      SELECT 
        COUNT(*) >= COALESCE((p_params->>'min_count')::INTEGER, 5),
        COUNT(*)::NUMERIC,
        COALESCE((p_params->>'min_count')::NUMERIC, 5),
        jsonb_build_object('open_tickets_count', COUNT(*))
      FROM support_tickets
      WHERE statut NOT IN ('Résolu', 'Fermé');
    
    -- EMAIL CONDITIONS
    WHEN 'unread_emails_count' THEN
      RETURN QUERY
      SELECT 
        COUNT(*) >= COALESCE((p_params->>'min_count')::INTEGER, 10),
        COUNT(*)::NUMERIC,
        COALESCE((p_params->>'min_count')::NUMERIC, 10),
        jsonb_build_object('unread_count', COUNT(*))
      FROM email_threads
      WHERE unread_count > 0;
      
    -- SATISFACTION CONDITIONS
    WHEN 'low_satisfaction_score' THEN
      RETURN QUERY
      SELECT 
        AVG(note_globale) < COALESCE((p_params->>'threshold')::NUMERIC, 3),
        COALESCE(AVG(note_globale), 0)::NUMERIC,
        COALESCE((p_params->>'threshold')::NUMERIC, 3),
        jsonb_build_object('avg_score', COALESCE(AVG(note_globale), 0), 'sample_size', COUNT(*))
      FROM enquetes_satisfaction
      WHERE created_at > now() - INTERVAL '30 days';
    
    -- DEFAULT: condition not found
    ELSE
      RETURN QUERY SELECT FALSE, 0::NUMERIC, 0::NUMERIC, jsonb_build_object('error', 'Unknown condition type: ' || p_condition_type);
      
  END CASE;
END;
$$;


--
-- Name: FUNCTION evaluate_jarvis_condition(p_condition_type text, p_user_id uuid, p_params jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.evaluate_jarvis_condition(p_condition_type text, p_user_id uuid, p_params jsonb) IS 'Evaluates predefined business conditions for Jarvis autopilot rules.
Supported condition types:
- treasury_below_threshold (params: threshold)
- monthly_revenue_above (params: threshold)
- prospect_inactive_days (params: days)
- overdue_tasks_count (params: min_count)
- unpaid_invoices_over_days (params: days)
- open_tickets_count (params: min_count)
- unread_emails_count (params: min_count)
- low_satisfaction_score (params: threshold)';


--
-- Name: execute_readonly_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_readonly_query(query_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  result jsonb;
  normalized_query text;
BEGIN
  -- Normalize: strip leading/trailing whitespace and uppercase for checks
  normalized_query := regexp_replace(query_text, '^\s+|\s+$', '', 'g');
  normalized_query := UPPER(normalized_query);

  -- Must start with SELECT or WITH
  IF NOT (normalized_query ~ '^(SELECT|WITH)\s') THEN
    RAISE EXCEPTION 'Only SELECT queries are allowed. Query starts with: "%"',
      substring(normalized_query from 1 for 50);
  END IF;

  -- Block write/DDL operations (word-boundary match)
  IF normalized_query ~ '\m(INSERT|UPDATE|DELETE|DROP|TRUNCATE|ALTER|CREATE|GRANT|REVOKE|MERGE|CALL|VACUUM|ANALYZE|REINDEX|REFRESH|LISTEN|NOTIFY|LOCK|SECURITY\s+DEFINER)\M' THEN
    RAISE EXCEPTION 'Query contains forbidden operations';
  END IF;

  -- Block dangerous PostgreSQL constructs (data exfiltration, filesystem, DoS, network)
  IF normalized_query ~ '\m(COPY|PG_READ_FILE|PG_READ_BINARY_FILE|PG_STAT_FILE|PG_LS_DIR|PG_SLEEP|LO_EXPORT|LO_IMPORT|DBLINK|PG_TERMINATE_BACKEND|PG_CANCEL_BACKEND|SET_CONFIG|CURRENT_SETTING|PG_AUTHID|PG_SHADOW|PG_USER_MAPPINGS)\M' THEN
    RAISE EXCEPTION 'Query contains forbidden constructs';
  END IF;

  -- Block multi-statement injection
  IF position(';' in regexp_replace(query_text, ';\s*$', '', 'g')) > 0 THEN
    RAISE EXCEPTION 'Multi-statement queries are not allowed';
  END IF;

  -- Enforce read-only and short timeout for this execution
  PERFORM set_config('statement_timeout', '5s', true);
  PERFORM set_config('transaction_read_only', 'on', true);

  EXECUTE format('SELECT jsonb_agg(row_to_json(t)) FROM (%s) t', query_text) INTO result;

  RETURN COALESCE(result, '[]'::jsonb);

EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Query execution failed: %', SQLERRM;
END;
$_$;


--
-- Name: extract_email_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_email_domain(email_address text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF email_address IS NULL OR email_address !~ '@' THEN
    RETURN NULL;
  END IF;
  
  RETURN lower(split_part(email_address, '@', 2));
END;
$$;


--
-- Name: extract_topic_uuid(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_topic_uuid(_topic text, _prefix text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  _suffix text;
BEGIN
  IF _topic IS NULL OR _topic NOT LIKE (_prefix || '%') THEN
    RETURN NULL;
  END IF;
  _suffix := substring(_topic FROM (length(_prefix) + 1));
  _suffix := split_part(split_part(_suffix, ':', 1), '/', 1);
  BEGIN
    RETURN _suffix::uuid;
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
END;
$$;


