-- Name: fix_malformed_utf8(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fix_malformed_utf8(input_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN regexp_replace(
    regexp_replace(
      regexp_replace(input_text, 'Ã©', 'é', 'g'),
      'Ã¨', 'è', 'g'
    ),
    'Ã ', 'à', 'g'
  );
END;
$$;


--
-- Name: fix_mojibake(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fix_mojibake(input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  r text := input;
BEGIN
  IF r IS NULL THEN RETURN NULL; END IF;
  r := replace(r, 'â€™', '''');
  r := replace(r, 'â€˜', '''');
  r := replace(r, 'â€œ', '"');
  r := replace(r, 'â€¦', '…');
  r := replace(r, 'Ã©', 'é');
  r := replace(r, 'Ã¨', 'è');
  r := replace(r, 'Ãª', 'ê');
  r := replace(r, 'Ã«', 'ë');
  r := replace(r, 'Ã ', 'à');
  r := replace(r, 'Ã¢', 'â');
  r := replace(r, 'Ã¤', 'ä');
  r := replace(r, 'Ã®', 'î');
  r := replace(r, 'Ã¯', 'ï');
  r := replace(r, 'Ã´', 'ô');
  r := replace(r, 'Ã¶', 'ö');
  r := replace(r, 'Ã»', 'û');
  r := replace(r, 'Ã¼', 'ü');
  r := replace(r, 'Ã§', 'ç');
  r := replace(r, 'Ã‰', 'É');
  r := replace(r, 'Ãˆ', 'È');
  r := replace(r, 'ÃŠ', 'Ê');
  r := replace(r, 'Ã€', 'À');
  r := replace(r, 'Ã‚', 'Â');
  r := replace(r, 'ÃŽ', 'Î');
  r := replace(r, 'Ã”', 'Ô');
  r := replace(r, 'Ã›', 'Û');
  r := replace(r, 'Ã‡', 'Ç');
  r := replace(r, 'Â«', '«');
  r := replace(r, 'Â»', '»');
  r := replace(r, 'Â ', ' ');
  RETURN r;
END;
$$;


--
-- Name: fix_thread_counters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fix_thread_counters() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  fixed_count integer := 0;
BEGIN
  -- Update threads where counts or dates are incorrect
  WITH thread_stats AS (
    SELECT 
      et.id,
      COALESCE(COUNT(em.id), 0) AS real_count,
      MAX(em.sent_date) AS real_last_date
    FROM email_threads et
    LEFT JOIN email_messages em ON em.thread_id = et.id
    GROUP BY et.id
  ),
  updated AS (
    UPDATE email_threads et
    SET 
      message_count = ts.real_count,
      last_message_date = COALESCE(ts.real_last_date, et.last_message_date),
      updated_at = now()
    FROM thread_stats ts
    WHERE et.id = ts.id
      AND (
        et.message_count != ts.real_count 
        OR (ts.real_last_date IS NOT NULL AND et.last_message_date != ts.real_last_date)
      )
    RETURNING et.id
  )
  SELECT COUNT(*) INTO fixed_count FROM updated;
  
  RETURN fixed_count;
END;
$$;


--
-- Name: FUNCTION fix_thread_counters(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fix_thread_counters() IS 'Recalculates and fixes message_count and last_message_date for all email threads based on actual email_messages data';


--
-- Name: generate_avoir_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_avoir_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  year_prefix TEXT;
  next_number INTEGER;
  new_numero TEXT;
BEGIN
  year_prefix := 'AV-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-';
  
  SELECT COALESCE(MAX(CAST(SUBSTRING(numero FROM LENGTH(year_prefix) + 1) AS INTEGER)), 0) + 1
  INTO next_number
  FROM avoirs
  WHERE numero LIKE year_prefix || '%';
  
  new_numero := year_prefix || LPAD(next_number::TEXT, 4, '0');
  
  RETURN new_numero;
END;
$$;


--
-- Name: generate_contrat_numero(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_contrat_numero() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  year_suffix TEXT;
  next_num INTEGER;
BEGIN
  year_suffix := TO_CHAR(NOW(), 'YY');
  
  SELECT COALESCE(MAX(CAST(SUBSTRING(numero FROM 'CT-' || year_suffix || '-(\d+)') AS INTEGER)), 0) + 1
  INTO next_num
  FROM public.contrats
  WHERE numero LIKE 'CT-' || year_suffix || '-%';
  
  NEW.numero := 'CT-' || year_suffix || '-' || LPAD(next_num::TEXT, 4, '0');
  
  RETURN NEW;
END;
$$;


--
-- Name: generate_devis_numero(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_devis_numero() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  year_suffix TEXT;
  next_num INTEGER;
BEGIN
  year_suffix := TO_CHAR(NOW(), 'YY');
  
  SELECT COALESCE(MAX(CAST(SUBSTRING(numero FROM 'DEV-' || year_suffix || '-(\d+)') AS INTEGER)), 0) + 1
  INTO next_num
  FROM public.devis
  WHERE numero LIKE 'DEV-' || year_suffix || '-%';
  
  NEW.numero := 'DEV-' || year_suffix || '-' || LPAD(next_num::TEXT, 5, '0');
  
  RETURN NEW;
END;
$$;


--
-- Name: generate_etablissement_qr_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_etablissement_qr_token(etablissement_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  new_token TEXT;
BEGIN
  -- Générer un token aléatoire sécurisé
  new_token := encode(gen_random_bytes(32), 'base64');
  new_token := replace(new_token, '/', '_');
  new_token := replace(new_token, '+', '-');
  new_token := replace(new_token, '=', '');
  
  -- Mettre à jour l'établissement
  UPDATE public.etablissements 
  SET 
    qr_access_token = new_token,
    qr_access_expires_at = NOW() + INTERVAL '1 year'
  WHERE id = etablissement_id;
  
  RETURN new_token;
END;
$$;


--
-- Name: generate_etablissement_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_etablissement_slug() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  NEW.slug := lower(
    regexp_replace(
      regexp_replace(
        unaccent(NEW.nom || '-' || NEW.ville),
        '[^a-zA-Z0-9\s-]', '', 'g'
      ),
      '\s+', '-', 'g'
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: generate_facture_numero(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_facture_numero() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  year_suffix TEXT;
  next_num INTEGER;
BEGIN
  year_suffix := TO_CHAR(NOW(), 'YY');
  
  SELECT COALESCE(MAX(CAST(SUBSTRING(numero FROM 'FAC-' || year_suffix || '-(\d+)') AS INTEGER)), 0) + 1
  INTO next_num
  FROM public.factures
  WHERE numero LIKE 'FAC-' || year_suffix || '-%';
  
  NEW.numero := 'FAC-' || year_suffix || '-' || LPAD(next_num::TEXT, 5, '0');
  
  RETURN NEW;
END;
$$;


--
-- Name: generate_form_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_form_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.slug IS NULL THEN
    NEW.slug := lower(regexp_replace(NEW.title, '[^a-zA-Z0-9]+', '-', 'g')) || '-' || substr(NEW.id::text, 1, 8);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: generate_room_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_room_code() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT lower(substr(md5(random()::text), 1, 4) || '-' || 
               substr(md5(random()::text), 1, 4) || '-' || 
               substr(md5(random()::text), 1, 4))
$$;


--
-- Name: generate_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_slug() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
BEGIN
  -- Generate base slug from name
  base_slug := lower(regexp_replace(NEW.nom, '[^a-zA-Z0-9]+', '-', 'g'));
  base_slug := regexp_replace(base_slug, '^-+|-+$', '', 'g');
  
  -- Check for uniqueness
  final_slug := base_slug;
  WHILE EXISTS (SELECT 1 FROM etablissements WHERE slug = final_slug AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)) LOOP
    counter := counter + 1;
    final_slug := base_slug || '-' || counter;
  END LOOP;
  
  NEW.slug := final_slug;
  RETURN NEW;
END;
$_$;


--
-- Name: generate_slug_from_nom(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_slug_from_nom() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    NEW.slug := lower(
      regexp_replace(
        regexp_replace(
          unaccent(NEW.nom), 
          '[^a-zA-Z0-9]+', 
          '-', 
          'g'
        ),
        '^-+|-+$',
        '',
        'g'
      )
    );
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: generate_ticket_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_ticket_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_year TEXT;
  v_count INTEGER;
BEGIN
  v_year := to_char(now(), 'YYYY');
  
  SELECT COUNT(*) + 1 INTO v_count
  FROM public.support_tickets
  WHERE numero_ticket LIKE 'SUP-' || v_year || '-%';
  
  NEW.numero_ticket := 'SUP-' || v_year || '-' || LPAD(v_count::TEXT, 4, '0');
  RETURN NEW;
END;
$$;


--
-- Name: generate_unique_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_unique_slug() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
BEGIN
  base_slug := lower(regexp_replace(NEW.nom, '[^a-zA-Z0-9]+', '-', 'g'));
  base_slug := regexp_replace(base_slug, '^-+|-+$', '', 'g');
  final_slug := base_slug;
  WHILE EXISTS (SELECT 1 FROM etablissements WHERE slug = final_slug AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)) LOOP
    counter := counter + 1;
    final_slug := base_slug || '-' || counter;
  END LOOP;
  NEW.slug := final_slug;
  RETURN NEW;
END;
$_$;


--
-- Name: get_accessible_calendar_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_calendar_ids(p_user_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Calendriers dont l'utilisateur est propriétaire
  SELECT id FROM calendars WHERE owner_id = p_user_id
  UNION
  -- Calendriers partagés avec l'utilisateur
  SELECT calendar_id FROM calendar_shares WHERE shared_with_user_id = p_user_id
$$;


--
-- Name: get_accessible_visio_room_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_visio_room_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT DISTINCT pvr.id FROM pulse_visio_rooms pvr
  WHERE pvr.created_by = get_current_profile_id()
     OR pvr.conversation_id IN (SELECT pcm.conversation_id FROM pulse_conversation_members pcm WHERE pcm.user_id = get_current_profile_id())
$$;


--
-- Name: get_active_profiles_with_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_profiles_with_roles() RETURNS TABLE(id uuid, user_id uuid, prenom text, nom text, email text, actif boolean, created_at timestamp with time zone, updated_at timestamp with time zone, role text, telephone text, fonction text, date_embauche date, type_contrat text, salaire_brut numeric, avatar_url text, linkedin_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    p.id,
    p.user_id,
    p.prenom,
    p.nom,
    p.email,
    p.actif,
    p.created_at,
    p.updated_at,
    COALESCE(ur.role::text, 'commercial') as role,
    p.telephone,
    p.fonction,
    p.date_embauche,
    p.type_contrat,
    p.salaire_brut,
    p.avatar_url,
    p.linkedin_url
  FROM public.profiles p
  LEFT JOIN public.user_roles ur ON ur.user_id = p.user_id
  WHERE p.actif = true
  ORDER BY p.nom, p.prenom;
$$;


--
-- Name: get_activity_feed_stats(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_activity_feed_stats(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_today_start timestamptz := date_trunc('day', now());
  v_week_start timestamptz := date_trunc('week', now());
  v_month_start timestamptz := date_trunc('month', now());
  v_today int := 0;
  v_week int := 0;
  v_month int := 0;
  v_by_type jsonb := '{}'::jsonb;
  v_by_user jsonb := '[]'::jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT COUNT(*) FILTER (WHERE occurred_at >= v_today_start),
         COUNT(*) FILTER (WHERE occurred_at >= v_week_start),
         COUNT(*)
  INTO v_today, v_week, v_month
  FROM (
    SELECT 'interaction'::text as type, COALESCE(ca.activity_date, ca.created_at) as occurred_at, ca.created_by as actor_user_id
      FROM customer_activities ca
      WHERE COALESCE(ca.activity_date, ca.created_at) >= v_month_start
    UNION ALL SELECT 'tache', created_at, created_by FROM taches WHERE created_at >= v_month_start AND etablissement_id IS NOT NULL
    UNION ALL SELECT 'calendar', created_at, created_by FROM calendar_events WHERE created_at >= v_month_start
    UNION ALL SELECT 'email', COALESCE(em.received_date, em.sent_date, em.created_at), NULL::uuid
      FROM email_messages em JOIN email_threads et ON et.id = em.thread_id
      WHERE COALESCE(em.received_date, em.sent_date, em.created_at) >= v_month_start
        AND COALESCE(em.is_sent,false)=false AND COALESCE(et.is_deleted,false)=false AND COALESCE(et.is_spam,false)=false
    UNION ALL SELECT 'devis', created_at, created_by FROM devis WHERE created_at >= v_month_start
    UNION ALL SELECT 'facture', created_at, created_by FROM factures WHERE created_at >= v_month_start
    UNION ALL SELECT 'signature', COALESCE(completed_at, created_at), created_by FROM signature_requests WHERE COALESCE(completed_at, created_at) >= v_month_start
    UNION ALL SELECT 'workflow', COALESCE(finished_at, started_at), NULL::uuid FROM workflow_runs WHERE COALESCE(finished_at, started_at) >= v_month_start
  ) z;

  SELECT COALESCE(jsonb_object_agg(type, cnt), '{}'::jsonb) INTO v_by_type FROM (
    SELECT type, COUNT(*) cnt FROM (
      SELECT 'interaction'::text as type, COALESCE(ca.activity_date, ca.created_at) as occurred_at
        FROM customer_activities ca
        WHERE COALESCE(ca.activity_date, ca.created_at) >= v_week_start
      UNION ALL SELECT 'tache', created_at FROM taches WHERE created_at >= v_week_start AND etablissement_id IS NOT NULL
      UNION ALL SELECT 'calendar', created_at FROM calendar_events WHERE created_at >= v_week_start
      UNION ALL SELECT 'email', COALESCE(em.received_date, em.sent_date, em.created_at)
        FROM email_messages em JOIN email_threads et ON et.id = em.thread_id
        WHERE COALESCE(em.received_date, em.sent_date, em.created_at) >= v_week_start
          AND COALESCE(em.is_sent,false)=false AND COALESCE(et.is_deleted,false)=false AND COALESCE(et.is_spam,false)=false
      UNION ALL SELECT 'devis', created_at FROM devis WHERE created_at >= v_week_start
      UNION ALL SELECT 'facture', created_at FROM factures WHERE created_at >= v_week_start
      UNION ALL SELECT 'signature', COALESCE(completed_at, created_at) FROM signature_requests WHERE COALESCE(completed_at, created_at) >= v_week_start
      UNION ALL SELECT 'workflow', COALESCE(finished_at, started_at) FROM workflow_runs WHERE COALESCE(finished_at, started_at) >= v_week_start
    ) z GROUP BY type
  ) tt;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id', user_id, 'name', actor_name, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_by_user
  FROM (
    SELECT actor_user_id as user_id,
           COALESCE(NULLIF(TRIM(p.prenom||' '||p.nom),''), 'Système') AS actor_name,
           COUNT(*) cnt
    FROM (
      SELECT ca.created_by as actor_user_id
        FROM customer_activities ca
        WHERE COALESCE(ca.activity_date, ca.created_at) >= v_week_start AND ca.created_by IS NOT NULL
      UNION ALL SELECT created_by FROM taches WHERE created_at >= v_week_start AND etablissement_id IS NOT NULL AND created_by IS NOT NULL
      UNION ALL SELECT created_by FROM calendar_events WHERE created_at >= v_week_start AND created_by IS NOT NULL
      UNION ALL SELECT created_by FROM devis WHERE created_at >= v_week_start AND created_by IS NOT NULL
      UNION ALL SELECT created_by FROM factures WHERE created_at >= v_week_start AND created_by IS NOT NULL
      UNION ALL SELECT created_by FROM signature_requests WHERE COALESCE(completed_at, created_at) >= v_week_start AND created_by IS NOT NULL
    ) acts
    LEFT JOIN profiles p ON p.user_id = acts.actor_user_id
    GROUP BY actor_user_id, p.prenom, p.nom
    ORDER BY cnt DESC
    LIMIT 5
  ) top;

  RETURN jsonb_build_object(
    'today', v_today,
    'week', v_week,
    'month', v_month,
    'by_type', v_by_type,
    'by_user', v_by_user
  );
END;
$$;


--
-- Name: get_admin_2fa_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_2fa_status() RETURNS TABLE(admin_user_id uuid, admin_email text, has_2fa boolean, risk_level text, action_required text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.user_id,
    p.email,
    p.two_factor_enabled,
    CASE 
      WHEN p.two_factor_enabled THEN 'low'
      ELSE 'critical'
    END::text as risk_level,
    CASE 
      WHEN p.two_factor_enabled THEN 'compliant'
      ELSE 'immediate_2fa_setup_required'
    END::text as action_required
  FROM public.profiles p
  JOIN public.user_roles ur ON ur.user_id = p.user_id
  WHERE ur.role = 'admin' AND p.actif = true
  ORDER BY p.two_factor_enabled ASC, p.email;
END;
$$;


--
-- Name: get_ai_usage_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_usage_stats(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  v_since timestamptz;
  v_today_start timestamptz;
  v_week_start timestamptz;
  v_month_start timestamptz;
  v_7days_ago timestamptz;
BEGIN
  v_since := now() - (p_days || ' days')::interval;
  v_today_start := date_trunc('day', now());
  v_week_start := date_trunc('week', now());
  v_month_start := date_trunc('month', now());
  v_7days_ago := now() - interval '7 days';

  SELECT jsonb_build_object(
    -- Global KPIs
    'totalCalls', count(*),
    'totalTokens', coalesce(sum(total_tokens), 0),
    'promptTokens', coalesce(sum(prompt_tokens), 0),
    'completionTokens', coalesce(sum(completion_tokens), 0),
    'estimatedCost', coalesce(sum(
      CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
      ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03
      END
    ), 0),
    'successRate', CASE WHEN count(*) > 0 
      THEN round((count(*) FILTER (WHERE success))::numeric / count(*) * 100, 1)
      ELSE 100 END,
    'avgProcessingTime', coalesce(round(avg(processing_duration_ms)), 0),
    'avgCostPerCall', CASE WHEN count(*) > 0 
      THEN coalesce(sum(
        CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
        ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03
        END
      ), 0) / count(*)
      ELSE 0 END,

    -- Per period
    'callsToday', count(*) FILTER (WHERE processed_at >= v_today_start),
    'callsThisWeek', count(*) FILTER (WHERE processed_at >= v_week_start),
    'callsThisMonth', count(*) FILTER (WHERE processed_at >= v_month_start),
    'tokensToday', coalesce(sum(total_tokens) FILTER (WHERE processed_at >= v_today_start), 0),
    'tokensThisWeek', coalesce(sum(total_tokens) FILTER (WHERE processed_at >= v_week_start), 0),
    'tokensThisMonth', coalesce(sum(total_tokens) FILTER (WHERE processed_at >= v_month_start), 0),
    'costToday', coalesce(sum(
      CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
      ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03 END
    ) FILTER (WHERE processed_at >= v_today_start), 0),
    'costThisWeek', coalesce(sum(
      CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
      ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03 END
    ) FILTER (WHERE processed_at >= v_week_start), 0),
    'costThisMonth', coalesce(sum(
      CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
      ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03 END
    ) FILTER (WHERE processed_at >= v_month_start), 0),

    -- By type
    'callsByType', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.cost DESC)
      FROM (
        SELECT 
          processing_type AS type,
          count(*) AS count,
          coalesce(sum(total_tokens), 0) AS tokens,
          CASE WHEN count(*) > 0 THEN round(avg(processing_duration_ms)) ELSE 0 END AS "avgDuration",
          coalesce(sum(
            CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
            ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03 END
          ), 0) AS cost,
          CASE WHEN count(*) > 0 THEN round((count(*) FILTER (WHERE success))::numeric / count(*) * 100, 1) ELSE 100 END AS "successRate"
        FROM ai_processing_log
        WHERE processed_at >= v_since
        GROUP BY processing_type
      ) t
    ), '[]'::jsonb),

    -- By model
    'callsByModel', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.cost DESC)
      FROM (
        SELECT 
          model_used AS model,
          count(*) AS count,
          coalesce(sum(total_tokens), 0) AS tokens,
          coalesce(sum(
            CASE WHEN estimated_cost IS NOT NULL AND estimated_cost > 0 THEN estimated_cost
            ELSE coalesce(prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(completion_tokens, 0)::numeric / 1000 * 0.03 END
          ), 0) AS cost
        FROM ai_processing_log
        WHERE processed_at >= v_since
        GROUP BY model_used
      ) t
    ), '[]'::jsonb),

    -- Daily stats (last 7 days)
    'dailyStats', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.date)
      FROM (
        SELECT 
          to_char(d::date, 'YYYY-MM-DD') AS date,
          coalesce(count(l.id), 0) AS calls,
          coalesce(sum(l.total_tokens), 0) AS tokens,
          coalesce(sum(l.prompt_tokens), 0) AS "promptTokens",
          coalesce(sum(l.completion_tokens), 0) AS "completionTokens",
          coalesce(sum(
            CASE WHEN l.estimated_cost IS NOT NULL AND l.estimated_cost > 0 THEN l.estimated_cost
            ELSE coalesce(l.prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(l.completion_tokens, 0)::numeric / 1000 * 0.03 END
          ), 0) AS cost
        FROM generate_series(v_7days_ago::date, now()::date, '1 day') d
        LEFT JOIN ai_processing_log l ON l.processed_at::date = d::date
        GROUP BY d::date
      ) t
    ), '[]'::jsonb),

    -- Top errors
    'topErrors', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb)
      FROM (
        SELECT 
          left(error_message, 150) AS message,
          count(*) AS count,
          max(processed_at)::text AS "lastSeen"
        FROM ai_processing_log
        WHERE NOT success AND error_message IS NOT NULL AND processed_at >= v_since
        GROUP BY left(error_message, 150)
        ORDER BY count(*) DESC
        LIMIT 10
      ) t
    ), '[]'::jsonb),

    -- Top thread consumers
    'topThreadConsumers', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb)
      FROM (
        SELECT 
          l.email_thread_id AS "threadId",
          coalesce(et.subject, 'Thread supprimé') AS subject,
          count(*) AS passages,
          coalesce(sum(l.total_tokens), 0) AS "totalTokens",
          coalesce(sum(
            CASE WHEN l.estimated_cost IS NOT NULL AND l.estimated_cost > 0 THEN l.estimated_cost
            ELSE coalesce(l.prompt_tokens, 0)::numeric / 1000 * 0.01 + coalesce(l.completion_tokens, 0)::numeric / 1000 * 0.03 END
          ), 0) AS "estimatedCost",
          max(l.processed_at)::text AS "lastProcessed"
        FROM ai_processing_log l
        LEFT JOIN email_threads et ON et.id = l.email_thread_id
        WHERE l.email_thread_id IS NOT NULL AND l.processed_at >= v_since
        GROUP BY l.email_thread_id, et.subject
        ORDER BY coalesce(sum(l.total_tokens), 0) DESC
        LIMIT 10
      ) t
    ), '[]'::jsonb),

    -- Recent logs (last 50)
    'recentLogs', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb)
      FROM (
        SELECT id, email_thread_id, processing_type, model_used, prompt_tokens, completion_tokens, 
               total_tokens, success, error_message, processing_duration_ms, processed_at, 
               processed_by, confidence_score, estimated_cost
        FROM ai_processing_log
        ORDER BY processed_at DESC
        LIMIT 50
      ) t
    ), '[]'::jsonb)
  )
  INTO result
  FROM ai_processing_log
  WHERE processed_at >= v_since;

  RETURN result;
END;
$$;


--
-- Name: get_analytics_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analytics_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb; v_total_etab bigint; v_high_risk bigint; v_medium_risk bigint;
  v_low_risk bigint; v_active_alerts bigint; v_pending_upsells bigint;
  v_upsell_potential numeric; v_forecasted_ca numeric; v_realized_ca numeric; v_avg_churn numeric;
BEGIN
  IF NOT (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'direction'::app_role)
       OR has_role(auth.uid(),'commercial'::app_role) OR has_role(auth.uid(),'csm'::app_role)) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO v_total_etab FROM etablissements;
  SELECT count(*) INTO v_high_risk FROM churn_predictions WHERE risk_level='high';
  SELECT count(*) INTO v_medium_risk FROM churn_predictions WHERE risk_level='medium';
  SELECT count(*) INTO v_low_risk FROM churn_predictions WHERE risk_level='low';
  SELECT count(*) INTO v_active_alerts FROM proactive_alerts WHERE statut='active';
  SELECT count(*), COALESCE(sum(montant_estime),0) INTO v_pending_upsells, v_upsell_potential
    FROM upsell_recommendations WHERE statut='pending';
  SELECT COALESCE(sum(montant_prevu),0), COALESCE(sum(montant_realise),0)
    INTO v_forecasted_ca, v_realized_ca FROM ca_forecasts WHERE type_periode='monthly';
  SELECT COALESCE(avg(score),0) INTO v_avg_churn FROM churn_predictions;
  result := jsonb_build_object(
    'total_etablissements',v_total_etab,'high_risk_count',v_high_risk,
    'medium_risk_count',v_medium_risk,'low_risk_count',v_low_risk,
    'average_churn_score',round(v_avg_churn::numeric,2),'active_alerts',v_active_alerts,
    'pending_upsells',v_pending_upsells,'upsell_potential',v_upsell_potential,
    'forecasted_ca',v_forecasted_ca,'realized_ca',v_realized_ca);
  RETURN result;
END; $$;


--
-- Name: get_catalogue_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalogue_stats() RETURNS TABLE(produit_id uuid, nb_devis bigint, nb_factures bigint, ca_cumule_ht numeric, derniere_utilisation timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH devis_stats AS (
    SELECT dl.produit_id,
           COUNT(*)::bigint AS nb,
           COALESCE(SUM(dl.montant_ht), 0)::numeric AS ca,
           MAX(dl.created_at) AS last_at
    FROM public.devis_lignes dl
    WHERE dl.produit_id IS NOT NULL
    GROUP BY dl.produit_id
  ),
  facture_stats AS (
    SELECT fl.produit_id,
           COUNT(*)::bigint AS nb,
           COALESCE(SUM(fl.montant_ht), 0)::numeric AS ca,
           MAX(fl.created_at) AS last_at
    FROM public.factures_lignes fl
    WHERE fl.produit_id IS NOT NULL
    GROUP BY fl.produit_id
  )
  SELECT
    p.id AS produit_id,
    COALESCE(d.nb, 0) AS nb_devis,
    COALESCE(f.nb, 0) AS nb_factures,
    COALESCE(d.ca, 0) + COALESCE(f.ca, 0) AS ca_cumule_ht,
    GREATEST(d.last_at, f.last_at) AS derniere_utilisation
  FROM public.catalogue_produits p
  LEFT JOIN devis_stats d ON d.produit_id = p.id
  LEFT JOIN facture_stats f ON f.produit_id = p.id;
$$;


--
-- Name: get_churn_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_churn_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public._churn_can_read() THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  WITH active AS (
    SELECT cp.*, e.nom, e.statut::text AS statut, e.csm_id
    FROM public.churn_predictions cp
    JOIN public.etablissements e ON e.id = cp.etablissement_id
    WHERE cp.acknowledged_until IS NULL OR cp.acknowledged_until < now()
  ),
  prev_day AS (
    SELECT etablissement_id, score, risk_level
    FROM (
      SELECT etablissement_id, score, risk_level,
             ROW_NUMBER() OVER (PARTITION BY etablissement_id ORDER BY snapshot_date DESC) AS rn
      FROM public.churn_predictions_history
      WHERE snapshot_date <= CURRENT_DATE - 7
    ) t WHERE rn = 1
  ),
  kpis AS (
    SELECT
      COUNT(*)::int AS total,
      COUNT(*) FILTER (WHERE risk_level='critical')::int AS critical,
      COUNT(*) FILTER (WHERE risk_level='high')::int AS high,
      COUNT(*) FILTER (WHERE risk_level='medium')::int AS medium,
      COUNT(*) FILTER (WHERE risk_level='low')::int AS low,
      AVG(score)::numeric(10,2) AS avg_score
    FROM active
  ),
  prev_kpis AS (
    SELECT
      COUNT(*) FILTER (WHERE risk_level='critical')::int AS critical,
      COUNT(*) FILTER (WHERE risk_level='high')::int AS high,
      COUNT(*) FILTER (WHERE risk_level='medium')::int AS medium,
      COUNT(*) FILTER (WHERE risk_level='low')::int AS low,
      AVG(score)::numeric(10,2) AS avg_score
    FROM prev_day
  ),
  -- MRR à risque : on additionne les montants_total des facturation_periodes actives mensualisées
  mrr_at_risk AS (
    SELECT COALESCE(SUM(fp.montant_total)::numeric, 0) AS mrr
    FROM public.facturation_periodes fp
    JOIN active a ON a.etablissement_id = fp.etablissement_id
    WHERE a.risk_level IN ('critical','high')
      AND fp.statut = 'active'
  ),
  factors_breakdown AS (
    SELECT
      COUNT(*) FILTER (WHERE (factors->>'open_tickets')::int >= 5)::int AS many_tickets,
      COUNT(*) FILTER (WHERE (factors->>'emails_30d')::int = 0)::int AS no_emails,
      COUNT(*) FILTER (WHERE (factors->>'unpaid_invoices')::int >= 2)::int AS many_unpaid,
      COUNT(*) FILTER (WHERE (factors->>'days_since_last_interaction')::int > 60)::int AS no_interaction
    FROM active
  ),
  movements AS (
    SELECT
      a.etablissement_id, a.nom, a.score, a.risk_level,
      pd.score AS prev_score,
      (a.score - pd.score) AS delta
    FROM active a
    LEFT JOIN prev_day pd ON pd.etablissement_id = a.etablissement_id
    WHERE pd.score IS NOT NULL
  ),
  worsened AS (
    SELECT etablissement_id, nom, score, risk_level, prev_score, delta
    FROM movements WHERE delta >= 10
    ORDER BY delta DESC LIMIT 10
  ),
  improved AS (
    SELECT etablissement_id, nom, score, risk_level, prev_score, delta
    FROM movements WHERE delta <= -10
    ORDER BY delta ASC LIMIT 10
  )
  SELECT jsonb_build_object(
    'computed_at', now(),
    'kpis', (SELECT row_to_json(k) FROM kpis k),
    'prev_kpis', COALESCE((SELECT row_to_json(p) FROM prev_kpis p), '{}'::json),
    'mrr_at_risk', (SELECT mrr FROM mrr_at_risk),
    'factors_breakdown', (SELECT row_to_json(f) FROM factors_breakdown f),
    'worsened', COALESCE((SELECT jsonb_agg(row_to_json(w)) FROM worsened w), '[]'::jsonb),
    'improved', COALESCE((SELECT jsonb_agg(row_to_json(i)) FROM improved i), '[]'::jsonb),
    'snoozed_count', (SELECT COUNT(*)::int FROM public.churn_predictions WHERE acknowledged_until IS NOT NULL AND acknowledged_until > now())
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_churn_trends(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_churn_trends(p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF NOT public._churn_can_read() THEN RAISE EXCEPTION 'Accès refusé'; END IF;

  WITH days AS (
    SELECT generate_series(CURRENT_DATE - (p_days - 1), CURRENT_DATE, interval '1 day')::date AS day
  ),
  daily AS (
    SELECT snapshot_date AS day, etablissement_id, risk_level, score,
           ROW_NUMBER() OVER (PARTITION BY snapshot_date, etablissement_id ORDER BY snapshotted_at DESC) AS rn
    FROM public.churn_predictions_history
    WHERE snapshot_date >= CURRENT_DATE - p_days
  ),
  daily_last AS (SELECT day, etablissement_id, risk_level, score FROM daily WHERE rn = 1),
  agg AS (
    SELECT
      d.day,
      COUNT(dl.etablissement_id)::int AS total,
      COUNT(*) FILTER (WHERE dl.risk_level='critical')::int AS critical,
      COUNT(*) FILTER (WHERE dl.risk_level='high')::int AS high,
      COUNT(*) FILTER (WHERE dl.risk_level='medium')::int AS medium,
      COUNT(*) FILTER (WHERE dl.risk_level='low')::int AS low,
      COALESCE(AVG(dl.score)::numeric(10,2), 0) AS avg_score
    FROM days d LEFT JOIN daily_last dl ON dl.day = d.day
    GROUP BY d.day ORDER BY d.day
  )
  SELECT COALESCE(jsonb_agg(row_to_json(agg)), '[]'::jsonb) INTO v_result FROM agg;

  RETURN v_result;
END;
$$;


--
-- Name: get_contacts_secure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contacts_secure(etablissement_id_param uuid) RETURNS TABLE(id uuid, etablissement_id uuid, nom text, prenom text, fonction text, email text, telephone text, est_contact_principal boolean, type_contact text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Validate access before returning data
  IF NOT can_access_contact(etablissement_id_param) THEN
    RAISE EXCEPTION 'Access denied: You do not have permission to view contacts for this establishment';
  END IF;
  
  -- Log the access
  PERFORM log_contact_access(
    NULL, -- contact_id not specific
    etablissement_id_param,
    'bulk_select',
    ARRAY['contact_list_access']
  );
  
  -- Return filtered results
  RETURN QUERY
  SELECT 
    c.id,
    c.etablissement_id,
    c.nom,
    c.prenom, 
    c.fonction,
    c.email,
    c.telephone,
    c.est_contact_principal,
    c.type_contact,
    c.created_at,
    c.updated_at
  FROM public.contacts c
  WHERE c.etablissement_id = etablissement_id_param;
END;
$$;


--
-- Name: get_contacts_secure_by_establishment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contacts_secure_by_establishment(etablissement_id_param uuid) RETURNS TABLE(id uuid, etablissement_id uuid, nom text, prenom text, fonction text, email text, telephone text, est_contact_principal boolean, type_contact text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Validate access before returning customer data
  IF NOT can_access_contact(etablissement_id_param) THEN
    RAISE EXCEPTION 'Access denied: You do not have permission to view contacts for this establishment';
  END IF;
  
  -- Return filtered customer contact data
  RETURN QUERY
  SELECT c.id, c.etablissement_id, c.nom, c.prenom, c.fonction, c.email, c.telephone, 
         c.est_contact_principal, c.type_contact, c.created_at, c.updated_at
  FROM public.contacts c
  WHERE c.etablissement_id = etablissement_id_param;
END;
$$;


--
-- Name: get_csm_playbook_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_csm_playbook_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_playbooks', (SELECT COUNT(*) FROM public.csm_playbooks),
    'active_playbooks', (SELECT COUNT(*) FROM public.csm_playbooks WHERE is_active = true),
    'pending_executions', (SELECT COUNT(*) FROM public.csm_playbook_executions WHERE status IN ('pending','running')),
    'completed_30d', (SELECT COUNT(*) FROM public.csm_playbook_executions WHERE status = 'completed' AND completed_at > now() - interval '30 days'),
    'failed_30d', (SELECT COUNT(*) FROM public.csm_playbook_executions WHERE status = 'failed' AND updated_at > now() - interval '30 days'),
    'next_actions', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT
          e.id, e.playbook_id, e.etablissement_id, e.current_step_order,
          e.next_action_at, e.status,
          p.name as playbook_name
        FROM public.csm_playbook_executions e
        JOIN public.csm_playbooks p ON p.id = e.playbook_id
        WHERE e.status IN ('pending','running')
          AND e.next_action_at IS NOT NULL
        ORDER BY e.next_action_at ASC
        LIMIT 20
      ) t
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


