--
-- Name: get_dashboard_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_overview() RETURNS TABLE(total_etablissements bigint, total_prospects bigint, total_pipeline bigint, total_contractuel bigint, total_production bigint, total_bloques bigint, valeur_bloquee numeric, total_taches bigint, valeur_totale numeric, valeur_pipeline numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH tarifs AS (
    SELECT
      e.statut::text AS statut_txt,
      COALESCE(
        CASE
          WHEN e.type_offre = 'Au succès'
            AND e.pallier_vise IS NOT NULL
            AND e.tarifs_palliers IS NOT NULL
          THEN (
            SELECT COALESCE((e.tarifs_palliers->>k)::numeric, 0)
            FROM (
              SELECT unnest(ARRAY['palier','pallier','palier_','pallier_']) AS prefix
            ) p,
            LATERAL (
              SELECT p.prefix || substring(lower(e.pallier_vise) FROM '\d+') AS k
            ) candidate
            WHERE e.tarifs_palliers ? candidate.k
            LIMIT 1
          )
          ELSE NULL
        END,
        CASE
          WHEN e.modele_statique_succes ~ '^[0-9]+\.?[0-9]*$'
          THEN e.modele_statique_succes::numeric
          ELSE NULL
        END,
        CASE
          WHEN e.nombre_passages_urgences_annuel IS NOT NULL
          THEN e.nombre_passages_urgences_annuel * 2
          ELSE NULL
        END,
        0
      )::numeric AS tarif
    FROM public.etablissements e
  ),
  agg AS (
    SELECT
      COUNT(*)::bigint AS total_etablissements,
      COUNT(*) FILTER (WHERE statut_txt = 'Prospect')::bigint AS total_prospects,
      COUNT(*) FILTER (WHERE statut_txt = ANY (ARRAY[
        'Prospect','Contacté','Attente RDV','RDV pris','Attente post RDV',
        'Dans les RDV','Etude émise','Dans les RDV post EME',
        'Négociation','Contractualisation','Vendu'
      ]))::bigint AS total_pipeline,
      COUNT(*) FILTER (WHERE statut_txt = ANY (ARRAY[
        'Contractuel','Conformité','Déploiement','Formation','Go-Live'
      ]))::bigint AS total_contractuel,
      COUNT(*) FILTER (WHERE statut_txt = 'Production')::bigint AS total_production,
      COUNT(*) FILTER (WHERE statut_txt = 'Bloqué')::bigint AS total_bloques,
      COALESCE(SUM(tarif), 0)::numeric AS valeur_totale,
      COALESCE(SUM(tarif) FILTER (WHERE statut_txt = ANY (ARRAY[
        'Prospect','Contacté','Attente RDV','RDV pris','Attente post RDV',
        'Dans les RDV','Etude émise','Dans les RDV post EME',
        'Négociation','Contractualisation','Vendu'
      ])), 0)::numeric AS valeur_pipeline,
      COALESCE(SUM(tarif) FILTER (WHERE statut_txt = 'Bloqué'), 0)::numeric AS valeur_bloquee
    FROM tarifs
  )
  SELECT
    agg.total_etablissements,
    agg.total_prospects,
    agg.total_pipeline,
    agg.total_contractuel,
    agg.total_production,
    agg.total_bloques,
    agg.valeur_bloquee,
    (SELECT COUNT(*)::bigint FROM public.taches WHERE archive = false) AS total_taches,
    agg.valeur_totale,
    agg.valeur_pipeline
  FROM agg;
$_$;


--
-- Name: FUNCTION get_dashboard_overview(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_dashboard_overview() IS 'Retourne les statistiques globales du dashboard. 
IMPORTANT: Les établissements bloqués sont exclus des calculs de CA pipeline mais conservent leur valeur dans valeur_bloquee pour le suivi.';


--
-- Name: get_dashboard_task_summaries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_task_summaries() RETURNS TABLE(id uuid, titre text, statut text, echeance date, responsable_id uuid, etablissement_nom text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
