--
-- Name: get_db_health_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_db_health_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  -- Vérifier que l'utilisateur est admin
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  SELECT jsonb_build_object(
    'tables', (
      SELECT jsonb_agg(t ORDER BY total_size DESC)
      FROM (
        SELECT 
          c.relname AS table_name,
          c.reltuples::bigint AS estimated_rows,
          pg_total_relation_size(c.oid) AS total_size,
          pg_size_pretty(pg_total_relation_size(c.oid)) AS total_size_pretty,
          pg_size_pretty(pg_relation_size(c.oid)) AS data_size_pretty,
          pg_size_pretty(pg_total_relation_size(c.oid) - pg_relation_size(c.oid)) AS index_size_pretty,
          s.seq_scan,
          s.idx_scan,
          CASE WHEN (s.seq_scan + COALESCE(s.idx_scan, 0)) > 0 
            THEN round(COALESCE(s.idx_scan, 0)::numeric / (s.seq_scan + COALESCE(s.idx_scan, 0))::numeric * 100, 1)
            ELSE 0 
          END AS idx_scan_pct,
          s.n_live_tup,
          s.n_dead_tup,
          CASE WHEN s.n_live_tup > 0 
            THEN round(s.n_dead_tup::numeric / s.n_live_tup::numeric * 100, 1)
            ELSE 0 
          END AS dead_tup_pct
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        LEFT JOIN pg_stat_user_tables s ON s.relid = c.oid
        WHERE n.nspname = 'public'
          AND c.relkind = 'r'
        ORDER BY pg_total_relation_size(c.oid) DESC
        LIMIT 30
      ) t
    ),
    'total_db_size', pg_size_pretty(
      (SELECT sum(pg_total_relation_size(c.oid))
       FROM pg_class c
       JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname = 'public' AND c.relkind = 'r')
    ),
    'table_count', (
      SELECT count(*)::int
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relkind = 'r'
    ),
    'high_seq_scan_tables', (
      SELECT jsonb_agg(t)
      FROM (
        SELECT 
          s.relname AS table_name,
          s.seq_scan,
          COALESCE(s.idx_scan, 0) AS idx_scan,
          s.n_live_tup AS rows
        FROM pg_stat_user_tables s
        WHERE s.schemaname = 'public'
          AND s.seq_scan > 1000
          AND (s.seq_scan > COALESCE(s.idx_scan, 0) * 10 OR COALESCE(s.idx_scan, 0) = 0)
        ORDER BY s.seq_scan DESC
        LIMIT 10
      ) t
    )
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_db_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_db_stats() RETURNS TABLE(total_records bigint, table_count bigint, storage_size text, cache_hit_ratio numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    (SELECT COUNT(*) FROM public.etablissements) + 
    (SELECT COUNT(*) FROM public.taches) + 
    (SELECT COUNT(*) FROM public.contacts) + 
    (SELECT COUNT(*) FROM public.profiles) as total_records,
    
    (SELECT COUNT(*) 
     FROM information_schema.tables 
     WHERE table_schema = 'public' 
     AND table_type = 'BASE TABLE') as table_count,
     
    pg_size_pretty(pg_database_size(current_database()))::TEXT as storage_size,
    
    COALESCE(
      (SELECT 
        ROUND(
          (sum(heap_blks_hit) * 100.0 / NULLIF(sum(heap_blks_hit) + sum(heap_blks_read), 0))::numeric, 
          2
        )
       FROM pg_statio_user_tables), 
      95.0
    ) as cache_hit_ratio;
END;
$$;


--
-- Name: get_duplicate_emails(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_duplicate_emails() RETURNS TABLE(email text, count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT c.email, COUNT(*) as count
  FROM contacts c
  WHERE c.email IS NOT NULL AND c.email != ''
  GROUP BY c.email
  HAVING COUNT(*) > 1;
END;
$$;


--
-- Name: get_email_account_credentials_secure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_account_credentials_secure(p_account_id uuid) RETURNS TABLE(imap_host text, imap_port integer, smtp_host text, smtp_port integer, encrypted_password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile_id uuid;
  v_account_profile_id uuid;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE user_id = auth.uid();
  SELECT profile_id INTO v_account_profile_id FROM user_email_accounts WHERE id = p_account_id;
  
  IF v_account_profile_id != v_profile_id AND NOT is_admin() THEN
    RAISE EXCEPTION 'Access denied: You can only access your own email credentials';
  END IF;
  
  RETURN QUERY
  SELECT uea.imap_host, uea.imap_port, uea.smtp_host, uea.smtp_port, uea.encrypted_password
  FROM user_email_accounts uea WHERE uea.id = p_account_id;
END;
$$;


--
-- Name: get_email_account_with_password(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_account_with_password(account_uuid uuid, encryption_key text) RETURNS TABLE(account_id uuid, email_address text, password text, imap_host text, imap_port integer, smtp_host text, smtp_port integer, last_uid_synced text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- Only allow service_role to call this function
  IF current_setting('request.jwt.claims', true)::json->>'role' IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Access denied: this function requires service_role privileges';
  END IF;

  RETURN QUERY
  SELECT 
    uea.id,
    uea.email_address,
    extensions.pgp_sym_decrypt(decode(uea.encrypted_password, 'base64'), encryption_key) AS password,
    uea.imap_host,
    uea.imap_port,
    uea.smtp_host,
    uea.smtp_port,
    uea.last_uid_synced
  FROM public.user_email_accounts AS uea
  WHERE uea.id = account_uuid AND uea.is_active = true;
END;
$$;


--
-- Name: get_email_analytics(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_analytics(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  volume_data jsonb;
  commercial_data jsonb;
  ai_quality_data jsonb;
  threads_data jsonb;
  v_since timestamptz;
BEGIN
  v_since := now() - (p_days || ' days')::interval;

  -- 1. Volume: daily sent/received
  SELECT coalesce(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.date), '[]'::jsonb)
  INTO volume_data
  FROM (
    SELECT 
      to_char(created_at::date, 'YYYY-MM-DD') AS date,
      count(*) FILTER (WHERE NOT is_sent) AS received,
      count(*) FILTER (WHERE is_sent) AS sent
    FROM email_messages
    WHERE created_at >= v_since
    GROUP BY created_at::date
    ORDER BY created_at::date
  ) t;

  -- 2. Commercial: etablissements created from emails
  SELECT jsonb_build_object(
    'totalEtablissements', (
      SELECT count(*) FROM etablissements
      WHERE created_at >= v_since
        AND notes ILIKE '%Créé automatiquement depuis email%'
    ),
    'suggestions', coalesce((
      SELECT row_to_json(s)::jsonb FROM (
        SELECT 
          count(*) AS total,
          count(*) FILTER (WHERE status = 'accepted') AS accepted,
          count(*) FILTER (WHERE status = 'rejected') AS rejected,
          count(*) FILTER (WHERE status = 'pending') AS pending,
          coalesce(avg(confidence_score), 0) AS avg_confidence
        FROM email_to_etablissement_suggestions
        WHERE created_at >= v_since
      ) s
    ), '{"total":0,"accepted":0,"rejected":0,"pending":0,"avg_confidence":0}'::jsonb)
  ) INTO commercial_data;

  -- 3. AI quality metrics
  SELECT jsonb_build_object(
    'avgProcessingTime', coalesce(round(avg(processing_duration_ms)), 0),
    'totalTokens', coalesce(sum(total_tokens), 0),
    'estimatedCost', round(coalesce(sum(total_tokens), 0)::numeric / 1000 * 0.002, 4),
    'successRate', CASE WHEN count(*) > 0 
      THEN round((count(*) FILTER (WHERE success))::numeric / count(*) * 100, 1)
      ELSE 100 END,
    'recentLogs', coalesce((
      SELECT jsonb_agg(row_to_json(r)::jsonb)
      FROM (
        SELECT processing_duration_ms, total_tokens, success, processed_at
        FROM ai_processing_log
        ORDER BY processed_at DESC
        LIMIT 10
      ) r
    ), '[]'::jsonb)
  )
  INTO ai_quality_data
  FROM ai_processing_log
  WHERE processed_at >= now() - interval '30 days';

  -- 4. Recent threads
  SELECT coalesce(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO threads_data
  FROM (
    SELECT id, subject, last_message_date
    FROM email_threads
    WHERE last_message_date IS NOT NULL
    ORDER BY last_message_date DESC
    LIMIT 5
  ) t;

  result := jsonb_build_object(
    'volume', volume_data,
    'commercial', commercial_data,
    'aiQuality', ai_quality_data,
    'threads', threads_data
  );

  RETURN result;
END;
$$;


--
-- Name: get_email_classification_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_classification_stats(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb; v_pending bigint; v_accepted bigint; v_rejected bigint;
        v_total bigint; v_avg_confidence numeric; v_since timestamptz;
BEGIN
  IF NOT (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'direction'::app_role)
       OR has_role(auth.uid(),'commercial'::app_role) OR has_role(auth.uid(),'csm'::app_role)) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;
  v_since := now() - (p_days || ' days')::interval;
  SELECT count(*) FILTER (WHERE status='pending'), count(*) FILTER (WHERE status='accepted'),
         count(*) FILTER (WHERE status='rejected'), count(*), COALESCE(avg(match_confidence),0)
    INTO v_pending, v_accepted, v_rejected, v_total, v_avg_confidence
    FROM email_to_etablissement_suggestions WHERE created_at >= v_since;
  result := jsonb_build_object('pending',v_pending,'accepted',v_accepted,'rejected',v_rejected,
    'total',v_total,'avg_confidence',round(v_avg_confidence::numeric,2));
  RETURN result;
END; $$;


