--
-- Name: get_email_thread_participants(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_thread_participants(p_thread_id uuid) RETURNS TABLE(email text, name text, participant_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Vérifier que l'utilisateur a accès au thread
  IF NOT EXISTS (
    SELECT 1 FROM email_threads et
    JOIN user_email_accounts uea ON uea.id = et.user_email_account_id
    JOIN profiles p ON p.id = uea.profile_id
    WHERE et.id = p_thread_id AND p.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Accès non autorisé au thread';
  END IF;

  RETURN QUERY
  SELECT DISTINCT
    em.from_address as email,
    em.from_name as name,
    'from'::TEXT as participant_type
  FROM email_messages em
  WHERE em.thread_id = p_thread_id
  
  UNION
  
  SELECT DISTINCT
    jsonb_array_elements_text(em.to_addresses) as email,
    NULL::TEXT as name,
    'to'::TEXT as participant_type
  FROM email_messages em
  WHERE em.thread_id = p_thread_id
  
  UNION
  
  SELECT DISTINCT
    jsonb_array_elements_text(em.cc_addresses) as email,
    NULL::TEXT as name,
    'cc'::TEXT as participant_type
  FROM email_messages em
  WHERE em.thread_id = p_thread_id
  AND em.cc_addresses IS NOT NULL;
END;
$$;


--
-- Name: get_email_threads_health_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_threads_health_admin() RETURNS TABLE(thread_id uuid, subject text, recorded_message_count integer, actual_message_count bigint, count_difference bigint, recorded_last_date timestamp with time zone, actual_last_date timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Admin-only access check
  IF NOT EXISTS (
    SELECT 1 FROM user_roles 
    WHERE user_id = auth.uid() 
    AND role IN ('admin', 'direction')
  ) THEN
    RAISE EXCEPTION 'Access denied: Admin role required';
  END IF;
  
  RETURN QUERY
  SELECT 
    et.id as thread_id,
    et.subject,
    et.message_count as recorded_message_count,
    COUNT(em.id) as actual_message_count,
    COUNT(em.id) - COALESCE(et.message_count, 0) as count_difference,
    et.last_message_date as recorded_last_date,
    MAX(em.date) as actual_last_date
  FROM email_threads et
  LEFT JOIN email_messages em ON em.thread_id = et.id
  WHERE et.is_deleted = false
  GROUP BY et.id, et.subject, et.message_count, et.last_message_date
  HAVING COUNT(em.id) != COALESCE(et.message_count, 0)
  ORDER BY count_difference DESC
  LIMIT 100;
END;
$$;


--
-- Name: FUNCTION get_email_threads_health_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_email_threads_health_admin() IS 'Admin-only function to check email thread health metrics. 
Replaces the public email_threads_health view for security.';


