--
-- Name: get_enquete_context(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_enquete_context(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_campagne public.enquetes_campagnes%ROWTYPE;
  v_etab_nom TEXT;
  v_user_nom TEXT;
  v_csm_nom TEXT;
  v_session_titre TEXT;
  v_session_date DATE;
BEGIN
  SELECT * INTO v_campagne FROM public.enquetes_campagnes WHERE token_unique = p_token;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'token_invalide');
  END IF;

  IF v_campagne.expires_at < now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'token_expire');
  END IF;

  IF v_campagne.status = 'responded' THEN
    RETURN jsonb_build_object('success', false, 'error', 'deja_repondu');
  END IF;

  SELECT nom INTO v_etab_nom FROM public.etablissements WHERE id = v_campagne.etablissement_id;
  SELECT (prenom || ' ' || nom) INTO v_user_nom FROM public.etablissement_users WHERE id = v_campagne.user_id;
  SELECT full_name INTO v_csm_nom FROM public.profiles WHERE id = v_campagne.csm_id;
  SELECT titre, date_debut::date INTO v_session_titre, v_session_date FROM public.formation_sessions WHERE id = v_campagne.session_id;

  RETURN jsonb_build_object(
    'success', true,
    'type', v_campagne.type,
    'etablissement', jsonb_build_object('id', v_campagne.etablissement_id, 'nom', v_etab_nom),
    'user', jsonb_build_object('id', v_campagne.user_id, 'nom', v_user_nom),
    'csm', CASE WHEN v_campagne.csm_id IS NOT NULL THEN jsonb_build_object('id', v_campagne.csm_id, 'nom', v_csm_nom) ELSE NULL END,
    'session', CASE WHEN v_campagne.session_id IS NOT NULL THEN jsonb_build_object('id', v_campagne.session_id, 'titre', v_session_titre, 'date', v_session_date) ELSE NULL END
  );
END;
$$;


--
-- Name: get_etablissement_churn_history(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_etablissement_churn_history(p_etab uuid, p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF NOT public._churn_can_read() THEN RAISE EXCEPTION 'Accès refusé'; END IF;

  WITH h AS (
    SELECT snapshot_date, score, risk_level,
           ROW_NUMBER() OVER (PARTITION BY snapshot_date ORDER BY snapshotted_at DESC) AS rn
    FROM public.churn_predictions_history
    WHERE etablissement_id = p_etab
      AND snapshot_date >= CURRENT_DATE - p_days
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object('day', snapshot_date, 'score', score, 'risk_level', risk_level) ORDER BY snapshot_date), '[]'::jsonb)
  INTO v_result FROM h WHERE rn = 1;

  RETURN v_result;
END;
$$;


--
-- Name: get_etablissement_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_etablissement_stats() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM public.etablissements),
    'byStatus', COALESCE((
      SELECT jsonb_object_agg(statut, c)
      FROM (
        SELECT statut, COUNT(*)::int AS c
        FROM public.etablissements
        WHERE statut IS NOT NULL
        GROUP BY statut
      ) s
    ), '{}'::jsonb),
    'byType', COALESCE((
      SELECT jsonb_object_agg(type, c)
      FROM (
        SELECT type, COUNT(*)::int AS c
        FROM public.etablissements
        WHERE type IS NOT NULL
        GROUP BY type
      ) t
    ), '{}'::jsonb),
    'avgProgression', COALESCE((SELECT AVG(progression)::float FROM public.etablissements), 0)
  );
$$;


