--
-- Name: get_filtered_rh_data(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_filtered_rh_data(data_type text, user_id uuid, filter_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  user_role TEXT;
  user_view_scope TEXT;
  result JSONB;
BEGIN
  -- Récupérer le rôle et le scope de l'utilisateur
  SELECT role, view_scope INTO user_role, user_view_scope
  FROM user_roles
  WHERE profile_id = (SELECT id FROM profiles WHERE user_id = get_filtered_rh_data.user_id);

  -- Si pas de rôle trouvé, retourner vide
  IF user_role IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  -- Filtrage selon le type de données demandé
  CASE data_type
    WHEN 'salaires' THEN
      -- Vérifier les permissions pour voir les salaires
      IF user_view_scope = 'all' OR user_role IN ('admin', 'manager') THEN
        -- Retourner tous les salaires (avec filtre optionnel par mois)
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', s.id,
            'profile_id', s.profile_id,
            'mois', s.mois,
            'salaire_brut', s.salaire_brut,
            'salaire_net', s.salaire_net,
            'cotisations_patronales', s.cotisations_patronales,
            'cotisations_salariales', s.cotisations_salariales,
            'primes', s.primes,
            'heures_supplementaires', s.heures_supplementaires,
            'source_type', s.source_type,
            'profiles', jsonb_build_object(
              'id', p.id,
              'prenom', p.prenom,
              'nom', p.nom,
              'email', p.email,
              'fonction', p.fonction
            )
          )
        ) INTO result
        FROM rh_salaires_mensuels s
        LEFT JOIN profiles p ON s.profile_id = p.id
        WHERE (filter_month IS NULL OR s.mois LIKE filter_month || '%')
        ORDER BY s.mois DESC;
      ELSIF user_view_scope = 'own' THEN
        -- Retourner uniquement ses propres salaires
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', s.id,
            'profile_id', s.profile_id,
            'mois', s.mois,
            'salaire_brut', s.salaire_brut,
            'salaire_net', s.salaire_net,
            'profiles', jsonb_build_object(
              'prenom', p.prenom,
              'nom', p.nom
            )
          )
        ) INTO result
        FROM rh_salaires_mensuels s
        LEFT JOIN profiles p ON s.profile_id = p.id
        WHERE s.profile_id = (SELECT id FROM profiles WHERE user_id = get_filtered_rh_data.user_id)
          AND (filter_month IS NULL OR s.mois LIKE filter_month || '%');
      ELSE
        result := '[]'::JSONB;
      END IF;

    WHEN 'absences' THEN
      -- Filtrage des absences selon les permissions
      IF user_view_scope = 'all' OR user_role IN ('admin', 'manager') THEN
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', a.id,
            'profile_id', a.profile_id,
            'type_absence', a.type_absence,
            'date_debut', a.date_debut,
            'date_fin', a.date_fin,
            'statut', a.statut,
            'profiles', jsonb_build_object(
              'prenom', p.prenom,
              'nom', p.nom,
              'fonction', p.fonction
            )
          )
        ) INTO result
        FROM rh_absences a
        LEFT JOIN profiles p ON a.profile_id = p.id
        ORDER BY a.date_debut DESC;
      ELSIF user_view_scope = 'own' THEN
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', a.id,
            'profile_id', a.profile_id,
            'type_absence', a.type_absence,
            'date_debut', a.date_debut,
            'date_fin', a.date_fin,
            'statut', a.statut
          )
        ) INTO result
        FROM rh_absences a
        WHERE a.profile_id = (SELECT id FROM profiles WHERE user_id = get_filtered_rh_data.user_id);
      ELSE
        result := '[]'::JSONB;
      END IF;

    WHEN 'objectifs' THEN
      -- Filtrage des objectifs selon les permissions
      IF user_view_scope = 'all' OR user_role IN ('admin', 'manager') THEN
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', o.id,
            'profile_id', o.profile_id,
            'trimestre', o.trimestre,
            'annee', o.annee,
            'objectif_ca', o.objectif_ca,
            'ca_realise', o.ca_realise,
            'profiles', jsonb_build_object(
              'prenom', p.prenom,
              'nom', p.nom,
              'fonction', p.fonction
            )
          )
        ) INTO result
        FROM rh_objectifs_ca o
        LEFT JOIN profiles p ON o.profile_id = p.id
        ORDER BY o.annee DESC, o.trimestre DESC;
      ELSIF user_view_scope = 'own' THEN
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', o.id,
            'trimestre', o.trimestre,
            'annee', o.annee,
            'objectif_ca', o.objectif_ca,
            'ca_realise', o.ca_realise
          )
        ) INTO result
        FROM rh_objectifs_ca o
        WHERE o.profile_id = (SELECT id FROM profiles WHERE user_id = get_filtered_rh_data.user_id);
      ELSE
        result := '[]'::JSONB;
      END IF;

    ELSE
      result := '[]'::JSONB;
  END CASE;

  RETURN COALESCE(result, '[]'::JSONB);
END;
$$;


