--
-- Name: get_global_activity_feed(integer, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_global_activity_feed(p_limit integer DEFAULT 50, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id text, type text, occurred_at timestamp with time zone, actor_user_id uuid, actor_name text, etablissement_id uuid, etablissement_nom text, title text, description text, icon text, color text, link text, metadata jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_types text[] := COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_filters->'types')), ARRAY[]::text[]);
  v_user_ids uuid[] := COALESCE(ARRAY(SELECT (jsonb_array_elements_text(p_filters->'user_ids'))::uuid), ARRAY[]::uuid[]);
  v_etab_ids uuid[] := COALESCE(ARRAY(SELECT (jsonb_array_elements_text(p_filters->'etablissement_ids'))::uuid), ARRAY[]::uuid[]);
  v_date_from timestamptz := NULLIF(p_filters->>'date_from','')::timestamptz;
  v_date_to timestamptz := NULLIF(p_filters->>'date_to','')::timestamptz;
  v_search text := NULLIF(TRIM(COALESCE(p_filters->>'search','')),'');
  v_search_pat text := CASE WHEN v_search IS NOT NULL THEN '%'||v_search||'%' ELSE NULL END;
  v_cursor timestamptz := COALESCE(p_cursor, now() + interval '1 day');
  v_limit int := LEAST(GREATEST(COALESCE(p_limit,50), 1), 200);
  v_can_see_audit boolean := has_role(v_user_id, 'admin'::app_role) OR has_role(v_user_id, 'direction'::app_role);
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  WITH unified AS (
    SELECT ('act_'||ca.id::text) AS id, 'interaction'::text AS type,
      COALESCE(ca.activity_date, ca.created_at) AS occurred_at,
      ca.created_by AS actor_user_id, ca.etablissement_id,
      ca.title, ca.description,
      'MessageSquare'::text AS icon, 'blue'::text AS color,
      ('/etablissements/'||ca.etablissement_id::text) AS link,
      jsonb_build_object('activity_type', ca.activity_type, 'status', ca.status) AS metadata
    FROM customer_activities ca
    WHERE COALESCE(ca.activity_date, ca.created_at) < v_cursor
      AND (v_date_from IS NULL OR COALESCE(ca.activity_date, ca.created_at) >= v_date_from)
      AND (v_date_to IS NULL OR COALESCE(ca.activity_date, ca.created_at) <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR ca.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_user_ids,1) IS NULL OR ca.created_by = ANY(v_user_ids))
      AND (array_length(v_types,1) IS NULL OR 'interaction' = ANY(v_types))

    UNION ALL
    SELECT ('tache_'||t.id::text), 'tache', t.created_at, t.created_by, t.etablissement_id,
      t.titre, t.description, 'CheckSquare',
      CASE WHEN t.statut = 'termine' THEN 'green' ELSE 'amber' END,
      ('/etablissements/'||t.etablissement_id::text),
      jsonb_build_object('statut', t.statut, 'priorite', t.priorite)
    FROM taches t
    WHERE t.created_at < v_cursor AND t.etablissement_id IS NOT NULL
      AND (v_date_from IS NULL OR t.created_at >= v_date_from)
      AND (v_date_to IS NULL OR t.created_at <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR t.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_user_ids,1) IS NULL OR t.created_by = ANY(v_user_ids))
      AND (array_length(v_types,1) IS NULL OR 'tache' = ANY(v_types))

    UNION ALL
    SELECT ('cal_'||c.id::text), 'calendar', c.created_at, c.created_by, c.etablissement_id,
      c.title, c.description, 'Calendar', 'purple',
      CASE WHEN c.etablissement_id IS NOT NULL THEN ('/etablissements/'||c.etablissement_id::text) ELSE '/calendrier' END,
      jsonb_build_object('start_time', c.start_time)
    FROM calendar_events c
    WHERE c.created_at < v_cursor
      AND (v_date_from IS NULL OR c.created_at >= v_date_from)
      AND (v_date_to IS NULL OR c.created_at <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR c.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_user_ids,1) IS NULL OR c.created_by = ANY(v_user_ids))
      AND (array_length(v_types,1) IS NULL OR 'calendar' = ANY(v_types))

    UNION ALL
    SELECT ('email_'||em.id::text), 'email',
      COALESCE(em.received_date, em.sent_date, em.created_at),
      NULL::uuid, et.etablissement_id,
      COALESCE(NULLIF(et.ai_generated_title,''), em.subject, '(sans objet)'),
      em.from_name || ' <' || em.from_address || '>',
      'Mail', 'sky',
      ('/emails?thread=' || et.id::text),
      jsonb_build_object('from', em.from_address, 'thread_id', et.id, 'category', et.category)
    FROM email_messages em
    JOIN email_threads et ON et.id = em.thread_id
    WHERE COALESCE(em.received_date, em.sent_date, em.created_at) < v_cursor
      AND COALESCE(em.is_sent, false) = false
      AND COALESCE(et.is_deleted, false) = false
      AND COALESCE(et.is_spam, false) = false
      AND (v_date_from IS NULL OR COALESCE(em.received_date, em.sent_date, em.created_at) >= v_date_from)
      AND (v_date_to IS NULL OR COALESCE(em.received_date, em.sent_date, em.created_at) <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR et.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_types,1) IS NULL OR 'email' = ANY(v_types))

    UNION ALL
    SELECT ('devis_'||d.id::text), 'devis', d.created_at, d.created_by, d.etablissement_id,
      'Devis ' || COALESCE(d.numero, '?'),
      'Montant ' || to_char(COALESCE(d.montant_ttc,0),'FM999G999G990D00') || ' € TTC',
      'FileText',
      CASE d.statut WHEN 'accepte' THEN 'green' WHEN 'refuse' THEN 'red' WHEN 'envoye' THEN 'blue' ELSE 'slate' END,
      ('/devis/' || d.id::text),
      jsonb_build_object('numero', d.numero, 'statut', d.statut, 'montant_ttc', d.montant_ttc)
    FROM devis d
    WHERE d.created_at < v_cursor
      AND (v_date_from IS NULL OR d.created_at >= v_date_from)
      AND (v_date_to IS NULL OR d.created_at <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR d.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_user_ids,1) IS NULL OR d.created_by = ANY(v_user_ids))
      AND (array_length(v_types,1) IS NULL OR 'devis' = ANY(v_types))

    UNION ALL
    SELECT ('facture_'||f.id::text), 'facture', f.created_at, f.created_by, f.etablissement_id,
      'Facture ' || COALESCE(f.numero, '?'),
      'Montant ' || to_char(COALESCE(f.montant_ttc,0),'FM999G999G990D00') || ' € TTC',
      'Receipt',
      CASE f.statut WHEN 'payee' THEN 'green' WHEN 'en_retard' THEN 'red' WHEN 'envoyee' THEN 'blue' ELSE 'slate' END,
      ('/factures/' || f.id::text),
      jsonb_build_object('numero', f.numero, 'statut', f.statut, 'montant_ttc', f.montant_ttc)
    FROM factures f
    WHERE f.created_at < v_cursor
      AND (v_date_from IS NULL OR f.created_at >= v_date_from)
      AND (v_date_to IS NULL OR f.created_at <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR f.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_user_ids,1) IS NULL OR f.created_by = ANY(v_user_ids))
      AND (array_length(v_types,1) IS NULL OR 'facture' = ANY(v_types))

    UNION ALL
    SELECT ('sig_'||sr.id::text), 'signature',
      COALESCE(sr.completed_at, sr.created_at),
      sr.created_by, ct.etablissement_id,
      CASE WHEN sr.completed_at IS NOT NULL THEN 'Contrat signé : ' ELSE 'Demande de signature : ' END
        || COALESCE(ct.titre, 'Contrat ' || COALESCE(ct.numero,'')),
      'Statut : ' || sr.status,
      'PenLine',
      CASE sr.status WHEN 'completed' THEN 'green' WHEN 'cancelled' THEN 'red' WHEN 'pending' THEN 'amber' ELSE 'slate' END,
      ('/contrats/' || ct.id::text),
      jsonb_build_object('status', sr.status, 'provider', sr.provider, 'contrat_id', ct.id)
    FROM signature_requests sr
    LEFT JOIN contrats ct ON ct.id = sr.contrat_id
    WHERE COALESCE(sr.completed_at, sr.created_at) < v_cursor
      AND (v_date_from IS NULL OR COALESCE(sr.completed_at, sr.created_at) >= v_date_from)
      AND (v_date_to IS NULL OR COALESCE(sr.completed_at, sr.created_at) <= v_date_to)
      AND (array_length(v_etab_ids,1) IS NULL OR ct.etablissement_id = ANY(v_etab_ids))
      AND (array_length(v_user_ids,1) IS NULL OR sr.created_by = ANY(v_user_ids))
      AND (array_length(v_types,1) IS NULL OR 'signature' = ANY(v_types))

    UNION ALL
    SELECT ('wf_'||wr.id::text), 'workflow',
      COALESCE(wr.finished_at, wr.started_at),
      NULL::uuid, NULL::uuid,
      'Workflow : ' || COALESCE(w.nom,'?'),
      CASE WHEN wr.duration_ms IS NOT NULL THEN 'Durée ' || (wr.duration_ms/1000) || 's' ELSE NULL END,
      'Workflow',
      CASE wr.status::text WHEN 'success' THEN 'green' WHEN 'failed' THEN 'red' WHEN 'running' THEN 'blue' ELSE 'slate' END,
      ('/automatisations?run=' || wr.id::text),
      jsonb_build_object('status', wr.status, 'workflow_id', wr.workflow_id, 'duration_ms', wr.duration_ms)
    FROM workflow_runs wr
    LEFT JOIN workflows w ON w.id = wr.workflow_id
    WHERE COALESCE(wr.finished_at, wr.started_at) < v_cursor
      AND (v_date_from IS NULL OR COALESCE(wr.finished_at, wr.started_at) >= v_date_from)
      AND (v_date_to IS NULL OR COALESCE(wr.finished_at, wr.started_at) <= v_date_to)
      AND (array_length(v_types,1) IS NULL OR 'workflow' = ANY(v_types))

    UNION ALL
    -- 9e source : audit (admin/direction only)
    SELECT ('audit_rgpd_'||ral.id::text), 'audit', ral.created_at, ral.user_id, NULL::uuid,
      'RGPD : ' || ral.action,
      COALESCE('Table ' || ral.table_name, ral.user_email),
      'ShieldAlert', 'red',
      '/parametres/rgpd',
      jsonb_build_object('source', 'rgpd', 'action', ral.action, 'table', ral.table_name, 'record_id', ral.record_id)
    FROM rgpd_audit_logs ral
    WHERE v_can_see_audit
      AND ral.created_at < v_cursor
      AND (v_date_from IS NULL OR ral.created_at >= v_date_from)
      AND (v_date_to IS NULL OR ral.created_at <= v_date_to)
      AND (array_length(v_user_ids,1) IS NULL OR ral.user_id = ANY(v_user_ids))
      AND (array_length(v_etab_ids,1) IS NULL)
      AND (array_length(v_types,1) IS NULL OR 'audit' = ANY(v_types))

    UNION ALL
    SELECT ('audit_2fa_'||tfa.id::text), 'audit', tfa.created_at, tfa.user_id, NULL::uuid,
      '2FA : ' || tfa.event_type,
      NULLIF(host(tfa.ip_address), ''),
      'ShieldAlert', 'red',
      '/parametres/securite',
      jsonb_build_object('source', '2fa', 'event_type', tfa.event_type)
    FROM two_factor_audit tfa
    WHERE v_can_see_audit
      AND tfa.created_at < v_cursor
      AND (v_date_from IS NULL OR tfa.created_at >= v_date_from)
      AND (v_date_to IS NULL OR tfa.created_at <= v_date_to)
      AND (array_length(v_user_ids,1) IS NULL OR tfa.user_id = ANY(v_user_ids))
      AND (array_length(v_etab_ids,1) IS NULL)
      AND (array_length(v_types,1) IS NULL OR 'audit' = ANY(v_types))

    UNION ALL
    SELECT ('audit_pulse_'||pal.id::text), 'audit', pal.created_at, pal.actor_id, NULL::uuid,
      'Pulse : ' || pal.action,
      COALESCE(pal.error_message, pal.status),
      'ShieldAlert', 'red',
      '/pulse',
      jsonb_build_object('source', 'pulse', 'action', pal.action, 'target_type', pal.target_type, 'target_id', pal.target_id)
    FROM pulse_audit_log pal
    WHERE v_can_see_audit
      AND pal.created_at < v_cursor
      AND pal.action::text IN ('conversation_archived','conversation_deleted','message_deleted','member_removed','role_changed')
      AND (v_date_from IS NULL OR pal.created_at >= v_date_from)
      AND (v_date_to IS NULL OR pal.created_at <= v_date_to)
      AND (array_length(v_user_ids,1) IS NULL OR pal.actor_id = ANY(v_user_ids))
      AND (array_length(v_etab_ids,1) IS NULL)
      AND (array_length(v_types,1) IS NULL OR 'audit' = ANY(v_types))

    UNION ALL
    SELECT ('audit_doc_'||dal.id::text), 'audit', dal.created_at, dal.performed_by, NULL::uuid,
      'Document : ' || dal.action,
      'Document ' || dal.document_id::text,
      'ShieldAlert', 'red',
      ('/documents/' || dal.document_id::text),
      jsonb_build_object('source', 'document', 'action', dal.action, 'document_id', dal.document_id)
    FROM document_audit_log dal
    WHERE v_can_see_audit
      AND dal.created_at < v_cursor
      AND dal.action IN ('deleted','shared','permission_changed','permission_granted','permission_revoked','unshared')
      AND (v_date_from IS NULL OR dal.created_at >= v_date_from)
      AND (v_date_to IS NULL OR dal.created_at <= v_date_to)
      AND (array_length(v_user_ids,1) IS NULL OR dal.performed_by = ANY(v_user_ids))
      AND (array_length(v_etab_ids,1) IS NULL)
      AND (array_length(v_types,1) IS NULL OR 'audit' = ANY(v_types))

    UNION ALL
    SELECT ('audit_wf_'||wal.id::text), 'audit', wal.created_at, wal.user_id, NULL::uuid,
      'Workflow : ' || wal.action,
      'Workflow ' || wal.workflow_id::text,
      'ShieldAlert', 'red',
      ('/automatisations?workflow=' || wal.workflow_id::text),
      jsonb_build_object('source', 'workflow', 'action', wal.action, 'workflow_id', wal.workflow_id)
    FROM workflow_audit_log wal
    WHERE v_can_see_audit
      AND wal.created_at < v_cursor
      AND wal.action IN ('deleted','published','unpublished','updated','enabled','disabled')
      AND (v_date_from IS NULL OR wal.created_at >= v_date_from)
      AND (v_date_to IS NULL OR wal.created_at <= v_date_to)
      AND (array_length(v_user_ids,1) IS NULL OR wal.user_id = ANY(v_user_ids))
      AND (array_length(v_etab_ids,1) IS NULL)
      AND (array_length(v_types,1) IS NULL OR 'audit' = ANY(v_types))
  )
  SELECT
    u.id, u.type, u.occurred_at, u.actor_user_id,
    COALESCE(NULLIF(TRIM(p.prenom||' '||p.nom),''), 'Système') AS actor_name,
    u.etablissement_id, e.nom AS etablissement_nom,
    u.title, u.description, u.icon, u.color, u.link, u.metadata
  FROM unified u
  LEFT JOIN profiles p ON p.user_id = u.actor_user_id
  LEFT JOIN etablissements e ON e.id = u.etablissement_id
  WHERE v_search_pat IS NULL
     OR u.title ILIKE v_search_pat
     OR COALESCE(u.description,'') ILIKE v_search_pat
     OR COALESCE(e.nom,'') ILIKE v_search_pat
     OR COALESCE(p.prenom||' '||p.nom,'') ILIKE v_search_pat
  ORDER BY u.occurred_at DESC
  LIMIT v_limit;
END;
$$;


--
-- Name: get_global_formation_analytics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_global_formation_analytics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    -- Global KPIs
    'totalEtablissements', (
      SELECT count(*) FROM etablissements WHERE statut IN ('Production', 'Go-Live', 'Formation')
    ),
    'totalUsers', (SELECT count(*) FROM etablissement_users eu 
      JOIN etablissements e ON e.id = eu.etablissement_id 
      WHERE e.statut IN ('Production', 'Go-Live', 'Formation')),
    'totalFormedUsers', (SELECT count(*) FROM etablissement_users eu 
      JOIN etablissements e ON e.id = eu.etablissement_id 
      WHERE e.statut IN ('Production', 'Go-Live', 'Formation') AND eu.statut_formation = 'forme'),

    -- Formation satisfaction details
    'satisfactionFormationDetails', (
      SELECT jsonb_build_object(
        'npsGlobal', coalesce(round(avg(nps_score)::numeric, 1), 0),
        'csatGlobal', coalesce(round(avg(csat_score)::numeric, 1), 0),
        'clartePedagogique', coalesce(round(avg(clarte_pedagogique)::numeric, 1), 0),
        'qualiteSupports', coalesce(round(avg(qualite_supports)::numeric, 1), 0),
        'competenceFormateur', coalesce(round(avg(competence_formateur)::numeric, 1), 0),
        'totalReponses', count(*)
      ) FROM enquetes_satisfaction_formation
    ),

    -- Solution satisfaction details
    'satisfactionSolutionDetails', (
      SELECT jsonb_build_object(
        'satisfactionGlobale', coalesce(round(avg(satisfaction_solution)::numeric, 1), 0),
        'faciliteUtilisation', coalesce(round(avg(facilite_utilisation)::numeric, 1), 0),
        'recommandationCollegues', coalesce(round(avg(recommandation_collegues)::numeric, 1), 0),
        'totalReponses', count(*)
      ) FROM enquetes_satisfaction_solution
    ),

    -- Etablissements by formation survey
    'etablissementsByFormation', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb)
      FROM (
        SELECT 
          e.id,
          e.nom,
          coalesce(round(avg(esf.nps_score)::numeric, 1), 0) AS "npsFormation",
          coalesce(round(avg(esf.csat_score)::numeric, 1), 0) AS "csatFormation",
          count(esf.id) AS "totalReponses"
        FROM etablissements e
        JOIN etablissement_users eu ON eu.etablissement_id = e.id
        JOIN enquetes_satisfaction_formation esf ON esf.user_id = eu.id
        WHERE e.statut IN ('Production', 'Go-Live', 'Formation')
        GROUP BY e.id, e.nom
        HAVING count(esf.id) > 0
      ) t
    ), '[]'::jsonb),

    -- Etablissements by solution survey
    'etablissementsBySolution', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb)
      FROM (
        SELECT 
          e.id,
          e.nom,
          coalesce(round(avg(ess.satisfaction_solution)::numeric, 1), 0) AS "satisfactionSolution",
          coalesce(round(avg(ess.recommandation_collegues)::numeric, 1), 0) AS recommandation,
          count(ess.id) AS "totalReponses"
        FROM etablissements e
        JOIN enquetes_satisfaction_solution ess ON ess.etablissement_id = e.id
        WHERE e.statut IN ('Production', 'Go-Live', 'Formation')
        GROUP BY e.id, e.nom
        HAVING count(ess.id) > 0
      ) t
    ), '[]'::jsonb),

    -- Champions & struggling
    'etablissementsStats', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb)
      FROM (
        SELECT 
          e.id,
          e.nom,
          count(eu.id) AS "totalUsers",
          count(eu.id) FILTER (WHERE eu.statut_formation = 'forme') AS "formedUsers",
          CASE WHEN count(eu.id) > 0 
            THEN round((count(eu.id) FILTER (WHERE eu.statut_formation = 'forme'))::numeric / count(eu.id) * 100, 1)
            ELSE 0 END AS "tauxFormation"
        FROM etablissements e
        LEFT JOIN etablissement_users eu ON eu.etablissement_id = e.id
        WHERE e.statut IN ('Production', 'Go-Live', 'Formation')
        GROUP BY e.id, e.nom
      ) t
    ), '[]'::jsonb),

    -- Monthly evolution (formation + solution)
    'evolutionFormation', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.mois)
      FROM (
        SELECT 
          to_char(date_reponse, 'Mon YY') AS mois,
          to_char(date_reponse, 'YYYY-MM') AS mois_sort,
          round(avg(nps_score)::numeric, 1) AS "avgNps",
          round(avg(csat_score)::numeric, 1) AS "avgCsat",
          count(*) AS total
        FROM enquetes_satisfaction_formation
        GROUP BY to_char(date_reponse, 'Mon YY'), to_char(date_reponse, 'YYYY-MM')
        ORDER BY mois_sort
      ) t
    ), '[]'::jsonb),

    'evolutionSolution', coalesce((
      SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.mois)
      FROM (
        SELECT 
          to_char(date_reponse, 'Mon YY') AS mois,
          to_char(date_reponse, 'YYYY-MM') AS mois_sort,
          round(avg(satisfaction_solution)::numeric, 1) AS "avgSatisfaction",
          count(*) AS total
        FROM enquetes_satisfaction_solution
        GROUP BY to_char(date_reponse, 'Mon YY'), to_char(date_reponse, 'YYYY-MM')
        ORDER BY mois_sort
      ) t
    ), '[]'::jsonb)
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_jarvis_suggestion_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_jarvis_suggestion_stats(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_suggestions', COUNT(*),
    'accepted_count', COUNT(*) FILTER (WHERE action = 'accepted'),
    'rejected_count', COUNT(*) FILTER (WHERE action = 'rejected'),
    'dismissed_count', COUNT(*) FILTER (WHERE action = 'dismissed'),
    'executed_count', COUNT(*) FILTER (WHERE action = 'executed'),
    'acceptance_rate', CASE WHEN COUNT(*) > 0 
      THEN ROUND((COUNT(*) FILTER (WHERE action IN ('accepted', 'executed'))::numeric / COUNT(*)::numeric) * 100, 2)
      ELSE 0 END,
    'by_type', (
      SELECT jsonb_object_agg(
        suggestion_type,
        jsonb_build_object(
          'total', type_total,
          'accepted', type_accepted,
          'rate', CASE WHEN type_total > 0 
            THEN ROUND((type_accepted::numeric / type_total::numeric) * 100, 2)
            ELSE 0 END
        )
      )
      FROM (
        SELECT 
          suggestion_type,
          COUNT(*) as type_total,
          COUNT(*) FILTER (WHERE action IN ('accepted', 'executed')) as type_accepted
        FROM jarvis_suggestion_feedback
        WHERE user_id = p_user_id
        GROUP BY suggestion_type
      ) type_stats
    )
  ) INTO result
  FROM jarvis_suggestion_feedback
  WHERE user_id = p_user_id
  AND created_at > now() - interval '30 days';
  
  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_leaderboard(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_leaderboard(p_period text DEFAULT 'month'::text, p_team text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, avatar_url text, total_points integer, rank integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  WITH active_users AS (
    SELECT p.user_id, COALESCE(p.prenom||' '||p.nom, p.email) AS display_name, p.avatar_url
    FROM profiles p
    WHERE p.actif = true
  ),
  scored AS (
    SELECT u.user_id, u.display_name, u.avatar_url,
           public.compute_gamification_points(u.user_id, p_period) AS total_points
    FROM active_users u
  )
  SELECT s.user_id, s.display_name, s.avatar_url, s.total_points,
         (RANK() OVER (ORDER BY s.total_points DESC))::int AS rank
  FROM scored s
  WHERE s.total_points > 0
  ORDER BY s.total_points DESC
  LIMIT 50;
END;
$$;


--
-- Name: get_live_chat_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_live_chat_kpis() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH win AS (
    SELECT *
    FROM public.live_chat_conversations
    WHERE created_at >= (now() - interval '30 days')
  )
  SELECT jsonb_build_object(
    'total_conversations', (SELECT COUNT(*) FROM win),
    'active_conversations', (SELECT COUNT(*) FROM win WHERE status = 'active'),
    'waiting_conversations', (SELECT COUNT(*) FROM win WHERE status = 'waiting'),
    'resolved_today', (
      SELECT COUNT(*) FROM win
      WHERE status = 'resolved'
        AND resolved_at >= date_trunc('day', now())
    ),
    'avg_response_time_minutes', COALESCE((
      SELECT ROUND(AVG(EXTRACT(EPOCH FROM (first_response_at - created_at)) / 60.0))
      FROM win WHERE first_response_at IS NOT NULL
    ), 0),
    'avg_resolution_time_minutes', COALESCE((
      SELECT ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)) / 60.0))
      FROM win WHERE resolved_at IS NOT NULL
    ), 0),
    'satisfaction_avg', COALESCE((
      SELECT ROUND(AVG(satisfaction_rating)::numeric, 1)
      FROM win WHERE satisfaction_rating IS NOT NULL
    ), 0),
    'escalation_rate', COALESCE((
      SELECT ROUND((COUNT(*) FILTER (WHERE status = 'escalated')::numeric * 100.0 / NULLIF(COUNT(*), 0))::numeric, 1)
      FROM win
    ), 0),
    'agents_online', (SELECT COUNT(*) FROM public.live_chat_agents WHERE is_available = true)
  );
$$;


--
-- Name: get_next_document_version(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_document_version(p_tache_id uuid, p_document_type text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_version INTEGER;
BEGIN
  SELECT COALESCE(MAX(version_number), 0)
  INTO v_max_version
  FROM taches_documents
  WHERE tache_id = p_tache_id
    AND document_type = p_document_type;
  
  RETURN v_max_version + 1;
END;
$$;


--
-- Name: get_phase_categories(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_phase_categories(p_statut text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_statut IN ('Prospect', 'Attente RDV', 'RDV pris', 'Dans les RDV', 
                  'Attente post RDV', 'Etude émise', 'Négociation', 'Bloqué') THEN
    RETURN ARRAY['commercial'];
  ELSIF p_statut IN ('Contractuel', 'Contractualisation', 'Conformité', 
                     'Déploiement', 'Formation', 'Go-Live') THEN
    RETURN ARRAY['contractuel', 'conformité', 'configuration', 
                 'déploiement', 'formation', 'documentation', 'go-live'];
  ELSIF p_statut = 'Production' THEN
    RETURN ARRAY['suivi production', 'suivi', 'support'];
  ELSE
    RETURN ARRAY['commercial', 'contractuel', 'conformité', 'configuration', 
                 'déploiement', 'formation', 'documentation', 'go-live',
                 'suivi production', 'suivi', 'support'];
  END IF;
END;
$$;


--
-- Name: get_phase_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_phase_counts() RETURNS TABLE(statut text, count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT statut::text, COUNT(*)::bigint
  FROM public.etablissements
  WHERE statut IS NOT NULL
  GROUP BY statut;
$$;


--
-- Name: get_phase_order(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_phase_order(p_statut text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_statut IN ('Prospect', 'Attente RDV', 'RDV pris', 'Dans les RDV', 
                  'Attente post RDV', 'Etude émise', 'Négociation', 'Bloqué') THEN
    RETURN 1;
  ELSIF p_statut IN ('Contractuel', 'Contractualisation', 'Conformité', 
                     'Déploiement', 'Formation', 'Go-Live') THEN
    RETURN 2;
  ELSIF p_statut = 'Production' THEN
    RETURN 3;
  ELSE
    RETURN 0;
  END IF;
END;
$$;


--
-- Name: get_pipeline_breakdown(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pipeline_breakdown() RETURNS TABLE(statut text, count bigint, valeur_potentielle numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    e.statut::text,
    COUNT(*) as count,
    COALESCE(SUM(
      CASE 
        WHEN e.modele_statique_succes IS NOT NULL AND e.modele_statique_succes != '' 
        THEN CAST(e.modele_statique_succes AS numeric)
        WHEN e.pallier_vise IS NOT NULL AND e.nombre_passages_urgences_annuel IS NOT NULL 
        THEN e.nombre_passages_urgences_annuel * 
          CASE e.pallier_vise
            WHEN 'Pallier 1' THEN 2.5
            WHEN 'Pallier 2' THEN 3.0
            WHEN 'Pallier 3' THEN 3.5
            WHEN 'Pallier 4' THEN 4.0
            ELSE 3.0
          END
        WHEN e.nombre_passages_urgences_annuel IS NOT NULL 
        THEN e.nombre_passages_urgences_annuel * 1.5
        ELSE 0
      END
    ), 0) as valeur_potentielle
  FROM public.etablissements e
  GROUP BY e.statut
  ORDER BY COUNT(*) DESC;
END;
$$;


--
-- Name: get_profile_id_for_auth_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profile_id_for_auth_user() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT id FROM profiles WHERE user_id = auth.uid() LIMIT 1;
$$;


--
-- Name: get_profile_rh_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profile_rh_data(p_profile_id uuid) RETURNS TABLE(numero_secu text, iban text, date_entree date, type_contrat text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT can_manage_rh_data() THEN
    RAISE EXCEPTION 'Access denied: RH permissions required';
  END IF;
  
  RETURN QUERY
  SELECT p.numero_securite_sociale, p.iban, p.date_embauche, p.type_contrat
  FROM profiles p WHERE p.id = p_profile_id;
END;
$$;


--
-- Name: get_profiles_public(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profiles_public() RETURNS TABLE(id uuid, user_id uuid, prenom text, nom text, email text, avatar_url text, linkedin_url text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT 
    p.id,
    p.user_id,
    p.prenom,
    p.nom,
    p.email,
    p.avatar_url,
    p.linkedin_url
  FROM profiles p
  WHERE p.actif = true
  ORDER BY p.nom, p.prenom;
$$;


--
-- Name: get_profiles_with_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profiles_with_roles() RETURNS TABLE(id uuid, user_id uuid, prenom text, nom text, email text, actif boolean, created_at timestamp with time zone, updated_at timestamp with time zone, role text, telephone text, fonction text, date_embauche date, type_contrat text, salaire_brut numeric, avatar_url text, linkedin_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    p.id,
    p.user_id,
    p.prenom,
    p.nom,
    p.email,
    p.actif,
    p.created_at,
    p.updated_at,
    COALESCE(ur.role::text, 'commercial') as role,
    p.telephone,
    p.fonction,
    p.date_embauche,
    p.type_contrat,
    p.salaire_brut,
    p.avatar_url,
    p.linkedin_url
  FROM public.profiles p
  LEFT JOIN public.user_roles ur ON ur.user_id = p.user_id
  ORDER BY p.nom, p.prenom;
$$;


--
-- Name: get_reaction_counts(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reaction_counts(target_id uuid, target_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF target_type = 'post' THEN
    SELECT jsonb_object_agg(emoji, count)
    INTO result
    FROM (
      SELECT emoji, COUNT(*)::int as count
      FROM forum_reactions
      WHERE post_id = target_id
      GROUP BY emoji
    ) counts;
  ELSIF target_type = 'comment' THEN
    SELECT jsonb_object_agg(emoji, count)
    INTO result
    FROM (
      SELECT emoji, COUNT(*)::int as count
      FROM forum_reactions
      WHERE comment_id = target_id
      GROUP BY emoji
    ) counts;
  END IF;
  
  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_region_from_department(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_region_from_department(department_name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN CASE LOWER(department_name)
    WHEN 'ain' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'allier' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'ardèche' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'cantal' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'drôme' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'isère' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'loire' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'haute-loire' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'puy-de-dôme' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'rhône' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'savoie' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'haute-savoie' THEN 'Auvergne-Rhône-Alpes'
    WHEN 'côte-d''or' THEN 'Bourgogne-Franche-Comté'
    WHEN 'doubs' THEN 'Bourgogne-Franche-Comté'
    WHEN 'jura' THEN 'Bourgogne-Franche-Comté'
    WHEN 'nièvre' THEN 'Bourgogne-Franche-Comté'
    WHEN 'haute-saône' THEN 'Bourgogne-Franche-Comté'
    WHEN 'saône-et-loire' THEN 'Bourgogne-Franche-Comté'
    WHEN 'territoire de belfort' THEN 'Bourgogne-Franche-Comté'
    WHEN 'yonne' THEN 'Bourgogne-Franche-Comté'
    WHEN 'côtes-d''armor' THEN 'Bretagne'
    WHEN 'finistère' THEN 'Bretagne'
    WHEN 'ille-et-vilaine' THEN 'Bretagne'
    WHEN 'morbihan' THEN 'Bretagne'
    WHEN 'cher' THEN 'Centre-Val de Loire'
    WHEN 'eure-et-loir' THEN 'Centre-Val de Loire'
    WHEN 'indre' THEN 'Centre-Val de Loire'
    WHEN 'indre-et-loire' THEN 'Centre-Val de Loire'
    WHEN 'loir-et-cher' THEN 'Centre-Val de Loire'
    WHEN 'loiret' THEN 'Centre-Val de Loire'
    ELSE department_name
  END;
END;
$$;


--
-- Name: get_report_data(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_report_data(source_key text, params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  result JSONB;
  date_start DATE;
  date_end DATE;
BEGIN
  -- Authentification obligatoire
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentification requise';
  END IF;

  -- Période optionnelle (par défaut 12 derniers mois)
  date_start := COALESCE((params->>'date_start')::date, (CURRENT_DATE - INTERVAL '12 months')::date);
  date_end := COALESCE((params->>'date_end')::date, CURRENT_DATE);

  CASE source_key

    WHEN 'etablissements_pipeline' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
      ) INTO result
      FROM (
        SELECT statut::text AS statut, COUNT(*) AS cnt
        FROM etablissements
        WHERE statut IS NOT NULL
        GROUP BY statut
      ) s;

    WHEN 'etablissements_par_statut' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt)), '[]'::jsonb)
      ) INTO result
      FROM (
        SELECT statut::text AS statut, COUNT(*) AS cnt
        FROM etablissements
        WHERE created_at BETWEEN date_start AND date_end + INTERVAL '1 day'
        GROUP BY statut
      ) s;

    WHEN 'factures_par_mois' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('mois', mois, 'total_ht', total_ht, 'total_ttc', total_ttc, 'count', cnt) ORDER BY mois), '[]'::jsonb)
      ) INTO result
      FROM (
        SELECT to_char(date_emission, 'YYYY-MM') AS mois,
               SUM(montant_ht)::numeric AS total_ht,
               SUM(montant_ttc)::numeric AS total_ttc,
               COUNT(*) AS cnt
        FROM factures
        WHERE date_emission BETWEEN date_start AND date_end
        GROUP BY 1
      ) s;

    WHEN 'factures_impayees' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt, 'total_ttc', total_ttc)), '[]'::jsonb)
      ) INTO result
      FROM (
        SELECT statut, COUNT(*) AS cnt, SUM(montant_ttc)::numeric AS total_ttc
        FROM factures
        WHERE statut IN ('emise','envoyee','en_retard','impayee') AND date_echeance < CURRENT_DATE
        GROUP BY statut
      ) s;

    WHEN 'devis_par_statut' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt)), '[]'::jsonb)
      ) INTO result
      FROM (SELECT statut, COUNT(*) AS cnt FROM devis GROUP BY statut) s;

    WHEN 'tresorerie_revenus_par_categorie' THEN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='tresorerie_mouvements') THEN
        EXECUTE $q$
          SELECT jsonb_build_object(
            'rows', COALESCE(jsonb_agg(jsonb_build_object('categorie', categorie, 'total', total)), '[]'::jsonb)
          )
          FROM (
            SELECT COALESCE(categorie,'Non catégorisé') AS categorie, SUM(montant)::numeric AS total
            FROM tresorerie_mouvements
            WHERE type = 'revenu' AND date_mouvement BETWEEN $1 AND $2
            GROUP BY 1
          ) s
        $q$ INTO result USING date_start, date_end;
      ELSE
        result := jsonb_build_object('rows', '[]'::jsonb, 'note', 'tresorerie_mouvements indisponible');
      END IF;

    WHEN 'tresorerie_depenses_par_categorie' THEN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='tresorerie_mouvements') THEN
        EXECUTE $q$
          SELECT jsonb_build_object(
            'rows', COALESCE(jsonb_agg(jsonb_build_object('categorie', categorie, 'total', total)), '[]'::jsonb)
          )
          FROM (
            SELECT COALESCE(categorie,'Non catégorisé') AS categorie, ABS(SUM(montant))::numeric AS total
            FROM tresorerie_mouvements
            WHERE type = 'depense' AND date_mouvement BETWEEN $1 AND $2
            GROUP BY 1
          ) s
        $q$ INTO result USING date_start, date_end;
      ELSE
        result := jsonb_build_object('rows', '[]'::jsonb, 'note', 'tresorerie_mouvements indisponible');
      END IF;

    WHEN 'taches_par_statut' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt)), '[]'::jsonb)
      ) INTO result
      FROM (SELECT statut, COUNT(*) AS cnt FROM taches GROUP BY statut) s;

    WHEN 'support_tickets_par_statut' THEN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='support_tickets') THEN
        EXECUTE $q$
          SELECT jsonb_build_object(
            'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt)), '[]'::jsonb)
          )
          FROM (SELECT statut, COUNT(*) AS cnt FROM support_tickets GROUP BY statut) s
        $q$ INTO result;
      ELSE
        result := jsonb_build_object('rows','[]'::jsonb,'note','support_tickets indisponible');
      END IF;

    WHEN 'rh_masse_salariale' THEN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='rh_collaborateurs') THEN
        EXECUTE $q$
          SELECT jsonb_build_object(
            'total_brut', COALESCE(SUM(salaire_brut),0),
            'total_net', COALESCE(SUM(salaire_net),0),
            'effectif', COUNT(*)
          )
          FROM rh_collaborateurs
          WHERE statut = 'actif'
        $q$ INTO result;
      ELSE
        result := jsonb_build_object('note','rh_collaborateurs indisponible');
      END IF;

    WHEN 'formations_sessions' THEN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='formation_sessions') THEN
        EXECUTE $q$
          SELECT jsonb_build_object(
            'rows', COALESCE(jsonb_agg(jsonb_build_object('statut', statut, 'count', cnt)), '[]'::jsonb)
          )
          FROM (SELECT statut, COUNT(*) AS cnt FROM formation_sessions WHERE created_at BETWEEN $1 AND $2 + INTERVAL '1 day' GROUP BY statut) s
        $q$ INTO result USING date_start, date_end;
      ELSE
        result := jsonb_build_object('rows','[]'::jsonb,'note','formation_sessions indisponible');
      END IF;

    WHEN 'csm_health_distribution' THEN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='csm_account_health') THEN
        EXECUTE $q$
          SELECT jsonb_build_object(
            'rows', COALESCE(jsonb_agg(jsonb_build_object('niveau', niveau, 'count', cnt)), '[]'::jsonb)
          )
          FROM (
            SELECT CASE WHEN health_score >= 80 THEN 'Excellent' WHEN health_score >= 60 THEN 'Bon' WHEN health_score >= 40 THEN 'Moyen' ELSE 'Faible' END AS niveau, COUNT(*) AS cnt
            FROM csm_account_health GROUP BY 1
          ) s
        $q$ INTO result;
      ELSE
        result := jsonb_build_object('rows','[]'::jsonb,'note','csm_account_health indisponible');
      END IF;

    WHEN 'churn_risk_distribution' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('tier', tier, 'count', cnt)), '[]'::jsonb)
      ) INTO result
      FROM (SELECT risk_tier AS tier, COUNT(*) AS cnt FROM churn_predictions GROUP BY risk_tier) s;

    WHEN 'sales_forecast_pipeline' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('periode', periode, 'montant_prevu', montant_prevu) ORDER BY periode), '[]'::jsonb)
      ) INTO result
      FROM (SELECT periode::text, SUM(montant_prevu)::numeric AS montant_prevu FROM ca_forecasts WHERE periode BETWEEN date_start::text AND date_end::text GROUP BY periode) s;

    WHEN 'activity_volume' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('jour', jour, 'count', cnt) ORDER BY jour), '[]'::jsonb)
      ) INTO result
      FROM (
        SELECT to_char(created_at, 'YYYY-MM-DD') AS jour, COUNT(*) AS cnt
        FROM interactions
        WHERE created_at BETWEEN date_start AND date_end + INTERVAL '1 day'
        GROUP BY 1
      ) s;

    WHEN 'mrr_evolution' THEN
      SELECT jsonb_build_object(
        'rows', COALESCE(jsonb_agg(jsonb_build_object('mois', mois, 'mrr', mrr) ORDER BY mois), '[]'::jsonb)
      ) INTO result
      FROM (
        SELECT to_char(date_emission, 'YYYY-MM') AS mois, SUM(montant_ht)::numeric AS mrr
        FROM factures
        WHERE date_emission BETWEEN date_start AND date_end AND statut IN ('payee','envoyee','emise')
        GROUP BY 1
      ) s;

    ELSE
      RAISE EXCEPTION 'Source non autorisée: %. Sources valides: etablissements_pipeline, etablissements_par_statut, factures_par_mois, factures_impayees, devis_par_statut, tresorerie_revenus_par_categorie, tresorerie_depenses_par_categorie, taches_par_statut, support_tickets_par_statut, rh_masse_salariale, formations_sessions, csm_health_distribution, churn_risk_distribution, sales_forecast_pipeline, activity_volume, mrr_evolution', source_key;
  END CASE;

  RETURN COALESCE(result, jsonb_build_object('rows', '[]'::jsonb));
END;
$_$;


--
-- Name: FUNCTION get_report_data(source_key text, params jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_report_data(source_key text, params jsonb) IS 'Moteur unifié de rapports OpenPulse : 16 sources whitelistées (factures, devis, etablissements, treso, RH, support, formations, csm, churn, forecast, MRR, activité). Utilisé par useReportData, report-export et le tool Jarvis run_custom_report.';


--
-- Name: get_rh_tresorerie_reconciliation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rh_tresorerie_reconciliation() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_salaires int;
  v_total_depenses int;
  v_salaires_non_synchro int;
  v_depenses_orphelines int;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'rh') OR public.has_role(auth.uid(), 'manager')) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COUNT(*) INTO v_total_salaires FROM public.rh_salaires_mensuels;
  SELECT COUNT(*) INTO v_total_depenses FROM public.tresorerie_depenses WHERE source = 'rh_salaires';

  SELECT COUNT(*) INTO v_salaires_non_synchro
  FROM public.rh_salaires_mensuels s
  WHERE NOT EXISTS (
    SELECT 1 FROM public.tresorerie_depenses d
    WHERE d.source = 'rh_salaires' AND d.source_id = s.id
  );

  SELECT COUNT(*) INTO v_depenses_orphelines
  FROM public.tresorerie_depenses d
  WHERE d.source = 'rh_salaires'
    AND NOT EXISTS (
      SELECT 1 FROM public.rh_salaires_mensuels s WHERE s.id = d.source_id
    );

  RETURN jsonb_build_object(
    'totalSalaires', v_total_salaires,
    'totalDepenses', v_total_depenses,
    'salairesNonSynchro', v_salaires_non_synchro,
    'depensesOrphelines', v_depenses_orphelines,
    'isSync', (v_salaires_non_synchro = 0 AND v_depenses_orphelines = 0)
  );
END;
$$;


--
-- Name: get_sales_forecast(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_forecast(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start date := COALESCE(p_start, date_trunc('year', now())::date);
  v_end   date := COALESCE(p_end, (date_trunc('year', now()) + interval '1 year - 1 day')::date);
  v_q_start date := date_trunc('quarter', now())::date;
  v_q_end   date := (date_trunc('quarter', now()) + interval '3 months - 1 day')::date;
  v_nq_start date := (date_trunc('quarter', now()) + interval '3 months')::date;
  v_nq_end   date := (date_trunc('quarter', now()) + interval '6 months - 1 day')::date;
  v_period_len int := (v_end - v_start) + 1;
  v_prev_end date := v_start - 1;
  v_prev_start date := v_start - v_period_len;
  v_result jsonb;
BEGIN
  IF NOT (
    public.has_role(auth.uid(), 'admin')
    OR public.has_role(auth.uid(), 'direction')
    OR public.has_role(auth.uid(), 'commercial')
    OR public.has_role(auth.uid(), 'copil')
  ) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  WITH deals AS (
    SELECT
      e.id,
      e.nom,
      e.statut::text AS statut_code,
      e.commercial_id,
      COALESCE(e.date_previsionnelle_signature, e.date_signature, e.updated_at::date) AS closing_date,
      CASE
        WHEN e.modele_statique_succes IS NOT NULL AND e.modele_statique_succes <> ''
          THEN CAST(e.modele_statique_succes AS numeric)
        WHEN e.pallier_vise IS NOT NULL AND e.nombre_passages_urgences_annuel IS NOT NULL THEN
          e.nombre_passages_urgences_annuel *
          CASE e.pallier_vise
            WHEN 'Pallier 1' THEN 2.5 WHEN 'Pallier 2' THEN 3.0
            WHEN 'Pallier 3' THEN 3.5 WHEN 'Pallier 4' THEN 4.0
            ELSE 3.0
          END
        WHEN e.nombre_passages_urgences_annuel IS NOT NULL
          THEN e.nombre_passages_urgences_annuel * 1.5
        ELSE 0
      END::numeric AS deal_value
    FROM public.etablissements e
  ),
  enriched AS (
    SELECT
      d.*,
      COALESCE((rd.metadata->>'probability')::numeric, 0) AS probability,
      COALESCE(rd.metadata->>'phase', 'commercial') AS phase_group,
      COALESCE(rd.label, d.statut_code) AS statut_label,
      d.deal_value * COALESCE((rd.metadata->>'probability')::numeric, 0) / 100.0 AS weighted_value,
      to_char(d.closing_date, 'YYYY-"Q"Q') AS quarter_label,
      EXTRACT(YEAR FROM d.closing_date)::int AS year_n,
      EXTRACT(QUARTER FROM d.closing_date)::int AS quarter_n
    FROM deals d
    LEFT JOIN public.reference_data rd
      ON rd.type = 'statut_etablissement' AND rd.code = d.statut_code
  ),
  in_range AS (
    SELECT * FROM enriched WHERE closing_date BETWEEN v_start AND v_end
  ),
  in_prev AS (
    SELECT * FROM enriched WHERE closing_date BETWEEN v_prev_start AND v_prev_end
  ),
  quotas AS (
    SELECT
      to_char(make_date(annee, ((trimestre - 1) * 3) + 1, 1), 'YYYY-"Q"Q') AS quarter_label,
      SUM(cible_ca) AS target
    FROM public.objectifs_commerciaux
    WHERE trimestre IS NOT NULL AND mois IS NULL
      AND make_date(annee, ((trimestre - 1) * 3) + 1, 1) BETWEEN v_start AND v_end
    GROUP BY annee, trimestre
  ),
  kpis AS (
    SELECT
      COALESCE(SUM(deal_value) FILTER (WHERE probability > 0 AND probability < 100), 0) AS pipeline_raw,
      COALESCE(SUM(weighted_value) FILTER (WHERE probability < 100), 0) AS pipeline_weighted,
      COALESCE(SUM(weighted_value) FILTER (WHERE closing_date BETWEEN v_q_start AND v_q_end AND probability < 100), 0) AS current_quarter,
      COALESCE(SUM(weighted_value) FILTER (WHERE closing_date BETWEEN v_nq_start AND v_nq_end AND probability < 100), 0) AS next_quarter,
      COALESCE(SUM(deal_value) FILTER (WHERE probability = 100), 0) AS won_total,
      (SELECT COALESCE(SUM(target), 0) FROM quotas) AS target_total,
      (SELECT COALESCE(SUM(target), 0) FROM quotas q WHERE q.quarter_label = to_char(now(), 'YYYY-"Q"Q')) AS current_quarter_target
    FROM enriched
  ),
  prev_kpis AS (
    SELECT
      COALESCE(SUM(deal_value) FILTER (WHERE probability > 0 AND probability < 100), 0) AS pipeline_raw,
      COALESCE(SUM(weighted_value) FILTER (WHERE probability < 100), 0) AS pipeline_weighted,
      COALESCE(SUM(deal_value) FILTER (WHERE probability = 100), 0) AS won_total
    FROM in_prev
  ),
  by_quarter AS (
    SELECT jsonb_agg(jsonb_build_object(
      'quarter', quarter_label,
      'raw', raw_total,
      'weighted', weighted_total,
      'won', won_total,
      'target', target,
      'count', deal_count
    ) ORDER BY quarter_label) AS data
    FROM (
      SELECT
        ir.quarter_label,
        SUM(ir.deal_value) FILTER (WHERE ir.probability < 100) AS raw_total,
        SUM(ir.weighted_value) FILTER (WHERE ir.probability < 100) AS weighted_total,
        SUM(ir.deal_value) FILTER (WHERE ir.probability = 100) AS won_total,
        COUNT(*) AS deal_count,
        COALESCE(MAX(q.target), 0) AS target
      FROM in_range ir
      LEFT JOIN quotas q ON q.quarter_label = ir.quarter_label
      GROUP BY ir.quarter_label
    ) qq
  ),
  by_commercial AS (
    SELECT jsonb_agg(jsonb_build_object(
      'user_id', user_id,
      'display_name', display_name,
      'raw', raw_total,
      'weighted', weighted_total,
      'won', won_total,
      'deals_count', deals_count
    ) ORDER BY weighted_total DESC NULLS LAST) AS data
    FROM (
      SELECT
        ir.commercial_id AS user_id,
        COALESCE(
          NULLIF(TRIM(COALESCE(p.prenom,'') || ' ' || COALESCE(p.nom,'')), ''),
          p.email,
          'Non assigné'
        ) AS display_name,
        SUM(ir.deal_value) FILTER (WHERE ir.probability < 100) AS raw_total,
        SUM(ir.weighted_value) FILTER (WHERE ir.probability < 100) AS weighted_total,
        SUM(ir.deal_value) FILTER (WHERE ir.probability = 100) AS won_total,
        COUNT(*) FILTER (WHERE ir.probability < 100) AS deals_count
      FROM in_range ir
      LEFT JOIN public.profiles p ON p.id = ir.commercial_id
      GROUP BY ir.commercial_id, p.prenom, p.nom, p.email
    ) c
  ),
  by_phase AS (
    SELECT jsonb_agg(jsonb_build_object(
      'statut', statut_code,
      'label', statut_label,
      'phase_group', phase_group,
      'probability', probability,
      'raw', raw_total,
      'weighted', weighted_total,
      'count', deal_count
    ) ORDER BY probability ASC) AS data
    FROM (
      SELECT
        statut_code,
        MAX(statut_label) AS statut_label,
        MAX(phase_group) AS phase_group,
        MAX(probability) AS probability,
        SUM(deal_value) AS raw_total,
        SUM(weighted_value) AS weighted_total,
        COUNT(*) AS deal_count
      FROM in_range
      WHERE probability < 100
      GROUP BY statut_code
    ) ph
  ),
  by_phase_group AS (
    SELECT jsonb_agg(jsonb_build_object(
      'phase_group', phase_group,
      'raw', raw_total,
      'weighted', weighted_total,
      'count', deal_count
    ) ORDER BY phase_group) AS data
    FROM (
      SELECT
        phase_group,
        SUM(deal_value) FILTER (WHERE probability < 100) AS raw_total,
        SUM(weighted_value) FILTER (WHERE probability < 100) AS weighted_total,
        COUNT(*) FILTER (WHERE probability < 100) AS deal_count
      FROM in_range
      GROUP BY phase_group
    ) pg
  ),
  top_deals AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id', id,
      'nom', nom,
      'statut', statut_code,
      'probability', probability,
      'deal_value', deal_value,
      'weighted_value', weighted_value,
      'closing_date', closing_date
    ) ORDER BY weighted_value DESC) AS data
    FROM (
      SELECT id, nom, statut_code, probability, deal_value, weighted_value, closing_date
      FROM in_range
      WHERE probability > 0 AND probability < 100 AND deal_value > 0
      ORDER BY weighted_value DESC
      LIMIT 10
    ) td
  ),
  hot_deals AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id', id,
      'nom', nom,
      'statut', statut_code,
      'probability', probability,
      'deal_value', deal_value,
      'weighted_value', weighted_value,
      'closing_date', closing_date
    ) ORDER BY weighted_value DESC) AS data
    FROM (
      SELECT id, nom, statut_code, probability, deal_value, weighted_value, closing_date
      FROM in_range
      WHERE probability >= 65 AND probability < 100 AND deal_value > 0
      ORDER BY weighted_value DESC
      LIMIT 10
    ) hd
  ),
  at_risk_deals AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id', id,
      'nom', nom,
      'statut', statut_code,
      'probability', probability,
      'deal_value', deal_value,
      'weighted_value', weighted_value,
      'closing_date', closing_date
    ) ORDER BY closing_date ASC) AS data
    FROM (
      SELECT id, nom, statut_code, probability, deal_value, weighted_value, closing_date
      FROM enriched
      WHERE probability > 0 AND probability < 100
        AND closing_date < CURRENT_DATE
      ORDER BY closing_date ASC
      LIMIT 10
    ) ar
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('start', v_start, 'end', v_end),
    'previous_range', jsonb_build_object('start', v_prev_start, 'end', v_prev_end),
    'kpis', (SELECT to_jsonb(kpis) FROM kpis),
    'previous_period', (SELECT to_jsonb(prev_kpis) FROM prev_kpis),
    'by_quarter',     COALESCE((SELECT data FROM by_quarter), '[]'::jsonb),
    'by_commercial',  COALESCE((SELECT data FROM by_commercial), '[]'::jsonb),
    'by_phase',       COALESCE((SELECT data FROM by_phase), '[]'::jsonb),
    'by_phase_group', COALESCE((SELECT data FROM by_phase_group), '[]'::jsonb),
    'top_deals',      COALESCE((SELECT data FROM top_deals), '[]'::jsonb),
    'hot_deals',      COALESCE((SELECT data FROM hot_deals), '[]'::jsonb),
    'at_risk_deals',  COALESCE((SELECT data FROM at_risk_deals), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_sales_forecast_v2(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_forecast_v2(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start date := COALESCE(p_start, date_trunc('year', now())::date);
  v_end   date := COALESCE(p_end, (date_trunc('year', now()) + interval '1 year - 1 day')::date);
  v_q_start date := date_trunc('quarter', now())::date;
  v_q_end   date := (date_trunc('quarter', now()) + interval '3 months - 1 day')::date;
  v_result jsonb;
BEGIN
  IF NOT (
    public.has_role(auth.uid(), 'admin')
    OR public.has_role(auth.uid(), 'direction')
    OR public.has_role(auth.uid(), 'commercial')
    OR public.has_role(auth.uid(), 'copil')
  ) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  WITH deals AS (
    SELECT
      e.id,
      e.nom,
      e.statut::text AS statut_code,
      e.commercial_id,
      COALESCE(e.date_previsionnelle_signature, e.date_signature, e.updated_at::date) AS closing_date,
      CASE
        WHEN e.modele_statique_succes IS NOT NULL AND e.modele_statique_succes <> ''
          THEN CAST(e.modele_statique_succes AS numeric)
        WHEN e.pallier_vise IS NOT NULL AND e.nombre_passages_urgences_annuel IS NOT NULL THEN
          e.nombre_passages_urgences_annuel *
          CASE e.pallier_vise
            WHEN 'Pallier 1' THEN 2.5 WHEN 'Pallier 2' THEN 3.0
            WHEN 'Pallier 3' THEN 3.5 WHEN 'Pallier 4' THEN 4.0
            ELSE 3.0
          END
        WHEN e.nombre_passages_urgences_annuel IS NOT NULL
          THEN e.nombre_passages_urgences_annuel * 1.5
        ELSE 0
      END::numeric AS deal_value,
      public.compute_deal_probability_v2(e.id) AS proba_v2,
      COALESCE((SELECT (rd.metadata->>'probability')::numeric FROM public.reference_data rd WHERE rd.type='statut_etablissement' AND rd.code = e.statut::text LIMIT 1), 0) AS proba_v1
    FROM public.etablissements e
    WHERE COALESCE(e.date_previsionnelle_signature, e.date_signature, e.updated_at::date) BETWEEN v_start AND v_end
  ),
  enriched AS (
    SELECT
      d.*,
      COALESCE((d.proba_v2->>'probability')::numeric, 0) AS probability_v2,
      d.deal_value * COALESCE((d.proba_v2->>'probability')::numeric, 0) / 100.0 AS weighted_v2,
      d.deal_value * d.proba_v1 / 100.0 AS weighted_v1
    FROM deals d
  ),
  kpis AS (
    SELECT
      COALESCE(SUM(deal_value) FILTER (WHERE probability_v2 > 0 AND probability_v2 < 100), 0) AS pipeline_raw,
      COALESCE(SUM(weighted_v2) FILTER (WHERE probability_v2 < 100), 0) AS pipeline_weighted_v2,
      COALESCE(SUM(weighted_v1) FILTER (WHERE proba_v1 < 100), 0) AS pipeline_weighted_v1,
      COALESCE(SUM(weighted_v2) FILTER (WHERE closing_date BETWEEN v_q_start AND v_q_end AND probability_v2 < 100), 0) AS current_quarter_v2,
      COALESCE(SUM(deal_value) FILTER (WHERE probability_v2 >= 100), 0) AS won_total
    FROM enriched
  ),
  top_v2 AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id', id,
      'nom', nom,
      'statut', statut_code,
      'probability_v1', proba_v1,
      'probability_v2', probability_v2,
      'delta', round(probability_v2 - proba_v1, 1),
      'deal_value', deal_value,
      'weighted_v1', round(weighted_v1, 0),
      'weighted_v2', round(weighted_v2, 0),
      'closing_date', closing_date,
      'factors', proba_v2->'factors'
    ) ORDER BY weighted_v2 DESC) AS items
    FROM (SELECT * FROM enriched WHERE probability_v2 > 0 AND probability_v2 < 100 ORDER BY weighted_v2 DESC LIMIT 20) sub
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('start', v_start, 'end', v_end),
    'kpis', (SELECT row_to_json(k)::jsonb FROM kpis k),
    'top_deals', COALESCE((SELECT items FROM top_v2), '[]'::jsonb),
    'model_version', 'v2.0',
    'computed_at', now()
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_scoring_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scoring_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_commercial_statuts text[] := ARRAY[
    'Prospect','Contacté','Attente RDV','Reporté','RDV pris','Dans les RDV',
    'Attente post RDV','Etude émise','Négociation','Bloqué'
  ];
BEGIN
  IF NOT public._scoring_can_read() THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  WITH base AS (
    SELECT
      e.id, e.nom, e.statut::text AS statut, e.commercial_id,
      COALESCE(e.score_conversion, 0) AS score,
      COALESCE(e.behavioral_score, 0) AS behavioral_score,
      COALESCE(e.engagement_velocity, 0) AS velocity,
      e.last_engagement_at,
      e.scoring_snoozed_until,
      rd.metadata->>'phase' AS phase,
      COALESCE((rd.metadata->>'probability')::int, 0) AS probability
    FROM public.etablissements e
    LEFT JOIN public.reference_data rd
      ON rd.type = 'statut_etablissement' AND rd.label = e.statut::text
    WHERE e.statut::text = ANY (v_commercial_statuts)
      AND (e.scoring_snoozed_until IS NULL OR e.scoring_snoozed_until < CURRENT_DATE)
  ),
  prev_snapshot AS (
    SELECT etablissement_id, score
    FROM (
      SELECT etablissement_id, score,
             ROW_NUMBER() OVER (PARTITION BY etablissement_id ORDER BY computed_at DESC) AS rn
      FROM public.prospect_score_history
      WHERE computed_at < now() - interval '6 days'
        AND computed_at >= now() - interval '10 days'
    ) t WHERE rn = 1
  ),
  kpis AS (
    SELECT
      COUNT(*)::int AS total,
      COUNT(*) FILTER (WHERE score >= 80)::int AS hot,
      COUNT(*) FILTER (WHERE score BETWEEN 60 AND 79)::int AS warm,
      COUNT(*) FILTER (WHERE score BETWEEN 40 AND 59)::int AS working,
      COUNT(*) FILTER (WHERE score < 40)::int AS cold,
      COALESCE(SUM(probability * 0.01 * 1500)::int, 0) AS weighted_mrr_potential,
      AVG(score)::numeric(10,2) AS avg_score
    FROM base
  ),
  prev_kpis AS (
    SELECT
      COUNT(*)::int AS total,
      COUNT(*) FILTER (WHERE score >= 80)::int AS hot,
      COUNT(*) FILTER (WHERE score BETWEEN 60 AND 79)::int AS warm,
      COUNT(*) FILTER (WHERE score BETWEEN 40 AND 59)::int AS working,
      COUNT(*) FILTER (WHERE score < 40)::int AS cold
    FROM prev_snapshot
  ),
  by_phase AS (
    SELECT phase, COUNT(*)::int AS count, AVG(score)::int AS avg_score
    FROM base WHERE phase IS NOT NULL GROUP BY phase
  ),
  by_status AS (
    SELECT statut, COUNT(*)::int AS count
    FROM base GROUP BY statut ORDER BY COUNT(*) DESC
  ),
  channels AS (
    SELECT channel::text AS channel, COUNT(*)::int AS touchpoints, SUM(weight)::numeric AS total_weight
    FROM public.attribution_touchpoints t
    WHERE t.etablissement_id IN (SELECT id FROM base)
      AND t.occurred_at > now() - interval '90 days'
    GROUP BY channel ORDER BY SUM(weight) DESC LIMIT 8
  ),
  top_score AS (
    SELECT id, nom, score, behavioral_score, velocity, last_engagement_at, statut
    FROM base ORDER BY score DESC, behavioral_score DESC LIMIT 10
  ),
  hot_streaks AS (
    SELECT id, nom, score, behavioral_score, velocity, last_engagement_at, statut
    FROM base WHERE velocity > 0 ORDER BY velocity DESC LIMIT 10
  ),
  to_relaunch AS (
    SELECT id, nom, score, behavioral_score, velocity, last_engagement_at, statut
    FROM base
    WHERE velocity < 0
       OR (last_engagement_at IS NOT NULL AND last_engagement_at < now() - interval '14 days' AND score >= 40)
    ORDER BY velocity ASC NULLS LAST, last_engagement_at ASC NULLS LAST LIMIT 10
  ),
  dormant AS (
    SELECT id, nom, score, behavioral_score, velocity, last_engagement_at, statut
    FROM base
    WHERE (last_engagement_at IS NULL OR last_engagement_at < now() - interval '30 days')
      AND score >= 50
    ORDER BY score DESC LIMIT 10
  ),
  orphans AS (
    SELECT id, nom, score, behavioral_score, velocity, last_engagement_at, statut
    FROM base WHERE commercial_id IS NULL ORDER BY score DESC LIMIT 10
  )
  SELECT jsonb_build_object(
    'computed_at', now(),
    'kpis', (SELECT row_to_json(k) FROM kpis k),
    'prev_kpis', COALESCE((SELECT row_to_json(p) FROM prev_kpis p), '{}'::json),
    'by_phase', COALESCE((SELECT jsonb_agg(row_to_json(bp)) FROM by_phase bp), '[]'::jsonb),
    'by_status', COALESCE((SELECT jsonb_agg(row_to_json(bs)) FROM by_status bs), '[]'::jsonb),
    'channels', COALESCE((SELECT jsonb_agg(row_to_json(c)) FROM channels c), '[]'::jsonb),
    'top_score', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM top_score t), '[]'::jsonb),
    'hot_streaks', COALESCE((SELECT jsonb_agg(row_to_json(h)) FROM hot_streaks h), '[]'::jsonb),
    'to_relaunch', COALESCE((SELECT jsonb_agg(row_to_json(r)) FROM to_relaunch r), '[]'::jsonb),
    'dormant', COALESCE((SELECT jsonb_agg(row_to_json(d)) FROM dormant d), '[]'::jsonb),
    'orphans', COALESCE((SELECT jsonb_agg(row_to_json(o)) FROM orphans o), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_scoring_trends(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scoring_trends(p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public._scoring_can_read() THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  WITH days AS (
    SELECT generate_series(
      (CURRENT_DATE - (p_days - 1))::timestamp,
      CURRENT_DATE::timestamp,
      interval '1 day'
    )::date AS day
  ),
  daily AS (
    SELECT
      date_trunc('day', computed_at)::date AS day,
      etablissement_id,
      score,
      ROW_NUMBER() OVER (PARTITION BY date_trunc('day', computed_at)::date, etablissement_id ORDER BY computed_at DESC) AS rn
    FROM public.prospect_score_history
    WHERE computed_at >= CURRENT_DATE - p_days
  ),
  daily_last AS (
    SELECT day, etablissement_id, score FROM daily WHERE rn = 1
  ),
  agg AS (
    SELECT
      d.day,
      COUNT(dl.etablissement_id)::int AS total,
      COUNT(*) FILTER (WHERE dl.score >= 80)::int AS hot,
      COUNT(*) FILTER (WHERE dl.score BETWEEN 60 AND 79)::int AS warm,
      COUNT(*) FILTER (WHERE dl.score BETWEEN 40 AND 59)::int AS working,
      COUNT(*) FILTER (WHERE dl.score < 40)::int AS cold,
      COALESCE(AVG(dl.score)::numeric(10,2), 0) AS avg_score
    FROM days d
    LEFT JOIN daily_last dl ON dl.day = d.day
    GROUP BY d.day ORDER BY d.day
  )
  SELECT COALESCE(jsonb_agg(row_to_json(agg)), '[]'::jsonb) INTO v_result FROM agg;

  RETURN v_result;
END;
$$;


--
-- Name: get_security_compliance_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_security_compliance_report() RETURNS TABLE(check_name text, status text, details text, recommendation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_total       int;
  v_admin_no_2fa      int;
  v_active_users      int;
  v_admin_count       int;
  v_high_risk_events  int;
BEGIN
  -- Compute all counts in a single pass
  SELECT
    COUNT(*) FILTER (
      WHERE ur.role = 'admin' AND p.actif = true
    ),
    COUNT(*) FILTER (
      WHERE ur.role = 'admin' AND p.actif = true AND p.two_factor_enabled = false
    ),
    COUNT(DISTINCT p.user_id) FILTER (WHERE p.actif = true)
  INTO v_admin_total, v_admin_no_2fa, v_active_users
  FROM public.profiles p
  LEFT JOIN public.user_roles ur ON ur.user_id = p.user_id;

  SELECT COUNT(*) INTO v_admin_count
  FROM public.user_roles WHERE role = 'admin';

  SELECT COUNT(*) INTO v_high_risk_events
  FROM public.security_logs
  WHERE risk_level = 'high'
    AND created_at > now() - INTERVAL '7 days';

  -- Admin 2FA Compliance
  RETURN QUERY SELECT
    'Admin 2FA Compliance'::text,
    CASE WHEN v_admin_no_2fa > 0 THEN 'CRITICAL' ELSE 'OK' END::text,
    CASE WHEN v_admin_no_2fa > 0
      THEN 'Admin users without 2FA: ' || v_admin_no_2fa::text
      ELSE 'All admin users have 2FA enabled'
    END::text,
    'All admin users must enable 2FA to perform critical operations'::text;

  -- Customer Data Protection
  RETURN QUERY SELECT
    'Customer Data Protection'::text,
    'OK'::text,
    'Customer contact data protected by RLS policies using can_access_contact() function'::text,
    'Continue monitoring contact data access through security logs'::text;

  -- Employee Information Protection
  RETURN QUERY SELECT
    'Employee Information Protection'::text,
    'OK'::text,
    'Employee profile data protected by existing RLS policies'::text,
    'Ensure employee information access is properly logged'::text;

  -- Role Distribution
  RETURN QUERY SELECT
    'Role Distribution'::text,
    CASE WHEN v_admin_count::numeric > v_active_users::numeric * 0.2
      THEN 'WARNING' ELSE 'OK' END::text,
    'Admin users: ' || v_admin_count::text || ' / Total users: ' || v_active_users::text,
    'Limit admin privileges to essential personnel only'::text;

  -- Recent Security Activity
  RETURN QUERY SELECT
    'Recent Security Activity'::text,
    CASE WHEN v_high_risk_events > 0 THEN 'WARNING' ELSE 'OK' END::text,
    'High-risk events (7 days): ' || v_high_risk_events::text,
    'Review security logs for unusual high-risk activities'::text;

  -- Admin Operations Security
  RETURN QUERY SELECT
    'Admin Operations Security'::text,
    'OK'::text,
    'Critical admin operations now require 2FA verification'::text,
    'Monitor admin operations through audit logs'::text;
END;
$$;


--
-- Name: get_security_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_security_stats() RETURNS TABLE(total_users bigint, blocked_ips bigint, failed_logins bigint, active_sessions bigint, security_incidents bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    (SELECT COUNT(*) FROM public.profiles WHERE actif = true) as total_users,
    (SELECT COUNT(*) FROM public.blocked_ips WHERE expires_at > now() OR expires_at IS NULL) as blocked_ips,
    (SELECT COUNT(*) FROM public.security_logs WHERE log_type = 'failed_login' AND created_at > now() - INTERVAL '24 hours') as failed_logins,
    (SELECT COUNT(DISTINCT user_id) FROM public.security_logs WHERE log_type = 'login_success' AND created_at > now() - INTERVAL '1 hour') as active_sessions,
    (SELECT COUNT(*) FROM public.security_logs WHERE risk_level = 'high' AND created_at > now() - INTERVAL '7 days') as security_incidents;
END;
$$;


--
-- Name: get_sip_credentials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sip_credentials() RETURNS TABLE(sip_uri text, sip_username text, sip_password text, sip_domain text, sip_proxy text, sip_transport public.sip_transport, caller_id text, record_calls boolean, rgpd_announcement text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Récupère la clé de chiffrement (réutilise EMAIL_ENCRYPTION_KEY via vault si dispo, sinon via app_internal_settings)
  SELECT value INTO v_key FROM public.app_internal_settings WHERE key = 'email_encryption_key' LIMIT 1;

  RETURN QUERY
  SELECT
    s.sip_uri,
    s.sip_username,
    CASE
      WHEN v_key IS NOT NULL THEN
        convert_from(
          extensions.pgp_sym_decrypt_bytea(decode(s.sip_password_encrypted, 'base64'), v_key),
          'UTF8'
        )
      ELSE s.sip_password_encrypted
    END AS sip_password,
    s.sip_domain,
    s.sip_proxy,
    s.sip_transport,
    s.caller_id,
    s.record_calls,
    s.rgpd_announcement
  FROM public.user_phone_settings s
  WHERE s.user_id = v_user_id AND s.is_active = true;
END;
$$;


--
-- Name: get_system_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb; v_total_users bigint; v_active_users bigint; v_total_etab bigint;
        v_total_taches bigint; v_completed_taches bigint;
BEGIN
  IF NOT (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'direction'::app_role)
       OR has_role(auth.uid(),'commercial'::app_role) OR has_role(auth.uid(),'csm'::app_role)) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO v_total_users FROM profiles;
  SELECT count(*) INTO v_active_users FROM profiles WHERE actif=true;
  SELECT count(*) INTO v_total_etab FROM etablissements;
  SELECT count(*) INTO v_total_taches FROM taches;
  SELECT count(*) INTO v_completed_taches FROM taches WHERE statut='Terminé';
  result := jsonb_build_object('total_users',v_total_users,'active_users',v_active_users,
    'total_establishments',v_total_etab,'total_tasks',v_total_taches,'completed_tasks',v_completed_taches);
  RETURN result;
END; $$;


--
-- Name: get_top_slow_routes(integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_slow_routes(p_hours integer DEFAULT 24, p_metric text DEFAULT 'LCP'::text, p_limit integer DEFAULT 10) RETURNS TABLE(route text, samples bigint, p75 double precision, p95 double precision, avg_value double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    route,
    count(*)::bigint AS samples,
    percentile_cont(0.75) WITHIN GROUP (ORDER BY value)::double precision AS p75,
    percentile_cont(0.95) WITHIN GROUP (ORDER BY value)::double precision AS p95,
    avg(value)::double precision AS avg_value
  FROM public.web_vitals_log
  WHERE created_at > now() - make_interval(hours => p_hours)
    AND metric = p_metric
    AND public.has_admin_role_strict(auth.uid())
  GROUP BY route
  HAVING count(*) >= 5
  ORDER BY p75 DESC NULLS LAST
  LIMIT p_limit;
$$;


--
-- Name: get_top_users_with_errors(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_users_with_errors(p_days integer DEFAULT 7, p_limit integer DEFAULT 10) RETURNS TABLE(user_id uuid, user_email text, error_count bigint, last_error_at timestamp with time zone, distinct_types bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    fel.user_id,
    p.email AS user_email,
    count(*)::bigint AS error_count,
    max(fel.created_at) AS last_error_at,
    count(DISTINCT fel.error_type)::bigint AS distinct_types
  FROM public.frontend_error_logs fel
  LEFT JOIN public.profiles p ON p.id = fel.user_id
  WHERE fel.created_at > now() - make_interval(days => p_days)
    AND fel.user_id IS NOT NULL
    AND public.has_admin_role_strict(auth.uid())
  GROUP BY fel.user_id, p.email
  ORDER BY error_count DESC
  LIMIT p_limit;
$$;


--
-- Name: get_tresorerie_kpis_aggregates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tresorerie_kpis_aggregates() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := CURRENT_DATE;
  v_six_months_ago date := date_trunc('month', v_today - interval '6 months')::date;
  v_six_months_ahead date := (v_today + interval '6 months')::date;
  v_five_years_ago date := make_date(extract(year from v_today)::int - 5, 1, 1);
  v_depenses_reelles numeric := 0;
  v_depenses_projetees numeric := 0;
  v_factures_count int := 0;
  v_factures_montant numeric := 0;
  v_ca jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COALESCE(SUM(ABS(COALESCE(montant, 0))), 0)
  INTO v_depenses_reelles
  FROM public.tresorerie_depenses
  WHERE date_prevue >= v_six_months_ago
    AND date_prevue <= v_today
    AND (statut = 'paye' OR date_paiement_reel IS NOT NULL);

  SELECT COALESCE(SUM(ABS(COALESCE(montant, 0))), 0)
  INTO v_depenses_projetees
  FROM public.tresorerie_depenses
  WHERE date_prevue > v_today
    AND date_prevue <= v_six_months_ahead
    AND statut = 'en_attente'
    AND date_prevue > DATE '1900-01-02';

  SELECT COUNT(*)::int, COALESCE(SUM(COALESCE(montant_prevu, 0)), 0)
  INTO v_factures_count, v_factures_montant
  FROM public.tresorerie_revenus
  WHERE statut IN ('a_facturer', 'contractualise');

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'annee', annee,
    'caComptable', ca_comptable,
    'caPercu', ca_percu
  ) ORDER BY annee DESC), '[]'::jsonb)
  INTO v_ca
  FROM (
    SELECT
      extract(year FROM date_prevue)::int AS annee,
      SUM(COALESCE(montant_prevu, 0)) AS ca_comptable,
      SUM(COALESCE(montant_paye, 0)) AS ca_percu
    FROM public.tresorerie_revenus
    WHERE date_prevue >= v_five_years_ago
      AND statut <> 'annule'
      AND date_prevue IS NOT NULL
    GROUP BY 1
    HAVING SUM(COALESCE(montant_prevu, 0)) > 0 OR SUM(COALESCE(montant_paye, 0)) > 0
  ) y;

  RETURN jsonb_build_object(
    'depensesReelles6m', v_depenses_reelles,
    'depensesProjetees6m', v_depenses_projetees,
    'facturesEnAttenteCount', v_factures_count,
    'facturesEnAttenteMontant', v_factures_montant,
    'caParExercice', v_ca
  );
END;
$$;


--
-- Name: get_user_2fa_secret(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_2fa_secret(target_user_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  secret TEXT;
BEGIN
  -- Enhanced service role check using JWT instead of current_setting
  IF COALESCE((auth.jwt() ->> 'role')::text, '') != 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized access to 2FA secrets';
  END IF;
  
  SELECT two_factor_secret INTO secret
  FROM public.profiles_secrets
  WHERE user_id = target_user_id;
  
  RETURN secret;
END;
$$;


--
-- Name: get_user_gamification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_gamification(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_points int;
  v_level int;
  v_curve_base numeric;
  v_curve_exp numeric;
  v_next int;
  v_badges jsonb;
  v_challenges jsonb;
  v_weights jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_points := compute_gamification_points(v_uid, 'all');

  SELECT value INTO v_weights FROM app_config WHERE key='gamification_weights';
  v_curve_base := COALESCE((v_weights->>'level_curve_base')::numeric, 100);
  v_curve_exp := COALESCE((v_weights->>'level_curve_exp')::numeric, 1.5);

  -- Niveau (1..50): plus haut niveau dont seuil <= points
  v_level := 1;
  FOR i IN 1..50 LOOP
    IF v_points >= (v_curve_base * power(i, v_curve_exp))::int THEN
      v_level := i;
    ELSE
      EXIT;
    END IF;
  END LOOP;
  v_next := (v_curve_base * power(v_level + 1, v_curve_exp))::int;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'code', b.code, 'nom', b.nom, 'description', b.description,
    'icon', b.icon, 'tier', b.tier, 'points', b.points,
    'unlocked_at', ub.unlocked_at
  ) ORDER BY ub.unlocked_at DESC), '[]'::jsonb)
  INTO v_badges
  FROM gamification_user_badges ub
  JOIN gamification_badges b ON b.code = ub.badge_code
  WHERE ub.user_id = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'nom', c.nom, 'description', c.description,
    'metric', c.metric, 'target_value', c.target_value,
    'reward_points', c.reward_points, 'end_date', c.end_date,
    'progress', COALESCE(p.progress, 0),
    'completed_at', p.completed_at
  ) ORDER BY c.end_date ASC), '[]'::jsonb)
  INTO v_challenges
  FROM gamification_challenges c
  LEFT JOIN gamification_challenge_participants p
    ON p.challenge_id = c.id AND p.user_id = v_uid
  WHERE c.is_active AND c.end_date > now();

  RETURN jsonb_build_object(
    'user_id', v_uid,
    'total_points', v_points,
    'level', v_level,
    'next_level_points', v_next,
    'badges', v_badges,
    'challenges', v_challenges
  );
END;
$$;


