CREATE FUNCTION public.get_user_team() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    CASE 
      WHEN role = 'admin' THEN 'direction'
      WHEN role = 'chef_projet' THEN 'technique'
      WHEN role = 'csm' THEN 'csm'
      WHEN role = 'commercial' THEN 'commercial'
      WHEN role = 'rh' THEN 'direction'
      ELSE 'direction'
    END
  FROM user_roles
  WHERE user_id = auth.uid()
  LIMIT 1
$$;


