--
-- Name: get_workflow_health(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_workflow_health(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => p_days);
  v_total int;
  v_success int;
  v_failed int;
  v_paused int;
  v_avg_duration numeric;
  v_top_failing jsonb;
  v_per_day jsonb;
  v_pending_scheduled int;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin'::app_role)
          OR public.has_role(auth.uid(), 'direction'::app_role)
          OR public.has_role(auth.uid(), 'manager'::app_role)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT
    count(*) FILTER (WHERE NOT coalesce(is_dry_run, false)),
    count(*) FILTER (WHERE status = 'success' AND NOT coalesce(is_dry_run, false)),
    count(*) FILTER (WHERE status = 'failed' AND NOT coalesce(is_dry_run, false)),
    count(*) FILTER (WHERE status = 'paused' AND NOT coalesce(is_dry_run, false)),
    avg(duration_ms) FILTER (WHERE status = 'success' AND duration_ms IS NOT NULL)
  INTO v_total, v_success, v_failed, v_paused, v_avg_duration
  FROM public.workflow_runs
  WHERE started_at >= v_since;

  SELECT coalesce(jsonb_agg(t), '[]'::jsonb) INTO v_top_failing FROM (
    SELECT w.id, w.nom,
      count(r.*) FILTER (WHERE r.status = 'failed') AS failed,
      count(r.*) AS total
    FROM public.workflow_runs r
    JOIN public.workflows w ON w.id = r.workflow_id
    WHERE r.started_at >= v_since AND NOT coalesce(r.is_dry_run, false)
    GROUP BY w.id, w.nom
    HAVING count(r.*) FILTER (WHERE r.status = 'failed') > 0
    ORDER BY failed DESC
    LIMIT 5
  ) t;

  SELECT coalesce(jsonb_agg(t ORDER BY t.day), '[]'::jsonb) INTO v_per_day FROM (
    SELECT date_trunc('day', started_at)::date AS day,
      count(*) FILTER (WHERE status = 'success') AS success,
      count(*) FILTER (WHERE status = 'failed') AS failed
    FROM public.workflow_runs
    WHERE started_at >= v_since AND NOT coalesce(is_dry_run, false)
    GROUP BY 1
  ) t;

  SELECT count(*) INTO v_pending_scheduled
  FROM public.workflow_scheduled_steps
  WHERE execute_at <= now() AND processed_at IS NULL;

  RETURN jsonb_build_object(
    'window_days', p_days,
    'total_runs', coalesce(v_total, 0),
    'success', coalesce(v_success, 0),
    'failed', coalesce(v_failed, 0),
    'paused', coalesce(v_paused, 0),
    'success_rate', CASE WHEN coalesce(v_total, 0) > 0 THEN round((v_success::numeric / v_total) * 100, 1) ELSE 0 END,
    'avg_duration_ms', coalesce(round(v_avg_duration), 0),
    'pending_scheduled', coalesce(v_pending_scheduled, 0),
    'top_failing', v_top_failing,
    'per_day', v_per_day
  );
END;
$$;


--
-- Name: get_workflow_run_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_workflow_run_status(p_run_id uuid) RETURNS TABLE(node_id text, node_type text, status text, error text, output jsonb, started_at timestamp with time zone, finished_at timestamp with time zone, duration_ms integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (s->>'node_id')::text,
    (s->>'node_type')::text,
    (s->>'status')::text,
    (s->>'error')::text,
    CASE WHEN s ? 'output' THEN s->'output' ELSE NULL END,
    NULLIF(s->>'started_at','')::timestamptz,
    NULLIF(s->>'finished_at','')::timestamptz,
    CASE
      WHEN (s ? 'started_at') AND (s ? 'finished_at')
        AND NULLIF(s->>'started_at','') IS NOT NULL
        AND NULLIF(s->>'finished_at','') IS NOT NULL
      THEN EXTRACT(EPOCH FROM (NULLIF(s->>'finished_at','')::timestamptz - NULLIF(s->>'started_at','')::timestamptz))::int * 1000
      ELSE NULL
    END
  FROM public.workflow_runs r
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(r.steps_log, '[]'::jsonb)) AS s
  WHERE r.id = p_run_id
    AND EXISTS (
      SELECT 1 FROM public.user_roles ur
      WHERE ur.user_id = auth.uid()
        AND ur.role IN ('admin','direction')
    );
$$;


--
-- Name: handle_deploiement_production_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_deploiement_production_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  deploiement_category_id UUID;
  production_category_id UUID;
BEGIN
  -- Récupérer les IDs des catégories
  SELECT id INTO deploiement_category_id 
  FROM categories_taches WHERE nom = 'Déploiement';
  
  SELECT id INTO production_category_id 
  FROM categories_taches WHERE nom = 'Suivi Production';
  
  -- Détecter si c'est la tâche "Déploiement production" qui passe en "Terminé"
  IF NEW.statut = 'Terminé' 
     AND OLD.statut != 'Terminé'
     AND NEW.titre = 'Déploiement production' 
     AND NEW.categorie_id = deploiement_category_id THEN
    
    -- 1. Basculer toutes les tâches NON terminées de Déploiement vers Suivi Production
    UPDATE taches
    SET categorie_id = production_category_id,
        updated_at = now()
    WHERE etablissement_id = NEW.etablissement_id
      AND categorie_id = deploiement_category_id
      AND statut != 'Terminé'
      AND id != NEW.id;
    
    -- 2. Passer l'établissement en statut "Production" avec la date_go_live
    UPDATE etablissements
    SET statut = 'Production',
        date_go_live = COALESCE(NEW.date_realisation, CURRENT_DATE),
        updated_at = now()
    WHERE id = NEW.etablissement_id;
    
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, user_id, email, prenom, nom, created_at, updated_at)
  VALUES (
    NEW.id,
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'prenom', split_part(NEW.email, '@', 1)),
    COALESCE(NEW.raw_user_meta_data->>'nom', '-'),
    NOW(),
    NOW()
  )
  ON CONFLICT (user_id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: handle_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: has_admin_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_admin_role(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = _user_id
      AND role IN ('admin'::public.app_role, 'direction'::public.app_role)
  );
$$;


--
-- Name: has_admin_role_strict(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_admin_role_strict(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL
    AND _user_id = auth.uid()
    AND COALESCE(auth.jwt() ->> 'aal', '') = 'aal2'
    AND public.has_admin_role(_user_id)
    AND EXISTS (
      SELECT 1
      FROM public.profiles
      WHERE user_id = _user_id
        AND actif = true
    );
$$;


--
-- Name: FUNCTION has_admin_role_strict(_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_admin_role_strict(_user_id uuid) IS 'Admin authorization for sensitive operations. Requires the current caller JWT to be AAL2; profiles.two_factor_enabled is not an authorization signal.';


--
-- Name: has_any_role(public.app_role[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_any_role(_roles public.app_role[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = auth.uid() AND role = ANY(_roles)
  )
$$;


--
-- Name: has_document_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_document_access(doc_id uuid, check_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.document_shares ds
    WHERE ds.document_id = doc_id
    AND (
      ds.shared_with_user_id = check_user_id
      OR ds.shared_with_group_id IN (
        SELECT gm.group_id FROM public.user_group_members gm WHERE gm.user_id = check_user_id
      )
    )
    AND (ds.expires_at IS NULL OR ds.expires_at > now())
  )
  OR EXISTS (
    SELECT 1 FROM public.documents d WHERE d.id = doc_id AND d.created_by = check_user_id
  )
$$;


--
-- Name: has_etablissement_role(uuid, public.etablissement_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_etablissement_role(_user_id uuid, _role public.etablissement_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.etablissement_user_roles
    WHERE user_id = _user_id
      AND role = _role
  )
$$;


--
-- Name: has_folder_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_folder_access(check_folder_id uuid, check_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.document_folder_permissions dfp
    WHERE dfp.folder_id = check_folder_id
    AND (
      dfp.user_id = check_user_id
      OR dfp.group_id IN (
        SELECT gm.group_id FROM public.user_group_members gm WHERE gm.user_id = check_user_id
      )
    )
  )
  OR EXISTS (
    SELECT 1 FROM public.document_folders df WHERE df.id = check_folder_id AND df.owner_id = check_user_id
  )
$$;


--
-- Name: has_required_mfa_aal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_required_mfa_aal() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    auth.uid() IS NOT NULL
    AND (
      NOT EXISTS (
        SELECT 1
        FROM auth.mfa_factors factor
        WHERE factor.user_id = auth.uid()
          AND factor.status = 'verified'
      )
      OR COALESCE(auth.jwt() ->> 'aal', 'aal1') = 'aal2'
    );
$$;


