  WHERE id = post_id;
END;
$$;


--
-- Name: increment_jarvis_score(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_jarvis_score(p_user_id uuid, p_score_type text, p_value integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO jarvis_user_scores (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;
  
  CASE p_score_type
    WHEN 'time_saved' THEN
      UPDATE jarvis_user_scores 
      SET time_saved_minutes = time_saved_minutes + p_value,
          total_score = total_score + (p_value / 5),
          weekly_score = weekly_score + (p_value / 5),
          updated_at = now()
      WHERE user_id = p_user_id;
    WHEN 'task_completed' THEN
      UPDATE jarvis_user_scores 
      SET tasks_auto_completed = tasks_auto_completed + p_value,
          total_score = total_score + (p_value * 10),
          weekly_score = weekly_score + (p_value * 10),
          updated_at = now()
      WHERE user_id = p_user_id;
    WHEN 'email_processed' THEN
      UPDATE jarvis_user_scores 
      SET emails_processed = emails_processed + p_value,
          total_score = total_score + (p_value * 5),
          weekly_score = weekly_score + (p_value * 5),
          updated_at = now()
      WHERE user_id = p_user_id;
    WHEN 'suggestion_accepted' THEN
      UPDATE jarvis_user_scores 
      SET suggestions_accepted = suggestions_accepted + p_value,
          total_score = total_score + (p_value * 15),
          weekly_score = weekly_score + (p_value * 15),
          updated_at = now()
      WHERE user_id = p_user_id;
    WHEN 'suggestion_rejected' THEN
      UPDATE jarvis_user_scores 
      SET suggestions_rejected = suggestions_rejected + p_value,
          updated_at = now()
      WHERE user_id = p_user_id;
    ELSE
      NULL;
  END CASE;
END;
$$;


--
-- Name: increment_post_comments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_post_comments() RETURNS trigger
