--
-- Name: it_asset_log_assignment_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.it_asset_log_assignment_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.assigned_to_profile_id IS DISTINCT FROM OLD.assigned_to_profile_id THEN
    INSERT INTO public.it_asset_events(asset_id, event_type, profile_id, note, created_by)
    VALUES (NEW.id,
            CASE WHEN NEW.assigned_to_profile_id IS NULL THEN 'returned' ELSE 'assigned' END,
            COALESCE(NEW.assigned_to_profile_id, OLD.assigned_to_profile_id),
            'Auto: assignation modifiée',
            auth.uid());
    IF NEW.assigned_to_profile_id IS NOT NULL AND NEW.assigned_at IS NULL THEN
      NEW.assigned_at := now();
    ELSIF NEW.assigned_to_profile_id IS NULL THEN
      NEW.assigned_at := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: jarvis_analyze_sender_emails(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jarvis_analyze_sender_emails(p_sender_pattern text, p_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_account_ids UUID[];
BEGIN
  -- Récupérer les comptes email accessibles par le profil
  SELECT ARRAY_AGG(id) INTO v_account_ids
  FROM user_email_accounts
  WHERE is_active = true
    AND (profile_id = p_profile_id OR is_shared = true);

  IF v_account_ids IS NULL OR array_length(v_account_ids, 1) = 0 THEN
    RETURN jsonb_build_object('error', 'Aucun compte email trouvé', 'total', 0);
  END IF;

  WITH sender_messages AS (
    SELECT
      em.id,
      em.from_address,
      em.from_name,
      em.subject,
      em.sent_date,
      EXTRACT(HOUR FROM em.sent_date) AS hour_of_day,
      EXTRACT(DOW FROM em.sent_date) AS day_of_week,
      em.sent_date::date AS send_date
    FROM email_messages em
    JOIN email_threads et ON et.id = em.thread_id
    WHERE et.user_email_account_id = ANY(v_account_ids)
      AND (
        em.from_name ILIKE '%' || p_sender_pattern || '%'
        OR em.from_address ILIKE '%' || p_sender_pattern || '%'
      )
  ),
  hourly_dist AS (
    SELECT hour_of_day::int AS hour, COUNT(*) AS count
    FROM sender_messages
    GROUP BY hour_of_day
    ORDER BY hour_of_day
  ),
  dow_dist AS (
    SELECT day_of_week::int AS dow, COUNT(*) AS count
    FROM sender_messages
    GROUP BY day_of_week
    ORDER BY day_of_week
  ),
  daily_amplitude AS (
    SELECT
      send_date,
      MIN(em.sent_date) AS first_email,
      MAX(em.sent_date) AS last_email,
      COUNT(*) AS emails_count,
      EXTRACT(EPOCH FROM MAX(em.sent_date) - MIN(em.sent_date)) / 3600.0 AS amplitude_hours
    FROM sender_messages em
    GROUP BY send_date
    HAVING COUNT(*) >= 2
  ),
  out_of_hours AS (
    SELECT COUNT(*) AS count
    FROM sender_messages
    WHERE hour_of_day < 8 OR hour_of_day >= 19
      OR day_of_week IN (0, 6) -- dimanche=0, samedi=6
  ),
  before_8 AS (
    SELECT COUNT(*) AS count FROM sender_messages WHERE hour_of_day < 8
  ),
  after_19 AS (
    SELECT COUNT(*) AS count FROM sender_messages WHERE hour_of_day >= 19
  ),
  weekend AS (
    SELECT COUNT(*) AS count FROM sender_messages WHERE day_of_week IN (0, 6)
  ),
  date_range AS (
    SELECT
      MIN(sent_date) AS first_email_ever,
      MAX(sent_date) AS last_email_ever,
      COUNT(DISTINCT send_date) AS active_days,
      COUNT(*) AS total
    FROM sender_messages
  ),
  top_addresses AS (
    SELECT from_address, from_name, COUNT(*) AS count
    FROM sender_messages
    GROUP BY from_address, from_name
    ORDER BY count DESC
    LIMIT 5
  ),
  extreme_days AS (
    SELECT send_date, first_email, last_email, emails_count, ROUND(amplitude_hours::numeric, 1) AS amplitude_hours
    FROM daily_amplitude
    WHERE amplitude_hours > 10
    ORDER BY amplitude_hours DESC
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'total', (SELECT total FROM date_range),
    'first_email', (SELECT first_email_ever FROM date_range),
    'last_email', (SELECT last_email_ever FROM date_range),
    'active_days', (SELECT active_days FROM date_range),
    'addresses', (SELECT COALESCE(jsonb_agg(jsonb_build_object('address', from_address, 'name', from_name, 'count', count)), '[]'::jsonb) FROM top_addresses),
    'hourly_distribution', (SELECT COALESCE(jsonb_agg(jsonb_build_object('hour', hour, 'count', count)), '[]'::jsonb) FROM hourly_dist),
    'day_of_week_distribution', (SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'count', count)), '[]'::jsonb) FROM dow_dist),
    'out_of_hours', jsonb_build_object(
      'total', (SELECT count FROM out_of_hours),
      'before_8h', (SELECT count FROM before_8),
      'after_19h', (SELECT count FROM after_19),
      'weekends', (SELECT count FROM weekend)
    ),
    'amplitude', jsonb_build_object(
      'avg_hours', (SELECT ROUND(AVG(amplitude_hours)::numeric, 1) FROM daily_amplitude),
      'max_hours', (SELECT ROUND(MAX(amplitude_hours)::numeric, 1) FROM daily_amplitude),
      'days_over_10h', (SELECT COUNT(*) FROM daily_amplitude WHERE amplitude_hours > 10)
    ),
    'extreme_days', (SELECT COALESCE(jsonb_agg(jsonb_build_object('date', send_date, 'first', first_email, 'last', last_email, 'count', emails_count, 'amplitude_h', amplitude_hours)), '[]'::jsonb) FROM extreme_days)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


