--

CREATE FUNCTION public.list_client_portal_users() RETURNS TABLE(id uuid, email text, full_name text, nom text, prenom text, etablissement_id uuid, etablissement_nom text, actif boolean, last_login timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT u.id, u.email, u.full_name, u.nom, u.prenom,
         u.etablissement_id, e.nom AS etablissement_nom,
         u.actif, u.last_login, u.created_at
  FROM public.client_portal_users u
  LEFT JOIN public.etablissements e ON e.id = u.etablissement_id
  WHERE public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'direction')
  ORDER BY u.created_at DESC;
$$;


--
-- Name: live_chat_sessions_set_token_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.live_chat_sessions_set_token_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.session_token IS NOT NULL THEN
    NEW.session_token_hash := encode(extensions.digest(NEW.session_token, 'sha256'), 'hex');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_call_to_activities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_call_to_activities() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Seulement quand l'appel passe à completed et qu'il dure > 0
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status <> 'completed') AND NEW.etablissement_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.activites (
        etablissement_id, user_id, type, titre, description, date_activite, metadata
      ) VALUES (
        NEW.etablissement_id,
        NEW.user_id,
        'call',
        CASE NEW.direction
          WHEN 'outbound' THEN 'Appel sortant vers ' || COALESCE(NEW.display_name, NEW.to_number)
          ELSE 'Appel entrant de ' || COALESCE(NEW.display_name, NEW.from_number)
        END,
        CASE
          WHEN NEW.duration_sec > 0 THEN 'Durée : ' || NEW.duration_sec || 's' || COALESCE(E'\nNotes : ' || NEW.notes, '')
          ELSE COALESCE(NEW.notes, '')
        END,
        NEW.started_at,
        jsonb_build_object(
          'call_id', NEW.id,
          'duration_sec', NEW.duration_sec,
          'direction', NEW.direction,
          'has_recording', NEW.recording_path IS NOT NULL
        )
      );
    EXCEPTION WHEN OTHERS THEN
      -- Ne bloque jamais l'appel si la table activites n'existe pas / RLS
      RAISE WARNING 'log_call_to_activities failed: %', SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_contact_access(uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_contact_access(contact_id uuid, etablissement_id uuid, access_type text, sensitive_fields text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_user_profile profiles%ROWTYPE;
  current_role text;
BEGIN
  -- Get current user profile
  SELECT p.* INTO current_user_profile
  FROM public.profiles p
  WHERE p.user_id = auth.uid() AND p.actif = true;

  -- Get role from user_roles table
  SELECT ur.role::text INTO current_role
  FROM public.user_roles ur
  WHERE ur.user_id = current_user_profile.user_id
  LIMIT 1;

  -- Insert security log
  BEGIN
    INSERT INTO public.security_logs (
      log_type,
      user_id,
      user_email,
      ip_address,
      risk_level,
      metadata
    ) VALUES (
      'contact_data_access',
      current_user_profile.user_id,
      current_user_profile.email,
      NULL,
      CASE 
        WHEN sensitive_fields IS NOT NULL AND array_length(sensitive_fields, 1) > 0 
        THEN 'medium' 
        ELSE 'low' 
      END,
      jsonb_build_object(
        'contact_id', contact_id,
        'etablissement_id', etablissement_id,
        'access_type', access_type,
        'user_role', COALESCE(current_role, 'user'),
        'user_profile_id', current_user_profile.id,
        'sensitive_fields_accessed', sensitive_fields,
        'timestamp', now()
      )
    );
  EXCEPTION
    WHEN check_violation THEN
      RAISE WARNING 'Security log constraint violation for contact access: %', SQLERRM;
    WHEN OTHERS THEN
      RAISE WARNING 'Error logging contact access: %', SQLERRM;
  END;
END;
$$;


