--
-- Name: log_profile_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_profile_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  old_role_record user_roles%ROWTYPE;
  new_role_record user_roles%ROWTYPE;
BEGIN
  -- Get old and new roles from user_roles table
  SELECT * INTO old_role_record FROM public.user_roles WHERE user_id = OLD.user_id LIMIT 1;
  SELECT * INTO new_role_record FROM public.user_roles WHERE user_id = NEW.user_id LIMIT 1;
  
  -- Log role changes if detected
  IF old_role_record.role IS DISTINCT FROM new_role_record.role THEN
    INSERT INTO public.security_logs (
      log_type,
      user_id,
      user_email,
      risk_level,
      metadata
    ) VALUES (
      'profile_role_change',
      auth.uid(),
      NEW.email,
      'high',
      jsonb_build_object(
        'target_user_id', NEW.user_id,
        'old_role', old_role_record.role,
        'new_role', new_role_record.role,
        'changed_by_admin', is_admin(),
        'timestamp', now()
      )
    );
  END IF;
  
  IF OLD.two_factor_enabled IS DISTINCT FROM NEW.two_factor_enabled THEN
    INSERT INTO public.security_logs (
      log_type,
      user_id,
      user_email,
      risk_level,
      metadata
    ) VALUES (
      'profile_2fa_change',
      auth.uid(),
      NEW.email,
      'medium',
      jsonb_build_object(
        'target_user_id', NEW.user_id,
        'old_2fa_status', OLD.two_factor_enabled,
        'new_2fa_status', NEW.two_factor_enabled,
        'timestamp', now()
      )
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: log_pulse_conversation_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_pulse_conversation_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.pulse_audit_log (
      action, actor_id, target_type, target_id,
      conversation_id, details, status
    ) VALUES (
      'conversation_created', NEW.created_by, 'conversation', NEW.id,
      NEW.id,
      -- CORRECTION: utiliser metadata->>'type' au lieu de NEW.type qui n'existe pas
      jsonb_build_object('name', NEW.name, 'type', NEW.metadata->>'type'),
      'success'
    );
  ELSIF TG_OP = 'UPDATE' AND OLD.is_archived IS DISTINCT FROM NEW.is_archived THEN
    INSERT INTO public.pulse_audit_log (
      action, actor_id, target_type, target_id,
      conversation_id, details, status
    ) VALUES (
      CASE WHEN NEW.is_archived THEN 'conversation_archived' ELSE 'conversation_unarchived' END,
      NEW.created_by, 'conversation', NEW.id,
      NEW.id,
      jsonb_build_object('name', NEW.name),
      'success'
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_pulse_message_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_pulse_message_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.pulse_audit_log (
      action, actor_id, target_type, target_id, 
      conversation_id, details, status
    ) VALUES (
      'message_created', NEW.user_id, 'message', NEW.id,
      NEW.conversation_id, 
      jsonb_build_object('content_preview', LEFT(NEW.content, 100)),
      'success'
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Log soft delete
    IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
      INSERT INTO public.pulse_audit_log (
        action, actor_id, target_type, target_id,
        conversation_id, details, status
      ) VALUES (
        'message_deleted', NEW.user_id, 'message', NEW.id,
        NEW.conversation_id,
        jsonb_build_object('deleted_at', NEW.deleted_at),
        'success'
      );
      
      -- Archive the message
      INSERT INTO public.pulse_message_archive (
        original_message_id, conversation_id, user_id, content,
        message_type, metadata, created_at, deleted_at, deleted_by, archive_reason
      ) VALUES (
        OLD.id, OLD.conversation_id, OLD.user_id, OLD.content,
        OLD.message_type, OLD.metadata, OLD.created_at, NEW.deleted_at, NEW.user_id, 'soft_delete'
      );
    -- Log edit
    ELSIF OLD.content IS DISTINCT FROM NEW.content THEN
      INSERT INTO public.pulse_audit_log (
        action, actor_id, target_type, target_id,
        conversation_id, details, status
      ) VALUES (
        'message_edited', NEW.user_id, 'message', NEW.id,
        NEW.conversation_id,
        jsonb_build_object(
          'old_content_preview', LEFT(OLD.content, 100),
          'new_content_preview', LEFT(NEW.content, 100)
        ),
        'success'
      );
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


