CREATE FUNCTION public.log_security_event(p_action text, p_resource text, p_details jsonb DEFAULT NULL::jsonb, p_resource_id text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS void
