--
-- Name: log_sensitive_etablissement_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_sensitive_etablissement_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  current_role text;
  changes jsonb := '{}'::jsonb;
BEGIN
  -- Ne logger que si des colonnes sensibles ont changé
  IF NOT (
    OLD.statut IS DISTINCT FROM NEW.statut OR
    OLD.type_offre IS DISTINCT FROM NEW.type_offre OR
    OLD.commercial_id IS DISTINCT FROM NEW.commercial_id OR
    OLD.chef_projet_id IS DISTINCT FROM NEW.chef_projet_id OR
    OLD.csm_id IS DISTINCT FROM NEW.csm_id
  ) THEN
    RETURN NEW;
  END IF;

  SELECT ur.role::text INTO current_role
  FROM public.user_roles ur
  WHERE ur.user_id = auth.uid()
  LIMIT 1;

  IF OLD.statut IS DISTINCT FROM NEW.statut THEN
    changes := changes || jsonb_build_object('statut_old', OLD.statut, 'statut_new', NEW.statut);
  END IF;

  IF OLD.type_offre IS DISTINCT FROM NEW.type_offre THEN
    changes := changes || jsonb_build_object('type_offre_old', OLD.type_offre, 'type_offre_new', NEW.type_offre);
  END IF;

  IF OLD.commercial_id IS DISTINCT FROM NEW.commercial_id THEN
    changes := changes || jsonb_build_object(
      'commercial_id_old', OLD.commercial_id::text,
      'commercial_id_new', NEW.commercial_id::text
    );
  END IF;

  IF OLD.chef_projet_id IS DISTINCT FROM NEW.chef_projet_id THEN
    changes := changes || jsonb_build_object(
      'chef_projet_id_old', OLD.chef_projet_id::text,
      'chef_projet_id_new', NEW.chef_projet_id::text
    );
  END IF;

  IF OLD.csm_id IS DISTINCT FROM NEW.csm_id THEN
    changes := changes || jsonb_build_object(
      'csm_id_old', OLD.csm_id::text,
      'csm_id_new', NEW.csm_id::text
    );
  END IF;

  INSERT INTO public.security_logs (log_type, user_id, user_email, risk_level, metadata)
  VALUES (
    'critical_admin_action',
    auth.uid(),
    (SELECT email FROM public.profiles WHERE user_id = auth.uid()),
    'medium',
    jsonb_build_object(
      'table_name', 'etablissements',
      'operation', 'UPDATE',
      'etablissement_id', NEW.id::text,
      'etablissement_nom', NEW.nom,
      'changes', changes,
      'timestamp', now(),
      'user_role', COALESCE(current_role, 'user')
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: log_tache_statut_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_tache_statut_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_user_profile_id UUID;
BEGIN
  -- Récupérer l'ID du profil de l'utilisateur actuel
  SELECT id INTO current_user_profile_id 
  FROM public.profiles 
  WHERE user_id = auth.uid();
  
