--
-- Name: log_web_vital(text, text, double precision, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_web_vital(p_route text, p_metric text, p_value double precision, p_rating text DEFAULT NULL::text, p_navigation_type text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN; -- silently drop unauthenticated
  END IF;

  IF p_metric NOT IN ('LCP','INP','CLS','FCP','TTFB') THEN
    RETURN;
  END IF;

  IF p_value IS NULL OR p_value < 0 OR p_value > 600000 THEN
    RETURN; -- clamp insane values
  END IF;

  INSERT INTO public.web_vitals_log (user_id, route, metric, value, rating, navigation_type, user_agent)
  VALUES (
    v_uid,
    LEFT(COALESCE(p_route, '/'), 200),
    p_metric,
    p_value,
    p_rating,
    LEFT(COALESCE(p_navigation_type, ''), 30),
    LEFT(COALESCE(p_user_agent, ''), 300)
  );
END;
$$;


--
-- Name: mark_messages_as_delivered(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_messages_as_delivered(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO pulse_message_receipts (message_id, user_id, delivered_at)
  SELECT pm.id, p_user_id, now()
  FROM pulse_messages pm
  JOIN pulse_conversation_members pcm ON pcm.conversation_id = pm.conversation_id
  WHERE pcm.user_id = p_user_id
    AND pm.user_id != p_user_id
    AND pm.deleted_at IS NULL
  ON CONFLICT (message_id, user_id) 
  DO UPDATE SET delivered_at = COALESCE(pulse_message_receipts.delivered_at, now());
END;
$$;


--
-- Name: mark_messages_as_read(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_messages_as_read(p_conversation_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- 1. Mettre à jour les receipts existants
  INSERT INTO pulse_message_receipts (message_id, user_id, delivered_at, read_at)
  SELECT pm.id, p_user_id, now(), now()
  FROM pulse_messages pm
  WHERE pm.conversation_id = p_conversation_id
    AND pm.user_id != p_user_id
    AND pm.deleted_at IS NULL
  ON CONFLICT (message_id, user_id) 
  DO UPDATE SET read_at = COALESCE(pulse_message_receipts.read_at, now());
  
  -- 2. NOUVEAU: Mettre à jour last_read_at dans pulse_conversation_members
  -- C'est ce champ qui est utilisé par count_pulse_unread pour les badges
  UPDATE pulse_conversation_members
  SET last_read_at = now()
  WHERE conversation_id = p_conversation_id
    AND user_id = p_user_id;
END;
$$;


--
-- Name: mark_ticket_origin_portal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_ticket_origin_portal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.created_by IS NULL AND NEW.contact_email IS NOT NULL THEN
    SELECT id INTO NEW.client_portal_user_id
    FROM client_portal_users
    WHERE email = NEW.contact_email
      AND etablissement_id = NEW.etablissement_id
    LIMIT 1;
    IF NEW.client_portal_user_id IS NOT NULL THEN
      NEW.created_via_portal := true;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: match_email_to_etablissement(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_email_to_etablissement(email_address text) RETURNS TABLE(etablissement_id uuid, etablissement_nom text, etablissement_ville text, confidence text, match_reason text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  domain text;
BEGIN
  domain := public.extract_email_domain(email_address);
  
  RETURN QUERY
  SELECT 
    e.id,
    e.nom,
    e.ville,
    edm.confidence_level,
    'Domaine enregistré: ' || edm.domain
  FROM email_domain_mappings edm
  JOIN etablissements e ON e.id = edm.etablissement_id
  WHERE edm.domain = domain
  LIMIT 1;
  
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT 
      e.id,
      e.nom,
      e.ville,
      'high'::text,
      'Domaine dans liste établissement'
    FROM etablissements e
    WHERE domain = ANY(e.email_domains)
    LIMIT 1;
  END IF;
  
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT 
      e.id,
      e.nom,
      e.ville,
      'low'::text,
      'Correspondance approximative du domaine'
    FROM etablissements e
    WHERE 
      domain ILIKE '%' || lower(replace(e.ville, ' ', '-')) || '%'
      OR domain ILIKE '%' || lower(replace(e.nom, ' ', '-')) || '%'
    ORDER BY 
      CASE 
        WHEN domain ILIKE '%' || lower(replace(e.ville, ' ', '-')) || '%' THEN 2
        ELSE 1
      END DESC
    LIMIT 3;
  END IF;
END;
$$;


--
-- Name: match_email_to_etablissement(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_email_to_etablissement(email_address text, email_subject text DEFAULT NULL::text, email_body text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  matched_id uuid;
  email_domain text;
BEGIN
  email_domain := public.extract_email_domain(email_address);
  
  IF email_domain IS NULL THEN
    RETURN NULL;
  END IF;
  
  SELECT e.id INTO matched_id
  FROM public.etablissements e
  WHERE email_domain = ANY(e.email_domains)
  LIMIT 1;
  
  RETURN matched_id;
END;
$$;


--
-- Name: match_email_to_etablissement_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_email_to_etablissement_v2(email_address text) RETURNS TABLE(etablissement_id uuid, etablissement_nom text, confidence text, match_reason text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  domain TEXT;
  local_part TEXT;
  acronym TEXT;
  clean_domain TEXT;
BEGIN
  domain := lower(split_part(email_address, '@', 2));
  local_part := lower(split_part(email_address, '@', 1));
  
  RETURN QUERY
  SELECT 
    e.id,
    e.nom,
    'high'::TEXT,
    format('Domaine exact: %s', domain)
  FROM etablissements e
  WHERE domain = ANY(e.email_domains)
  LIMIT 1;
  
  IF FOUND THEN RETURN; END IF;
  
  RETURN QUERY
  SELECT 
    edm.etablissement_id,
    e.nom,
    'high'::TEXT,
    format('Domaine mappé: %s', domain)
  FROM email_domain_mappings edm
  JOIN etablissements e ON e.id = edm.etablissement_id
  WHERE edm.domain = domain AND edm.verified = true
  LIMIT 1;
  
  IF FOUND THEN RETURN; END IF;
  
  acronym := upper(split_part(domain, '.', 1));
  
  IF length(acronym) >= 2 AND length(acronym) <= 6 THEN
    RETURN QUERY
    WITH acronym_candidates AS (
      SELECT 
        e.id,
        e.nom,
        upper(string_agg(substring(word, 1, 1), '')) as initiales
      FROM etablissements e,
      unnest(
        string_to_array(
          regexp_replace(e.nom, '[^A-ZÉÈÊËÀÂÔÎÛa-zéèêëàâôîû ]', '', 'g'), 
          ' '
        )
      ) AS word
      WHERE word != ''
      GROUP BY e.id, e.nom
    )
    SELECT 
      ac.id,
      ac.nom,
      'medium'::TEXT,
      format('Acronyme potentiel: %s → %s (%s)', acronym, ac.nom, ac.initiales)
    FROM acronym_candidates ac
    WHERE ac.initiales = acronym
    LIMIT 3;
  END IF;
  
  clean_domain := regexp_replace(split_part(domain, '.', 1), '^(ch|chu|ght|hopital|hopitaux|clinique|group|groupe|ste|societe|sas|sarl|cabinet|agence|asso|association|centre)-?', '');
  
  IF length(clean_domain) >= 4 THEN
    RETURN QUERY
    SELECT 
      e.id,
      e.nom,
      'low'::TEXT,
      format('Correspondance approximative ville/nom: %s', clean_domain)
    FROM etablissements e
    WHERE 
      replace(lower(e.ville), ' ', '') LIKE '%' || replace(clean_domain, '-', '') || '%'
      OR replace(lower(e.ville), '-', '') LIKE '%' || replace(clean_domain, '-', '') || '%'
      OR replace(lower(e.nom), ' ', '') LIKE '%' || replace(clean_domain, '-', '') || '%'
      OR replace(lower(e.nom), '-', '') LIKE '%' || replace(clean_domain, '-', '') || '%'
    LIMIT 5;
  END IF;
END;
$$;


