--
-- Name: match_email_to_etablissement_v3(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_email_to_etablissement_v3(email_address text) RETURNS TABLE(etablissement_id uuid, etablissement_nom text, confidence text, match_reason text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  domain TEXT;
  local_part TEXT;
  acronym TEXT;
  clean_domain TEXT;
BEGIN
  domain := lower(split_part(email_address, '@', 2));
  local_part := lower(split_part(email_address, '@', 1));
  acronym := upper(split_part(domain, '.', 1));
  clean_domain := regexp_replace(split_part(domain, '.', 1), '^(ch|chu|ght|hopital|clinique|group|groupe|ste|societe|sas|sarl|cabinet|agence|asso|association|centre)-', '');
  
  RETURN QUERY
  WITH all_matches AS (
    SELECT 
      e.id,
      e.nom,
      'high'::TEXT,
      format('Domaine exact dans email_domains: %s', domain) as reason,
      1 as priority_order
    FROM etablissements e
    WHERE domain = ANY(e.email_domains)
    
    UNION ALL
    
    SELECT 
      edm.etablissement_id,
      e.nom,
      'high'::TEXT,
      format('Domaine mappé: %s', edm.domain) as reason,
      2 as priority_order
    FROM email_domain_mappings edm
    JOIN etablissements e ON e.id = edm.etablissement_id
    WHERE edm.domain = domain
    
    UNION ALL
    
    SELECT 
      e.id,
      e.nom,
      'medium'::TEXT,
      format('Acronyme potentiel: %s → %s', acronym, e.nom) as reason,
      3 as priority_order
    FROM etablissements e
    WHERE 
      length(acronym) BETWEEN 2 AND 6
      AND acronym = (
        SELECT upper(string_agg(substring(word, 1, 1), ''))
        FROM unnest(string_to_array(
          regexp_replace(e.nom, '[^A-ZÉÈÊËÀÂÔÎÛa-zéèêëàâôîû ]', '', 'g'), 
          ' '
        )) AS word
        WHERE length(word) > 0
      )
    
    UNION ALL
    
    SELECT 
      e.id,
      e.nom,
      'low'::TEXT,
      format('Correspondance domaine-ville/nom: %s → %s / %s', clean_domain, e.ville, e.nom) as reason,
      4 as priority_order
    FROM etablissements e
    WHERE 
      length(clean_domain) >= 4
      AND (
        unaccent(lower(e.ville)) LIKE '%' || unaccent(clean_domain) || '%'
        OR unaccent(lower(e.nom)) LIKE '%' || unaccent(clean_domain) || '%'
        OR unaccent(clean_domain) LIKE '%' || unaccent(lower(regexp_replace(e.ville, '[^a-zA-Z]', '', 'g'))) || '%'
      )
  )
  SELECT 
    am.id,
    am.nom,
    am.confidence,
    am.reason
  FROM all_matches am
  ORDER BY 
    am.priority_order,
    CASE am.confidence 
      WHEN 'high' THEN 1
      WHEN 'medium' THEN 2
      WHEN 'low' THEN 3
    END,
    length(am.nom)
  LIMIT 10;
END;
$$;


