--
-- Name: match_email_to_etablissement_v4(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_email_to_etablissement_v4(email_address text) RETURNS TABLE(etablissement_id uuid, etablissement_nom text, etablissement_ville text, confidence text, match_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  domain TEXT;
  domain_clean TEXT;
BEGIN
  -- Extraire le domaine de l'email
  domain := split_part(email_address, '@', 2);
  
  -- Nettoyer le domaine : enlever les préfixes courants et normaliser
  domain_clean := regexp_replace(
    lower(unaccent(split_part(domain, '.', 1))),
    '^(ch|chu|ght|hopital|clinique|group|groupe|ste|societe|sas|sarl|cabinet|agence|asso|association|centre)-?',
    ''
  );
  
  -- Collecter TOUS les matches possibles (ne pas s'arrêter au premier)
  RETURN QUERY
  WITH all_matches AS (
    -- 1. Match exact par domaine dans email_domains (high confidence)
    SELECT 
      e.id AS etablissement_id,
      e.nom AS etablissement_nom,
      e.ville AS etablissement_ville,
      'high' AS confidence,
      'Domaine exact dans email_domains' AS match_reason
    FROM public.etablissements e
    WHERE e.email_domains @> ARRAY[domain]::TEXT[]
    
    UNION ALL
    
    -- 2. Match via email_domain_mappings (high confidence)
    SELECT 
      edm.etablissement_id,
      e.nom AS etablissement_nom,
      e.ville AS etablissement_ville,
      'high' AS confidence,
      'Domaine mappé manuellement' AS match_reason
    FROM public.email_domain_mappings edm
    JOIN public.etablissements e ON e.id = edm.etablissement_id
    WHERE edm.domain = domain AND edm.verified = true
    
    UNION ALL
    
    -- 3. Match par acronyme/initiales (medium confidence)
    SELECT 
      e.id AS etablissement_id,
      e.nom AS etablissement_nom,
      e.ville AS etablissement_ville,
      'medium' AS confidence,
      'Match par initiales' AS match_reason
    FROM public.etablissements e
    WHERE lower(unaccent(
      regexp_replace(regexp_replace(e.nom, '\s+', '', 'g'), '[^a-zA-Z]', '', 'g')
    )) = domain_clean
    
    UNION ALL
    
    -- 4. Match par dérivation ville (low confidence)
    -- Nettoyer la ville et chercher si domain_clean contient la ville
    SELECT 
      e.id AS etablissement_id,
      e.nom AS etablissement_nom,
      e.ville AS etablissement_ville,
      'low' AS confidence,
      'Match par ville dans domaine' AS match_reason
    FROM public.etablissements e
    WHERE regexp_replace(lower(unaccent(e.ville)), '[^a-z0-9]', '', 'g') != ''
      AND domain_clean LIKE '%' || regexp_replace(lower(unaccent(e.ville)), '[^a-z0-9]', '', 'g') || '%'
      AND length(regexp_replace(lower(unaccent(e.ville)), '[^a-z0-9]', '', 'g')) >= 4
    
    UNION ALL
    
    -- 5. Match par similarité trigram sur le nom (low confidence)
    SELECT 
      e.id AS etablissement_id,
      e.nom AS etablissement_nom,
      e.ville AS etablissement_ville,
      'low' AS confidence,
      'Match par similarité de nom (' || ROUND(similarity(lower(unaccent(e.nom)), domain_clean) * 100)::TEXT || '%)' AS match_reason
    FROM public.etablissements e
    WHERE similarity(lower(unaccent(e.nom)), domain_clean) > 0.3
  )
  -- Retourner tous les matches, triés par confiance puis par nom
  SELECT DISTINCT ON (am.etablissement_id)
    am.etablissement_id,
    am.etablissement_nom,
    am.etablissement_ville,
    am.confidence,
    am.match_reason
  FROM all_matches am
  ORDER BY am.etablissement_id,
    CASE am.confidence 
      WHEN 'high' THEN 1
      WHEN 'medium' THEN 2
      WHEN 'low' THEN 3
    END,
    am.etablissement_nom
  LIMIT 10;
END;
$$;


--
-- Name: match_email_to_etablissement_v4(text, text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_email_to_etablissement_v4(p_from_address text, p_from_name text DEFAULT NULL::text, p_to_addresses jsonb DEFAULT NULL::jsonb, p_cc_addresses jsonb DEFAULT NULL::jsonb, p_subject text DEFAULT NULL::text, p_body_text text DEFAULT NULL::text) RETURNS TABLE(etablissement_id uuid, groupe_id uuid, partenaire_id uuid, confidence_score numeric, match_reason text, niveau_mapping text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_domain text;
  v_email_lower text;
  v_result record;
  v_all_emails text[];
  v_search_term text;
BEGIN
  -- Extract domain from email
  v_email_lower := lower(p_from_address);
  v_domain := substring(v_email_lower from '@(.+)$');
  
  -- Collect all email addresses
  v_all_emails := ARRAY[v_email_lower];
  IF p_to_addresses IS NOT NULL THEN
    v_all_emails := v_all_emails || ARRAY(SELECT lower(jsonb_array_elements_text(p_to_addresses)));
  END IF;
  IF p_cc_addresses IS NOT NULL THEN
    v_all_emails := v_all_emails || ARRAY(SELECT lower(jsonb_array_elements_text(p_cc_addresses)));
  END IF;

  -- 1. Check email_specific_mappings
  FOR v_result IN
    SELECT 
      esm.etablissement_id,
      esm.groupe_id,
      esm.partenaire_id,
      1.0 as score,
      'Specific email mapping' as reason,
      esm.niveau_mapping
    FROM public.email_specific_mappings esm
    WHERE lower(esm.email_address) = ANY(v_all_emails)
    LIMIT 1
  LOOP
    etablissement_id := v_result.etablissement_id;
    groupe_id := v_result.groupe_id;
    partenaire_id := v_result.partenaire_id;
    confidence_score := v_result.score;
    match_reason := v_result.reason;
    niveau_mapping := v_result.niveau_mapping;
    RETURN NEXT;
    RETURN;
  END LOOP;

  -- 2. Check email_domain_mappings
  FOR v_result IN
    SELECT 
      edm.etablissement_id,
      edm.groupe_id,
      edm.partenaire_id,
      0.95 as score,
      'Domain mapping' as reason,
      edm.niveau_mapping
    FROM public.email_domain_mappings edm
    WHERE edm.domain = v_domain
      AND edm.is_excluded = false
    ORDER BY edm.verified DESC, edm.confidence_level DESC
    LIMIT 1
  LOOP
    etablissement_id := v_result.etablissement_id;
    groupe_id := v_result.groupe_id;
    partenaire_id := v_result.partenaire_id;
    confidence_score := v_result.score;
    match_reason := v_result.reason;
    niveau_mapping := v_result.niveau_mapping;
    RETURN NEXT;
    RETURN;
  END LOOP;

  -- 3. Fuzzy match on etablissement name in subject/body
  IF p_subject IS NOT NULL OR p_body_text IS NOT NULL THEN
    v_search_term := lower(unaccent(coalesce(p_subject, '') || ' ' || coalesce(p_body_text, '')));
    
    FOR v_result IN
      SELECT 
        e.id as etablissement_id,
        NULL::uuid as groupe_id,
        NULL::uuid as partenaire_id,
        0.7 as score,
        'Fuzzy name match in email content' as reason,
        'etablissement'::text as niveau_mapping
      FROM public.etablissements e
      WHERE v_search_term LIKE '%' || lower(unaccent(e.nom)) || '%'
         OR v_search_term LIKE '%' || lower(unaccent(e.ville)) || '%'
      ORDER BY length(e.nom) DESC
      LIMIT 1
    LOOP
      etablissement_id := v_result.etablissement_id;
      groupe_id := v_result.groupe_id;
      partenaire_id := v_result.partenaire_id;
      confidence_score := v_result.score;
      match_reason := v_result.reason;
      niveau_mapping := v_result.niveau_mapping;
      RETURN NEXT;
      RETURN;
    END LOOP;
  END IF;

  -- No match found
  RETURN;
END;
$_$;


--
-- Name: notify_csm_on_portal_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_csm_on_portal_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_csm uuid;
BEGIN
  SELECT csm_id INTO v_csm FROM public.etablissements WHERE id = NEW.etablissement_id;
  INSERT INTO public.taches (etablissement_id, titre, description, priorite, statut, responsable_id)
  VALUES (
    NEW.etablissement_id,
    'Demande portail client : ' || COALESCE(NEW.sujet, NEW.subject, '(sans sujet)'),
    COALESCE(NEW.message, '') || E'\n\n— Type: ' || NEW.type || ' / Email: ' || COALESCE(NEW.email, '—'),
    'haute', 'a_faire', v_csm
  );
  RETURN NEW;
END;
$$;


--
-- Name: notify_establishment_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_establishment_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_exists BOOLEAN;
BEGIN
  -- Ne notifier que si le statut change
  IF OLD.statut = NEW.statut THEN
    RETURN NEW;
  END IF;
  
  -- Notifier le CSM assigné s'il existe
  IF NEW.csm_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = NEW.csm_id) INTO v_user_exists;
    IF v_user_exists THEN
      INSERT INTO public.in_app_notifications (
        user_id,
        title,
        message,
        type,
        related_id,
        related_type,
        is_read,
        created_at
      ) VALUES (
        NEW.csm_id,
        'Changement de statut établissement',
        'L''établissement "' || COALESCE(NEW.nom, 'Sans nom') || '" est passé de "' || 
        COALESCE(OLD.statut, 'inconnu') || '" à "' || COALESCE(NEW.statut, 'inconnu') || '"',
        'establishment_update',
        NEW.id,
        'etablissement',
        false,
        NOW()
      );
    END IF;
  END IF;
  
  -- Notifier aussi le commercial assigné s'il est différent du CSM
  IF NEW.commercial_id IS NOT NULL AND NEW.commercial_id != COALESCE(NEW.csm_id, '00000000-0000-0000-0000-000000000000') THEN
    SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = NEW.commercial_id) INTO v_user_exists;
    IF v_user_exists THEN
      INSERT INTO public.in_app_notifications (
        user_id,
        title,
        message,
        type,
        related_id,
        related_type,
        is_read,
        created_at
      ) VALUES (
        NEW.commercial_id,
        'Changement de statut établissement',
        'L''établissement "' || COALESCE(NEW.nom, 'Sans nom') || '" est passé de "' || 
        COALESCE(OLD.statut, 'inconnu') || '" à "' || COALESCE(NEW.statut, 'inconnu') || '"',
        'establishment_update',
        NEW.id,
        'etablissement',
        false,
        NOW()
      );
    END IF;
  END IF;
  
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Erreur création notification statut: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: notify_jarvis_new_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_jarvis_new_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  alert_id text;
  alert_priority text;
  normalized_priority text;
BEGIN
  -- Ne créer une alerte que si un responsable est assigné
  IF NEW.responsable_id IS NOT NULL THEN
    -- Générer un ID unique pour l'alerte
    alert_id := 'task_' || NEW.id || '_' || extract(epoch from now())::text;
    
    -- Normaliser la priorité en texte pour éviter les erreurs de cast enum
    normalized_priority := lower(coalesce(NEW.priorite::text, 'medium'));
    
    -- Déterminer la priorité (supporte ancien et nouveau format)
    alert_priority := CASE 
      WHEN normalized_priority IN ('high', 'haute') THEN 'high'
      WHEN normalized_priority IN ('critical', 'urgent', 'urgente') THEN 'critical'
      ELSE 'medium'
    END;
    
    -- Insérer l'alerte
    INSERT INTO jarvis_proactive_alerts (
      id, user_id, type, priority, title, message, action_type, action_data, read, dismissed
    ) VALUES (
      alert_id,
      NEW.responsable_id,
      'new_task',
      alert_priority,
      'Nouvelle tâche assignée',
      '"' || COALESCE(NEW.titre, 'Sans titre') || '"',
      'navigate',
      jsonb_build_object('path', '/taches?id=' || NEW.id, 'task_id', NEW.id),
      false,
      false
    )
    ON CONFLICT (id) DO NOTHING;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: notify_jarvis_task_reassigned(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_jarvis_task_reassigned() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  alert_id text;
BEGIN
  -- Notifier seulement si le responsable change et le nouveau responsable est différent de l'ancien
  IF NEW.responsable_id IS NOT NULL 
     AND (OLD.responsable_id IS NULL OR NEW.responsable_id != OLD.responsable_id) THEN
    
    alert_id := 'task_reassign_' || NEW.id || '_' || extract(epoch from now())::text;
    
    INSERT INTO jarvis_proactive_alerts (
      id, user_id, type, priority, title, message, action_type, action_data, read, dismissed
    ) VALUES (
      alert_id,
      NEW.responsable_id,
      'task_assigned',
      'medium',
      'Tâche transférée',
      'La tâche "' || COALESCE(NEW.titre, 'Sans titre') || '" vous a été assignée',
      'navigate',
      jsonb_build_object('path', '/taches?id=' || NEW.id, 'task_id', NEW.id),
      false,
      false
    )
    ON CONFLICT (id) DO NOTHING;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: notify_pulse_on_task_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_pulse_on_task_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  conv_id UUID;
  task_title TEXT;
  assignee_name TEXT;
BEGIN
  -- Chercher une conversation liée via pulse_message_task_links
  SELECT DISTINCT pm.conversation_id INTO conv_id
  FROM pulse_message_task_links pmtl
  JOIN pulse_messages pm ON pm.id = pmtl.message_id
  WHERE pmtl.task_id = NEW.id
  LIMIT 1;
  
  -- Si pas de conversation liée, utiliser celle directement sur la tâche
  IF conv_id IS NULL THEN
    conv_id := NEW.pulse_conversation_id;
  END IF;
  
  -- Si toujours pas de conversation, ne rien faire
  IF conv_id IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Récupérer le titre de la tâche
  task_title := COALESCE(NEW.titre, 'Sans titre');
  
  -- Récupérer le nom de l'assigné
  SELECT CONCAT(prenom, ' ', nom) INTO assignee_name
  FROM profiles
  WHERE id = NEW.assigne_a;
  
  -- Poster un message système si le statut a changé
  IF TG_OP = 'UPDATE' AND NEW.statut IS DISTINCT FROM OLD.statut THEN
    INSERT INTO pulse_messages (
      conversation_id,
      user_id,
      content,
      message_type,
      ai_processed
    ) VALUES (
      conv_id,
      COALESCE(NEW.assigne_a, NEW.cree_par),
      format('📋 **Tâche mise à jour** : %s%s→ Statut : ~~%s~~ → **%s**', 
             task_title,
             E'\n',
             COALESCE(OLD.statut, 'nouveau'),
             NEW.statut),
      'task_update',
      false
    );
  END IF;
  
  -- Poster un message si la tâche est assignée à quelqu'un d'autre
  IF TG_OP = 'UPDATE' AND NEW.assigne_a IS DISTINCT FROM OLD.assigne_a AND NEW.assigne_a IS NOT NULL THEN
    INSERT INTO pulse_messages (
      conversation_id,
      user_id,
      content,
      message_type,
      ai_processed
    ) VALUES (
      conv_id,
      COALESCE(OLD.assigne_a, NEW.cree_par),
      format('👤 **Tâche réassignée** : %s%s→ Assigné à : **%s**', 
             task_title,
             E'\n',
             COALESCE(assignee_name, 'Non assigné')),
      'task_update',
      false
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: notify_staff_on_client_portal_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_on_client_portal_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  staff_id uuid;
  etab_nom text;
BEGIN
  IF NEW.created_by <> 'etablissement' THEN RETURN NEW; END IF;
  SELECT nom INTO etab_nom FROM etablissements WHERE id = NEW.etablissement_id;

  FOR staff_id IN
    SELECT DISTINCT user_id FROM user_roles
    WHERE role::text IN ('admin','direction','csm','chef_projet','commercial')
  LOOP
    INSERT INTO in_app_notifications(user_id, title, message, type, related_type, related_id)
    VALUES (
      staff_id,
      'Nouvelle tâche portail — ' || COALESCE(etab_nom,'établissement'),
      LEFT(COALESCE(NEW.titre,''), 140),
      'task_assignment',
      'client_portal_task',
      NEW.id
    );
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: notify_staff_on_client_portal_ticket(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_on_client_portal_ticket() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  staff_id uuid;
  etab_nom text;
BEGIN
  IF NEW.created_via_portal IS NOT TRUE THEN RETURN NEW; END IF;
  SELECT nom INTO etab_nom FROM etablissements WHERE id = NEW.etablissement_id;

  FOR staff_id IN
    SELECT DISTINCT user_id FROM user_roles
    WHERE role::text IN ('admin','direction','csm','chef_projet','commercial')
  LOOP
    INSERT INTO in_app_notifications(user_id, title, message, type, related_type, related_id)
    VALUES (
      staff_id,
      'Nouveau ticket portail — ' || COALESCE(etab_nom,'établissement'),
      LEFT(COALESCE(NEW.titre,''), 140),
      'other',
      'support_ticket',
      NEW.id
    );
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: notify_staff_on_client_portal_ticket_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_on_client_portal_ticket_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ticket record;
  v_etab_nom text;
  v_targets uuid[];
  v_uid uuid;
  v_is_staff boolean;
BEGIN
  -- Ignorer commentaires internes
  IF NEW.is_internal = true THEN
    RETURN NEW;
  END IF;

  -- Vérifier si l'auteur est un staff (a un profil)
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE user_id = NEW.author_id)
    INTO v_is_staff;

  IF v_is_staff THEN
    RETURN NEW; -- réponse staff : pas de notif
  END IF;

  SELECT t.id, t.titre, t.assigne_a, t.etablissement_id, e.nom AS etab_nom,
         e.csm_id, e.chef_projet_id, e.commercial_id
    INTO v_ticket
  FROM public.support_tickets t
  LEFT JOIN public.etablissements e ON e.id = t.etablissement_id
  WHERE t.id = NEW.ticket_id;

  -- Cible prioritaire : assigne_a, sinon contacts établissement, sinon admins
  v_targets := ARRAY(
    SELECT DISTINCT u FROM unnest(
      ARRAY[v_ticket.assigne_a, v_ticket.csm_id, v_ticket.chef_projet_id, v_ticket.commercial_id]
    ) AS u
    WHERE u IS NOT NULL
  );

  IF array_length(v_targets, 1) IS NULL THEN
    v_targets := ARRAY(SELECT user_id FROM public.user_roles WHERE role = 'admin'::app_role);
  END IF;

  FOREACH v_uid IN ARRAY v_targets LOOP
    INSERT INTO public.in_app_notifications (user_id, title, message, type, related_id, related_type)
    VALUES (
      v_uid,
      'Nouvelle réponse client',
      COALESCE(v_ticket.etab_nom, 'Établissement') || ' : ' || COALESCE(v_ticket.titre, 'Ticket'),
      'support_ticket_message',
      NEW.ticket_id,
      'support_ticket'
    );
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: notify_task_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_task_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_etablissement_nom TEXT;
  v_user_exists BOOLEAN;
  v_url TEXT;
  v_key TEXT;
  v_body TEXT;
BEGIN
  -- Ne rien faire si pas de responsable assigné
  IF NEW.responsable_id IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Ne notifier que si le responsable change
  IF TG_OP = 'UPDATE' AND OLD.responsable_id IS NOT NULL AND OLD.responsable_id = NEW.responsable_id THEN
    RETURN NEW;
  END IF;
  
  -- Vérifier que l'utilisateur existe
  SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = NEW.responsable_id) INTO v_user_exists;
  IF NOT v_user_exists THEN
    RETURN NEW;
  END IF;
  
  -- Récupérer le nom de l'établissement
  SELECT nom INTO v_etablissement_nom
  FROM public.etablissements
  WHERE id = NEW.etablissement_id;
  
  -- Construire le body du message
  v_body := 'Vous avez été assigné(e) à la tâche "' || COALESCE(NEW.titre, 'Sans titre') || '"' ||
    CASE WHEN v_etablissement_nom IS NOT NULL THEN ' pour ' || v_etablissement_nom ELSE '' END;
  
  -- A) Insérer la notification in-app
  INSERT INTO public.in_app_notifications (
    user_id, title, message, type, related_id, related_type, is_read, created_at
  ) VALUES (
    NEW.responsable_id, 'Nouvelle tâche assignée', v_body,
    'task_assignment', NEW.id, 'tache', false, NOW()
  );
  
  -- B) Envoyer push notification via pg_net
  SELECT value INTO v_url FROM public.app_internal_settings WHERE key = 'supabase_url';
  SELECT value INTO v_key FROM public.app_internal_settings WHERE key = 'service_role_key';
  
  IF v_url IS NOT NULL AND v_key IS NOT NULL THEN
    PERFORM net.http_post(
      url := v_url || '/functions/v1/send-push-notification',
      body := jsonb_build_object(
        'user_id', NEW.responsable_id::text,
        'title', 'Nouvelle tâche assignée',
        'body', COALESCE(v_etablissement_nom || ': ', '') || COALESCE(NEW.titre, 'Sans titre'),
        'url', '/projets',
        'type', 'task',
        'related_id', NEW.id::text
      ),
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_key
      )
    );
  END IF;
  
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Erreur notification assignation: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: notify_task_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_task_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_creator_id UUID;
  v_etablissement_nom TEXT;
  v_user_exists BOOLEAN;
BEGIN
  -- Ne notifier que si le statut passe à "terminée"
  IF NEW.statut != 'terminée' OR OLD.statut = 'terminée' THEN
    RETURN NEW;
  END IF;
  
  -- Récupérer l'ID du créateur de la tâche (si différent du responsable)
  v_creator_id := NEW.created_by;
  
  -- Ne pas notifier si le créateur est le responsable
  IF v_creator_id IS NULL OR v_creator_id = NEW.responsable_id THEN
    RETURN NEW;
  END IF;
  
  -- Vérifier que l'utilisateur existe dans auth.users
  SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = v_creator_id) INTO v_user_exists;
  IF NOT v_user_exists THEN
    RETURN NEW;
  END IF;
  
  -- Récupérer le nom de l'établissement
  SELECT nom INTO v_etablissement_nom
  FROM public.etablissements
  WHERE id = NEW.etablissement_id;
  
  -- Insérer la notification
  INSERT INTO public.in_app_notifications (
    user_id,
    title,
    message,
    type,
    related_id,
    related_type,
    is_read,
    created_at
  ) VALUES (
    v_creator_id,
    'Tâche terminée',
    'La tâche "' || COALESCE(NEW.titre, 'Sans titre') || '" a été marquée comme terminée' ||
    CASE WHEN v_etablissement_nom IS NOT NULL THEN ' (' || v_etablissement_nom || ')' ELSE '' END,
    'task_completion',
    NEW.id,
    'tache',
    false,
    NOW()
  );
  
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Erreur création notification complétion: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: on_status_change_generate_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.on_status_change_generate_tasks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_phase INTEGER;
  v_new_phase INTEGER;
  v_new_categories TEXT[];
BEGIN
  IF OLD.statut = NEW.statut THEN
    RETURN NEW;
  END IF;
  
  v_old_phase := public.get_phase_order(OLD.statut::TEXT);
  v_new_phase := public.get_phase_order(NEW.statut::TEXT);
  
  IF v_new_phase > v_old_phase THEN
    v_new_categories := public.get_phase_categories(NEW.statut::TEXT);
    
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
    SELECT 
      NEW.id,
      mt.categorie_id,
      mt.titre,
      mt.description,
      mt.priorite,
      mt.ordre,
      CASE 
        WHEN mt.delai_jours IS NOT NULL AND NEW.date_signature IS NOT NULL
        THEN NEW.date_signature::date + INTERVAL '1 day' * mt.delai_jours
        WHEN mt.delai_jours IS NOT NULL AND NEW.date_previsionnelle_signature IS NOT NULL
        THEN NEW.date_previsionnelle_signature::date + INTERVAL '1 day' * mt.delai_jours
        ELSE NULL
      END
    FROM public.modeles_taches mt
    INNER JOIN public.categories_taches ct ON ct.id = mt.categorie_id
    WHERE mt.actif = true
      AND LOWER(ct.nom) = ANY(v_new_categories)
      AND NOT EXISTS (
        SELECT 1 FROM public.taches t
        WHERE t.etablissement_id = NEW.id
          AND t.categorie_id = mt.categorie_id
          AND t.titre = mt.titre
      );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: pick_sequence_variant(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pick_sequence_variant(_sequence_id uuid, _step_index integer) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  _winner_id uuid;
  _picked uuid;
  _total_weight integer;
  _r integer;
  _cumul integer := 0;
  _v record;
BEGIN
  -- Si un gagnant est désigné, toujours l'utiliser
  SELECT id INTO _winner_id
  FROM public.email_sequence_variants
  WHERE sequence_id = _sequence_id
    AND step_index = _step_index
    AND is_winner = true
    AND is_active = true
  LIMIT 1;
  IF _winner_id IS NOT NULL THEN RETURN _winner_id; END IF;

  -- Sinon split pondéré
  SELECT COALESCE(SUM(weight), 0) INTO _total_weight
  FROM public.email_sequence_variants
  WHERE sequence_id = _sequence_id
    AND step_index = _step_index
    AND is_active = true;

  IF _total_weight = 0 THEN RETURN NULL; END IF;

  _r := floor(random() * _total_weight)::int;

  FOR _v IN
    SELECT id, weight FROM public.email_sequence_variants
    WHERE sequence_id = _sequence_id
      AND step_index = _step_index
      AND is_active = true
    ORDER BY variant_label
  LOOP
    _cumul := _cumul + _v.weight;
    IF _r < _cumul THEN
      _picked := _v.id;
      EXIT;
    END IF;
  END LOOP;

  RETURN _picked;
END;
$$;


