--
-- Name: prevent_2fa_self_toggle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_2fa_self_toggle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only service_role or the generate-2fa-secret edge function should toggle this
  IF OLD.two_factor_enabled IS DISTINCT FROM NEW.two_factor_enabled THEN
    -- Check if caller is service_role (edge functions use service_role)
    IF current_setting('request.jwt.claims', true)::jsonb ->> 'role' != 'service_role' THEN
      RAISE EXCEPTION 'two_factor_enabled can only be changed by the server after 2FA verification';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_privilege_escalation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_privilege_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Allow admins to update anything
  IF is_admin() THEN
    RETURN NEW;
  END IF;
  
  -- For non-admins, prevent changes to critical security fields
  
  -- Prevent ID changes
  IF OLD.id IS DISTINCT FROM NEW.id THEN
    RAISE EXCEPTION 'Unauthorized: Cannot modify profile ID';
  END IF;
  
  -- Prevent user_id changes
  IF OLD.user_id IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'Unauthorized: Cannot modify user ID';
  END IF;
  
  -- Try to check role column (for user_roles table)
  BEGIN
    IF TG_TABLE_NAME = 'user_roles' THEN
      IF (to_jsonb(OLD)->>'role') IS DISTINCT FROM (to_jsonb(NEW)->>'role') THEN
        RAISE EXCEPTION 'Unauthorized: Cannot modify role';
      END IF;
    END IF;
  EXCEPTION
    WHEN undefined_column THEN
      -- Column doesn't exist, skip this check
      NULL;
  END;
  
  -- Try to check email column (for profiles table)
  BEGIN
    IF TG_TABLE_NAME = 'profiles' THEN
      IF (to_jsonb(OLD)->>'email') IS DISTINCT FROM (to_jsonb(NEW)->>'email') THEN
        RAISE EXCEPTION 'Unauthorized: Cannot modify email';
      END IF;
    END IF;
  EXCEPTION
    WHEN undefined_column THEN
      -- Column doesn't exist, skip this check
      NULL;
  END;
  
  -- Allow updates to safe fields only
  RETURN NEW;
END;
$$;


--
-- Name: prevent_profile_privilege_escalation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_profile_privilege_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('request.jwt.claim.role', true) = 'service_role'
     OR current_setting('role', true) = 'service_role'
  THEN
    RETURN NEW;
  END IF;

  IF NEW.two_factor_enabled IS DISTINCT FROM OLD.two_factor_enabled THEN
    NEW.two_factor_enabled := OLD.two_factor_enabled;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_self_2fa_flag_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_self_2fa_flag_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.two_factor_enabled IS DISTINCT FROM OLD.two_factor_enabled THEN
    -- Allow if explicitly authorized via session GUC set by trusted SECURITY DEFINER function
    IF current_setting('app.allow_2fa_flag_update', true) = 'on' THEN
      RETURN NEW;
    END IF;
    -- Allow service role
    IF auth.role() = 'service_role' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'two_factor_enabled cannot be updated directly. Use the verified 2FA enrollment flow.'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: process_scheduled_report_exports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_scheduled_report_exports() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'net'
    AS $$
DECLARE
  v_row record;
  v_processed int := 0;
  v_url text;
  v_anon text;
  v_resp record;
BEGIN
  -- Récupérer les paramètres pour appeler l'edge function via pg_net
  SELECT value INTO v_url FROM public.app_internal_settings WHERE key = 'supabase_functions_url';
  SELECT value INTO v_anon FROM public.app_internal_settings WHERE key = 'supabase_anon_key';
  IF v_url IS NULL OR v_anon IS NULL THEN
    RETURN jsonb_build_object('error', 'missing_settings', 'processed', 0);
  END IF;

  FOR v_row IN
    SELECT e.id, e.dashboard_id, e.format, e.recipients
    FROM public.custom_dashboard_exports e
    WHERE e.is_active = true
      AND e.next_run_at IS NOT NULL
      AND e.next_run_at <= now()
    LIMIT 50
  LOOP
    -- Marquer en cours
    UPDATE public.custom_dashboard_exports
       SET last_run_at = now(),
           last_status = 'processing',
           error_message = NULL
     WHERE id = v_row.id;

    -- Appeler edge function via pg_net (asynchrone, fire-and-forget)
    BEGIN
      PERFORM net.http_post(
        url := v_url || '/functions/v1/report-export',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_anon,
          'x-scheduled-export-id', v_row.id::text
        ),
        body := jsonb_build_object(
          'dashboard_id', v_row.dashboard_id,
          'format', v_row.format,
          'filters', '{}'::jsonb,
          'scheduled_export_id', v_row.id,
          'recipients', v_row.recipients
        )
      );
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.custom_dashboard_exports
         SET last_status = 'error',
             error_message = SQLERRM
       WHERE id = v_row.id;
      CONTINUE;
    END;

    -- Reprogrammer le prochain run
    UPDATE public.custom_dashboard_exports
       SET next_run_at = public.compute_next_export_run(frequency, hour_utc, day_of_week, day_of_month, now())
     WHERE id = v_row.id;

    v_processed := v_processed + 1;
  END LOOP;

  RETURN jsonb_build_object('processed', v_processed, 'at', now());
END;
$$;


--
-- Name: pulse_archive_message_before_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pulse_archive_message_before_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
        INSERT INTO pulse_message_archive (
            original_message_id, conversation_id, user_id,
            content_snapshot, deleted_by, deletion_reason
        ) VALUES (
            OLD.id, OLD.conversation_id, OLD.user_id,
            jsonb_build_object(
                'content', OLD.content,
                'content_html', OLD.content_html,
                'mentions', OLD.mentions,
                'created_at', OLD.created_at,
                'edited_at', OLD.edited_at,
                'edit_count', OLD.edit_count
            ),
            NEW.deleted_by, NEW.deletion_reason
        );
    END IF;
    RETURN NEW;
END;
$$;


