--
-- Name: pulse_update_reaction_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pulse_update_reaction_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE pulse_messages SET reaction_count = reaction_count + 1 WHERE id = NEW.message_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE pulse_messages SET reaction_count = GREATEST(0, reaction_count - 1) WHERE id = OLD.message_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: pulse_update_reply_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pulse_update_reply_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.parent_message_id IS NOT NULL THEN
        UPDATE pulse_messages SET reply_count = reply_count + 1 WHERE id = NEW.parent_message_id;
    ELSIF TG_OP = 'DELETE' AND OLD.parent_message_id IS NOT NULL THEN
        UPDATE pulse_messages SET reply_count = GREATEST(0, reply_count - 1) WHERE id = OLD.parent_message_id;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: purge_email_tracking_retention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_email_tracking_retention() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_opens_deleted int := 0;
  v_clicks_deleted int := 0;
BEGIN
  DELETE FROM public.email_opens WHERE opened_at < now() - interval '13 months';
  GET DIAGNOSTICS v_opens_deleted = ROW_COUNT;

  DELETE FROM public.email_link_clicks WHERE clicked_at < now() - interval '13 months';
  GET DIAGNOSTICS v_clicks_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'opens_deleted', v_opens_deleted,
    'clicks_deleted', v_clicks_deleted,
    'executed_at', now()
  );
END;
$$;


--
-- Name: purge_old_call_recordings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_call_recordings() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
  r RECORD;
BEGIN
  FOR r IN
    SELECT id, recording_path
    FROM public.calls
    WHERE recording_path IS NOT NULL
      AND recording_purged_at IS NULL
      AND ended_at < (now() - interval '90 days')
    LIMIT 500
  LOOP
    BEGIN
      DELETE FROM storage.objects
      WHERE bucket_id = 'call-recordings' AND name = r.recording_path;

      UPDATE public.calls
      SET recording_path = NULL, recording_purged_at = now()
      WHERE id = r.id;

      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Failed to purge recording %: %', r.recording_path, SQLERRM;
    END;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: recalculate_devis_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_devis_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_devis_id UUID;
  v_montant_ht NUMERIC;
  v_montant_tva NUMERIC;
  v_montant_ttc NUMERIC;
BEGIN
  -- Get devis_id from OLD or NEW
  v_devis_id := COALESCE(NEW.devis_id, OLD.devis_id);
  
  -- Calculate totals from lines
  SELECT 
    COALESCE(SUM(montant_ht), 0),
    COALESCE(SUM(montant_tva), 0),
    COALESCE(SUM(montant_ttc), 0)
  INTO v_montant_ht, v_montant_tva, v_montant_ttc
  FROM public.devis_lignes
  WHERE devis_id = v_devis_id;
  
  -- Update devis
  UPDATE public.devis
  SET 
    montant_ht = v_montant_ht,
    montant_tva = v_montant_tva,
    montant_ttc = v_montant_ttc,
    updated_at = NOW()
  WHERE id = v_devis_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recalculate_facture_paiements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_facture_paiements() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_facture_id UUID;
  v_total_paye NUMERIC;
  v_montant_ttc NUMERIC;
BEGIN
  -- Get facture_id from OLD or NEW
  v_facture_id := COALESCE(NEW.facture_id, OLD.facture_id);
  
  -- Calculate total paid
  SELECT COALESCE(SUM(montant), 0)
  INTO v_total_paye
  FROM public.paiements_factures
  WHERE facture_id = v_facture_id;
  
  -- Get facture amount
  SELECT montant_ttc
  INTO v_montant_ttc
  FROM public.factures
  WHERE id = v_facture_id;
  
  -- Update facture status
  UPDATE public.factures
  SET 
    montant_paye = v_total_paye,
    statut = CASE 
      WHEN v_total_paye >= v_montant_ttc THEN 'payée'
      WHEN v_total_paye > 0 THEN 'partiellement_payée'
      ELSE statut
    END,
    updated_at = NOW()
  WHERE id = v_facture_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recalculate_facture_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_facture_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_facture_id UUID;
  v_montant_ht NUMERIC;
  v_montant_tva NUMERIC;
  v_montant_ttc NUMERIC;
BEGIN
  -- Get facture_id from OLD or NEW
  v_facture_id := COALESCE(NEW.facture_id, OLD.facture_id);
  
  -- Calculate totals from lines
  SELECT 
    COALESCE(SUM(montant_ht), 0),
    COALESCE(SUM(montant_tva), 0),
    COALESCE(SUM(montant_ttc), 0)
  INTO v_montant_ht, v_montant_tva, v_montant_ttc
  FROM public.factures_lignes
  WHERE facture_id = v_facture_id;
  
  -- Update facture
  UPDATE public.factures
  SET 
    montant_ht = v_montant_ht,
    montant_tva = v_montant_tva,
    montant_ttc = v_montant_ttc,
    updated_at = NOW()
  WHERE id = v_facture_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recompute_all_prospect_scores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_all_prospect_scores() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_etab record;
  v_behav jsonb;
  v_processed int := 0;
  v_updated int := 0;
BEGIN
  IF NOT public._scoring_can_write() THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  FOR v_etab IN
    SELECT id, score_conversion, behavioral_score
    FROM public.etablissements
    WHERE statut::text = ANY (ARRAY[
      'Prospect','Contacté','Attente RDV','Reporté','RDV pris','Dans les RDV',
      'Attente post RDV','Etude émise','Négociation','Bloqué'
    ])
  LOOP
    v_processed := v_processed + 1;
    BEGIN
      v_behav := public.compute_behavioral_score(v_etab.id);
      UPDATE public.etablissements
      SET behavioral_score = COALESCE((v_behav->>'behavioral_score')::int, 0),
          engagement_velocity = COALESCE((v_behav->>'engagement_velocity')::numeric, 0),
          last_engagement_at = COALESCE((v_behav->>'last_event_at')::timestamptz, last_engagement_at),
          score_conversion = LEAST(100, GREATEST(0,
            COALESCE(score_conversion,0) - COALESCE(behavioral_score,0) + COALESCE((v_behav->>'behavioral_score')::int, 0)
          ))
      WHERE id = v_etab.id;
      v_updated := v_updated + 1;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  PERFORM public.snapshot_prospect_scores();

  RETURN jsonb_build_object('processed', v_processed, 'updated', v_updated, 'at', now());
END;
$$;


--
-- Name: recompute_email_thread_counters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_email_thread_counters() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_thread_id uuid;
BEGIN
  v_thread_id := COALESCE(NEW.thread_id, OLD.thread_id);
  IF v_thread_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  UPDATE public.email_threads t
  SET
    message_count = sub.cnt,
    unread_count  = sub.unread,
    last_message_date = COALESCE(sub.last_date, t.last_message_date),
    last_message_from_email = COALESCE(sub.last_from_email, t.last_message_from_email),
    last_message_from_name  = COALESCE(sub.last_from_name,  t.last_message_from_name),
    last_message_is_sent = COALESCE(sub.last_is_sent, t.last_message_is_sent),
    last_inbound_from_email = sub.last_in_from_email,
    last_inbound_from_name  = sub.last_in_from_name,
    last_inbound_date       = sub.last_in_date,
    has_sent_messages = COALESCE(sub.has_sent, false),
    is_outbound = COALESCE(sub.has_sent, false) AND sub.last_in_from_email IS NULL,
    updated_at = now()
  FROM (
    SELECT
      COUNT(*)::int AS cnt,
      COUNT(*) FILTER (WHERE is_read = false AND COALESCE(is_sent, false) = false)::int AS unread,
      MAX(COALESCE(received_date, sent_date)) AS last_date,
      bool_or(COALESCE(is_sent, false)) AS has_sent,
      (
        SELECT m.from_address
        FROM public.email_messages m
        WHERE m.thread_id = v_thread_id
        ORDER BY COALESCE(m.received_date, m.sent_date) DESC NULLS LAST,
                 m.created_at DESC NULLS LAST,
                 m.id DESC
        LIMIT 1
      ) AS last_from_email,
      (
        SELECT m.from_name
        FROM public.email_messages m
        WHERE m.thread_id = v_thread_id
        ORDER BY COALESCE(m.received_date, m.sent_date) DESC NULLS LAST,
                 m.created_at DESC NULLS LAST,
                 m.id DESC
        LIMIT 1
      ) AS last_from_name,
      (
        SELECT COALESCE(m.is_sent, false)
        FROM public.email_messages m
        WHERE m.thread_id = v_thread_id
        ORDER BY COALESCE(m.received_date, m.sent_date) DESC NULLS LAST,
                 m.created_at DESC NULLS LAST,
                 m.id DESC
        LIMIT 1
      ) AS last_is_sent,
      (
        SELECT m.from_address
        FROM public.email_messages m
        WHERE m.thread_id = v_thread_id
          AND COALESCE(m.is_sent, false) = false
        ORDER BY COALESCE(m.received_date, m.sent_date) DESC NULLS LAST,
                 m.created_at DESC NULLS LAST,
                 m.id DESC
        LIMIT 1
      ) AS last_in_from_email,
      (
        SELECT m.from_name
        FROM public.email_messages m
        WHERE m.thread_id = v_thread_id
          AND COALESCE(m.is_sent, false) = false
        ORDER BY COALESCE(m.received_date, m.sent_date) DESC NULLS LAST,
                 m.created_at DESC NULLS LAST,
                 m.id DESC
        LIMIT 1
      ) AS last_in_from_name,
      (
        SELECT COALESCE(m.received_date, m.sent_date)
        FROM public.email_messages m
        WHERE m.thread_id = v_thread_id
          AND COALESCE(m.is_sent, false) = false
        ORDER BY COALESCE(m.received_date, m.sent_date) DESC NULLS LAST,
                 m.created_at DESC NULLS LAST,
                 m.id DESC
        LIMIT 1
      ) AS last_in_date
    FROM public.email_messages
    WHERE thread_id = v_thread_id
  ) sub
  WHERE t.id = v_thread_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: FUNCTION recompute_email_thread_counters(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recompute_email_thread_counters() IS 'Session 9 — Lot A: recalcul automatique message_count/unread_count/last_message_date.';


--
-- Name: record_behavioral_event(uuid, public.behavioral_event_type, timestamp with time zone, numeric, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_behavioral_event(_etablissement_id uuid, _event_type public.behavioral_event_type, _occurred_at timestamp with time zone, _weight numeric DEFAULT 1, _source_id uuid DEFAULT NULL::uuid, _source_type text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _id uuid;
BEGIN
  IF _etablissement_id IS NULL THEN RETURN NULL; END IF;
  IF _source_id IS NOT NULL AND _source_type IS NOT NULL THEN
    SELECT id INTO _id FROM public.prospect_behavioral_events
    WHERE source_id = _source_id AND source_type = _source_type AND event_type = _event_type LIMIT 1;
    IF _id IS NOT NULL THEN RETURN _id; END IF;
  END IF;
  INSERT INTO public.prospect_behavioral_events
    (etablissement_id, event_type, occurred_at, weight, source_id, source_type, metadata)
  VALUES (_etablissement_id, _event_type, COALESCE(_occurred_at, now()), _weight, _source_id, _source_type, _metadata)
  RETURNING id INTO _id;
  UPDATE public.etablissements
  SET last_engagement_at = GREATEST(COALESCE(last_engagement_at, '1970-01-01'::timestamptz), COALESCE(_occurred_at, now()))
  WHERE id = _etablissement_id;
  RETURN _id;
END; $$;


--
-- Name: record_email_sync_attempt(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_email_sync_attempt(_account_id uuid, _status text, _error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF _status = 'success' THEN
    UPDATE public.user_email_accounts
       SET last_sync_status = 'success',
           last_sync_error = NULL,
           last_sync_attempted_at = NOW(),
           consecutive_failures = 0
     WHERE id = _account_id;
  ELSE
    UPDATE public.user_email_accounts
       SET last_sync_status = COALESCE(_status, 'error'),
           last_sync_error = LEFT(COALESCE(_error_message, ''), 1000),
           last_sync_attempted_at = NOW(),
           consecutive_failures = consecutive_failures + 1
     WHERE id = _account_id;
  END IF;
END;
$$;


--
-- Name: regenerate_missing_tasks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regenerate_missing_tasks(p_etablissement_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
  v_date_signature DATE;
  v_date_previsionnelle DATE;
  v_statut TEXT;
  v_phase_categories TEXT[];
BEGIN
  SELECT date_signature, date_previsionnelle_signature, statut::TEXT 
  INTO v_date_signature, v_date_previsionnelle, v_statut
  FROM public.etablissements 
  WHERE id = p_etablissement_id;
  
  v_phase_categories := public.get_phase_categories(v_statut);
  
  INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
  SELECT 
    p_etablissement_id,
    mt.categorie_id,
    mt.titre,
    mt.description,
    mt.priorite,
    mt.ordre,
    CASE 
      WHEN mt.delai_jours IS NOT NULL AND v_date_signature IS NOT NULL
      THEN v_date_signature + INTERVAL '1 day' * mt.delai_jours
      WHEN mt.delai_jours IS NOT NULL AND v_date_previsionnelle IS NOT NULL
      THEN v_date_previsionnelle + INTERVAL '1 day' * mt.delai_jours
      ELSE NULL
    END
  FROM public.modeles_taches mt
  INNER JOIN public.categories_taches ct ON ct.id = mt.categorie_id
  WHERE mt.actif = true
    AND LOWER(ct.nom) = ANY(v_phase_categories)
    AND NOT EXISTS (
      SELECT 1 FROM public.taches t
      WHERE t.etablissement_id = p_etablissement_id
        AND t.categorie_id = mt.categorie_id
        AND t.titre = mt.titre
    );
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: require_admin_2fa(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_admin_2fa(operation_name text DEFAULT 'sensitive operation'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Check if current user is admin with 2FA using new system
  IF NOT public.has_admin_role_strict(auth.uid()) THEN
    -- Log the attempt
    INSERT INTO public.security_logs (
      log_type,
      user_id,
      user_email,
      risk_level,
      metadata
    ) VALUES (
      'unauthorized_admin_operation_attempt',
      auth.uid(),
      (SELECT email FROM public.profiles WHERE user_id = auth.uid()),
      'high',
      jsonb_build_object(
        'operation', operation_name,
        'timestamp', now(),
        'has_admin_role', public.has_admin_role(auth.uid()),
        'has_2fa', (SELECT two_factor_enabled FROM public.profiles WHERE user_id = auth.uid())
      )
    );
    
    RAISE EXCEPTION 'Operation "%" requires admin privileges with 2FA enabled', operation_name;
  END IF;
  
  -- Log successful admin operation  
  INSERT INTO public.security_logs (
    log_type,
    user_id,
    user_email,
    risk_level,
    metadata
  ) VALUES (
    'admin_operation_authorized',
    auth.uid(),
    (SELECT email FROM public.profiles WHERE user_id = auth.uid()),
    'medium',
    jsonb_build_object(
      'operation', operation_name,
      'timestamp', now()
    )
  );
  
  RETURN true;
END;
$$;


--
-- Name: reset_client_portal_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_client_portal_password(p_user_id uuid) RETURNS TABLE(temp_password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_password text;
  v_hash text;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin'::app_role)
          OR public.has_role(auth.uid(), 'direction'::app_role)) THEN
    RAISE EXCEPTION 'Accès refusé : admin ou direction requis';
  END IF;

  v_password := encode(extensions.gen_random_bytes(10), 'base64');
  v_password := replace(replace(replace(v_password, '/', 'A'), '+', 'B'), '=', '');
  v_password := substring(v_password from 1 for 14);

  v_hash := extensions.crypt(v_password, extensions.gen_salt('bf', 10));

  UPDATE public.client_portal_users
     SET password_hash = v_hash,
         updated_at = now()
   WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Compte portail introuvable';
  END IF;

  RETURN QUERY SELECT v_password;
END;
$$;


--
-- Name: reset_prospect_tasks_to_model(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_prospect_tasks_to_model() RETURNS TABLE(etablissement_id uuid, etablissement_nom text, anciennes_taches integer, nouvelles_taches integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  prospect_record RECORD;
  commercial_category_id UUID;
  old_tasks_count INTEGER;
  new_tasks_count INTEGER;
BEGIN
  -- Récupérer l'ID de la catégorie Commercial/Prospect
  SELECT id INTO commercial_category_id 
  FROM public.categories_taches 
  WHERE nom = 'Commercial';
  
  -- Si la catégorie n'existe pas, on ne peut pas continuer
  IF commercial_category_id IS NULL THEN
    RAISE EXCEPTION 'Catégorie Commercial non trouvée';
  END IF;
  
  -- Parcourir tous les établissements prospects
  FOR prospect_record IN 
    SELECT e.id, e.nom, e.date_signature
    FROM public.etablissements e
    WHERE e.statut = 'Prospect'
    ORDER BY e.created_at
  LOOP
    -- Compter les tâches existantes
    SELECT COUNT(*) INTO old_tasks_count
    FROM public.taches t
    WHERE t.etablissement_id = prospect_record.id;
    
    -- Supprimer toutes les tâches existantes pour cet établissement
    DELETE FROM public.taches t
    WHERE t.etablissement_id = prospect_record.id;
    
    -- Créer uniquement les tâches du modèle Commercial/Prospect
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
    SELECT 
      prospect_record.id,
      mt.categorie_id,
      mt.titre,
      mt.description,
      mt.priorite,
      mt.ordre,
      CASE 
        WHEN mt.delai_jours IS NOT NULL 
        THEN prospect_record.date_signature + INTERVAL '1 day' * mt.delai_jours
        ELSE NULL
      END
    FROM public.modeles_taches mt
    WHERE mt.actif = true 
      AND mt.categorie_id = commercial_category_id;
    
    -- Compter les nouvelles tâches créées
    GET DIAGNOSTICS new_tasks_count = ROW_COUNT;
    
    -- Remettre la progression à 0
    UPDATE public.etablissements e
    SET progression = 0, updated_at = now()
    WHERE e.id = prospect_record.id;
    
    -- Retourner les informations pour chaque établissement traité
    RETURN QUERY SELECT 
      prospect_record.id,
      prospect_record.nom,
      old_tasks_count,
      new_tasks_count;
  END LOOP;
  
  RETURN;
END;
$$;


--
-- Name: sanitize_audit_log_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_audit_log_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.old_values := sanitize_audit_values(NEW.old_values);
  NEW.new_values := sanitize_audit_values(NEW.new_values);
  RETURN NEW;
END;
$$;


--
-- Name: sanitize_audit_values(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_audit_values(p_values jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sensitive_fields text[] := ARRAY[
    'encrypted_password', 'password', 'mot_de_passe',
    'salaire_net', 'salaire_brut', 'salaire_mensuel_brut', 'salaire_mensuel_net',
    'iban', 'bic', 'numero_secu', 'numero_securite_sociale',
    'date_naissance', 'adresse', 'telephone', 'email_personnel',
    'api_key', 'secret', 'token', 'two_factor_secret'
  ];
  field text;
  result jsonb := p_values;
BEGIN
  IF p_values IS NULL THEN
    RETURN NULL;
  END IF;
  
  FOREACH field IN ARRAY sensitive_fields LOOP
    IF result ? field THEN
      result := jsonb_set(result, ARRAY[field], '"[DONNÉES MASQUÉES]"'::jsonb);
    END IF;
  END LOOP;
  RETURN result;
END;
$$;


--
-- Name: FUNCTION sanitize_audit_values(p_values jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sanitize_audit_values(p_values jsonb) IS 'Masque automatiquement les champs sensibles (mots de passe, salaires, IBAN, etc.) dans les logs RGPD';


--
-- Name: search_email_threads(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_email_threads(search_term text) RETURNS TABLE(thread_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Vérifier que l'utilisateur est authentifié
  IF auth.uid() IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT et.id as thread_id
  FROM email_threads et
  LEFT JOIN email_messages em ON em.thread_id = et.id
  LEFT JOIN user_email_accounts uea ON uea.id = et.user_email_account_id
  LEFT JOIN profiles p ON p.id = uea.profile_id
  WHERE 
    -- Filtrer par utilisateur (RLS via code)
    p.user_id = auth.uid()
    AND (
      -- Recherche dans le sujet
      et.subject ILIKE '%' || search_term || '%'
      -- Recherche dans le résumé IA
      OR et.ai_summary ILIKE '%' || search_term || '%'
      -- Recherche dans l'adresse de l'expéditeur
      OR em.from_address ILIKE '%' || search_term || '%'
      -- Recherche dans le nom de l'expéditeur
      OR em.from_name ILIKE '%' || search_term || '%'
      -- Recherche dans le corps des messages
      OR em.body_text ILIKE '%' || search_term || '%'
    );
END;
$$;


--
-- Name: search_email_threads_body(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_email_threads_body(search_term text) RETURNS TABLE(thread_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '5s'
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT em.thread_id
  FROM email_messages em
  WHERE 
    em.body_text ILIKE '%' || search_term || '%'
    OR em.from_name ILIKE '%' || search_term || '%'
    OR em.from_address ILIKE '%' || search_term || '%'
  LIMIT 100;
END;
$$;


--
-- Name: search_jarvis_conversations(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_jarvis_conversations(p_user_id uuid, p_search_term text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(conversation_id uuid, message_content text, message_role text, message_created_at timestamp with time zone, conversation_title text, relevance_score real)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.id AS conversation_id,
    m.content AS message_content,
    m.role AS message_role,
    m.created_at AS message_created_at,
    c.title AS conversation_title,
    ts_rank(to_tsvector('french', m.content), plainto_tsquery('french', p_search_term)) AS relevance_score
  FROM jarvis_conversations c
  JOIN jarvis_messages m ON m.conversation_id = c.id
  WHERE c.user_id = p_user_id
    AND to_tsvector('french', m.content) @@ plainto_tsquery('french', p_search_term)
  ORDER BY relevance_score DESC, m.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


