--
-- Name: set_client_portal_task_done_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_client_portal_task_done_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.statut = 'done' AND (TG_OP = 'INSERT' OR OLD.statut IS DISTINCT FROM 'done') THEN
    NEW.done_at = COALESCE(NEW.done_at, now());
  ELSIF NEW.statut <> 'done' THEN
    NEW.done_at = NULL;
    NEW.done_by = NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_date_go_live(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_date_go_live() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  deploiement_task_date DATE;
BEGIN
  -- Si le statut change vers "Production" et que date_go_live n'est pas déjà définie
  IF NEW.statut = 'Production' 
     AND (OLD.statut IS NULL OR OLD.statut != 'Production')
     AND NEW.date_go_live IS NULL THEN
    
    -- Chercher la date de réalisation de la tâche "Déploiement production"
    SELECT t.date_realisation INTO deploiement_task_date
    FROM taches t
    JOIN categories_taches ct ON ct.id = t.categorie_id
    WHERE t.etablissement_id = NEW.id
      AND ct.nom = 'Déploiement'
      AND t.titre = 'Déploiement production'
      AND t.statut = 'Terminé'
      AND t.date_realisation IS NOT NULL
    ORDER BY t.date_realisation DESC
    LIMIT 1;
    
    -- Utiliser cette date ou la date actuelle si non trouvée
    NEW.date_go_live := COALESCE(deploiement_task_date, CURRENT_DATE);
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: set_sip_credentials(text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sip_credentials(p_sip_uri text, p_sip_username text, p_sip_password text, p_sip_domain text, p_sip_transport text DEFAULT 'wss'::text, p_sip_proxy text DEFAULT NULL::text, p_caller_id text DEFAULT NULL::text, p_record_calls boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_key TEXT;
  v_encrypted TEXT;
  v_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT value INTO v_key FROM public.app_internal_settings WHERE key = 'email_encryption_key' LIMIT 1;

  IF v_key IS NULL THEN
    RAISE EXCEPTION 'Encryption key not configured';
  END IF;

  v_encrypted := encode(extensions.pgp_sym_encrypt(p_sip_password, v_key), 'base64');

  INSERT INTO public.user_phone_settings (
    user_id, sip_uri, sip_username, sip_password_encrypted,
    sip_domain, sip_transport, sip_proxy, caller_id, record_calls, is_active
  ) VALUES (
    v_user_id, p_sip_uri, p_sip_username, v_encrypted,
    p_sip_domain, p_sip_transport::public.sip_transport, p_sip_proxy, p_caller_id, p_record_calls, true
  )
  ON CONFLICT (user_id) DO UPDATE SET
    sip_uri = EXCLUDED.sip_uri,
    sip_username = EXCLUDED.sip_username,
    sip_password_encrypted = EXCLUDED.sip_password_encrypted,
    sip_domain = EXCLUDED.sip_domain,
    sip_transport = EXCLUDED.sip_transport,
    sip_proxy = EXCLUDED.sip_proxy,
    caller_id = EXCLUDED.caller_id,
    record_calls = EXCLUDED.record_calls,
    is_active = true,
    updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: set_two_factor_enabled(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_two_factor_enabled(_user_id uuid, _enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Only the user themselves (via their authenticated session) or service role may toggle their own flag,
  -- and only through this function (which the edge function calls AFTER verifying a TOTP token).
  IF auth.role() <> 'service_role' AND auth.uid() <> _user_id THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('app.allow_2fa_flag_update', 'on', true);
  UPDATE public.profiles SET two_factor_enabled = _enabled WHERE user_id = _user_id;
  PERFORM set_config('app.allow_2fa_flag_update', 'off', true);
END;
$$;


