--
-- Name: skip_duplicate_pending_suggestion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.skip_duplicate_pending_suggestion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'pending' AND EXISTS (
    SELECT 1 FROM public.email_to_etablissement_suggestions
    WHERE email_thread_id = NEW.email_thread_id
      AND COALESCE(suggested_etablissement_id, '00000000-0000-0000-0000-000000000000'::uuid)
          = COALESCE(NEW.suggested_etablissement_id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND suggestion_type = NEW.suggestion_type
      AND status = 'pending'
  ) THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: snapshot_prospect_scores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_prospect_scores() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int := 0;
BEGIN
  INSERT INTO public.prospect_score_history (etablissement_id, score, static_score, behavioral_score, engagement_velocity, factors, computed_at)
  SELECT
    e.id,
    COALESCE(e.score_conversion, 0),
    GREATEST(0, COALESCE(e.score_conversion, 0) - COALESCE(e.behavioral_score, 0)),
    COALESCE(e.behavioral_score, 0),
    COALESCE(e.engagement_velocity, 0),
    '[]'::jsonb,
    now()
  FROM public.etablissements e
  WHERE e.statut::text = ANY (ARRAY[
    'Prospect','Contacté','Attente RDV','Reporté','RDV pris','Dans les RDV',
    'Attente post RDV','Etude émise','Négociation','Bloqué'
  ]);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('snapshotted', v_count, 'at', now());
END;
$$;


