--
-- Name: submit_enquete(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_enquete(p_token text, p_type text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_campagne public.enquetes_campagnes%ROWTYPE;
  v_inserted_id UUID;
BEGIN
  -- Récupérer et valider la campagne
  SELECT * INTO v_campagne FROM public.enquetes_campagnes WHERE token_unique = p_token;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'token_invalide');
  END IF;

  IF v_campagne.expires_at < now() THEN
    UPDATE public.enquetes_campagnes SET status = 'expired' WHERE id = v_campagne.id;
    RETURN jsonb_build_object('success', false, 'error', 'token_expire');
  END IF;

  IF v_campagne.status = 'responded' THEN
    RETURN jsonb_build_object('success', false, 'error', 'deja_repondu');
  END IF;

  IF v_campagne.type::text <> p_type THEN
    RETURN jsonb_build_object('success', false, 'error', 'type_invalide');
  END IF;

  -- Insertion selon le type
  IF p_type = 'post_formation' THEN
    INSERT INTO public.enquetes_satisfaction_formation (
      etablissement_id, user_id, session_id, campagne_id,
      nom_prenom, fonction, fonction_autre, dpi, dpi_autre, date_formation,
      formation_complete, explications_claires, reponses_questions, reponses_questions_precision,
      intention_usage, autonomie, acces_formation_ligne,
      fonctionnalites_priorite, fonctionnalites_autre,
      note_globale, commentaire_libre, token_enquete, repondu_via
    ) VALUES (
      v_campagne.etablissement_id, v_campagne.user_id, v_campagne.session_id, v_campagne.id,
      p_payload->>'nom_prenom',
      (p_payload->>'fonction')::public.enquete_fonction,
      p_payload->>'fonction_autre',
      (p_payload->>'dpi'),
      p_payload->>'dpi_autre',
      NULLIF(p_payload->>'date_formation','')::date,
      p_payload->>'formation_complete',
      p_payload->>'explications_claires',
      p_payload->>'reponses_questions',
      p_payload->>'reponses_questions_precision',
      p_payload->>'intention_usage',
      p_payload->>'autonomie',
      p_payload->>'acces_formation_ligne',
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_payload->'fonctionnalites_priorite')), '{}'),
      p_payload->>'fonctionnalites_autre',
      (p_payload->>'note_globale')::int,
      p_payload->>'commentaire_libre',
      p_token,
      v_campagne.canal
    ) RETURNING id INTO v_inserted_id;

  ELSIF p_type = 'ces' THEN
    INSERT INTO public.enquetes_ces (
      etablissement_id, user_id, campagne_id,
      nom_prenom, fonction, fonction_autre, dpi, dpi_autre,
      formation_recue, modules_formes, effort_score, facteurs_freins,
      token_enquete, repondu_via
    ) VALUES (
      v_campagne.etablissement_id, v_campagne.user_id, v_campagne.id,
      p_payload->>'nom_prenom',
      (p_payload->>'fonction')::public.enquete_fonction,
      p_payload->>'fonction_autre',
      (p_payload->>'dpi'),
      p_payload->>'dpi_autre',
      p_payload->>'formation_recue',
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_payload->'modules_formes')), '{}'),
      (p_payload->>'effort_score')::int,
      p_payload->>'facteurs_freins',
      p_token, v_campagne.canal
    ) RETURNING id INTO v_inserted_id;

  ELSIF p_type = 'satisfaction' THEN
    INSERT INTO public.enquetes_satisfaction_solution (
      etablissement_id, user_id, campagne_id,
      nom_prenom, fonction, fonction_autre, dpi, dpi_autre,
      modules_utilises, frequence_usage, reduction_temps_admin, aide_cotation,
      gain_temps_estime, fonctionnalites_principales, fonctionnalites_autre,
      fonctionnalites_non_utilisees, satisfaction_globale, nps_score,
      points_forts, ameliorations, token_enquete, repondu_via
    ) VALUES (
      v_campagne.etablissement_id, v_campagne.user_id, v_campagne.id,
      p_payload->>'nom_prenom',
      (p_payload->>'fonction')::public.enquete_fonction,
      p_payload->>'fonction_autre',
      (p_payload->>'dpi'),
      p_payload->>'dpi_autre',
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_payload->'modules_utilises')), '{}'),
      p_payload->>'frequence_usage',
      p_payload->>'reduction_temps_admin',
      p_payload->>'aide_cotation',
      p_payload->>'gain_temps_estime',
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(p_payload->'fonctionnalites_principales')), '{}'),
      p_payload->>'fonctionnalites_autre',
      p_payload->>'fonctionnalites_non_utilisees',
      (p_payload->>'satisfaction_globale')::int,
      (p_payload->>'nps_score')::int,
      p_payload->>'points_forts',
      p_payload->>'ameliorations',
      p_token, v_campagne.canal
    ) RETURNING id INTO v_inserted_id;

  ELSIF p_type = 'suivi_csm' THEN
    INSERT INTO public.enquetes_suivi_csm (
      etablissement_id, user_id, csm_id, campagne_id,
      nom_prenom, fonction, fonction_autre, dpi, dpi_autre,
      contribution_usage, comprehension_enjeux, reactivite, utilite_comites,
      points_forts_axes, frequence_adaptee, note_globale, ameliorations,
      token_enquete, repondu_via
    ) VALUES (
      v_campagne.etablissement_id, v_campagne.user_id,
      COALESCE(NULLIF(p_payload->>'csm_id','')::uuid, v_campagne.csm_id),
      v_campagne.id,
      p_payload->>'nom_prenom',
      (p_payload->>'fonction')::public.enquete_fonction,
      p_payload->>'fonction_autre',
      (p_payload->>'dpi'),
      p_payload->>'dpi_autre',
      p_payload->>'contribution_usage',
      p_payload->>'comprehension_enjeux',
      p_payload->>'reactivite',
      p_payload->>'utilite_comites',
      p_payload->>'points_forts_axes',
      p_payload->>'frequence_adaptee',
      (p_payload->>'note_globale')::int,
      p_payload->>'ameliorations',
      p_token, v_campagne.canal
    ) RETURNING id INTO v_inserted_id;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'type_inconnu');
  END IF;

  UPDATE public.enquetes_campagnes
  SET status = 'responded', responded_at = now()
  WHERE id = v_campagne.id;

  RETURN jsonb_build_object('success', true, 'id', v_inserted_id);
END;
$$;


--
-- Name: sync_all_tasks_with_models(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_all_tasks_with_models(p_etablissement_id uuid) RETURNS TABLE(etablissement_nom text, statut_etablissement public.statut_etablissement, taches_supprimees integer, taches_creees integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_etablissement RECORD;
  v_deleted_count INTEGER := 0;
  v_created_count INTEGER := 0;
BEGIN
  -- Récupérer les infos de l'établissement
  SELECT nom, statut, date_signature, date_previsionnelle_signature
  INTO v_etablissement
  FROM public.etablissements
  WHERE id = p_etablissement_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Établissement non trouvé: %', p_etablissement_id;
  END IF;
  
  -- Supprimer TOUTES les tâches existantes
  DELETE FROM public.taches
  WHERE etablissement_id = p_etablissement_id;
  
  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
  
  -- Créer TOUTES les tâches actives des modèles (toutes phases confondues)
  INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, ordre, echeance)
  SELECT 
    p_etablissement_id,
    mt.categorie_id,
    mt.titre,
    mt.description,
    mt.priorite,
    mt.ordre,
    CASE 
      WHEN mt.delai_jours IS NOT NULL AND v_etablissement.date_signature IS NOT NULL
      THEN v_etablissement.date_signature + INTERVAL '1 day' * mt.delai_jours
      WHEN mt.delai_jours IS NOT NULL AND v_etablissement.date_previsionnelle_signature IS NOT NULL
      THEN v_etablissement.date_previsionnelle_signature + INTERVAL '1 day' * mt.delai_jours
      ELSE NULL
    END
  FROM public.modeles_taches mt
  WHERE mt.actif = true
  ORDER BY mt.ordre;
  
  GET DIAGNOSTICS v_created_count = ROW_COUNT;
  
  -- Retourner le résumé
  RETURN QUERY SELECT 
    v_etablissement.nom::TEXT,
    v_etablissement.statut,
    v_deleted_count,
    v_created_count;
END;
$$;


--
-- Name: sync_client_portal_requests_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_client_portal_requests_legacy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.subject IS NULL THEN NEW.subject := NEW.sujet; END IF;
    IF NEW.sujet IS NULL THEN NEW.sujet := NEW.subject; END IF;
    IF NEW.client_portal_user_id IS NULL THEN NEW.client_portal_user_id := NEW.user_id; END IF;
    IF NEW.user_id IS NULL THEN NEW.user_id := NEW.client_portal_user_id; END IF;
    IF NEW.status IS NULL THEN
      NEW.status := CASE NEW.statut
        WHEN 'nouveau' THEN 'open' WHEN 'en_cours' THEN 'open'
        WHEN 'traite' THEN 'handled' WHEN 'ferme' THEN 'closed' ELSE 'open' END;
    END IF;
  ELSE
    IF NEW.sujet IS DISTINCT FROM OLD.sujet THEN NEW.subject := NEW.sujet;
    ELSIF NEW.subject IS DISTINCT FROM OLD.subject THEN NEW.sujet := NEW.subject;
    END IF;
    IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN NEW.client_portal_user_id := NEW.user_id;
    ELSIF NEW.client_portal_user_id IS DISTINCT FROM OLD.client_portal_user_id THEN NEW.user_id := NEW.client_portal_user_id;
    END IF;
    IF NEW.statut IS DISTINCT FROM OLD.statut THEN
      NEW.status := CASE NEW.statut
        WHEN 'nouveau' THEN 'open' WHEN 'en_cours' THEN 'open'
        WHEN 'traite' THEN 'handled' WHEN 'ferme' THEN 'closed' ELSE 'open' END;
    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.statut := CASE NEW.status
        WHEN 'open' THEN 'nouveau' WHEN 'handled' THEN 'traite' WHEN 'closed' THEN 'ferme' ELSE 'nouveau' END;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_client_portal_users_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_client_portal_users_legacy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.nom IS DISTINCT FROM OLD.nom OR NEW.prenom IS DISTINCT FROM OLD.prenom THEN
    NEW.full_name := trim(both ' ' FROM coalesce(NEW.prenom,'') || ' ' || coalesce(NEW.nom,''));
  ELSIF NEW.full_name IS DISTINCT FROM OLD.full_name AND NEW.full_name IS NOT NULL THEN
    NEW.prenom := COALESCE(NULLIF(split_part(NEW.full_name, ' ', 1), ''), NEW.prenom);
    NEW.nom := COALESCE(NULLIF(substring(NEW.full_name FROM position(' ' IN NEW.full_name) + 1), ''), NEW.nom);
  END IF;
  IF NEW.actif IS DISTINCT FROM OLD.actif THEN NEW.is_active := NEW.actif;
  ELSIF NEW.is_active IS DISTINCT FROM OLD.is_active THEN NEW.actif := NEW.is_active;
  END IF;
  IF NEW.last_login IS DISTINCT FROM OLD.last_login THEN NEW.last_login_at := NEW.last_login;
  ELSIF NEW.last_login_at IS DISTINCT FROM OLD.last_login_at THEN NEW.last_login := NEW.last_login_at;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_client_portal_users_legacy_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_client_portal_users_legacy_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.full_name IS NULL AND (NEW.nom IS NOT NULL OR NEW.prenom IS NOT NULL) THEN
    NEW.full_name := trim(both ' ' FROM coalesce(NEW.prenom,'') || ' ' || coalesce(NEW.nom,''));
  END IF;
  IF (NEW.nom IS NULL AND NEW.prenom IS NULL) AND NEW.full_name IS NOT NULL THEN
    NEW.prenom := NULLIF(split_part(NEW.full_name, ' ', 1), '');
    NEW.nom := NULLIF(substring(NEW.full_name FROM position(' ' IN NEW.full_name) + 1), '');
  END IF;
  IF NEW.is_active IS NULL THEN NEW.is_active := COALESCE(NEW.actif, true); END IF;
  IF NEW.actif IS NULL THEN NEW.actif := COALESCE(NEW.is_active, true); END IF;
  IF NEW.last_login_at IS NULL AND NEW.last_login IS NOT NULL THEN NEW.last_login_at := NEW.last_login; END IF;
  IF NEW.last_login IS NULL AND NEW.last_login_at IS NOT NULL THEN NEW.last_login := NEW.last_login_at; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_customer_health_on_etablissement_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_health_on_etablissement_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  calculated_value numeric;
BEGIN
  -- Calculer le CA avec la logique de priorité standard
  -- Priorité 1: Modèle statique numérique
  IF NEW.modele_statique_succes IS NOT NULL 
     AND NEW.modele_statique_succes ~ '^[0-9]+\.?[0-9]*$' THEN
    calculated_value := NEW.modele_statique_succes::numeric;
  
  -- Priorité 2: Palliers définis
  ELSIF NEW.pallier_vise IS NOT NULL 
        AND NEW.nombre_passages_urgences_annuel IS NOT NULL THEN
    calculated_value := NEW.nombre_passages_urgences_annuel * 
      CASE NEW.pallier_vise
        WHEN 'Pallier 1' THEN 2.5
        WHEN 'Pallier 2' THEN 3.0
        WHEN 'Pallier 3' THEN 3.5
        WHEN 'Pallier 4' THEN 4.0
        ELSE 3.0
      END;
  
  -- Priorité 3: Approximation standard 1.5€/passage
  ELSIF NEW.nombre_passages_urgences_annuel IS NOT NULL THEN
    calculated_value := NEW.nombre_passages_urgences_annuel * 1.5;
  
  ELSE
    calculated_value := 0;
  END IF;
  
  -- Upsert dans customer_health_metrics
  INSERT INTO customer_health_metrics (
    etablissement_id,
    contract_value,
    contract_start_date,
    updated_at
  )
  VALUES (
    NEW.id,
    calculated_value,
    NEW.date_go_live,
    NOW()
  )
  ON CONFLICT (etablissement_id)
  DO UPDATE SET
    contract_value = calculated_value,
    contract_start_date = COALESCE(NEW.date_go_live, customer_health_metrics.contract_start_date),
    updated_at = NOW();
  
  RETURN NEW;
END;
$_$;


--
-- Name: sync_rd_story_to_client_portal_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_rd_story_to_client_portal_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_etab_statut text;
  v_phase text;
  v_task_statut text;
  v_clean_description text;
BEGIN
  -- Cas 1 : etablissement_id retiré → supprimer la task liée
  IF NEW.etablissement_id IS NULL THEN
    IF TG_OP = 'UPDATE' AND OLD.etablissement_id IS NOT NULL THEN
      DELETE FROM public.client_portal_tasks 
      WHERE source_rd_story_id = NEW.id;
    END IF;
    RETURN NEW;
  END IF;

  -- Récupérer le statut de l'établissement pour dériver la phase
  SELECT statut INTO v_etab_statut
  FROM public.etablissements
  WHERE id = NEW.etablissement_id;

  IF v_etab_statut = 'Production' THEN
    v_phase := 'production';
  ELSE
    v_phase := 'deploiement';
  END IF;

  -- Mapping statut story → statut task
  v_task_statut := CASE 
    WHEN NEW.statut = 'done' THEN 'done'
    WHEN NEW.statut = 'in_progress' THEN 'in_progress'
    ELSE 'todo'
  END;

  -- Strip HTML pour la description (RichTextEditor)
  v_clean_description := regexp_replace(COALESCE(NEW.description, ''), '<[^>]*>', '', 'g');
  IF v_clean_description = '' THEN
    v_clean_description := NULL;
  END IF;

  -- UPSERT idempotent sur source_rd_story_id
  INSERT INTO public.client_portal_tasks (
    etablissement_id, titre, description, assignee, created_by,
    statut, phase, source_rd_story_id
  ) VALUES (
    NEW.etablissement_id,
    NEW.titre,
    v_clean_description,
    'etablissement',
    'marque',
    v_task_statut,
    v_phase,
    NEW.id
  )
  ON CONFLICT (source_rd_story_id) WHERE source_rd_story_id IS NOT NULL
  DO UPDATE SET
    etablissement_id = EXCLUDED.etablissement_id,
    titre = EXCLUDED.titre,
    description = EXCLUDED.description,
    statut = EXCLUDED.statut,
    phase = EXCLUDED.phase,
    updated_at = now();

  RETURN NEW;
END;
$$;


--
-- Name: sync_rh_to_tresorerie(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_rh_to_tresorerie() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile_nom TEXT;
BEGIN
  -- Récupérer le nom du profil avec fallback robuste
  SELECT COALESCE(
    prenom || ' ' || nom, 
    nom, 
    prenom,
    email,
    'Employé inconnu'
  ) 
  INTO v_profile_nom 
  FROM profiles 
  WHERE id = NEW.profile_id;
  
  -- Si le profil n'existe pas du tout, utiliser un fallback
  IF v_profile_nom IS NULL THEN
    v_profile_nom := 'Employé ID: ' || NEW.profile_id;
    RAISE WARNING 'Profile non trouvé pour le salaire: profile_id=%', NEW.profile_id;
  END IF;
  
  -- Insérer ou mettre à jour la dépense de trésorerie
  INSERT INTO tresorerie_depenses (
    nom, 
    montant, 
    date_prevue, 
    categorie_code,
    est_recurrent, 
    source, 
    source_id,
    statut
  )
  VALUES (
    'Salaire ' || v_profile_nom, 
    NEW.salaire_net, 
    (date_trunc('month', NEW.mois)::date + interval '4 days')::date,
    'DEP_SALAIRES_NETS',
    TRUE, 
    'rh_salaires', 
    NEW.id,
    'en_attente'
  )
  ON CONFLICT (source_id, source) 
  DO UPDATE SET 
    montant = EXCLUDED.montant,
    nom = EXCLUDED.nom,
    date_prevue = EXCLUDED.date_prevue,
    updated_at = NOW();
  
  RETURN NEW;
END;
$$;


