--
-- Name: terminate_user_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_user_session(target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Vérifier que l'appelant est admin avec 2FA
  IF NOT is_admin_strict() THEN
    RAISE EXCEPTION 'Unauthorized: Admin with 2FA required';
  END IF;
  
  -- Logger l'action
  INSERT INTO public.security_logs (
    log_type,
    user_id,
    user_email,
    risk_level,
    metadata
  ) VALUES (
    'session_terminated',
    target_user_id,
    (SELECT email FROM public.profiles WHERE user_id = target_user_id),
    'medium',
    jsonb_build_object(
      'terminated_by', auth.uid(),
      'timestamp', now()
    )
  );
END;
$$;


--
-- Name: tg_enquete_plan_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_enquete_plan_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_score_problematique BOOLEAN := false;
  v_titre TEXT;
  v_description TEXT;
  v_assignee_id UUID;
  v_table_name TEXT := TG_TABLE_NAME;
BEGIN
  -- Déterminer si action requise selon le type
  IF v_table_name = 'enquetes_satisfaction_formation' AND NEW.note_globale < 6 THEN
    v_score_problematique := true;
    v_titre := 'Score formation faible (' || NEW.note_globale || '/10) - ' || NEW.nom_prenom;
    v_description := 'Analyse des commentaires et proposition d''un accompagnement complémentaire. Commentaire : ' || COALESCE(NEW.commentaire_libre, '(aucun)');

  ELSIF v_table_name = 'enquetes_ces' AND NEW.effort_score > 5 THEN
    v_score_problematique := true;
    v_titre := 'CES élevé (' || NEW.effort_score || '/10) - ' || NEW.nom_prenom;
    v_description := 'Effort important rapporté. Freins : ' || COALESCE(NEW.facteurs_freins, '(non précisés)');

  ELSIF v_table_name = 'enquetes_satisfaction_solution' THEN
    IF NEW.satisfaction_globale < 6 THEN
      v_score_problematique := true;
      v_titre := 'Insatisfaction OpenPulse (' || NEW.satisfaction_globale || '/10) - ' || NEW.nom_prenom;
      v_description := 'Améliorations demandées : ' || COALESCE(NEW.ameliorations, '(aucune)');
    ELSIF NEW.nps_score < 5 THEN
      v_score_problematique := true;
      v_titre := 'NPS détracteur (' || NEW.nps_score || '/10) - ' || NEW.nom_prenom;
      v_description := 'Contacter médecin référent. Améliorations : ' || COALESCE(NEW.ameliorations, '(aucune)');
    END IF;

  ELSIF v_table_name = 'enquetes_suivi_csm' AND NEW.note_globale <= 6 THEN
    v_score_problematique := true;
    v_titre := 'Suivi CSM jugé insuffisant (' || NEW.note_globale || '/10) - ' || NEW.nom_prenom;
    v_description := 'Améliorations : ' || COALESCE(NEW.ameliorations, '(aucune)');
  END IF;

  IF v_score_problematique THEN
    -- Trouver un assigné : CSM lié à l'établissement sinon premier admin
    SELECT chef_projet_id INTO v_assignee_id FROM public.etablissements WHERE id = NEW.etablissement_id;
    IF v_assignee_id IS NULL THEN
      SELECT user_id INTO v_assignee_id FROM public.user_roles WHERE role = 'admin' LIMIT 1;
    END IF;

    INSERT INTO public.taches (
      titre, description, etablissement_id, assigne_a,
      statut, priorite, type, date_echeance, created_by
    ) VALUES (
      v_titre,
      v_description || E'\n\n[Tâche générée automatiquement depuis enquête de satisfaction]',
      NEW.etablissement_id,
      v_assignee_id,
      'a_faire',
      'haute',
      'suivi_client',
      (now() + INTERVAL '7 days')::date,
      v_assignee_id
    );
  END IF;

  RETURN NEW;
END;
$$;


