--
-- Name: tg_rgpd_audit_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_rgpd_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_record_id text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_record_id := COALESCE((to_jsonb(OLD)->>'id'), NULL);
    v_old := to_jsonb(OLD);
    v_new := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_record_id := COALESCE((to_jsonb(NEW)->>'id'), NULL);
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    -- Skip si aucun changement réel
    IF v_old = v_new THEN
      RETURN NEW;
    END IF;
  ELSE -- INSERT
    v_record_id := COALESCE((to_jsonb(NEW)->>'id'), NULL);
    v_old := NULL;
    v_new := to_jsonb(NEW);
  END IF;

  BEGIN
    INSERT INTO public.rgpd_audit_logs(user_id, action, table_name, record_id, old_values, new_values)
    VALUES (auth.uid(), TG_OP, TG_TABLE_NAME, v_record_id, v_old, v_new);
  EXCEPTION WHEN OTHERS THEN
    -- Ne jamais faire échouer la mutation métier sur un log audit
    NULL;
  END;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: time_imputation_snapshot_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.time_imputation_snapshot_cost() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cfg public.time_user_config%ROWTYPE;
BEGIN
  -- Auto-compute week_iso
  NEW.week_iso := to_char(NEW.date_imputation, 'IYYY-"W"IW');

  -- Snapshot cost if missing
  IF NEW.cout_horaire_charge_snapshot IS NULL OR NEW.tjm_snapshot IS NULL THEN
    SELECT * INTO v_cfg FROM public.time_user_config WHERE user_id = NEW.user_id;
    IF FOUND THEN
      IF NEW.cout_horaire_charge_snapshot IS NULL THEN
        NEW.cout_horaire_charge_snapshot := v_cfg.cout_horaire_charge;
      END IF;
      IF NEW.tjm_snapshot IS NULL THEN
        NEW.tjm_snapshot := v_cfg.tjm;
      END IF;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


