--
-- Name: trg_calendar_to_behavioral_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_calendar_to_behavioral_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.etablissement_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.status IS NULL OR NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  IF NEW.status IN ('attended', 'completed', 'confirmed') THEN
    PERFORM public.record_behavioral_event(NEW.etablissement_id, 'meeting_attended', NEW.end_time, 10, NEW.id, 'calendar_event',
      jsonb_build_object('title', NEW.title));
  ELSIF NEW.status IN ('no_show', 'cancelled') THEN
    PERFORM public.record_behavioral_event(NEW.etablissement_id, 'meeting_no_show', NEW.end_time, -5, NEW.id, 'calendar_event',
      jsonb_build_object('title', NEW.title, 'status', NEW.status));
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_email_to_behavioral_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_email_to_behavioral_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _etab_id uuid; _last_outbound timestamptz; _delay_seconds numeric; _msg_at timestamptz;
BEGIN
  SELECT et.etablissement_id INTO _etab_id FROM public.email_threads et WHERE et.id = NEW.thread_id LIMIT 1;
  IF _etab_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' AND COALESCE(NEW.is_sent, false) = false AND COALESCE(NEW.is_draft, false) = false THEN
    _msg_at := COALESCE(NEW.received_date, NEW.created_at, now());
    PERFORM public.record_behavioral_event(_etab_id, 'email_replied', _msg_at, 5, NEW.id, 'email_message_reply',
      jsonb_build_object('subject', NEW.subject));
    SELECT MAX(em.sent_date) INTO _last_outbound FROM public.email_messages em
    WHERE em.thread_id = NEW.thread_id AND COALESCE(em.is_sent, false) = true AND em.sent_date < _msg_at;
    IF _last_outbound IS NOT NULL THEN
      _delay_seconds := EXTRACT(EPOCH FROM (_msg_at - _last_outbound));
      IF _delay_seconds < 14400 THEN
        PERFORM public.record_behavioral_event(_etab_id, 'quick_response', _msg_at, 7, NEW.id, 'email_quick',
          jsonb_build_object('delay_minutes', round(_delay_seconds/60)));
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_record_attribution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_record_attribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _etab_id uuid; _channel public.attribution_channel; _occurred timestamptz;
BEGIN
  IF TG_TABLE_NAME = 'email_messages' THEN
    SELECT et.etablissement_id INTO _etab_id FROM public.email_threads et WHERE et.id = NEW.thread_id LIMIT 1;
    IF _etab_id IS NULL THEN RETURN NEW; END IF;
    _channel := CASE WHEN COALESCE(NEW.is_sent, false) THEN 'email_outbound'::public.attribution_channel
                     ELSE 'email_inbound'::public.attribution_channel END;
    _occurred := COALESCE(NEW.sent_date, NEW.received_date, NEW.created_at, now());
    INSERT INTO public.attribution_touchpoints (etablissement_id, channel, occurred_at, weight, source_id, source_type)
    VALUES (_etab_id, _channel, _occurred, 1, NEW.id, 'email_message');
  ELSIF TG_TABLE_NAME = 'calendar_events' THEN
    IF NEW.etablissement_id IS NULL THEN RETURN NEW; END IF;
    INSERT INTO public.attribution_touchpoints (etablissement_id, channel, occurred_at, weight, user_id, source_id, source_type)
    VALUES (NEW.etablissement_id, 'meeting', NEW.start_time, 2, NEW.created_by, NEW.id, 'calendar_event');
  END IF;
  RETURN NEW;
END; $$;


