--
-- Name: trigger_ai_processing_on_new_thread(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_ai_processing_on_new_thread() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  service_role_key TEXT;
  supabase_url TEXT;
  request_id BIGINT;
BEGIN
  -- Get Supabase URL and service role key from app settings
  BEGIN
    supabase_url := current_setting('app.supabase_url', true);
    service_role_key := current_setting('app.service_role_key', true);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'AI processing trigger skipped: app.supabase_url or app.service_role_key not configured';
    RETURN NEW;
  END;
  
  -- Skip if settings are empty
  IF supabase_url IS NULL OR service_role_key IS NULL THEN
    RAISE WARNING 'AI processing trigger skipped: app.supabase_url or app.service_role_key is null';
    RETURN NEW;
  END IF;
  
  -- Call process-email-with-ai edge function asynchronously
  SELECT net.http_post(
    url := supabase_url || '/functions/v1/process-email-with-ai',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_role_key
    ),
    body := jsonb_build_object('thread_id', NEW.id::text)
  ) INTO request_id;
  
  RAISE LOG 'AI processing triggered for thread % (request_id: %)', NEW.id, request_id;
  
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Failed to trigger AI processing for thread %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


