--
-- Name: trigger_prospect_enrichment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_prospect_enrichment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Marquer comme à enrichir si pas encore enrichi et qu'on a au moins un signal (SIREN, email, ou nom)
  IF NEW.enrichment_status IS NULL OR NEW.enrichment_status = 'pending' THEN
    IF NEW.siren_client IS NOT NULL
       OR NEW.email IS NOT NULL
       OR NEW.email_domains IS NOT NULL
       OR NEW.nom IS NOT NULL THEN
      -- Note : l'appel HTTP réel se fait via cron qui ramasse les pending
      NEW.enrichment_status := 'pending';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


