-- Name: unlock_badges(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlock_badges(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_badge record;
  v_unlocked int := 0;
  v_value numeric;
  v_threshold numeric;
  v_type text;
BEGIN
  FOR v_badge IN SELECT * FROM gamification_badges WHERE is_active LOOP
    -- Skip if already unlocked
    IF EXISTS (SELECT 1 FROM gamification_user_badges WHERE user_id = p_user_id AND badge_code = v_badge.code) THEN
      CONTINUE;
    END IF;

    v_type := v_badge.criteria->>'type';
    v_threshold := COALESCE((v_badge.criteria->>'threshold')::numeric, 0);
    v_value := 0;

    IF v_type = 'welcome' THEN
      v_value := 1; v_threshold := 1;
    ELSIF v_type = 'deals_signed' THEN
      SELECT COUNT(*) INTO v_value FROM etablissements
        WHERE statut IN ('vendu','production','client')
          AND (commercial_id = p_user_id OR account_manager_id = p_user_id);
    ELSIF v_type = 'rdv_held' THEN
      SELECT COUNT(*) INTO v_value FROM interactions
        WHERE created_by = p_user_id AND type_interaction IN ('rdv','meeting','visite');
    ELSIF v_type = 'prospects_created' THEN
      SELECT COUNT(*) INTO v_value FROM etablissements
        WHERE created_by = p_user_id;
    ELSIF v_type = 'streak_days' THEN
      SELECT COALESCE(streak_days,0) INTO v_value FROM gamification_user_stats WHERE user_id = p_user_id;
    END IF;

    IF v_value >= v_threshold THEN
      INSERT INTO gamification_user_badges (user_id, badge_code, metadata)
      VALUES (p_user_id, v_badge.code, jsonb_build_object('value', v_value))
      ON CONFLICT DO NOTHING;
      v_unlocked := v_unlocked + 1;
    END IF;
  END LOOP;
  RETURN v_unlocked;
EXCEPTION WHEN OTHERS THEN
  RETURN 0;
END;
$$;


