--
-- Name: update_email_thread_classification(uuid, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_email_thread_classification(p_thread_id uuid, p_category text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Vérifier que l'utilisateur a accès au thread
  IF NOT EXISTS (
    SELECT 1 FROM email_threads et
    JOIN user_email_accounts uea ON uea.id = et.user_email_account_id
    JOIN profiles p ON p.id = uea.profile_id
    WHERE et.id = p_thread_id AND p.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Accès non autorisé au thread';
  END IF;

  -- Mettre à jour la classification
  UPDATE email_threads
  SET
    category = COALESCE(p_category, category),
    priority = COALESCE(p_priority::priorite_tache, priority),
    tags = COALESCE(p_tags, tags),
    updated_at = now()
  WHERE id = p_thread_id;
END;
$$;


