--
-- Name: update_establishment_progression_and_status_fixed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_establishment_progression_and_status_fixed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  total_tasks INTEGER;
  completed_tasks INTEGER;
  progression_pct DECIMAL(5,2);
  current_status public.statut_etablissement;
  etablissement_id_val UUID;
  
  -- Catégories de tâches
  commercial_category_id UUID;
  contract_category_id UUID;
  conformity_category_id UUID;
  deployment_category_id UUID;
  formation_category_id UUID;
  golive_category_id UUID;
  production_category_id UUID;
  
  -- Compteurs par catégorie
  commercial_total INTEGER := 0;
  commercial_completed INTEGER := 0;
  contract_total INTEGER := 0;
  contract_completed INTEGER := 0;
  conformity_total INTEGER := 0;
  conformity_completed INTEGER := 0;
  deployment_total INTEGER := 0;
  deployment_completed INTEGER := 0;
  formation_total INTEGER := 0;
  formation_completed INTEGER := 0;
  golive_total INTEGER := 0;
  golive_completed INTEGER := 0;
  production_total INTEGER := 0;
  production_completed INTEGER := 0;
BEGIN
  etablissement_id_val := COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  -- Récupérer les IDs des catégories
  SELECT id INTO commercial_category_id FROM public.categories_taches WHERE nom = 'Commercial';
  SELECT id INTO contract_category_id FROM public.categories_taches WHERE nom = 'Contractuel';
  SELECT id INTO conformity_category_id FROM public.categories_taches WHERE nom = 'Conformité';
  SELECT id INTO deployment_category_id FROM public.categories_taches WHERE nom = 'Déploiement';
  SELECT id INTO formation_category_id FROM public.categories_taches WHERE nom = 'Formation';
  SELECT id INTO golive_category_id FROM public.categories_taches WHERE nom = 'Go-Live';
  SELECT id INTO production_category_id FROM public.categories_taches WHERE nom = 'Suivi Production';
  
  -- Récupérer le statut actuel
  SELECT statut INTO current_status
  FROM public.etablissements 
  WHERE id = etablissement_id_val;
  
  -- Compter les tâches par catégorie
  IF commercial_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO commercial_total, commercial_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = commercial_category_id;
  END IF;
  
  IF contract_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO contract_total, contract_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = contract_category_id;
  END IF;
  
  IF conformity_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO conformity_total, conformity_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = conformity_category_id;
  END IF;
  
  IF deployment_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO deployment_total, deployment_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = deployment_category_id;
  END IF;
  
  IF formation_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO formation_total, formation_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = formation_category_id;
  END IF;
  
  IF golive_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO golive_total, golive_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = golive_category_id;
  END IF;
  
  IF production_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO production_total, production_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = production_category_id;
  END IF;
  
  -- Calculer la progression globale
  total_tasks := commercial_total + contract_total + conformity_total + deployment_total + formation_total + golive_total + production_total;
  completed_tasks := commercial_completed + contract_completed + conformity_completed + deployment_completed + formation_completed + golive_completed + production_completed;
  
  IF total_tasks > 0 THEN
    progression_pct := (completed_tasks::DECIMAL / total_tasks::DECIMAL) * 100;
  ELSE
    progression_pct := 0;
  END IF;
  
  -- Mettre à jour la progression
  UPDATE public.etablissements 
  SET progression = progression_pct, updated_at = now()
  WHERE id = etablissement_id_val;
  
  -- Logique de changement de statut basée sur l'achèvement des catégories
  IF current_status = 'Prospect' AND commercial_total > 0 AND commercial_completed = commercial_total THEN
    UPDATE public.etablissements 
    SET statut = 'Contractuel', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Contractuel' AND contract_total > 0 AND contract_completed = contract_total THEN
    UPDATE public.etablissements 
    SET statut = 'Conformité', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Conformité' AND conformity_total > 0 AND conformity_completed = conformity_total THEN
    UPDATE public.etablissements 
    SET statut = 'Déploiement', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Déploiement' AND deployment_total > 0 AND deployment_completed = deployment_total THEN
    UPDATE public.etablissements 
    SET statut = 'Formation', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Formation' AND formation_total > 0 AND formation_completed = formation_total THEN
    UPDATE public.etablissements 
    SET statut = 'Go-Live', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Go-Live' AND golive_total > 0 AND golive_completed = golive_total THEN
    UPDATE public.etablissements 
    SET statut = 'Production', updated_at = now()
    WHERE id = etablissement_id_val;
    
    -- Créer automatiquement les tâches de suivi production si elles n'existent pas
    IF production_category_id IS NOT NULL AND production_total = 0 THEN
      INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, echeance, ordre)
      VALUES 
        (etablissement_id_val, production_category_id, 'Suivi trimestriel T1', 
         'Suivi trimestriel de l''établissement en production', 'medium', 
         CURRENT_DATE + INTERVAL '3 months', 1),
        (etablissement_id_val, production_category_id, 'Suivi trimestriel T2', 
         'Suivi trimestriel de l''établissement en production', 'medium', 
         CURRENT_DATE + INTERVAL '6 months', 2),
        (etablissement_id_val, production_category_id, 'Suivi trimestriel T3', 
         'Suivi trimestriel de l''établissement en production', 'medium', 
         CURRENT_DATE + INTERVAL '9 months', 3),
        (etablissement_id_val, production_category_id, 'Suivi trimestriel T4', 
         'Suivi trimestriel de l''établissement en production', 'medium', 
         CURRENT_DATE + INTERVAL '12 months', 4);
    END IF;
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_establishment_progression_and_status_fixed_direct(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_establishment_progression_and_status_fixed_direct(etablissement_id_val uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_status TEXT;
  
  commercial_category_id UUID;
  contract_category_id UUID;
  conformity_category_id UUID;
  deployment_category_id UUID;
  formation_category_id UUID;
  golive_category_id UUID;
  production_category_id UUID;
  
  commercial_total INT := 0;
  commercial_completed INT := 0;
  contract_total INT := 0;
  contract_completed INT := 0;
  conformity_total INT := 0;
  conformity_completed INT := 0;
  deployment_total INT := 0;
  deployment_completed INT := 0;
  formation_total INT := 0;
  formation_completed INT := 0;
  golive_total INT := 0;
  golive_completed INT := 0;
  production_total INT := 0;
  production_completed INT := 0;
  
  total_tasks INT;
  completed_tasks INT;
  progression_pct DECIMAL;
BEGIN
  -- Récupérer le statut actuel
  SELECT statut INTO current_status 
  FROM public.etablissements 
  WHERE id = etablissement_id_val;
  
  -- Récupérer les IDs des catégories
  SELECT id INTO commercial_category_id FROM public.categories_taches WHERE nom = 'Commercial';
  SELECT id INTO contract_category_id FROM public.categories_taches WHERE nom = 'Contractuel';
  SELECT id INTO conformity_category_id FROM public.categories_taches WHERE nom = 'Conformité';
  SELECT id INTO deployment_category_id FROM public.categories_taches WHERE nom = 'Déploiement';
  SELECT id INTO formation_category_id FROM public.categories_taches WHERE nom = 'Formation';
  SELECT id INTO golive_category_id FROM public.categories_taches WHERE nom = 'Go-Live';
  SELECT id INTO production_category_id FROM public.categories_taches WHERE nom = 'Suivi Production';
  
  -- Compter les tâches par catégorie
  IF commercial_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO commercial_total, commercial_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = commercial_category_id;
  END IF;
  
  IF contract_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO contract_total, contract_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = contract_category_id;
  END IF;
  
  IF conformity_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO conformity_total, conformity_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = conformity_category_id;
  END IF;
  
  IF deployment_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO deployment_total, deployment_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = deployment_category_id;
  END IF;
  
  IF formation_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO formation_total, formation_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = formation_category_id;
  END IF;
  
  IF golive_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO golive_total, golive_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = golive_category_id;
  END IF;
  
  IF production_category_id IS NOT NULL THEN
    SELECT COUNT(*), COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
    INTO production_total, production_completed
    FROM public.taches 
    WHERE etablissement_id = etablissement_id_val AND categorie_id = production_category_id;
  END IF;
  
  -- ============================================
  -- AJUSTEMENT SELON LE STATUT ACTUEL
  -- Les phases précédentes sont considérées comme terminées à 100%
  -- ============================================
  
  -- Si statut = Contractuel ou après → Phase Commercial validée
  IF current_status IN ('Contractuel', 'Conformité', 'Déploiement', 'Formation', 'Go-Live', 'Production') THEN
    commercial_completed := commercial_total;
  END IF;
  
  -- Si statut = Conformité ou après → Phase Contractuel validée
  IF current_status IN ('Conformité', 'Déploiement', 'Formation', 'Go-Live', 'Production') THEN
    contract_completed := contract_total;
  END IF;
  
  -- Si statut = Déploiement ou après → Phase Conformité validée
  IF current_status IN ('Déploiement', 'Formation', 'Go-Live', 'Production') THEN
    conformity_completed := conformity_total;
  END IF;
  
  -- Si statut = Formation ou après → Phase Déploiement validée
  IF current_status IN ('Formation', 'Go-Live', 'Production') THEN
    deployment_completed := deployment_total;
  END IF;
  
  -- Si statut = Go-Live ou après → Phase Formation validée
  IF current_status IN ('Go-Live', 'Production') THEN
    formation_completed := formation_total;
  END IF;
  
  -- Si statut = Production → Phase Go-Live validée
  IF current_status = 'Production' THEN
    golive_completed := golive_total;
  END IF;
  
  -- Calculer la progression globale
  total_tasks := commercial_total + contract_total + conformity_total + deployment_total + formation_total + golive_total + production_total;
  completed_tasks := commercial_completed + contract_completed + conformity_completed + deployment_completed + formation_completed + golive_completed + production_completed;
  
  IF total_tasks > 0 THEN
    progression_pct := (completed_tasks::DECIMAL / total_tasks::DECIMAL) * 100;
  ELSE
    progression_pct := 0;
  END IF;
  
  -- Mettre à jour la progression
  UPDATE public.etablissements 
  SET progression = progression_pct, updated_at = now()
  WHERE id = etablissement_id_val;
  
  -- Logique de changement de statut basée sur l'achèvement des catégories
  IF current_status = 'Prospect' AND commercial_total > 0 AND commercial_completed = commercial_total THEN
    UPDATE public.etablissements 
    SET statut = 'Contractuel', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Contractuel' AND contract_total > 0 AND contract_completed = contract_total THEN
    UPDATE public.etablissements 
    SET statut = 'Conformité', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Conformité' AND conformity_total > 0 AND conformity_completed = conformity_total THEN
    UPDATE public.etablissements 
    SET statut = 'Déploiement', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Déploiement' AND deployment_total > 0 AND deployment_completed = deployment_total THEN
    UPDATE public.etablissements 
    SET statut = 'Formation', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Formation' AND formation_total > 0 AND formation_completed = formation_total THEN
    UPDATE public.etablissements 
    SET statut = 'Go-Live', updated_at = now()
    WHERE id = etablissement_id_val;
    
  ELSIF current_status = 'Go-Live' AND golive_total > 0 AND golive_completed = golive_total THEN
    UPDATE public.etablissements 
    SET statut = 'Production', updated_at = now()
    WHERE id = etablissement_id_val;
  END IF;
END;
$$;


--
-- Name: update_etablissement_email_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_etablissement_email_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  is_sent_flag boolean;
  msg_date timestamp with time zone;
  thread_etab_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'email_threads' THEN
    thread_etab_id := NEW.etablissement_id;
    
    IF thread_etab_id IS NOT NULL THEN
      SELECT MAX(sent_date) INTO msg_date
      FROM public.email_messages
      WHERE thread_id = NEW.id;
      
      IF msg_date IS NOT NULL THEN
        UPDATE public.etablissements
        SET last_email_received_at = GREATEST(COALESCE(last_email_received_at, msg_date), msg_date)
        WHERE id = thread_etab_id;
      END IF;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: update_etablissement_progression(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_etablissement_progression() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  total_tasks INTEGER;
  completed_tasks INTEGER;
  progression_pct DECIMAL(5,2);
  current_status public.statut_etablissement;
  conformite_category_id UUID;
  suivi_category_id UUID;
BEGIN
  -- Get task counts for the etablissement
  SELECT 
    COUNT(*),
    COUNT(CASE WHEN statut = 'Terminé' THEN 1 END)
  INTO total_tasks, completed_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  -- Calculate progression
  IF total_tasks > 0 THEN
    progression_pct = (completed_tasks::DECIMAL / total_tasks::DECIMAL) * 100;
  ELSE
    progression_pct = 0;
  END IF;
  
  -- Get current status
  SELECT statut INTO current_status
  FROM public.etablissements 
  WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  -- Update etablissement progression
  UPDATE public.etablissements 
  SET progression = progression_pct
  WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  -- Si on atteint 100% et qu'on est en statut "Conformité", passer en "Production"
  IF progression_pct = 100 AND current_status = 'Conformité' THEN
    -- Changer le statut en "Production"
    UPDATE public.etablissements 
    SET statut = 'Production',
        updated_at = now()
    WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
    
    -- Récupérer l'ID de la catégorie "Suivi" (ou la créer si elle n'existe pas)
    SELECT id INTO suivi_category_id 
    FROM public.categories_taches 
    WHERE nom = 'Suivi Production';
    
    -- Si la catégorie n'existe pas, la créer
    IF suivi_category_id IS NULL THEN
      INSERT INTO public.categories_taches (nom, description, couleur, ordre)
      VALUES ('Suivi Production', 'Tâches de suivi trimestriel en production', '#10B981', 999)
      RETURNING id INTO suivi_category_id;
    END IF;
    
    -- Créer les tâches de suivi trimestriel pour les 4 prochains trimestres
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, echeance, ordre)
    VALUES 
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T1', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '3 months', 1),
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T2', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '6 months', 2),
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T3', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '9 months', 3),
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T4', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '12 months', 4);
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_forum_user_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_forum_user_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Ne rien faire si c'est un post/commentaire anonyme
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Insérer ou mettre à jour les stats uniquement pour les utilisateurs authentifiés
  INSERT INTO forum_user_stats (user_id, posts_count, last_post_at)
  VALUES (NEW.user_id, 1, NOW())
  ON CONFLICT (user_id) 
  DO UPDATE SET 
    posts_count = forum_user_stats.posts_count + 1,
    last_post_at = NOW();
  
  RETURN NEW;
END;
$$;


