--
-- Name: update_groupe_on_etablissement_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_groupe_on_etablissement_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.etablissements_groupes
    WHERE etablissement_id = NEW.id
      AND date_sortie IS NULL
  ) THEN
    UPDATE public.groupes_etablissements g
    SET
      nombre_etablissements = (
        SELECT COUNT(*)
        FROM public.etablissements_groupes eg
        WHERE eg.groupe_id = g.id
          AND eg.date_sortie IS NULL
      ),
      progression_moyenne = (
        SELECT COALESCE(AVG(e.progression), 0)
        FROM public.etablissements_groupes eg
        JOIN public.etablissements e ON e.id = eg.etablissement_id
        WHERE eg.groupe_id = g.id
          AND eg.date_sortie IS NULL
      ),
      total_passages_urgences_annuel = (
        SELECT COALESCE(SUM(COALESCE(e.nombre_passages_urgences_annuel, 0)), 0)
        FROM public.etablissements_groupes eg
        JOIN public.etablissements e ON e.id = eg.etablissement_id
        WHERE eg.groupe_id = g.id
          AND eg.date_sortie IS NULL
      ),
      updated_at = NOW()
    WHERE g.id IN (
      SELECT eg.groupe_id
      FROM public.etablissements_groupes eg
      WHERE eg.etablissement_id = NEW.id
        AND eg.date_sortie IS NULL
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: update_groupe_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_groupe_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  target_groupe_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'etablissements' THEN
    FOR target_groupe_id IN
      SELECT DISTINCT eg.groupe_id
      FROM public.etablissements_groupes eg
      WHERE eg.etablissement_id = COALESCE(NEW.id, OLD.id)
        AND eg.date_sortie IS NULL
    LOOP
      UPDATE public.groupes_etablissements ge
      SET
        nombre_etablissements = (
          SELECT COUNT(*)
          FROM public.etablissements_groupes eg
          WHERE eg.groupe_id = ge.id
            AND eg.date_sortie IS NULL
        ),
        progression_moyenne = (
          SELECT COALESCE(AVG(e.progression), 0)
          FROM public.etablissements_groupes eg
          JOIN public.etablissements e ON e.id = eg.etablissement_id
          WHERE eg.groupe_id = ge.id
            AND eg.date_sortie IS NULL
        ),
        total_passages_urgences_annuel = (
          SELECT COALESCE(SUM(COALESCE(e.nombre_passages_urgences_annuel, 0)), 0)
          FROM public.etablissements_groupes eg
          JOIN public.etablissements e ON e.id = eg.etablissement_id
          WHERE eg.groupe_id = ge.id
            AND eg.date_sortie IS NULL
        ),
        modules_deployes = (
          SELECT COALESCE(ARRAY_AGG(DISTINCT m ORDER BY m), ARRAY[]::text[])
          FROM (
            SELECT UNNEST(e.modules_proposes) AS m
            FROM public.etablissements_groupes eg
            JOIN public.etablissements e ON e.id = eg.etablissement_id
            WHERE eg.groupe_id = ge.id
              AND eg.date_sortie IS NULL
              AND e.modules_proposes IS NOT NULL
              AND array_length(e.modules_proposes, 1) > 0
          ) t
        ),
        email_domains = (
          SELECT COALESCE(ARRAY_AGG(DISTINCT edm.domain), ARRAY[]::text[])
          FROM public.email_domain_mappings edm
          WHERE edm.groupe_id = ge.id
        ),
        updated_at = NOW()
      WHERE ge.id = target_groupe_id;
    END LOOP;
    
    RETURN COALESCE(NEW, OLD);
  ELSE
    target_groupe_id := COALESCE(NEW.groupe_id, OLD.groupe_id);
    
    IF target_groupe_id IS NOT NULL THEN
      UPDATE public.groupes_etablissements ge
      SET
        nombre_etablissements = (
          SELECT COUNT(*)
          FROM public.etablissements_groupes eg
          WHERE eg.groupe_id = ge.id
            AND eg.date_sortie IS NULL
        ),
        progression_moyenne = (
          SELECT COALESCE(AVG(e.progression), 0)
          FROM public.etablissements_groupes eg
          JOIN public.etablissements e ON e.id = eg.etablissement_id
          WHERE eg.groupe_id = ge.id
            AND eg.date_sortie IS NULL
        ),
        total_passages_urgences_annuel = (
          SELECT COALESCE(SUM(COALESCE(e.nombre_passages_urgences_annuel, 0)), 0)
          FROM public.etablissements_groupes eg
          JOIN public.etablissements e ON e.id = eg.etablissement_id
          WHERE eg.groupe_id = ge.id
            AND eg.date_sortie IS NULL
        ),
        modules_deployes = (
          SELECT COALESCE(ARRAY_AGG(DISTINCT m ORDER BY m), ARRAY[]::text[])
          FROM (
            SELECT UNNEST(e.modules_proposes) AS m
            FROM public.etablissements_groupes eg
            JOIN public.etablissements e ON e.id = eg.etablissement_id
            WHERE eg.groupe_id = ge.id
              AND eg.date_sortie IS NULL
              AND e.modules_proposes IS NOT NULL
              AND array_length(e.modules_proposes, 1) > 0
          ) t
        ),
        email_domains = (
          SELECT COALESCE(ARRAY_AGG(DISTINCT edm.domain), ARRAY[]::text[])
          FROM public.email_domain_mappings edm
          WHERE edm.groupe_id = ge.id
        ),
        updated_at = NOW()
      WHERE ge.id = target_groupe_id;
    END IF;
    
    RETURN COALESCE(NEW, OLD);
  END IF;
END;
$$;


--
-- Name: update_jarvis_circuit_state(text, text, integer, integer, integer, integer, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_jarvis_circuit_state(p_circuit_name text, p_state text, p_failure_count integer DEFAULT NULL::integer, p_success_count integer DEFAULT NULL::integer, p_consecutive_failures integer DEFAULT NULL::integer, p_consecutive_successes integer DEFAULT NULL::integer, p_avg_latency_ms numeric DEFAULT NULL::numeric, p_p95_latency_ms numeric DEFAULT NULL::numeric, p_config jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.jarvis_circuit_state (
    circuit_name, state, failure_count, success_count, 
    consecutive_failures, consecutive_successes,
    avg_latency_ms, p95_latency_ms, config, state_changed_at
  ) VALUES (
    p_circuit_name, p_state, 
    COALESCE(p_failure_count, 0), COALESCE(p_success_count, 0),
    COALESCE(p_consecutive_failures, 0), COALESCE(p_consecutive_successes, 0),
    COALESCE(p_avg_latency_ms, 0), COALESCE(p_p95_latency_ms, 0),
    COALESCE(p_config, '{}'), now()
  )
  ON CONFLICT (circuit_name) DO UPDATE SET
    state = EXCLUDED.state,
    failure_count = COALESCE(p_failure_count, jarvis_circuit_state.failure_count),
    success_count = COALESCE(p_success_count, jarvis_circuit_state.success_count),
    consecutive_failures = COALESCE(p_consecutive_failures, jarvis_circuit_state.consecutive_failures),
    consecutive_successes = COALESCE(p_consecutive_successes, jarvis_circuit_state.consecutive_successes),
    avg_latency_ms = COALESCE(p_avg_latency_ms, jarvis_circuit_state.avg_latency_ms),
    p95_latency_ms = COALESCE(p_p95_latency_ms, jarvis_circuit_state.p95_latency_ms),
    config = COALESCE(p_config, jarvis_circuit_state.config),
    state_changed_at = CASE WHEN jarvis_circuit_state.state != EXCLUDED.state THEN now() ELSE jarvis_circuit_state.state_changed_at END,
    updated_at = now();
END;
$$;


