--
-- Name: update_status_on_commercial_done(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_status_on_commercial_done() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  commercial_category_id UUID;
  total_commercial_tasks INTEGER;
  completed_commercial_tasks INTEGER;
  current_status public.statut_etablissement;
BEGIN
  -- Récupérer l'ID de la catégorie commerciale
  SELECT id INTO commercial_category_id 
  FROM public.categories_taches 
  WHERE nom IN ('Commercial', 'Prospection', 'Vente');
  
  -- Si la catégorie n'existe pas, on ne fait rien
  IF commercial_category_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  -- Récupérer le statut actuel de l'établissement
  SELECT statut INTO current_status
  FROM public.etablissements 
  WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  -- Ne traiter que si l'établissement est encore en statut "Prospect"
  IF current_status != 'Prospect' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  -- Compter le nombre total de tâches commerciales pour cet établissement
  SELECT COUNT(*) INTO total_commercial_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
    AND categorie_id = commercial_category_id;
  
  -- Compter le nombre de tâches commerciales terminées
  SELECT COUNT(*) INTO completed_commercial_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
    AND categorie_id = commercial_category_id
    AND statut = 'Terminé';
  
  -- Si toutes les tâches commerciales sont terminées, passer à "Contractuel"
  IF total_commercial_tasks > 0 AND completed_commercial_tasks = total_commercial_tasks THEN
    UPDATE public.etablissements 
    SET statut = 'Contractuel',
        updated_at = now()
    WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
      AND statut = 'Prospect';
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_status_on_contract_done(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_status_on_contract_done() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  contract_category_id UUID;
  total_contract_tasks INTEGER;
  completed_contract_tasks INTEGER;
  current_status public.statut_etablissement;
BEGIN
  SELECT id INTO contract_category_id 
  FROM public.categories_taches 
  WHERE nom = 'Contractuel';
  
  IF contract_category_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  SELECT statut INTO current_status
  FROM public.etablissements 
  WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  IF current_status != 'Contractuel' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  SELECT COUNT(*) INTO total_contract_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
    AND categorie_id = contract_category_id;
  
  SELECT COUNT(*) INTO completed_contract_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
    AND categorie_id = contract_category_id
    AND statut = 'Terminé';
  
  IF total_contract_tasks > 0 AND completed_contract_tasks = total_contract_tasks THEN
    UPDATE public.etablissements 
    SET statut = 'Conformité',
        updated_at = now()
    WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
      AND statut = 'Contractuel';
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_status_on_deployment_done(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_status_on_deployment_done() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  deployment_category_ids UUID[];
  total_deployment_tasks INTEGER;
  completed_deployment_tasks INTEGER;
  current_status public.statut_etablissement;
  suivi_category_id UUID;
BEGIN
  -- Récupérer les IDs des catégories de déploiement
  SELECT ARRAY_AGG(id) INTO deployment_category_ids
  FROM public.categories_taches 
  WHERE nom IN ('Déploiement', 'Formation', 'Go-Live', 'Documentation');
  
  -- Si aucune catégorie n'existe, on ne fait rien
  IF deployment_category_ids IS NULL OR array_length(deployment_category_ids, 1) = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  -- Récupérer le statut actuel de l'établissement
  SELECT statut INTO current_status
  FROM public.etablissements 
  WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
  
  -- Ne traiter que si l'établissement est en phase de déploiement
  IF current_status NOT IN ('Déploiement', 'Formation', 'Go-Live') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  -- Compter le nombre total de tâches de déploiement pour cet établissement
  SELECT COUNT(*) INTO total_deployment_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
    AND categorie_id = ANY(deployment_category_ids);
  
  -- Compter le nombre de tâches de déploiement terminées
  SELECT COUNT(*) INTO completed_deployment_tasks
  FROM public.taches 
  WHERE etablissement_id = COALESCE(NEW.etablissement_id, OLD.etablissement_id)
    AND categorie_id = ANY(deployment_category_ids)
    AND statut = 'Terminé';
  
  -- Si toutes les tâches de déploiement sont terminées, passer à "Production"
  IF total_deployment_tasks > 0 AND completed_deployment_tasks = total_deployment_tasks THEN
    UPDATE public.etablissements 
    SET statut = 'Production',
        updated_at = now()
    WHERE id = COALESCE(NEW.etablissement_id, OLD.etablissement_id);
    
    -- Créer les tâches de suivi comme avant
    SELECT id INTO suivi_category_id 
    FROM public.categories_taches 
    WHERE nom = 'Suivi Production';
    
    IF suivi_category_id IS NULL THEN
      INSERT INTO public.categories_taches (nom, description, couleur, ordre)
      VALUES ('Suivi Production', 'Tâches de suivi trimestriel en production', '#10B981', 999)
      RETURNING id INTO suivi_category_id;
    END IF;
    
    INSERT INTO public.taches (etablissement_id, categorie_id, titre, description, priorite, echeance, ordre)
    VALUES 
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T1', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '3 months', 1),
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T2', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '6 months', 2),
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T3', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '9 months', 3),
      (COALESCE(NEW.etablissement_id, OLD.etablissement_id), suivi_category_id, 
       'Suivi trimestriel T4', 'Suivi trimestriel de l''établissement en production', 'medium', 
       CURRENT_DATE + INTERVAL '12 months', 4);
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


