--
-- Name: update_thread_sent_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_thread_sent_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Utilise is_sent (booléen existant) au lieu de direction (inexistant)
  IF NEW.is_sent = true THEN
    UPDATE public.email_threads
    SET 
      last_message_date = COALESCE(NEW.sent_date, NOW()),
      has_sent_messages = true,
      updated_at = NOW()
    WHERE id = NEW.thread_id;
  END IF;
  
  RETURN NEW;
END;
$$;


