--
-- Name: update_user_2fa_secret(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_2fa_secret(target_user_id uuid, secret text, temp_secret text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Enhanced service role check
  IF COALESCE((auth.jwt() ->> 'role')::text, '') != 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized access to 2FA secrets';
  END IF;
  
  INSERT INTO public.profiles_secrets (user_id, two_factor_secret, temp_2fa_secret, updated_at)
  VALUES (target_user_id, secret, temp_secret, now())
  ON CONFLICT (user_id)
  DO UPDATE SET
    two_factor_secret = EXCLUDED.two_factor_secret,
    temp_2fa_secret = COALESCE(EXCLUDED.temp_2fa_secret, profiles_secrets.temp_2fa_secret),
    updated_at = now();
END;
$$;


--
-- Name: update_user_preference(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_preference(preference_key text, preference_value jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.profiles 
  SET 
    preferences = preferences || jsonb_build_object(preference_key, preference_value),
    updated_at = now()
  WHERE user_id = auth.uid();
END;
$$;


--
-- Name: update_user_role(uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_role(target_user_id uuid, new_role public.app_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Vérifier que l'utilisateur actuel est admin
  IF NOT has_admin_role_strict(auth.uid()) THEN
    RAISE EXCEPTION 'Seuls les administrateurs peuvent modifier les rôles';
  END IF;

  -- Vérifier que le target_user_id existe
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'Utilisateur inexistant';
  END IF;

  -- Supprimer les anciens rôles
  DELETE FROM public.user_roles 
  WHERE user_id = target_user_id;

  -- Insérer le nouveau rôle
  INSERT INTO public.user_roles (user_id, role, assigned_by)
  VALUES (target_user_id, new_role, auth.uid());
END;
$$;


--
