--
-- Name: update_variant_stats_from_send(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_variant_stats_from_send() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.variant_id IS NULL THEN RETURN NEW; END IF;

  -- Upsert ligne stats
  INSERT INTO public.email_sequence_variant_stats (variant_id, sends_count, last_recomputed_at)
  VALUES (NEW.variant_id, 1, now())
  ON CONFLICT (variant_id) DO UPDATE SET
    sends_count = email_sequence_variant_stats.sends_count
      + CASE WHEN TG_OP = 'INSERT' THEN 1 ELSE 0 END,
    opens_count = email_sequence_variant_stats.opens_count
      + CASE WHEN NEW.opened_at IS NOT NULL AND (OLD.opened_at IS NULL OR TG_OP='INSERT') THEN 1 ELSE 0 END,
    clicks_count = email_sequence_variant_stats.clicks_count
      + CASE WHEN NEW.clicked_at IS NOT NULL AND (OLD.clicked_at IS NULL OR TG_OP='INSERT') THEN 1 ELSE 0 END,
    replies_count = email_sequence_variant_stats.replies_count
      + CASE WHEN NEW.replied_at IS NOT NULL AND (OLD.replied_at IS NULL OR TG_OP='INSERT') THEN 1 ELSE 0 END,
    bounces_count = email_sequence_variant_stats.bounces_count
      + CASE WHEN NEW.bounced_at IS NOT NULL AND (OLD.bounced_at IS NULL OR TG_OP='INSERT') THEN 1 ELSE 0 END,
    last_recomputed_at = now();

  RETURN NEW;
END;
$$;


--
-- Name: user_has_document_share(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_document_share(doc_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM document_shares ds
    WHERE ds.document_id = doc_id
      AND (ds.expires_at IS NULL OR ds.expires_at > NOW())
      AND (
        ds.shared_with_user_id = p_user_id
        OR
        (ds.shared_with_group_id IS NOT NULL AND EXISTS (
          SELECT 1 FROM user_group_members ugm
          JOIN profiles prof ON prof.id = ugm.user_id
          WHERE ugm.group_id = ds.shared_with_group_id
            AND prof.user_id = p_user_id
        ))
      )
  )
$$;


