--
-- Name: validate_sync_method(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_sync_method() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.sync_method NOT IN ('imap', 'jmap') THEN
    RAISE EXCEPTION 'sync_method must be imap or jmap, got: %', NEW.sync_method;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_thread_last_message_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_thread_last_message_date() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actual_last_date TIMESTAMP WITH TIME ZONE;
BEGIN
  IF NEW.last_message_date > NOW() THEN
    RAISE WARNING 'last_message_date is in the future: %, forcing to NOW()', NEW.last_message_date;
    NEW.last_message_date := NOW();
  END IF;

  BEGIN
    SELECT MAX(COALESCE(received_date, sent_date))
      INTO actual_last_date
      FROM public.email_messages
     WHERE thread_id = NEW.id;

    IF actual_last_date IS NOT NULL
       AND (NEW.last_message_date IS NULL OR NEW.last_message_date <> actual_last_date) THEN
      NEW.last_message_date := actual_last_date;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error validating last_message_date: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: verify_cron_secret(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_cron_secret(_secret text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_temp'
    AS $$
DECLARE
  v_expected text;
BEGIN
  SELECT decrypted_secret INTO v_expected
  FROM vault.decrypted_secrets WHERE name = 'CRON_SECRET' LIMIT 1;
  RETURN v_expected IS NOT NULL AND _secret = v_expected;
END;
$$;


--
-- Name: verify_rh_tresorerie_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_rh_tresorerie_sync() RETURNS TABLE(check_name text, status text, details text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Check 1: Fonction utilise date_trunc
  RETURN QUERY
  SELECT 
    'sync_function_check'::TEXT,
    CASE 
      WHEN prosrc LIKE '%date_trunc%' THEN '✅ OK'
      ELSE '❌ FAIL'
    END,
    'Vérification que sync_rh_to_tresorerie utilise date_trunc'::TEXT
  FROM pg_proc
  WHERE proname = 'sync_rh_to_tresorerie';
  
  -- Check 2: Pas de dates invalides
  RETURN QUERY
  SELECT 
    'valid_dates_check'::TEXT,
    CASE 
      WHEN COUNT(*) = 0 THEN '✅ OK'
      ELSE '❌ FAIL (' || COUNT(*)::TEXT || ' erreurs)'
    END,
    'Vérification que tous les mois sont au 1er du mois'::TEXT
  FROM rh_salaires_mensuels
  WHERE EXTRACT(DAY FROM mois) != 1;
  
  -- Check 3: Pas de dépenses orphelines
  RETURN QUERY
  SELECT 
    'orphan_depenses_check'::TEXT,
    CASE 
      WHEN COUNT(*) = 0 THEN '✅ OK'
      ELSE '⚠️ WARNING (' || COUNT(*)::TEXT || ' orphelines)'
    END,
    'Vérification absence de dépenses orphelines'::TEXT
  FROM tresorerie_depenses d
  WHERE d.source = 'rh_salaires'
    AND NOT EXISTS (SELECT 1 FROM rh_salaires_mensuels s WHERE s.id = d.source_id);
  
  -- Check 4: Synchro complète
  RETURN QUERY
  SELECT 
    'sync_completeness_check'::TEXT,
    CASE 
      WHEN COUNT(*) = 0 THEN '✅ OK'
      ELSE '⚠️ WARNING (' || COUNT(*)::TEXT || ' salaires non synchronisés)'
    END,
    'Vérification que tous les salaires ont une dépense'::TEXT
  FROM rh_salaires_mensuels s
  WHERE NOT EXISTS (
    SELECT 1 FROM tresorerie_depenses d 
    WHERE d.source = 'rh_salaires' AND d.source_id = s.id
  );
END;
$$;


--
-- Name: FUNCTION verify_rh_tresorerie_sync(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verify_rh_tresorerie_sync() IS 'Fonction de vérification complète du flux RH → Trésorerie. Utiliser : SELECT * FROM verify_rh_tresorerie_sync();';


--
-- Name: workflow_trigger_email_received(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_trigger_email_received() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sender_email text;
  v_sender_name text;
BEGIN
  -- Extraction sécurisée de l'expéditeur depuis participants (jsonb)
  -- Format attendu: [{"email": "...", "name": "...", "type": "from"}, ...]
  BEGIN
    SELECT
      p->>'email',
      p->>'name'
    INTO v_sender_email, v_sender_name
    FROM jsonb_array_elements(COALESCE(NEW.participants, '[]'::jsonb)) AS p
    WHERE p->>'type' = 'from'
       OR p->>'role' = 'from'
       OR p->>'kind' = 'from'
    LIMIT 1;

    -- Fallback: prendre le premier participant si aucun "from" trouvé
    IF v_sender_email IS NULL THEN
      SELECT p->>'email', p->>'name'
      INTO v_sender_email, v_sender_name
      FROM jsonb_array_elements(COALESCE(NEW.participants, '[]'::jsonb)) AS p
      LIMIT 1;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_sender_email := NULL;
    v_sender_name := NULL;
  END;

  -- Enqueue dans la file d'attente des workflows (best-effort, ne bloque jamais l'INSERT)
  BEGIN
    INSERT INTO public.workflow_trigger_queue (
      trigger_type,
      payload,
      created_at
    ) VALUES (
      'email.received',
      jsonb_build_object(
        'email_thread_id', NEW.id,
        'subject', NEW.subject,
        'sender_email', v_sender_email,
        'sender_name', v_sender_name,
        'etablissement_id', NEW.etablissement_id,
        'user_email_account_id', NEW.user_email_account_id,
        'received_at', COALESCE(NEW.last_message_at, NEW.created_at, now())
      ),
      now()
    );
  EXCEPTION WHEN OTHERS THEN
    -- Ne jamais bloquer la synchronisation des emails à cause du workflow
    RAISE WARNING 'workflow_trigger_email_received enqueue failed: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: workflow_trigger_etablissement_statut(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_trigger_etablissement_statut() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.statut IS DISTINCT FROM OLD.statut THEN
    INSERT INTO public.workflow_trigger_queue (trigger_type, payload)
    VALUES (
      'etablissement.statut_changed',
      jsonb_build_object(
        'etablissement_id', NEW.id,
        'nom', NEW.nom,
        'statut_old', OLD.statut,
        'statut_new', NEW.statut,
        'commercial_id', NEW.commercial_id,
        'changed_at', now()
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: workflow_trigger_facture_overdue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_trigger_facture_overdue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.statut = 'en_retard' AND OLD.statut IS DISTINCT FROM 'en_retard' THEN
    INSERT INTO public.workflow_trigger_queue (trigger_type, payload)
    VALUES (
      'facture.overdue',
      jsonb_build_object(
        'facture_id', NEW.id,
        'numero', NEW.numero,
        'etablissement_id', NEW.etablissement_id,
        'montant_ttc', NEW.montant_ttc,
        'date_echeance', NEW.date_echeance,
        'detected_at', now()
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: workflow_trigger_task_completed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_trigger_task_completed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Le statut réel en base est 'Terminé' (français), pas 'completed'
  IF NEW.statut = 'Terminé' AND (OLD.statut IS DISTINCT FROM 'Terminé') THEN
    BEGIN
      INSERT INTO public.workflow_trigger_queue (
        trigger_type,
        payload,
        created_at
      ) VALUES (
        'task.completed',
        jsonb_build_object(
          'task_id', NEW.id,
          'titre', NEW.titre,
          'etablissement_id', NEW.etablissement_id,
          'responsable_id', NEW.responsable_id,
          'completed_at', now()
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'workflow_trigger_task_completed enqueue failed: %', SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: workflows_audit_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflows_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.workflow_audit_log (workflow_id, user_id, action, details)
    VALUES (NEW.id, auth.uid(), 'created', jsonb_build_object('nom', NEW.nom, 'trigger_type', NEW.trigger_type));
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
      INSERT INTO public.workflow_audit_log (workflow_id, user_id, action, details)
      VALUES (NEW.id, auth.uid(), CASE WHEN NEW.is_active THEN 'activated' ELSE 'paused' END, '{}'::jsonb);
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.workflow_audit_log (workflow_id, user_id, action, details)
    VALUES (OLD.id, auth.uid(), 'deleted', jsonb_build_object('nom', OLD.nom));
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


