    titre text NOT NULL,
    description text,
    statut public.statut_tache DEFAULT 'A faire'::public.statut_tache NOT NULL,
    priorite public.priorite_tache DEFAULT 'medium'::public.priorite_tache NOT NULL,
    echeance date,
    date_realisation date,
    responsable_id uuid,
    ordre integer DEFAULT 0,
    commentaires text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_by uuid,
    archive boolean DEFAULT false NOT NULL,
    updated_by uuid,
    groupe_id uuid,
    niveau_tache text DEFAULT 'etablissement'::text,
    partenaire_id uuid,
    date_debut date,
    pulse_conversation_id uuid,
    pulse_created_from_message_id uuid,
    last_pulse_update timestamp with time zone,
    pulse_mention_count integer DEFAULT 0 NOT NULL,
    recurrence_rule text,
    CONSTRAINT taches_entity_check CHECK ((((etablissement_id IS NOT NULL) AND (partenaire_id IS NULL)) OR ((etablissement_id IS NULL) AND (partenaire_id IS NOT NULL)))),
    CONSTRAINT taches_niveau_tache_check CHECK ((niveau_tache = ANY (ARRAY['etablissement'::text, 'groupe'::text])))
);

ALTER TABLE ONLY public.taches REPLICA IDENTITY FULL;


--
-- Name: COLUMN taches.date_debut; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.taches.date_debut IS 'Date de début planifiée de la tâche';


--
-- Name: bi_v_activite_users; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_v_activite_users WITH (security_invoker='true') AS
 SELECT p.id AS profile_id,
    p.user_id,
    p.prenom,
    p.nom,
    ( SELECT count(*) AS count
           FROM public.taches ta
          WHERE ((ta.responsable_id = p.user_id) AND (ta.date_realisation > (now() - '30 days'::interval)))) AS taches_completees_30d,
    ( SELECT count(*) AS count
           FROM public.taches ta
          WHERE ((ta.responsable_id = p.user_id) AND ((ta.statut)::text <> ALL (ARRAY['terminee'::text, 'annulee'::text, 'Terminée'::text, 'Annulée'::text])))) AS taches_ouvertes
   FROM public.profiles p
  WHERE (p.actif = true);


