--
-- Name: factures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.factures (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    numero character varying(50) NOT NULL,
    etablissement_id uuid,
    groupe_id uuid,
    partenaire_id uuid,
    contact_id uuid,
    client_nom character varying(255) NOT NULL,
    client_adresse text,
    client_email character varying(255),
    client_telephone character varying(50),
    client_siret character varying(20),
    date_emission date DEFAULT CURRENT_DATE NOT NULL,
    date_echeance date DEFAULT (CURRENT_DATE + '30 days'::interval) NOT NULL,
    statut character varying(50) DEFAULT 'brouillon'::character varying NOT NULL,
    montant_ht numeric(12,2) DEFAULT 0 NOT NULL,
    montant_tva numeric(12,2) DEFAULT 0 NOT NULL,
    montant_ttc numeric(12,2) DEFAULT 0 NOT NULL,
    montant_paye numeric(12,2) DEFAULT 0 NOT NULL,
    remise_globale_pourcent numeric(5,2) DEFAULT 0,
    remise_globale_montant numeric(12,2) DEFAULT 0,
    conditions_paiement text DEFAULT 'Paiement à 30 jours'::text,
    mode_paiement character varying(50),
    notes_internes text,
    notes_client text,
    devis_id uuid,
    numero_bon_commande character varying(100),
    created_by uuid,
    commercial_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    qonto_transaction_id text,
    echeance_mois date,
    periodicite_source text,
    CONSTRAINT factures_statut_check CHECK (((statut)::text = ANY ((ARRAY['brouillon'::character varying, 'emise'::character varying, 'envoyee'::character varying, 'en_attente'::character varying, 'partiellement_payee'::character varying, 'payee'::character varying, 'annulee'::character varying, 'contentieux'::character varying])::text[])))
);


