-- Name: bi_v_prospects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_v_prospects WITH (security_invoker='true') AS
 SELECT etablissements.id,
    etablissements.nom,
    (etablissements.statut)::text AS statut,
    etablissements.ville,
    etablissements.region,
    etablissements.score_conversion,
