   FROM public.etablissements
  WHERE ((etablissements.statut)::text = ANY (ARRAY['Prospect'::text, 'Contacté'::text, 'Attente RDV'::text, 'RDV pris'::text, 'Attente post RDV'::text, 'Dans les RDV'::text, 'Etude émise'::text, 'Dans les RDV post EME'::text, 'Négociation'::text]));


--
-- Name: tresorerie_revenus; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tresorerie_revenus (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    etablissement_id uuid,
    mois date NOT NULL,
    date_prevue date,
    date_facture date,
    date_paiement_reel date,
    montant_prevu numeric(12,2) DEFAULT 0,
    montant_facture numeric(12,2),
    montant_paye numeric(12,2),
    statut text DEFAULT 'pipeline'::text NOT NULL,
    type_revenu text DEFAULT 'abonnement_mensuel'::text,
    probabilite_signature integer,
    date_signature_estimee date,
    numero_facture text,
    reference_paiement text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    source_modele text,
    source_periodicite text,
    source_pallier text,
    categorie_code text,
    CONSTRAINT tresorerie_revenus_probabilite_signature_check CHECK (((probabilite_signature >= 0) AND (probabilite_signature <= 100))),
    CONSTRAINT tresorerie_revenus_statut_check CHECK ((statut = ANY (ARRAY['pipeline'::text, 'contractualise'::text, 'a_facturer'::text, 'facture'::text, 'paye'::text, 'en_retard'::text, 'annule'::text]))),
    CONSTRAINT tresorerie_revenus_type_revenu_check CHECK ((type_revenu = ANY (ARRAY['abonnement_mensuel'::text, 'paiement_initial'::text, 'etude_medico_eco'::text, 'autre'::text])))
);


--
-- Name: COLUMN tresorerie_revenus.source_modele; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tresorerie_revenus.source_modele IS 'Modèle de tarification: "succes", "statique", "ponctuel"';


--
-- Name: COLUMN tresorerie_revenus.source_periodicite; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tresorerie_revenus.source_periodicite IS 'Périodicité de paiement: "mensuel", "trimestriel", "annuel"';


--
-- Name: COLUMN tresorerie_revenus.source_pallier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tresorerie_revenus.source_pallier IS 'Pallier visé pour modèles "Au succès": "Pallier 1", "Pallier 2", etc.';


--
-- Name: bi_v_revenus_mensuels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_v_revenus_mensuels WITH (security_invoker='true') AS
 SELECT (date_trunc('month'::text, (COALESCE(tresorerie_revenus.date_paiement_reel, tresorerie_revenus.date_facture, tresorerie_revenus.date_prevue))::timestamp with time zone))::date AS mois,
    tresorerie_revenus.categorie_code AS categorie,
    tresorerie_revenus.type_revenu,
    tresorerie_revenus.etablissement_id,
    tresorerie_revenus.statut,
    sum(COALESCE(tresorerie_revenus.montant_facture, tresorerie_revenus.montant_prevu, (0)::numeric)) AS total_facture,
    sum(COALESCE(tresorerie_revenus.montant_paye, (0)::numeric)) AS total_paye,
    count(*) AS nb_operations
   FROM public.tresorerie_revenus
  GROUP BY ((date_trunc('month'::text, (COALESCE(tresorerie_revenus.date_paiement_reel, tresorerie_revenus.date_facture, tresorerie_revenus.date_prevue))::timestamp with time zone))::date), tresorerie_revenus.categorie_code, tresorerie_revenus.type_revenu, tresorerie_revenus.etablissement_id, tresorerie_revenus.statut;


