--
-- Name: time_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.time_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    clock_in timestamp with time zone DEFAULT now() NOT NULL,
    clock_out timestamp with time zone,
    duration_minutes numeric GENERATED ALWAYS AS (
CASE
    WHEN (clock_out IS NOT NULL) THEN (EXTRACT(epoch FROM (clock_out - clock_in)) / (60)::numeric)
    ELSE NULL::numeric
END) STORED,
    note text,
    auto_closed boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: bi_v_time_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_v_time_entries WITH (security_invoker='true') AS
 SELECT time_entries.id,
    time_entries.user_id,
    time_entries.clock_in,
    time_entries.clock_out,
    time_entries.duration_minutes,
    time_entries.note,
