--
-- Name: client_portal_documents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.client_portal_documents WITH (security_invoker='true') AS
 SELECT f.id,
    (f.numero)::text AS numero,
    'facture'::text AS type,
    f.date_emission AS date,
    f.etablissement_id,
    COALESCE(f.montant_ht, (0)::numeric) AS montant_ht,
    COALESCE(f.montant_ttc, (0)::numeric) AS montant_ttc,
    (f.statut)::text AS statut,
    NULL::text AS pdf_url
   FROM public.factures f
  WHERE (f.etablissement_id IS NOT NULL)
UNION ALL
 SELECT d.id,
    (d.numero)::text AS numero,
    'devis'::text AS type,
    d.date_emission AS date,
    d.etablissement_id,
    COALESCE(d.montant_ht, (0)::numeric) AS montant_ht,
    COALESCE(d.montant_ttc, (0)::numeric) AS montant_ttc,
    (d.statut)::text AS statut,
    d.signature_url AS pdf_url
   FROM public.devis d
  WHERE (d.etablissement_id IS NOT NULL);


