--
-- Name: client_portal_emargements; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.client_portal_emargements WITH (security_invoker='on') AS
 SELECT fe.id,
    fe.session_id,
    fs.etablissement_id,
    fs.titre AS session_titre,
    fs.date_debut AS session_date_debut,
    fs.date_fin AS session_date_fin,
    fs.formateur_nom,
    fs.formateur_prenom,
    fe.user_id,
    COALESCE(eu.prenom, p.prenom) AS prenom,
    COALESCE(eu.nom, p.nom) AS nom,
    COALESCE(eu.email, p.email) AS email,
    eu.fonction,
    eu.service,
    fe.date_emargement AS signed_at,
    fe.signature_storage_path AS signature_url,
    fe.signature_data,
    fe.present,
    fe.retard_minutes,
    fe.depart_anticipe,
    fe.signature_type,
    fe.commentaire
   FROM (((public.formation_emargements fe
     JOIN public.formation_sessions fs ON ((fs.id = fe.session_id)))
     LEFT JOIN public.etablissement_users eu ON ((eu.id = fe.user_id)))
     LEFT JOIN public.profiles p ON ((p.id = fe.user_id)));


