CREATE VIEW public.client_portal_etablissement_view WITH (security_invoker='true') AS
 SELECT e.id,
    e.nom,
    (e.statut)::text AS phase,
    (e.statut)::text AS statut,
    e.backend_url,
    TRIM(BOTH ' '::text FROM ((COALESCE(p.prenom, ''::text) || ' '::text) || COALESCE(p.nom, ''::text))) AS referent_nom,
    p.email AS referent_email,
    p.telephone AS referent_telephone
   FROM (public.etablissements e
     LEFT JOIN public.profiles p ON ((p.id = e.csm_id)));


