--
-- Name: client_portal_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.client_portal_timeline WITH (security_invoker='on') AS
 WITH phases AS (
         SELECT t.key,
            t.label,
            t.ordre,
            t.done_when
           FROM ( VALUES ('signature'::text,'Signature du contrat'::text,1,ARRAY['contractuel'::text, 'contractualisation'::text, 'deploiement'::text, 'production'::text]), ('kickoff'::text,'Réunion de lancement'::text,2,ARRAY['deploiement'::text, 'production'::text]), ('parametrage'::text,'Paramétrage technique'::text,3,ARRAY['deploiement'::text, 'production'::text]), ('formation'::text,'Formation des équipes'::text,4,ARRAY['deploiement'::text, 'production'::text]), ('go_live'::text,'Mise en production'::text,5,ARRAY['production'::text])) t(key, label, ordre, done_when)
        )
 SELECT e.id AS etablissement_id,
    p.key,
    p.label,
        CASE
            WHEN (lower((e.statut)::text) = ANY (p.done_when)) THEN 'done'::text
            WHEN (p.ordre = ( SELECT min(p2.ordre) AS min
               FROM phases p2
              WHERE (NOT (lower((e.statut)::text) = ANY (p2.done_when))))) THEN 'current'::text
            ELSE 'todo'::text
        END AS status,
        CASE p.key
            WHEN 'signature'::text THEN e.date_signature
            WHEN 'go_live'::text THEN e.date_go_live
            ELSE NULL::date
        END AS date,
    p.ordre
   FROM (public.etablissements e
     CROSS JOIN phases p);


