--
-- Name: email_classification_audit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.email_classification_audit WITH (security_invoker='true') AS
 SELECT 'Établissements'::text AS type,
    count(*) AS count,
    round((((count(*))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.email_threads email_threads_1
          WHERE (email_threads_1.is_deleted = false)), 0))::numeric), 1) AS percentage
   FROM public.email_threads
  WHERE ((email_threads.etablissement_id IS NOT NULL) AND (email_threads.is_deleted = false))
UNION ALL
 SELECT 'Partenaires'::text AS type,
    count(*) AS count,
    round((((count(*))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.email_threads email_threads_1
          WHERE (email_threads_1.is_deleted = false)), 0))::numeric), 1) AS percentage
   FROM public.email_threads
  WHERE ((email_threads.partenaire_id IS NOT NULL) AND (email_threads.is_deleted = false))
UNION ALL
 SELECT 'Groupes'::text AS type,
    count(*) AS count,
    round((((count(*))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.email_threads email_threads_1
          WHERE (email_threads_1.is_deleted = false)), 0))::numeric), 1) AS percentage
   FROM public.email_threads
  WHERE ((email_threads.groupe_id IS NOT NULL) AND (email_threads.is_deleted = false))
UNION ALL
 SELECT 'Hors établissement'::text AS type,
    count(*) AS count,
    round((((count(*))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.email_threads email_threads_1
          WHERE (email_threads_1.is_deleted = false)), 0))::numeric), 1) AS percentage
   FROM public.email_threads
  WHERE ((email_threads.is_hors_etablissement = true) AND (email_threads.is_deleted = false))
UNION ALL
 SELECT 'Interne OpenPulse'::text AS type,
    count(*) AS count,
    round((((count(*))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.email_threads email_threads_1
          WHERE (email_threads_1.is_deleted = false)), 0))::numeric), 1) AS percentage
   FROM public.email_threads
  WHERE ((email_threads.category = 'Interne OpenPulse I.A'::text) AND (email_threads.is_deleted = false))
UNION ALL
 SELECT 'Non classés'::text AS type,
    count(*) AS count,
    round((((count(*))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.email_threads email_threads_1
          WHERE (email_threads_1.is_deleted = false)), 0))::numeric), 1) AS percentage
   FROM public.email_threads
  WHERE ((email_threads.etablissement_id IS NULL) AND (email_threads.partenaire_id IS NULL) AND (email_threads.groupe_id IS NULL) AND (email_threads.is_hors_etablissement = false) AND ((email_threads.category IS NULL) OR (email_threads.category <> 'Interne OpenPulse I.A'::text)) AND (email_threads.is_deleted = false));


