-- Name: email_domain_mappings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.email_domain_mappings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    etablissement_id uuid,
    domain text NOT NULL,
