    created_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    verified boolean DEFAULT false,
    is_excluded boolean DEFAULT false NOT NULL,
    groupe_id uuid,
    niveau_mapping text,
    partenaire_id uuid,
    prevent_auto boolean DEFAULT false,
    last_seen_at timestamp with time zone DEFAULT now(),
    CONSTRAINT check_mapping_level CHECK ((((niveau_mapping = 'etablissement'::text) AND (etablissement_id IS NOT NULL) AND (groupe_id IS NULL) AND (partenaire_id IS NULL)) OR ((niveau_mapping = 'groupe'::text) AND (groupe_id IS NOT NULL) AND (etablissement_id IS NULL) AND (partenaire_id IS NULL)) OR ((niveau_mapping = 'partenaire'::text) AND (partenaire_id IS NOT NULL) AND (etablissement_id IS NULL) AND (groupe_id IS NULL)) OR ((is_excluded = true) AND (niveau_mapping IS NULL) AND (etablissement_id IS NULL) AND (groupe_id IS NULL) AND (partenaire_id IS NULL)))),
    CONSTRAINT email_domain_mappings_confidence_level_check CHECK ((confidence_level = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT email_domain_mappings_niveau_mapping_check CHECK ((niveau_mapping = ANY (ARRAY['etablissement'::text, 'groupe'::text, 'partenaire'::text])))
);


