);


--
-- Name: email_sequence_variant_stats; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.email_sequence_variant_stats (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    variant_id uuid NOT NULL,
    sends_count integer DEFAULT 0 NOT NULL,
    opens_count integer DEFAULT 0 NOT NULL,
    clicks_count integer DEFAULT 0 NOT NULL,
    replies_count integer DEFAULT 0 NOT NULL,
    bounces_count integer DEFAULT 0 NOT NULL,
    unsubscribes_count integer DEFAULT 0 NOT NULL,
    open_rate numeric GENERATED ALWAYS AS (
CASE
    WHEN (sends_count > 0) THEN ((opens_count)::numeric / (sends_count)::numeric)
    ELSE (0)::numeric
END) STORED,
    click_rate numeric GENERATED ALWAYS AS (
CASE
    WHEN (sends_count > 0) THEN ((clicks_count)::numeric / (sends_count)::numeric)
    ELSE (0)::numeric
END) STORED,
    reply_rate numeric GENERATED ALWAYS AS (
CASE
    WHEN (sends_count > 0) THEN ((replies_count)::numeric / (sends_count)::numeric)
    ELSE (0)::numeric
END) STORED,
    last_recomputed_at timestamp with time zone DEFAULT now() NOT NULL
);


