--
-- Name: etablissements_emargement_public; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.etablissements_emargement_public WITH (security_invoker='on') AS
 SELECT e.id,
    e.nom,
    e.ville,
    e.csm_id,
    p.prenom AS csm_prenom,
    p.nom AS csm_nom,
    p.email AS csm_email
   FROM (public.etablissements e
     LEFT JOIN public.profiles p ON ((p.id = e.csm_id)))
  WHERE (e.statut = ANY (ARRAY['Contractuel'::public.statut_etablissement, 'Contractualisation'::public.statut_etablissement, 'Vendu'::public.statut_etablissement, 'Conformité'::public.statut_etablissement, 'Déploiement'::public.statut_etablissement, 'Formation'::public.statut_etablissement, 'Go-Live'::public.statut_etablissement, 'Production'::public.statut_etablissement]));


--
-- Name: VIEW etablissements_emargement_public; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.etablissements_emargement_public IS 'Vue publique restreinte exposant les établissements éligibles à l''émargement formation, enrichie avec la CSM responsable (id/prenom/nom/email).';


