    modules_deployes text[] DEFAULT '{}'::text[],
    logo_url text,
    type_offre text,
    periodicite_paiement text DEFAULT 'mensuel'::text,
    pallier_vise text,
    modele_statique_succes text,
    tarifs_palliers jsonb,
    paiement_initial numeric,
    email_facturation text,
    adresse_facturation text,
    siret_facturation text,
    conditions_paiement_defaut text,
    mode_paiement_prefere text,
    vecteur_achat text,
    prochaine_action_orga text,
    date_action_orga date,
    CONSTRAINT groupes_etablissements_type_check CHECK ((type = ANY (ARRAY['GHT'::text, 'Groupe Cliniques'::text, 'Consortium'::text, 'Autre'::text])))
);


--
-- Name: etablissements_with_documents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.etablissements_with_documents WITH (security_invoker='true') AS
 SELECT e.id,
    e.nom,
    e.ville,
    e.statut,
    COALESCE(e.logo_url, g.logo_url) AS logo_url,
    e.logo_url AS etablissement_logo_url,
    g.logo_url AS groupe_logo_url,
    g.nom AS groupe_nom,
    count(DISTINCT dr.document_id) AS document_count
   FROM ((((public.etablissements e
     LEFT JOIN public.etablissements_groupes eg ON (((e.id = eg.etablissement_id) AND (eg.date_sortie IS NULL))))
     LEFT JOIN public.groupes_etablissements g ON ((eg.groupe_id = g.id)))
     JOIN public.document_relations dr ON ((dr.related_etablissement_id = e.id)))
     JOIN public.documents d ON (((d.id = dr.document_id) AND (d.deleted_at IS NULL) AND (COALESCE(d.is_hard_deleted, false) = false))))
  GROUP BY e.id, e.nom, e.ville, e.statut, e.logo_url, g.logo_url, g.nom
 HAVING (count(DISTINCT dr.document_id) > 0)
  ORDER BY (count(DISTINCT dr.document_id)) DESC;


