    quantite numeric(10,2) DEFAULT 1 NOT NULL,
    unite character varying(50) DEFAULT 'unité'::character varying,
    prix_unitaire_ht numeric(12,2) NOT NULL,
    taux_tva numeric(5,2) DEFAULT 20.00 NOT NULL,
    remise_pourcent numeric(5,2) DEFAULT 0,
    montant_ht numeric(12,2) GENERATED ALWAYS AS (((quantite * prix_unitaire_ht) * ((1)::numeric - (remise_pourcent / (100)::numeric)))) STORED,
    montant_tva numeric(12,2) GENERATED ALWAYS AS (((((quantite * prix_unitaire_ht) * ((1)::numeric - (remise_pourcent / (100)::numeric))) * taux_tva) / (100)::numeric)) STORED,
    montant_ttc numeric(12,2) GENERATED ALWAYS AS ((((quantite * prix_unitaire_ht) * ((1)::numeric - (remise_pourcent / (100)::numeric))) * ((1)::numeric + (taux_tva / (100)::numeric)))) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


