--
-- Name: rh_bulletins_parsing_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rh_bulletins_parsing_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid,
    profile_id uuid,
    salaire_id uuid,
    status text NOT NULL,
    extracted_data jsonb,
    confidence_score numeric,
    gpt_raw_response jsonb,
    error_message text,
    processing_duration_ms integer,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT rh_bulletins_parsing_log_confidence_score_check CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (100)::numeric))),
    CONSTRAINT rh_bulletins_parsing_log_status_check CHECK ((status = ANY (ARRAY['success'::text, 'partial'::text, 'failed'::text, 'pending'::text])))
);


--
-- Name: TABLE rh_bulletins_parsing_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rh_bulletins_parsing_log IS 'Journal d''audit du parsing automatique des bulletins de salaire par GPT-5';


