CREATE TABLE public.rh_salaires_mensuels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    mois date NOT NULL,
    salaire_brut numeric(10,2) NOT NULL,
    salaire_net numeric(10,2) NOT NULL,
