--
-- Name: support_tickets_safe; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.support_tickets_safe WITH (security_invoker='true') AS
 SELECT support_tickets.id,
    support_tickets.numero_ticket,
    support_tickets.etablissement_id,
    support_tickets.titre,
    support_tickets.description,
    support_tickets.type_probleme,
    support_tickets.priorite,
    support_tickets.statut,
    support_tickets.assigne_a,
        CASE
            WHEN public.is_support_team() THEN support_tickets.contact_nom
            ELSE '***'::text
        END AS contact_nom,
        CASE
            WHEN public.is_support_team() THEN support_tickets.contact_email
            ELSE '***@***'::text
        END AS contact_email,
        CASE
            WHEN public.is_support_team() THEN support_tickets.contact_telephone
            ELSE '**.**.**.**.**'::text
        END AS contact_telephone,
    support_tickets.ai_summary,
    support_tickets.ai_category,
    support_tickets.date_ouverture,
    support_tickets.date_resolution,
    support_tickets.tags,
    support_tickets.created_at,
    support_tickets.created_by
   FROM public.support_tickets;


