--
-- Name: v_audit_salaires_tresorerie; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_audit_salaires_tresorerie WITH (security_invoker='true') AS
 SELECT s.id AS salaire_id,
    s.profile_id,
    ((p.prenom || ' '::text) || p.nom) AS nom_complet,
    s.mois,
    s.salaire_net,
    d.id AS depense_id,
    d.date_prevue,
    d.montant AS montant_depense,
        CASE
            WHEN (d.id IS NULL) THEN '❌ Dépense manquante'::text
            WHEN (d.montant <> s.salaire_net) THEN '⚠️ Montant différent'::text
            WHEN (EXTRACT(day FROM d.date_prevue) <> (5)::numeric) THEN '⚠️ Date prévue pas le 5'::text
            ELSE '✅ OK'::text
        END AS statut_synchro
   FROM ((public.rh_salaires_mensuels s
     JOIN public.profiles p ON ((p.id = s.profile_id)))
     LEFT JOIN public.tresorerie_depenses d ON (((d.source = 'rh_salaires'::text) AND (d.source_id = s.id))))
  ORDER BY s.mois DESC, ((p.prenom || ' '::text) || p.nom);


