-- Name: v_compta_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_compta_balance WITH (security_invoker='true') AS
 SELECT c.id AS compte_id,
    c.numero,
    c.libelle,
    c.classe,
    c.type,
    e.exercice_id,
    COALESCE(sum(l.debit), (0)::numeric) AS total_debit,
    COALESCE(sum(l.credit), (0)::numeric) AS total_credit,
    COALESCE(sum((l.debit - l.credit)), (0)::numeric) AS solde
   FROM ((public.compta_comptes c
     LEFT JOIN public.compta_lignes l ON ((l.compte_id = c.id)))
     LEFT JOIN public.compta_ecritures e ON (((e.id = l.ecriture_id) AND (e.statut = ANY (ARRAY['validee'::text, 'cloturee'::text])))))
  GROUP BY c.id, c.numero, c.libelle, c.classe, c.type, e.exercice_id;


--
-- Name: v_compta_budget_vs_reel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_compta_budget_vs_reel WITH (security_invoker='true') AS
 WITH reel AS (
         SELECT l.compte_id,
            e.exercice_id,
            (EXTRACT(month FROM e.date_ecriture))::smallint AS mois,
            (sum((l.credit - l.debit)) FILTER (WHERE (c_1.classe = 7)) + sum((l.debit - l.credit)) FILTER (WHERE (c_1.classe = 6))) AS montant_reel_signe,
            sum((l.debit - l.credit)) AS solde_reel
           FROM ((public.compta_lignes l
             JOIN public.compta_ecritures e ON ((e.id = l.ecriture_id)))
             JOIN public.compta_comptes c_1 ON ((c_1.id = l.compte_id)))
          WHERE (e.statut = ANY (ARRAY['validee'::text, 'cloturee'::text]))
          GROUP BY l.compte_id, e.exercice_id, (EXTRACT(month FROM e.date_ecriture))
        )
 SELECT b.id AS budget_id,
    b.libelle AS budget_libelle,
    b.exercice_id,
    c.id AS compte_id,
    c.numero,
    c.libelle AS compte_libelle,
    c.classe,
    bl.mois,
    bl.montant AS montant_budget,
    COALESCE(r.solde_reel, (0)::numeric) AS montant_reel,
    (COALESCE(r.solde_reel, (0)::numeric) - bl.montant) AS ecart,
        CASE
            WHEN (bl.montant <> (0)::numeric) THEN round((((COALESCE(r.solde_reel, (0)::numeric) - bl.montant) / bl.montant) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS ecart_pct
   FROM (((public.compta_budgets b
     JOIN public.compta_budget_lignes bl ON ((bl.budget_id = b.id)))
     JOIN public.compta_comptes c ON ((c.id = bl.compte_id)))
     LEFT JOIN reel r ON (((r.compte_id = bl.compte_id) AND (r.exercice_id = b.exercice_id) AND (r.mois = bl.mois))));


--
-- Name: v_compta_grand_livre; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_compta_grand_livre WITH (security_invoker='true') AS
 SELECT c.id AS compte_id,
    c.numero,
    c.libelle AS compte_libelle,
    c.classe,
    e.id AS ecriture_id,
    e.date_ecriture,
    e.numero_piece,
    e.libelle AS ecriture_libelle,
    j.code AS journal_code,
    j.libelle AS journal_libelle,
    l.id AS ligne_id,
    l.libelle AS ligne_libelle,
    l.debit,
    l.credit,
    l.lettrage,
    l.tiers_type,
    l.tiers_id,
    l.date_echeance,
    e.statut,
    e.exercice_id
   FROM (((public.compta_lignes l
     JOIN public.compta_ecritures e ON ((e.id = l.ecriture_id)))
     JOIN public.compta_comptes c ON ((c.id = l.compte_id)))
     JOIN public.compta_journaux j ON ((j.id = e.journal_id)))
  WHERE (e.statut = ANY (ARRAY['validee'::text, 'cloturee'::text]));


--
-- Name: v_compta_journal_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_compta_journal_detail WITH (security_invoker='true') AS
 SELECT j.id AS journal_id,
    j.code AS journal_code,
    j.libelle AS journal_libelle,
    e.id AS ecriture_id,
    e.date_ecriture,
    e.numero_piece,
    e.libelle AS ecriture_libelle,
    e.statut,
    l.id AS ligne_id,
    c.numero AS compte_numero,
    c.libelle AS compte_libelle,
    l.libelle AS ligne_libelle,
    l.debit,
    l.credit,
    l.lettrage,
    l.ordre
   FROM (((public.compta_ecritures e
     JOIN public.compta_journaux j ON ((j.id = e.journal_id)))
     JOIN public.compta_lignes l ON ((l.ecriture_id = e.id)))
     JOIN public.compta_comptes c ON ((c.id = l.compte_id)))
  ORDER BY e.date_ecriture, e.id, l.ordre;


