--
-- Name: v_etablissement_provisioning_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_etablissement_provisioning_status WITH (security_invoker='on') AS
 WITH last_steps AS (
         SELECT DISTINCT ON (client_provisioning_log.etablissement_id, client_provisioning_log.step) client_provisioning_log.etablissement_id,
            client_provisioning_log.step,
            client_provisioning_log.status,
            client_provisioning_log.details,
            client_provisioning_log.error,
            client_provisioning_log.attempt,
            client_provisioning_log.created_at
           FROM public.client_provisioning_log
          ORDER BY client_provisioning_log.etablissement_id, client_provisioning_log.step, client_provisioning_log.created_at DESC
        )
 SELECT e.id AS etablissement_id,
    e.nom,
    e.statut,
    e.directeur_general_email,
    e.backend_url,
    ( SELECT row_to_json(s.*) AS row_to_json
           FROM last_steps s
          WHERE ((s.etablissement_id = e.id) AND (s.step = 'portal_user'::text))) AS portal_user,
    ( SELECT row_to_json(s.*) AS row_to_json
           FROM last_steps s
          WHERE ((s.etablissement_id = e.id) AND (s.step = 'link_site_web'::text))) AS link_site_web,
    ( SELECT row_to_json(s.*) AS row_to_json
           FROM last_steps s
          WHERE ((s.etablissement_id = e.id) AND (s.step = 'product_tenant'::text))) AS product_tenant,
    ( SELECT row_to_json(s.*) AS row_to_json
           FROM last_steps s
          WHERE ((s.etablissement_id = e.id) AND (s.step = 'link_product'::text))) AS link_product,
    (EXISTS ( SELECT 1
           FROM public.client_external_ids x
          WHERE ((x.etablissement_id = e.id) AND (x.system = 'site_web'::text)))) AS provisioned_site_web,
    (EXISTS ( SELECT 1
           FROM public.client_external_ids x
          WHERE ((x.etablissement_id = e.id) AND (x.system = 'product'::text)))) AS provisioned_product
   FROM public.etablissements e;


--
-- Name: v_it_renewals_upcoming; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_it_renewals_upcoming WITH (security_invoker='true') AS
 SELECT 'license'::text AS kind,
    l.id,
    l.name AS label,
    l.vendor,
    l.renewal_date AS due_date,
    l.cost_amount AS amount,
    (l.renewal_date - CURRENT_DATE) AS days_until,
    NULL::public.it_asset_category AS category
   FROM public.it_software_licenses l
  WHERE ((l.active = true) AND (l.renewal_date IS NOT NULL) AND (l.renewal_date <= (CURRENT_DATE + '120 days'::interval)))
UNION ALL
 SELECT 'warranty'::text AS kind,
    a.id,
    COALESCE(((a.brand || ' '::text) || a.model), a.model) AS label,
    a.supplier AS vendor,
    a.warranty_end AS due_date,
    a.purchase_price AS amount,
    (a.warranty_end - CURRENT_DATE) AS days_until,
    a.category
   FROM public.it_assets a
  WHERE ((a.warranty_end IS NOT NULL) AND (a.status <> ALL (ARRAY['decommissioned'::public.it_asset_status, 'lost'::public.it_asset_status, 'stolen'::public.it_asset_status])) AND (a.warranty_end <= (CURRENT_DATE + '120 days'::interval)));


--
-- Name: v_time_rentabilite_etablissement; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_time_rentabilite_etablissement WITH (security_invoker='true') AS
 SELECT ti.etablissement_id,
    e.nom AS etablissement_nom,
    (date_trunc('month'::text, (ti.date_imputation)::timestamp with time zone))::date AS mois,
    sum(ti.duration_minutes) AS total_minutes,
    sum(ti.duration_minutes) FILTER (WHERE ti.is_billable) AS billable_minutes,
    round(sum((((ti.duration_minutes)::numeric * COALESCE(ti.cout_horaire_charge_snapshot, (0)::numeric)) / 60.0)), 2) AS cout_total,
    round(sum((((ti.duration_minutes)::numeric * COALESCE(ti.hourly_rate_snapshot, (0)::numeric)) / 60.0)), 2) AS revenu_theorique
   FROM (public.time_imputations ti
     LEFT JOIN public.etablissements e ON ((e.id = ti.etablissement_id)))
  WHERE ((ti.status = 'approved'::text) AND (ti.etablissement_id IS NOT NULL))
  GROUP BY ti.etablissement_id, e.nom, (date_trunc('month'::text, (ti.date_imputation)::timestamp with time zone));


--
-- Name: v_time_rentabilite_projet_rd; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_time_rentabilite_projet_rd WITH (security_invoker='true') AS
 SELECT ti.projet_rd_id,
    p.nom AS projet_nom,
    (date_trunc('month'::text, (ti.date_imputation)::timestamp with time zone))::date AS mois,
    ti.user_id,
    sum(ti.duration_minutes) AS total_minutes,
    round(sum((((ti.duration_minutes)::numeric * COALESCE(ti.cout_horaire_charge_snapshot, (0)::numeric)) / 60.0)), 2) AS cout_total,
    bool_or(COALESCE(at.is_cir_eligible, false)) AS cir_eligible
   FROM ((public.time_imputations ti
     LEFT JOIN public.rd_projets p ON ((p.id = ti.projet_rd_id)))
     LEFT JOIN public.time_activity_types at ON ((at.id = ti.activity_type_id)))
  WHERE ((ti.status = 'approved'::text) AND (ti.projet_rd_id IS NOT NULL))
  GROUP BY ti.projet_rd_id, p.nom, (date_trunc('month'::text, (ti.date_imputation)::timestamp with time zone)), ti.user_id;


--
-- Name: v_time_semaine_utilisateur; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_time_semaine_utilisateur WITH (security_invoker='true') AS
 SELECT ti.user_id,
    ti.week_iso,
    min(ti.date_imputation) AS week_start,
    sum(ti.duration_minutes) AS total_minutes,
    sum(ti.duration_minutes) FILTER (WHERE ti.is_billable) AS billable_minutes,
    count(*) AS nb_imputations,
    max(ws.status) AS submission_status
   FROM (public.time_imputations ti
     LEFT JOIN public.time_weekly_submissions ws ON (((ws.user_id = ti.user_id) AND (ws.week_iso = ti.week_iso))))
  GROUP BY ti.user_id, ti.week_iso;


