--
-- Name: v_email_thread_integrity _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_email_thread_integrity WITH (security_invoker='on') AS
 SELECT t.id AS thread_id,
    t.subject,
    t.message_count AS stored_count,
    (COALESCE(count(m.id), (0)::bigint))::integer AS actual_count,
    (t.message_count - (COALESCE(count(m.id), (0)::bigint))::integer) AS drift,
    t.last_message_date AS stored_last_date,
    max(m.received_date) AS actual_last_date,
    t.updated_at
   FROM (public.email_threads t
     LEFT JOIN public.email_messages m ON ((m.thread_id = t.id)))
  GROUP BY t.id
 HAVING ((t.message_count <> (COALESCE(count(m.id), (0)::bigint))::integer) OR ((t.last_message_date IS DISTINCT FROM max(m.received_date)) AND (max(m.received_date) IS NOT NULL)));


