CREATE POLICY "Public can view planned session by qr token" ON public.formation_sessions FOR SELECT USING (((statut = 'planifiee'::text) AND (qr_code_token IS NOT NULL) AND (length(qr_code_token) >= 43) AND (qr_code_token = COALESCE(((current_setting('request.headers'::text, true))::json ->> 'x-session-token'::text), ''::text)) AND (length(COALESCE(((current_setting('request.headers'::text, true))::json ->> 'x-session-token'::text), ''::text)) >= 43) AND ((qr_code_expires_at IS NULL) OR (qr_code_expires_at > now()))));


