--
-- Name: etablissements Role-based update when unassigned; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Role-based update when unassigned" ON public.etablissements FOR UPDATE TO authenticated USING (((public.has_role(auth.uid(), 'commercial'::text) AND (commercial_id IS NULL)) OR (public.has_role(auth.uid(), 'chef_projet'::text) AND (chef_projet_id IS NULL)) OR (public.has_role(auth.uid(), 'csm'::text) AND (csm_id IS NULL)) OR (public.has_role(auth.uid(), 'manager'::text) AND ((commercial_id IS NULL) OR (chef_projet_id IS NULL) OR (csm_id IS NULL))))) WITH CHECK (((public.has_role(auth.uid(), 'commercial'::text) AND (commercial_id = ( SELECT profiles.id
   FROM public.profiles
  WHERE (profiles.user_id = auth.uid())
 LIMIT 1))) OR (public.has_role(auth.uid(), 'chef_projet'::text) AND (chef_projet_id = ( SELECT profiles.id
   FROM public.profiles
  WHERE (profiles.user_id = auth.uid())
 LIMIT 1))) OR (public.has_role(auth.uid(), 'csm'::text) AND (csm_id = ( SELECT profiles.id
   FROM public.profiles
  WHERE (profiles.user_id = auth.uid())
 LIMIT 1))) OR (public.has_role(auth.uid(), 'manager'::text) AND ((commercial_id = ( SELECT profiles.id
   FROM public.profiles
  WHERE (profiles.user_id = auth.uid())
 LIMIT 1)) OR (chef_projet_id = ( SELECT profiles.id
   FROM public.profiles
  WHERE (profiles.user_id = auth.uid())
 LIMIT 1)) OR (csm_id = ( SELECT profiles.id
   FROM public.profiles
  WHERE (profiles.user_id = auth.uid())
 LIMIT 1))))));


