--
-- Name: forum_votes Utilisateurs voient votes posts accessibles; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Utilisateurs voient votes posts accessibles" ON public.forum_votes FOR SELECT TO authenticated USING ((((post_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (public.forum_posts p
     LEFT JOIN public.etablissement_users eu_self ON ((eu_self.user_id = auth.uid())))
  WHERE ((p.id = forum_votes.post_id) AND (p.archive = false) AND ((p.visibilite = 'public'::text) OR (p.user_id IN ( SELECT etablissement_users.id
           FROM public.etablissement_users
          WHERE (etablissement_users.user_id = auth.uid()))) OR ((p.visibilite = 'etablissement'::text) AND (p.etablissement_id = eu_self.etablissement_id))))))) OR ((comment_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM ((public.forum_comments c
     JOIN public.forum_posts p ON ((p.id = c.post_id)))
     LEFT JOIN public.etablissement_users eu_self ON ((eu_self.user_id = auth.uid())))
  WHERE ((c.id = forum_votes.comment_id) AND (p.archive = false) AND ((p.visibilite = 'public'::text) OR (p.user_id IN ( SELECT etablissement_users.id
           FROM public.etablissement_users
          WHERE (etablissement_users.user_id = auth.uid()))) OR ((p.visibilite = 'etablissement'::text) AND (p.etablissement_id = eu_self.etablissement_id))))))) OR (user_id IN ( SELECT etablissement_users.id
   FROM public.etablissement_users
  WHERE (etablissement_users.user_id = auth.uid())))));


