--

CREATE POLICY "Visitors can create chat sessions" ON public.live_chat_sessions FOR INSERT WITH CHECK (((guest_name IS NOT NULL) AND (guest_email IS NOT NULL) AND (length(guest_name) <= 200) AND (length(guest_email) <= 255) AND (guest_email ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'::text) AND (assigned_agent_id IS NULL) AND ((etablissement_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.etablissements e
  WHERE (e.id = live_chat_sessions.etablissement_id))))));


