-- Name: live_chat_conversations Visitors can create conversations with valid session; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Visitors can create conversations with valid session" ON public.live_chat_conversations FOR INSERT WITH CHECK (((visitor_id IS NOT NULL) AND (length(COALESCE(((current_setting('request.headers'::text, true))::json ->> 'x-session-token'::text), ''::text)) >= 43) AND (assigned_to IS NULL) AND (ticket_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.live_chat_sessions s
  WHERE ((s.session_token_hash = encode(extensions.digest(COALESCE(((current_setting('request.headers'::text, true))::json ->> 'x-session-token'::text), ''::text), 'sha256'::text), 'hex'::text)) AND (((live_chat_conversations.etablissement_id IS NULL) AND (s.etablissement_id IS NULL)) OR ((live_chat_conversations.etablissement_id IS NOT NULL) AND (s.etablissement_id = live_chat_conversations.etablissement_id))))))));


