   FROM public.live_chat_sessions s
  WHERE ((s.id = live_chat_messages.session_id) AND (length(COALESCE(((current_setting('request.headers'::text, true))::json ->> 'x-session-token'::text), ''::text)) >= 64) AND (s.session_token_hash IS NOT NULL) AND (s.session_token_hash = encode(extensions.digest(COALESCE(((current_setting('request.headers'::text, true))::json ->> 'x-session-token'::text), ''::text), 'sha256'::text), 'hex'::text)))))));


