-- Name: custom_dashboard_exports users manage exports of their dashboards; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users manage exports of their dashboards" ON public.custom_dashboard_exports USING ((EXISTS ( SELECT 1
   FROM public.custom_dashboards d
  WHERE ((d.id = custom_dashboard_exports.dashboard_id) AND (d.owner_id = auth.uid()))))) WITH CHECK (((created_by = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.custom_dashboards d
  WHERE ((d.id = custom_dashboard_exports.dashboard_id) AND (d.owner_id = auth.uid()))))));


--
-- Name: custom_dashboard_exports users view exports of dashboards they own or share; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "users view exports of dashboards they own or share" ON public.custom_dashboard_exports FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.custom_dashboards d
  WHERE ((d.id = custom_dashboard_exports.dashboard_id) AND ((d.owner_id = auth.uid()) OR (auth.uid() = ANY (d.shared_with)))))));


